{
  "name": "نادي الكرامة الرياضي - مكتب كرة القدم",
  "description": "نظام متكامل لإدارة فرق كرة القدم، تتبع الحضور، تنظيم التدريبات، واستخراج التقارير.",
  "requestFramePermissions": [
    "camera"
  ]
}

export type Category = 'رجال' | 'شباب' | 'ناشئين' | 'أشبال';
export type Role = 'لاعب' | 'مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب';

export interface Person {
  id: string;
  name: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  users: AppUser[];
  currentUser: AppUser | null;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Users, 
  Calendar, 
  ClipboardCheck, 
  LayoutDashboard, 
  Settings, 
  LogOut, 
  Plus, 
  FileText, 
  MapPin, 
  Clock,
  Download,
  ShieldCheck,
  UserCircle,
  Menu,
  X,
  Bird
} from 'lucide-react';
import { 
  Category, 
  Person, 
  AttendanceRecord, 
  TrainingSession, 
  AppUser, 
  UserRole,
  AppState 
} from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import SettingsView from './components/SettingsView';
import Login from './components/Login';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_data');
    if (saved) return JSON.parse(saved);
    return {
      people: [],
      attendance: [],
      sessions: [],
      users: [
        { id: '1', username: 'admin', role: 'مدير' },
        { id: '2', username: 'coach1', role: 'مدرب' }
      ],
      currentUser: null
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(true);

  useEffect(() => {
    localStorage.setItem('alkaramah_data', JSON.stringify(state));
  }, [state]);

  const handleLogin = (user: AppUser) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} />;
      case 'squad': return <SquadManagement state={state} setState={setState} />;
      case 'attendance': return <AttendanceTracker state={state} setState={setState} />;
      case 'training': return <TrainingPlanner state={state} setState={setState} />;
      case 'settings': return <SettingsView state={state} setState={setState} />;
      default: return <Dashboard state={state} />;
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'الفئات واللاعبين', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'جدول التمارين', icon: Calendar },
    { id: 'settings', label: 'الإعدادات', icon: Settings, adminOnly: true },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-['Tajawal']" dir="rtl">
      {/* Sidebar */}
      <aside className={`bg-blue-900 text-white transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} flex flex-col no-print`}>
        <div className="p-4 flex items-center gap-3 border-b border-blue-800">
          <div className="bg-orange-500 p-2 rounded-lg shadow-lg">
            <Bird size={24} className="text-white" />
          </div>
          {isSidebarOpen && (
            <div className="overflow-hidden whitespace-nowrap">
              <h1 className="font-bold text-lg">نادي الكرامة</h1>
              <p className="text-xs text-blue-300">مكتب كرة القدم</p>
            </div>
          )}
        </div>

        <nav className="flex-1 mt-6 px-3 space-y-2">
          {menuItems.map((item) => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all ${
                  activeTab === item.id 
                  ? 'bg-orange-600 text-white shadow-md' 
                  : 'hover:bg-blue-800 text-blue-100'
                }`}
              >
                <Icon size={20} />
                {isSidebarOpen && <span className="font-medium">{item.label}</span>}
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-blue-800">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-3 p-3 rounded-xl text-red-300 hover:bg-red-900/30 transition-all"
          >
            <LogOut size={20} />
            {isSidebarOpen && <span className="font-medium">تسجيل الخروج</span>}
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white border-b px-8 py-4 flex items-center justify-between no-print">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"
            >
              <Menu size={20} />
            </button>
            <h2 className="text-xl font-bold text-slate-800">
              {menuItems.find(m => m.id === activeTab)?.label}
            </h2>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex flex-col text-left items-end">
              <span className="font-bold text-slate-700">{state.currentUser.username}</span>
              <span className="text-xs text-slate-500">{state.currentUser.role}</span>
            </div>
            <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center font-bold">
              {state.currentUser.username.charAt(0).toUpperCase()}
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-8">
          {renderContent()}
        </section>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { Users, Calendar, AlertCircle, TrendingUp } from 'lucide-react';
import { AppState, Category } from '../types';

interface DashboardProps {
  state: AppState;
}

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  const stats = [
    { label: 'إجمالي الكوادر', value: state.people.length, icon: Users, color: 'blue' },
    { label: 'تمارين هذا الشهر', value: state.sessions.length, icon: Calendar, color: 'orange' },
    { label: 'نسبة الحضور', value: '85%', icon: TrendingUp, color: 'green' },
    { label: 'بلاغات غياب', value: state.attendance.filter(a => a.status === 'غائب').length, icon: AlertCircle, color: 'red' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, idx) => {
          const Icon = stat.icon;
          return (
            <div key={idx} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
              <div className="flex items-center justify-between mb-4">
                <div className={`p-3 rounded-xl bg-${stat.color}-50 text-${stat.color}-600`}>
                  <Icon size={24} />
                </div>
              </div>
              <h3 className="text-slate-500 text-sm font-medium">{stat.label}</h3>
              <p className="text-2xl font-bold text-slate-900 mt-1">{stat.value}</p>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-800 mb-6">توزيع الفئات</h3>
          <div className="space-y-4">
            {categories.map(cat => {
              const count = state.people.filter(p => p.category === cat).length;
              const percentage = state.people.length ? (count / state.people.length) * 100 : 0;
              return (
                <div key={cat} className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="font-medium text-slate-600">{cat}</span>
                    <span className="text-slate-400">{count} عضو</span>
                  </div>
                  <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-blue-600 rounded-full" 
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-800 mb-6">آخر التمارين المجدولة</h3>
          <div className="space-y-4">
            {state.sessions.slice(0, 5).map(session => (
              <div key={session.id} className="flex items-center gap-4 p-4 rounded-xl bg-slate-50 border border-slate-100">
                <div className="bg-white p-3 rounded-lg border shadow-sm text-blue-600">
                  <Calendar size={20} />
                </div>
                <div className="flex-1">
                  <h4 className="font-bold text-slate-800">{session.category} - {session.location}</h4>
                  <p className="text-sm text-slate-500">{session.date} الساعة {session.time}</p>
                </div>
                <span className="px-3 py-1 rounded-full bg-blue-100 text-blue-700 text-xs font-bold">
                  مجدول
                </span>
              </div>
            ))}
            {state.sessions.length === 0 && (
              <div className="text-center py-8 text-slate-400 italic">لا توجد تمارين مجدولة حالياً</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Plus, Search, UserPlus, Filter, MoreVertical, Trash2 } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>('الكل');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: 'رجال',
    role: 'لاعب'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  const filteredPeople = state.people.filter(p => 
    selectedCategory === 'الكل' ? true : p.category === selectedCategory
  );

  const handleAddPerson = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const newPerson: Person = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name,
      category: formData.category as Category,
      role: formData.role as Role,
      number: formData.number,
      phone: formData.phone,
      joinDate: new Date().toISOString().split('T')[0]
    };

    setState(prev => ({
      ...prev,
      people: [...prev.people, newPerson]
    }));
    setIsModalOpen(false);
    setFormData({ category: 'رجال', role: 'لاعب' });
  };

  const removePerson = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({
        ...prev,
        people: prev.people.filter(p => p.id !== id)
      }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex bg-white p-1 rounded-xl shadow-sm border w-fit">
          <button 
            onClick={() => setSelectedCategory('الكل')}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white' : 'text-slate-600 hover:bg-slate-50'}`}
          >
            الكل
          </button>
          {categories.map(cat => (
            <button 
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${selectedCategory === cat ? 'bg-blue-600 text-white' : 'text-slate-600 hover:bg-slate-50'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-lg shadow-orange-200"
        >
          <UserPlus size={20} />
          إضافة عضو جديد
        </button>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-right">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-6 py-4 text-slate-600 font-bold">الاسم</th>
              <th className="px-6 py-4 text-slate-600 font-bold">الفئة</th>
              <th className="px-6 py-4 text-slate-600 font-bold">الدور</th>
              <th className="px-6 py-4 text-slate-600 font-bold">رقم القميص</th>
              <th className="px-6 py-4 text-slate-600 font-bold">الهاتف</th>
              <th className="px-6 py-4 text-slate-600 font-bold text-center">الإجراءات</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredPeople.map(person => (
              <tr key={person.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4 font-bold text-slate-800">{person.name}</td>
                <td className="px-6 py-4">
                   <span className="px-2 py-1 bg-blue-50 text-blue-600 rounded-md text-xs font-bold">{person.category}</span>
                </td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-md text-xs font-bold ${person.role === 'لاعب' ? 'bg-orange-50 text-orange-600' : 'bg-slate-100 text-slate-600'}`}>
                    {person.role}
                  </span>
                </td>
                <td className="px-6 py-4 text-slate-500 font-mono">{person.number || '-'}</td>
                <td className="px-6 py-4 text-slate-500">{person.phone || '-'}</td>
                <td className="px-6 py-4 text-center">
                  <button 
                    onClick={() => removePerson(person.id)}
                    className="text-red-400 hover:text-red-600 p-2"
                  >
                    <Trash2 size={18} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filteredPeople.length === 0 && (
          <div className="text-center py-20 bg-slate-50/50">
            <Users size={48} className="mx-auto text-slate-200 mb-4" />
            <p className="text-slate-400">لا يوجد أعضاء في هذه الفئة حالياً</p>
          </div>
        )}
      </div>

      {/* Modal Add Person */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b flex items-center justify-between bg-slate-50">
              <h3 className="text-xl font-bold text-slate-800">إضافة عضو جديد</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <Plus className="rotate-45" />
              </button>
            </div>
            <form onSubmit={handleAddPerson} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2 space-y-1">
                  <label className="text-sm font-bold text-slate-700">الاسم الكامل</label>
                  <input 
                    required
                    type="text" 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="مثال: أحمد محمد علي"
                    onChange={e => setFormData({ ...formData, name: e.target.value })}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">الفئة</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 outline-none"
                    value={formData.category}
                    onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                  >
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">الدور</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 outline-none"
                    value={formData.role}
                    onChange={e => setFormData({ ...formData, role: e.target.value as Role })}
                  >
                    {roles.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">رقم القميص</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 outline-none"
                    placeholder="0"
                    onChange={e => setFormData({ ...formData, number: parseInt(e.target.value) })}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">رقم الهاتف</label>
                  <input 
                    type="tel" 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 outline-none"
                    placeholder="09XXXXXXXX"
                    onChange={e => setFormData({ ...formData, phone: e.target.value })}
                  />
                </div>
              </div>
              <div className="pt-4 flex gap-3">
                <button 
                  type="submit" 
                  className="flex-1 bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
                >
                  حفظ البيانات
                </button>
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 bg-slate-100 text-slate-600 font-bold py-3 rounded-xl hover:bg-slate-200 transition-all"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState } from 'react';
import { ClipboardCheck, Search, Filter, Save, FileText, Download } from 'lucide-react';
import { AppState, Category, AttendanceRecord, AttendanceStatus, Person } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category>('رجال');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [localRecords, setLocalRecords] = useState<Record<string, AttendanceStatus>>({});

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const players = state.people.filter(p => p.category === selectedCategory);

  const setStatus = (personId: string, status: AttendanceStatus) => {
    setLocalRecords(prev => ({ ...prev, [personId]: status }));
  };

  const saveAttendance = () => {
    const now = new Date();
    const time = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;

    const newRecords: AttendanceRecord[] = Object.entries(localRecords).map(([pid, status]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      date,
      time,
      status
    }));

    setState(prev => ({
      ...prev,
      attendance: [...prev.attendance, ...newRecords]
    }));

    alert('تم حفظ الحضور بنجاح!');
    setLocalRecords({});
  };

  const exportPDF = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col md:flex-row items-center justify-between gap-6 no-print">
        <div className="flex flex-wrap gap-4 items-center">
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-500">الفئة</label>
            <select 
              value={selectedCategory}
              onChange={e => setSelectedCategory(e.target.value as Category)}
              className="bg-slate-50 border rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-blue-500 font-bold"
            >
              {categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-500">التاريخ</label>
            <input 
              type="date" 
              value={date}
              onChange={e => setDate(e.target.value)}
              className="bg-slate-50 border rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-blue-500 font-bold"
            />
          </div>
        </div>

        <div className="flex gap-3">
          <button 
            onClick={exportPDF}
            className="flex items-center gap-2 bg-slate-100 text-slate-700 px-6 py-2 rounded-xl font-bold hover:bg-slate-200 transition-all"
          >
            <FileText size={18} />
            استخراج تقرير PDF
          </button>
          <button 
            onClick={saveAttendance}
            className="flex items-center gap-2 bg-blue-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
          >
            <Save size={18} />
            حفظ السجل
          </button>
        </div>
      </div>

      {/* Printing Header */}
      <div className="hidden print:block text-center mb-8 border-b-2 pb-4 border-blue-900">
