              <div className="space-y-1">
                <label className="text-sm font-bold text-slate-700">المكان (الملعب)</label>
                <input type="text" required placeholder="مثال: الملعب الرئيسي" className="w-full bg-slate-100 rounded-xl p-3 outline-none" onChange={e => setFormData({ ...formData, location: e.target.value })} />
