                <label className="text-sm font-bold text-slate-700">موضوع التمرين</label>
                <input type="text" placeholder="مثال: لياقة بدنية وتكتيك" className="w-full bg-slate-100 rounded-xl p-3 outline-none" onChange={e => setFormData({ ...formData, objective: e.target.value })} />
              </div>
              <button type="submit" className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl mt-4">جدولة التمرين</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TrainingPlanner;

import React from 'react';
import { ShieldCheck, CloudUpload, Trash2, Key, Info } from 'lucide-react';
import { AppState } from '../types';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState }) => {
  const exportToDrive = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();

    alert('تم تجهيز ملف النسخة الاحتياطية. يمكنك رفعه الآن إلى حسابك في Google Drive لضمان أمان البيانات.');
  };

  const resetData = () => {
    if (confirm('هل أنت متأكد من مسح جميع البيانات؟ لا يمكن التراجع عن هذا الإجراء.')) {
      localStorage.removeItem('alkaramah_data');
      window.location.reload();
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
        <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
          <ShieldCheck className="text-blue-600" />
          إدارة الصلاحيات والمستخدمين
        </h3>
        <div className="space-y-4">
          {state.users.map(user => (
            <div key={user.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold">
                  {user.username.charAt(0).toUpperCase()}
                </div>
                <div>
                  <p className="font-bold text-slate-800">{user.username}</p>
                  <p className="text-xs text-slate-500">صلاحية: {user.role}</p>
                </div>
              </div>
              <button className="text-slate-400 hover:text-slate-600 p-2">
                <Key size={18} />
              </button>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
        <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
          <CloudUpload className="text-orange-600" />
          تخزين البيانات والنسخ الاحتياطي
        </h3>
        <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100 flex gap-4 mb-6">
          <Info className="text-blue-600 shrink-0" />
          <p className="text-sm text-blue-800 leading-relaxed">
            للتخزين على Google Drive: يمكنك تصدير البيانات كملف JSON ورفعه يدوياً إلى حسابك. 
            تأكد من الاحتفاظ بنسخة دورية لضمان عدم ضياع بيانات الحضور واللاعبين.
          </p>
        </div>
        <div className="flex flex-wrap gap-4">
          <button 
            onClick={exportToDrive}
            className="flex-1 bg-orange-600 text-white font-bold py-4 rounded-2xl hover:bg-orange-700 transition-all shadow-lg shadow-orange-200 flex items-center justify-center gap-2"
          >
            <CloudUpload size={20} />
            تصدير البيانات (Backup)
          </button>
          <button 
            onClick={resetData}
            className="flex-1 bg-red-50 text-red-600 font-bold py-4 rounded-2xl hover:bg-red-100 transition-all flex items-center justify-center gap-2"
          >
            <Trash2 size={20} />
            مسح جميع البيانات
          </button>
        </div>
      </div>

      <div className="bg-slate-100 p-8 rounded-3xl text-center">
        <p className="text-slate-500 text-sm">نظام إدارة مكتب كرة القدم - نادي الكرامة الرياضي</p>
        <p className="text-slate-400 text-xs mt-1">نسخة 1.0.0 © 2024</p>
      </div>
    </div>
  );
};

