                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">الفئة</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 outline-none"
                    value={formData.category}
                    onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                  >
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">الدور</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 outline-none"
                    value={formData.role}
                    onChange={e => setFormData({ ...formData, role: e.target.value as Role })}
                  >
                    {roles.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">رقم القميص</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 outline-none"
                    placeholder="0"
                    onChange={e => setFormData({ ...formData, number: parseInt(e.target.value) })}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">رقم الهاتف</label>
                  <input 
                    type="tel" 
                    className="w-full bg-slate-100 border-none rounded-xl p-3 outline-none"
                    placeholder="09XXXXXXXX"
                    onChange={e => setFormData({ ...formData, phone: e.target.value })}
                  />
                </div>
              </div>
              <div className="pt-4 flex gap-3">
                <button 
                  type="submit" 
                  className="flex-1 bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
                >
