import React, { useState, useEffect } from 'react';
import { 
  Users, 
  Calendar, 
  ClipboardCheck, 
  LayoutDashboard, 
  Settings, 
  LogOut, 
  Plus, 
  Menu,
  X,
  Bird
} from 'lucide-react';
import { 
  AppUser, 
  AppState 
} from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import SettingsView from './components/SettingsView';
import Login from './components/Login';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_data');
    if (saved) return JSON.parse(saved);
    return {
      people: [],
      attendance: [],
      sessions: [],
      users: [
        { id: '1', username: 'admin', role: 'مدير' },
        { id: '2', username: 'coach1', role: 'مدرب' }
      ],
      currentUser: null
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('alkaramah_data', JSON.stringify(state));
  }, [state]);

  const handleLogin = (user: AppUser) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} />;
      case 'squad': return <SquadManagement state={state} setState={setState} />;
      case 'attendance': return <AttendanceTracker state={state} setState={setState} />;
      case 'training': return <TrainingPlanner state={state} setState={setState} />;
      case 'settings': return <SettingsView state={state} setState={setState} />;
      default: return <Dashboard state={state} />;
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'الفئات واللاعبين', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'جدول التمارين', icon: Calendar },
    { id: 'settings', label: 'الإعدادات', icon: Settings, adminOnly: true },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-['Tajawal'] text-right" dir="rtl">
      {/* Sidebar Overlay for Mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 right-0 z-50 w-72 bg-blue-900 text-white transition-transform duration-300 transform 
        md:relative md:translate-x-0 md:w-64 flex flex-col no-print
        ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
      `}>
        <div className="p-6 flex items-center justify-between border-b border-blue-800">
          <div className="flex items-center gap-3">
            <div className="bg-orange-500 p-2 rounded-lg shadow-lg">
              <Bird size={24} className="text-white" />
            </div>
            <div className="overflow-hidden whitespace-nowrap">
              <h1 className="font-bold text-lg">نادي الكرامة</h1>
              <p className="text-xs text-blue-300">مكتب كرة القدم</p>
            </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="md:hidden text-blue-200">
            <X size={24} />
          </button>
        </div>

        <nav className="flex-1 mt-6 px-4 space-y-2 overflow-y-auto">
          {menuItems.map((item) => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => {
                  setActiveTab(item.id);
                  setSidebarOpen(false);
                }}
                className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${
                  activeTab === item.id 
                  ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/20' 
                  : 'hover:bg-blue-800 text-blue-100'
                }`}
              >
                <Icon size={22} />
                <span className="font-bold">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-6 border-t border-blue-800">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-4 p-4 rounded-2xl text-red-300 hover:bg-red-900/30 transition-all font-bold"
          >
            <LogOut size={22} />
            <span>تسجيل الخروج</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden w-full">
        <header className="bg-white border-b px-4 md:px-8 py-4 flex items-center justify-between no-print">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setSidebarOpen(true)}
              className="p-2 hover:bg-slate-100 rounded-xl text-slate-600 md:hidden"
            >
              <Menu size={24} />
            </button>
            <h2 className="text-lg md:text-xl font-bold text-slate-800 truncate">
              {menuItems.find(m => m.id === activeTab)?.label}
            </h2>
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden sm:flex flex-col text-left items-end">
              <span className="font-bold text-sm text-slate-700">{state.currentUser.username}</span>
              <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded-full text-slate-500">{state.currentUser.role}</span>
            </div>
            <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center font-bold shadow-sm">
              {state.currentUser.username.charAt(0).toUpperCase()}
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">
            {renderContent()}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Plus, UserPlus, Trash2, Users } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>('الكل');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: 'رجال',
    role: 'لاعب'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  const filteredPeople = state.people.filter(p => 
    selectedCategory === 'الكل' ? true : p.category === selectedCategory
  );

  const handleAddPerson = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const newPerson: Person = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name,
      category: formData.category as Category,
      role: formData.role as Role,
      number: formData.number,
      phone: formData.phone,
      joinDate: new Date().toISOString().split('T')[0]
    };

    setState(prev => ({
      ...prev,
      people: [...prev.people, newPerson]
    }));
    setIsModalOpen(false);
    setFormData({ category: 'رجال', role: 'لاعب' });
  };

  const removePerson = (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({
        ...prev,
        people: prev.people.filter(p => p.id !== id)
      }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        {/* Category Filter Scrollable on Mobile */}
        <div className="overflow-x-auto pb-2 -mx-2 px-2 no-scrollbar">
          <div className="flex bg-white p-1 rounded-2xl shadow-sm border w-max">
            <button 
              onClick={() => setSelectedCategory('الكل')}
              className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'text-slate-600 hover:bg-slate-50'}`}
            >
              الكل
            </button>
            {categories.map(cat => (
              <button 
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'text-slate-600 hover:bg-slate-50'}`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <button 
          onClick={() => setIsModalOpen(true)}
          className="w-full lg:w-auto bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-xl shadow-orange-200"
        >
          <UserPlus size={20} />
          إضافة عضو جديد
        </button>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        {/* Horizontal scroll container for table */}
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[800px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-600 font-bold">الاسم</th>
                <th className="px-6 py-5 text-slate-600 font-bold">الفئة</th>
                <th className="px-6 py-5 text-slate-600 font-bold">الدور</th>
                <th className="px-6 py-5 text-slate-600 font-bold">رقم القميص</th>
                <th className="px-6 py-5 text-slate-600 font-bold">الهاتف</th>
                <th className="px-6 py-5 text-slate-600 font-bold text-center">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4 font-bold text-slate-800">{person.name}</td>
                  <td className="px-6 py-4">
                     <span className="px-3 py-1 bg-blue-50 text-blue-600 rounded-lg text-xs font-bold">{person.category}</span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-3 py-1 rounded-lg text-xs font-bold ${person.role === 'لاعب' ? 'bg-orange-50 text-orange-600' : 'bg-slate-100 text-slate-600'}`}>
                      {person.role}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-slate-500 font-mono">{person.number || '-'}</td>
                  <td className="px-6 py-4 text-slate-500">{person.phone || '-'}</td>
                  <td className="px-6 py-4 text-center">
                    <button 
                      onClick={() => removePerson(person.id)}
                      className="text-red-400 hover:text-red-600 p-2 hover:bg-red-50 rounded-xl transition-all"
                    >
                      <Trash2 size={20} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filteredPeople.length === 0 && (
            <div className="text-center py-24 bg-slate-50/50">
              <Users size={64} className="mx-auto text-slate-200 mb-4" />
              <p className="text-slate-400 font-bold text-lg">لا يوجد أعضاء في هذه الفئة حالياً</p>
            </div>
          )}
        </div>
      </div>

      {/* Modal Add Person - Optimized for Mobile */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-end sm:items-center justify-center z-[100] p-0 sm:p-4">
          <div className="bg-white rounded-t-[2rem] sm:rounded-[2rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in slide-in-from-bottom sm:zoom-in-95 duration-300">
            <div className="p-6 border-b flex items-center justify-between bg-slate-50">
              <h3 className="text-xl font-bold text-slate-800">إضافة عضو جديد</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800">
                <Plus className="rotate-45" size={20} />
              </button>
            </div>
            <form onSubmit={handleAddPerson} className="p-6 space-y-4 max-h-[80vh] overflow-y-auto">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="sm:col-span-2 space-y-1.5">
                  <label className="text-sm font-bold text-slate-700">الاسم الكامل</label>
                  <input 
                    required
                    type="text" 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="مثال: أحمد محمد علي"
                    onChange={e => setFormData({ ...formData, name: e.target.value })}
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-bold text-slate-700">الفئة</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 outline-none appearance-none"
                    value={formData.category}
                    onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                  >
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-bold text-slate-700">الدور</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 outline-none appearance-none"
                    value={formData.role}
                    onChange={e => setFormData({ ...formData, role: e.target.value as Role })}
                  >
                    {roles.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-bold text-slate-700">رقم القميص</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 outline-none"
                    placeholder="اختياري"
                    onChange={e => setFormData({ ...formData, number: parseInt(e.target.value) })}
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-bold text-slate-700">رقم الهاتف</label>
                  <input 
                    type="tel" 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 outline-none text-left"
                    placeholder="09XXXXXXXX"
                    onChange={e => setFormData({ ...formData, phone: e.target.value })}
                  />
                </div>
              </div>
              <div className="pt-6 flex flex-col sm:flex-row gap-3">
                <button 
                  type="submit" 
                  className="flex-1 bg-blue-600 text-white font-bold py-4 rounded-2xl hover:bg-blue-700 transition-all shadow-xl shadow-blue-200 order-1 sm:order-2"
                >
                  حفظ البيانات
                </button>
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 bg-slate-100 text-slate-600 font-bold py-4 rounded-2xl hover:bg-slate-200 transition-all order-2 sm:order-1"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState } from 'react';
import { ClipboardCheck, Save, FileText } from 'lucide-react';
import { AppState, Category, AttendanceRecord, AttendanceStatus } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category>('رجال');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [localRecords, setLocalRecords] = useState<Record<string, AttendanceStatus>>({});

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const players = state.people.filter(p => p.category === selectedCategory);

  const setStatus = (personId: string, status: AttendanceStatus) => {
    setLocalRecords(prev => ({ ...prev, [personId]: status }));
  };

  const saveAttendance = () => {
    const now = new Date();
    const time = `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`;

    const newRecords: AttendanceRecord[] = Object.entries(localRecords).map(([pid, status]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      date,
      time,
      status
    }));

    setState(prev => ({
      ...prev,
      attendance: [...prev.attendance, ...newRecords]
    }));

    alert('تم حفظ الحضور بنجاح!');
    setLocalRecords({});
  };

  const exportPDF = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 md:p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col xl:flex-row items-stretch xl:items-end justify-between gap-6 no-print">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 flex-1">
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-wider">اختيار الفئة</label>
            <select 
              value={selectedCategory}
              onChange={e => setSelectedCategory(e.target.value as Category)}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold appearance-none"
            >
              {categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-wider">التاريخ</label>
            <input 
              type="date" 
              value={date}
              onChange={e => setDate(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold"
            />
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <button 
            onClick={exportPDF}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-slate-100 text-slate-700 px-8 py-3.5 rounded-2xl font-bold hover:bg-slate-200 transition-all"
          >
            <FileText size={20} />
            تقرير PDF
          </button>
          <button 
            onClick={saveAttendance}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-blue-600 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-xl shadow-blue-200"
          >
            <Save size={20} />
            حفظ السجل
          </button>
        </div>
      </div>

      {/* Printing Header */}
      <div className="hidden print:block text-center mb-10 border-b-4 pb-6 border-blue-900">
        <h1 className="text-3xl font-black mb-2">نادي الكرامة الرياضي - مكتب كرة القدم</h1>
        <h2 className="text-xl font-bold text-slate-600">تقرير حضور وانصراف فئة ({selectedCategory})</h2>
        <p className="mt-3 font-bold text-blue-800">التاريخ: {date}</p>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[700px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-600 font-bold">الاسم</th>
                <th className="px-6 py-5 text-slate-600 font-bold">الدور</th>
                <th className="px-6 py-5 text-slate-600 font-bold text-center">تحديد الحالة</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {players.map(person => (
                <tr key={person.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4 font-bold text-slate-800">{person.name}</td>
                  <td className="px-6 py-4 text-slate-500 text-sm">{person.role}</td>
                  <td className="px-6 py-4">
                    <div className="flex justify-center gap-2 no-print">
                      {(['حاضر', 'متأخر', 'غائب'] as AttendanceStatus[]).map(status => (
                        <button
                          key={status}
                          onClick={() => setStatus(person.id, status)}
                          className={`min-w-[80px] px-4 py-2.5 rounded-xl text-xs font-black border transition-all ${
                            localRecords[person.id] === status
                            ? status === 'حاضر' ? 'bg-green-600 border-green-600 text-white shadow-lg shadow-green-100' :
                              status === 'متأخر' ? 'bg-orange-500 border-orange-500 text-white shadow-lg shadow-orange-100' :
                              'bg-red-600 border-red-600 text-white shadow-lg shadow-red-100'
                            : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'
                          }`}
                        >
                          {status}
                        </button>
                      ))}
                    </div>
                    {/* Status indicator for print */}
                    <div className="hidden print:block text-center font-bold">
                      {localRecords[person.id] || '---'}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {players.length === 0 && (
            <div className="text-center py-24 bg-slate-50/50">
              <ClipboardCheck size={64} className="mx-auto text-slate-200 mb-4" />
              <p className="text-slate-400 font-bold text-lg">لا توجد أسماء مضافة لهذه الفئة بعد</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AttendanceTracker;

