            <button 
              onClick={() => setSelectedCategory('الكل')}
              className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'text-slate-600 hover:bg-slate-50'}`}
            >
              الكل
            </button>
            {categories.map(cat => (
              <button 
                key={cat}
