                      <Trash2 size={20} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filteredPeople.length === 0 && (
            <div className="text-center py-24 bg-slate-50/50">
              <Users size={64} className="mx-auto text-slate-200 mb-4" />
              <p className="text-slate-400 font-bold text-lg">لا يوجد أعضاء في هذه الفئة حالياً</p>
            </div>
          )}
        </div>
      </div>

      {/* Modal Add Person - Optimized for Mobile */}
      {isModalOpen && (
