import React, { useState } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2 } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const TrainingPlanner: React.FC<TrainingPlannerProps> = ({ state, setState }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  const handleAddSession = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.location) return;

    const newSession: TrainingSession = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      date: formData.date,
      time: formData.time || '16:00',
      location: formData.location,
      objective: formData.objective || 'تدريب عام'
    };

    setState(prev => ({
      ...prev,
      sessions: [newSession, ...prev.sessions]
    }));
    setIsModalOpen(false);
  };

  const removeSession = (id: string) => {
    setState(prev => ({
      ...prev,
      sessions: prev.sessions.filter(s => s.id !== id)
    }));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-slate-600 font-bold">الجدول الزمني للتدريبات</h3>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-blue-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
        >
          <Plus size={20} />
          إضافة تمرين جديد
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {state.sessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative group overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-opacity">
              <button onClick={() => removeSession(session.id)} className="text-red-400 hover:text-red-600">
                <Trash2 size={20} />
              </button>
            </div>

            <div className="flex items-center gap-3 mb-4">
              <div className="bg-orange-50 text-orange-600 p-3 rounded-xl">
                <Calendar size={24} />
              </div>
              <div>
                <span className="bg-blue-50 text-blue-700 text-xs px-2 py-1 rounded-md font-bold">{session.category}</span>
                <h4 className="font-bold text-lg text-slate-800 mt-1">{session.objective}</h4>
              </div>
            </div>

            <div className="space-y-3 mt-4 pt-4 border-t border-slate-50 text-sm">
              <div className="flex items-center gap-2 text-slate-600">
                <MapPin size={16} className="text-slate-400" />
                <span className="font-medium">{session.location}</span>
              </div>
              <div className="flex items-center gap-2 text-slate-600">
                <Clock size={16} className="text-slate-400" />
                <span className="font-medium font-mono">{session.date} | {session.time}</span>
              </div>
            </div>
          </div>
        ))}

        {state.sessions.length === 0 && (
          <div className="col-span-full text-center py-20 bg-slate-100/50 rounded-2xl border-2 border-dashed border-slate-200">
            <Calendar size={48} className="mx-auto text-slate-300 mb-4" />
            <p className="text-slate-400 font-bold">لا يوجد تمارين مجدولة</p>
            <p className="text-xs text-slate-400">ابدأ بإضافة أول تمرين للفريق</p>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold">إضافة تمرين</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleAddSession} className="p-6 space-y-4">
              <div className="space-y-1">
                <label className="text-sm font-bold text-slate-700">الفئة المستهدفة</label>
                <select 
                  className="w-full bg-slate-100 rounded-xl p-3 outline-none text-slate-900 font-bold"
                  value={formData.category}
                  onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                >
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">التاريخ</label>
                  <input type="date" required className="w-full bg-slate-100 rounded-xl p-3 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">الوقت</label>
                  <input type="time" required className="w-full bg-slate-100 rounded-xl p-3 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-sm font-bold text-slate-700">المكان (الملعب)</label>
                <input type="text" required placeholder="مثال: الملعب الرئيسي" className="w-full bg-slate-100 rounded-xl p-3 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-sm font-bold text-slate-700">موضوع التمرين</label>
                <input type="text" placeholder="مثال: لياقة بدنية وتكتيك" className="w-full bg-slate-100 rounded-xl p-3 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, objective: e.target.value })} />
              </div>
              <button type="submit" className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl mt-4">جدولة التمرين</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

