interface LoginProps {
  onLogin: (user: AppUser) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();

    // Admin check (admin1 to admin10)
    const isAdmin = username.startsWith('admin') && parseInt(username.slice(5)) >= 1 && parseInt(username.slice(5)) <= 10;

    // Category check
    const categories = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
    const isCategoryUser = categories.includes(username);

    if (isAdmin && password === 'admin123') {
      onLogin({ id: `admin-${username.slice(5)}`, username, role: 'مدير' });
    } else if (isCategoryUser && password === 'KSC2025') {
      onLogin({ id: `cat-${username}`, username, role: 'مدرب' });
    } else {
      setError('خطأ في اسم المستخدم أو كلمة المرور.');
    }
  };

  const quickLogin = (type: 'admin' | 'cat', val: string) => {
    if (type === 'admin') {
      setUsername('admin1');
      setPassword('admin123');
      onLogin({ id: 'admin-1', username: 'admin1', role: 'مدير' });
    } else {
      setUsername(val);
      setPassword('KSC2025');
      onLogin({ id: `cat-${val}`, username: val, role: 'مدرب' });
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4 font-['Tajawal']" dir="rtl">
      <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-500 border border-slate-100">
        <div className="bg-gradient-to-br from-blue-900 to-blue-800 p-12 flex flex-col items-center relative overflow-hidden">
          <div className="absolute -top-12 -right-12 w-48 h-48 bg-orange-500/20 rounded-full blur-3xl"></div>
          <div className="absolute -bottom-12 -left-12 w-48 h-48 bg-blue-500/20 rounded-full blur-3xl"></div>

          <div className="bg-white/10 backdrop-blur-md p-6 rounded-[2rem] shadow-2xl mb-6 border border-white/20">
            <EagleLogo size={64} className="text-orange-500" />
          </div>
          <h1 className="text-2xl font-black text-white text-center tracking-tight">نادي الكرامة الرياضي</h1>
          <p className="text-blue-200 font-bold mt-1 text-sm">مكتب كرة القدم | نسخة 2025</p>
        </div>

        <div className="p-10 space-y-6">
          <div className="grid grid-cols-2 gap-3 mb-2">
            <button 
              onClick={() => quickLogin('admin', '')}
              className="flex items-center justify-center gap-2 bg-blue-50 text-blue-700 py-3.5 rounded-2xl text-xs font-black hover:bg-blue-100 transition-all border border-blue-100"
            >
              <ShieldCheck size={18} />
              دخول الإدارة
            </button>
            <div className="relative group">
               <button 
                className="w-full flex items-center justify-center gap-2 bg-orange-50 text-orange-700 py-3.5 rounded-2xl text-xs font-black hover:bg-orange-100 transition-all border border-orange-100"
              >
                <UserCircle size={18} />
                دخول الفئات
              </button>
              <div className="absolute bottom-full left-0 w-full mb-2 bg-white rounded-2xl shadow-xl border border-slate-100 p-2 opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none group-hover:pointer-events-auto">
                {['رجال', 'شباب', 'ناشئين', 'أشبال'].map(cat => (
                  <button 
                    key={cat}
                    onClick={() => quickLogin('cat', cat)}
                    className="w-full text-right px-4 py-2 hover:bg-orange-50 rounded-xl text-xs font-bold text-slate-700"
                  >
                    فئة {cat}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            {error && (
              <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-xs font-black text-center border border-red-100 animate-bounce">
                {error}
              </div>
            )}

            <div className="space-y-1.5">
              <label className="text-xs font-black text-slate-500 mr-1">اسم المستخدم</label>
              <div className="relative">
                <User className="absolute right-4 top-4 text-slate-400" size={20} />
                <input 
                  type="text" 
                  value={username}
                  onChange={e => setUsername(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 pr-12 pl-4 outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all font-bold text-slate-900"
                  placeholder="admin1 أو اسم الفئة"
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-black text-slate-500 mr-1">كلمة المرور</label>
              <div className="relative">
                <Lock className="absolute right-4 top-4 text-slate-400" size={20} />
                <input 
                  type="password" 
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 pr-12 pl-4 outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all font-bold text-slate-900"
                  placeholder="KSC2025"
                />
              </div>
            </div>

            <button 
              type="submit"
              className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl hover:bg-black transition-all shadow-2xl shadow-blue-200 active:scale-[0.98] mt-2 flex items-center justify-center gap-3 text-lg"
            >
              دخول للنظام
            </button>
