          <div className="text-center pt-2">
            <p className="text-[10px] text-slate-400 font-bold leading-relaxed italic">
              كلمة مرور الفئات الموحدة: KSC2025
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

