              <p className="text-slate-400 text-sm mt-1">تأكد من كتابة الاسم بشكل صحيح أو تغيير الفئة المختارة</p>
            </div>
          )}
        </div>
      </div>

      {/* Modal Add Person */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-end sm:items-center justify-center z-[100] p-0 sm:p-4">
          <div className="bg-white rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in slide-in-from-bottom sm:zoom-in-95 duration-300">
