              <h3 className="text-xl font-black text-slate-800">إضافة عضو جديد للفريق</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800 transition-colors">
                <X size={20} />
