                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الفئة</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 outline-none appearance-none text-slate-900 font-bold cursor-pointer"
                    value={formData.category}
                    onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                  >
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الدور الوظيفي</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 outline-none appearance-none text-slate-900 font-bold cursor-pointer"
                    value={formData.role}
                    onChange={e => setFormData({ ...formData, role: e.target.value as Role })}
