                    {roles.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">رقم القميص</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 outline-none text-slate-900 font-bold"
