                    type="tel" 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 outline-none text-left text-slate-900 font-bold"
                    placeholder="09XXXXXXXX"
                    onChange={e => setFormData({ ...formData, phone: e.target.value })}
                  />
                </div>
              </div>
              <div className="pt-8 flex flex-col sm:flex-row gap-4">
                <button 
                  type="submit" 
                  className="flex-1 bg-blue-900 text-white font-black py-4 rounded-2xl hover:bg-black transition-all shadow-xl shadow-blue-200 order-1 sm:order-2"
                >
                  حفظ البيانات
                </button>
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 bg-slate-100 text-slate-500 font-black py-4 rounded-2xl hover:bg-slate-200 transition-all order-2 sm:order-1"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

