  id: string;
  name: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  users: AppUser[];
  currentUser: AppUser | null;
}

