import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Users, Search, X } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const isReadOnly = currentUser?.role === 'مشاهد';
  const restrictedCat = currentUser?.restrictedCategory;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || 'رجال',
    role: 'لاعب'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  // Force restricted category if applicable
  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
      setFormData(prev => ({ ...prev, category: restrictedCat }));
    }
  }, [restrictedCat]);

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleAddPerson = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.name) return;

    const newPerson: Person = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name,
      category: formData.category as Category,
      role: formData.role as Role,
      number: formData.number,
      phone: formData.phone,
      joinDate: new Date().toISOString().split('T')[0]
    };

    setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    setIsModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال', role: 'لاعب' });
  };

  const removePerson = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({ ...prev, people: prev.people.filter(p => p.id !== id) }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 md:p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث عن لاعب بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900" />
            {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><X size={18} /></button>}
          </div>

          {!isReadOnly && (
            <button onClick={() => setIsModalOpen(true)}
              className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
              <UserPlus size={20} />إضافة عضو
            </button>
          )}
        </div>

        {!restrictedCat && (
          <div className="overflow-x-auto pb-2 -mx-2 px-2 no-scrollbar">
            <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max">
              <button onClick={() => setSelectedCategory('الكل')}
                className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}>الكل</button>
              {categories.map(cat => (
                <button key={cat} onClick={() => setSelectedCategory(cat)}
                  className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}>{cat}</button>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[800px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الاسم</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الفئة</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الدور</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">رقم القميص</th>
                {!isReadOnly && <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase text-center">الإجراءات</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4 font-bold text-slate-900">{person.name}</td>
                  <td className="px-6 py-4"><span className="px-3 py-1 bg-blue-50 text-blue-700 rounded-lg text-xs font-black">{person.category}</span></td>
                  <td className="px-6 py-4"><span className={`px-3 py-1 rounded-lg text-xs font-black ${person.role === 'لاعب' ? 'bg-orange-50 text-orange-700' : 'bg-slate-100 text-slate-600'}`}>{person.role}</span></td>
                  <td className="px-6 py-4 text-slate-900 font-mono font-black">{person.number || '-'}</td>
                  {!isReadOnly && (
