import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, FileText, History, Clock } from 'lucide-react';
import { AppState, Category, AttendanceRecord, AttendanceStatus } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

interface LocalRecord {
  status: AttendanceStatus;
  time: string;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isReadOnly = currentUser?.role === 'مشاهد';

  const [selectedCategory, setSelectedCategory] = useState<Category>(restrictedCat || 'رجال');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [localRecords, setLocalRecords] = useState<Record<string, LocalRecord>>({});
  const [showHistory, setShowHistory] = useState(isReadOnly); // Default to history for viewers

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setSelectedCategory(restrictedCat);
  }, [restrictedCat]);

  const players = state.people.filter(p => p.category === selectedCategory);
  const historicalRecords = state.attendance.filter(r => r.date === date && state.people.find(p => p.id === r.personId)?.category === selectedCategory);

  const setStatus = (personId: string, status: AttendanceStatus) => {
    if (isReadOnly) return;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    setLocalRecords(prev => ({ ...prev, [personId]: { status, time } }));
  };

  const saveAttendance = () => {
    if (isReadOnly) return;
    if (Object.keys(localRecords).length === 0) { alert('الرجاء تحديد حالة حضور واحدة على الأقل'); return; }

    const newRecords: AttendanceRecord[] = Object.entries(localRecords).map(([pid, record]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      date,
      time: record.time,
      status: record.status
    }));

    setState(prev => ({ ...prev, attendance: [...prev.attendance, ...newRecords] }));
    alert('تم حفظ الحضور بنجاح!');
    setLocalRecords({});
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 md:p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col xl:flex-row items-stretch xl:items-end justify-between gap-6 no-print">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 flex-1">
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-wider">اختيار الفئة</label>
            <select value={selectedCategory} disabled={!!restrictedCat}
              onChange={e => { setSelectedCategory(e.target.value as Category); setLocalRecords({}); }}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-slate-900 appearance-none disabled:opacity-70">
              {categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-wider">التاريخ</label>
            <input type="date" value={date} onChange={e => setDate(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-slate-900" />
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <button onClick={() => setShowHistory(!showHistory)}
            className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3.5 rounded-2xl font-bold transition-all border ${showHistory ? 'bg-orange-100 border-orange-200 text-orange-700' : 'bg-slate-50 border-slate-200 text-slate-600'}`}>
            <History size={20} />{showHistory ? 'الرجوع للتسجيل' : 'عرض السجلات'}
          </button>
          <button onClick={() => window.print()} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-slate-900 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-black transition-all shadow-lg">
            <FileText size={20} />تقرير PDF
          </button>
          {!showHistory && !isReadOnly && (
            <button onClick={saveAttendance} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-blue-600 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-xl shadow-blue-200">
              <Save size={20} />حفظ السجل
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[700px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-600 font-bold">الاسم</th>
                <th className="px-6 py-5 text-slate-600 font-bold text-center">الحالة والوقت</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {showHistory ? (
                historicalRecords.length > 0 ? historicalRecords.map(record => (
                  <tr key={record.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4 font-bold text-slate-900">{state.people.find(p => p.id === record.personId)?.name}</td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex items-center justify-center gap-3">
                        <span className={`px-4 py-1.5 rounded-xl text-xs font-black ${record.status === 'حاضر' ? 'bg-green-100 text-green-700' : record.status === 'متأخر' ? 'bg-orange-100 text-orange-700' : 'bg-red-100 text-red-700'}`}>{record.status}</span>
                        <span className="text-xs text-slate-400 font-mono flex items-center gap-1"><Clock size={12} /> {record.time}</span>
                      </div>
                    </td>
                  </tr>
                )) : <tr><td colSpan={2} className="text-center py-20 text-slate-400 italic">لا توجد سجلات محفوظة</td></tr>
              ) : (
                players.map(person => (
                  <tr key={person.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-bold text-slate-900">{person.name}</td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col items-center gap-2 no-print">
                        <div className="flex justify-center gap-2">
                          {(['حاضر', 'متأخر', 'غائب'] as AttendanceStatus[]).map(status => (
                            <button key={status} onClick={() => setStatus(person.id, status)} disabled={isReadOnly}
                              className={`min-w-[80px] px-4 py-2.5 rounded-xl text-xs font-black border transition-all ${localRecords[person.id]?.status === status ? (status === 'حاضر' ? 'bg-green-600 text-white' : status === 'متأخر' ? 'bg-orange-500 text-white' : 'bg-red-600 text-white') : 'bg-white text-slate-400'}`}>
                              {status}
                            </button>
                          ))}
                        </div>
                        {localRecords[person.id] && <div className="text-[10px] font-bold text-blue-600 flex items-center gap-1"><Clock size={10} /> {localRecords[person.id].time}</div>}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AttendanceTracker;

