import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Users, Search, X } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  // Coaches and Viewers are read-only for the squad list
  const isReadOnly = currentUser?.role === 'مشاهد' || currentUser?.role === 'مدرب';
  const restrictedCat = currentUser?.restrictedCategory;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || 'رجال',
    role: 'لاعب'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  // Force restricted category if applicable
  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
      setFormData(prev => ({ ...prev, category: restrictedCat }));
    }
  }, [restrictedCat]);

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleAddPerson = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.name) return;

    const newPerson: Person = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name,
      category: formData.category as Category,
      role: formData.role as Role,
      number: formData.number,
      phone: formData.phone,
      joinDate: new Date().toISOString().split('T')[0]
    };

    setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    setIsModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال', role: 'لاعب' });
  };

  const removePerson = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({ ...prev, people: prev.people.filter(p => p.id !== id) }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 md:p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث عن لاعب بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900" />
            {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><X size={18} /></button>}
          </div>

          {!isReadOnly && (
            <button onClick={() => setIsModalOpen(true)}
              className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
              <UserPlus size={20} />إضافة عضو
            </button>
          )}
        </div>

        {!restrictedCat && (
          <div className="overflow-x-auto pb-2 -mx-2 px-2 no-scrollbar">
            <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max">
              <button onClick={() => setSelectedCategory('الكل')}
                className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}>الكل</button>
              {categories.map(cat => (
                <button key={cat} onClick={() => setSelectedCategory(cat)}
                  className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}>{cat}</button>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[800px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الاسم</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الفئة</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الدور</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">رقم القميص</th>
                {!isReadOnly && <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase text-center">الإجراءات</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4 font-bold text-slate-900">{person.name}</td>
                  <td className="px-6 py-4"><span className="px-3 py-1 bg-blue-50 text-blue-700 rounded-lg text-xs font-black">{person.category}</span></td>
                  <td className="px-6 py-4"><span className={`px-3 py-1 rounded-lg text-xs font-black ${person.role === 'لاعب' ? 'bg-orange-50 text-orange-700' : 'bg-slate-100 text-slate-600'}`}>{person.role}</span></td>
                  <td className="px-6 py-4 text-slate-900 font-mono font-black">{person.number || '-'}</td>
                  {!isReadOnly && (
                    <td className="px-6 py-4 text-center">
                      <button onClick={() => removePerson(person.id)} className="text-slate-300 hover:text-red-600 p-2 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
          {filteredPeople.length === 0 && (
            <div className="text-center py-24 bg-slate-50/30">
              <Users size={64} className="mx-auto text-slate-200 mb-4" />
              <p className="text-slate-400 font-black text-lg">لم يتم العثور على أي نتائج</p>
            </div>
          )}
        </div>
      </div>

      {isModalOpen && !isReadOnly && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-end sm:items-center justify-center z-[100] p-0 sm:p-4">
          <div className="bg-white rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in slide-in-from-bottom duration-300">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50/50">
              <h3 className="text-xl font-black text-slate-800">إضافة عضو جديد</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><X size={20} /></button>
            </div>
            <form onSubmit={handleAddPerson} className="p-8 space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div className="sm:col-span-2 space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الاسم الكامل</label>
                  <input required type="text" onChange={e => setFormData({ ...formData, name: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-slate-900" placeholder="الاسم الكامل" />
                </div>
                {!restrictedCat && (
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">الفئة</label>
                    <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                )}
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الدور</label>
                  <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold" value={formData.role} onChange={e => setFormData({ ...formData, role: e.target.value as Role })}>
                    {roles.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
              </div>
              <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl shadow-xl mt-4">حفظ البيانات</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, FileText, History, Clock } from 'lucide-react';
import { AppState, Category, AttendanceRecord, AttendanceStatus } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

interface LocalRecord {
  status: AttendanceStatus;
  time: string;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // Managers can edit anything, Coaches can edit their own category
  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [selectedCategory, setSelectedCategory] = useState<Category>(restrictedCat || 'رجال');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [localRecords, setLocalRecords] = useState<Record<string, LocalRecord>>({});
  const [showHistory, setShowHistory] = useState(isReadOnly);

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setSelectedCategory(restrictedCat);
  }, [restrictedCat]);

  const players = state.people.filter(p => p.category === selectedCategory);
  const historicalRecords = state.attendance.filter(r => r.date === date && state.people.find(p => p.id === r.personId)?.category === selectedCategory);

  const setStatus = (personId: string, status: AttendanceStatus) => {
    if (isReadOnly) return;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    setLocalRecords(prev => ({ ...prev, [personId]: { status, time } }));
  };

  const saveAttendance = () => {
    if (isReadOnly) return;
    if (Object.keys(localRecords).length === 0) { alert('الرجاء تحديد حالة حضور واحدة على الأقل'); return; }

    const newRecords: AttendanceRecord[] = Object.entries(localRecords).map(([pid, record]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      date,
      time: record.time,
      status: record.status
    }));

    setState(prev => ({ ...prev, attendance: [...prev.attendance, ...newRecords] }));
    alert('تم حفظ الحضور بنجاح!');
    setLocalRecords({});
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 md:p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col xl:flex-row items-stretch xl:items-end justify-between gap-6 no-print">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 flex-1">
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-wider">اختيار الفئة</label>
            <select value={selectedCategory} disabled={!!restrictedCat}
              onChange={e => { setSelectedCategory(e.target.value as Category); setLocalRecords({}); }}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-slate-900 appearance-none disabled:opacity-70">
              {categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-wider">التاريخ</label>
            <input type="date" value={date} onChange={e => setDate(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-slate-900" />
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <button onClick={() => setShowHistory(!showHistory)}
            className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3.5 rounded-2xl font-bold transition-all border ${showHistory ? 'bg-orange-100 border-orange-200 text-orange-700' : 'bg-slate-50 border-slate-200 text-slate-600'}`}>
            <History size={20} />{showHistory ? 'الرجوع للتسجيل' : 'عرض السجلات'}
          </button>
          <button onClick={() => window.print()} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-slate-900 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-black transition-all shadow-lg">
            <FileText size={20} />تقرير PDF
          </button>
          {!showHistory && canEdit && (
            <button onClick={saveAttendance} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-blue-600 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-xl shadow-blue-200">
              <Save size={20} />حفظ السجل
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[700px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-600 font-bold">الاسم</th>
                <th className="px-6 py-5 text-slate-600 font-bold text-center">الحالة والوقت</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {showHistory ? (
                historicalRecords.length > 0 ? historicalRecords.map(record => (
                  <tr key={record.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4 font-bold text-slate-900">{state.people.find(p => p.id === record.personId)?.name}</td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex items-center justify-center gap-3">
                        <span className={`px-4 py-1.5 rounded-xl text-xs font-black ${record.status === 'حاضر' ? 'bg-green-100 text-green-700' : record.status === 'متأخر' ? 'bg-orange-100 text-orange-700' : 'bg-red-100 text-red-700'}`}>{record.status}</span>
                        <span className="text-xs text-slate-400 font-mono flex items-center gap-1"><Clock size={12} /> {record.time}</span>
                      </div>
                    </td>
                  </tr>
                )) : <tr><td colSpan={2} className="text-center py-20 text-slate-400 italic">لا توجد سجلات محفوظة</td></tr>
              ) : (
                players.map(person => (
                  <tr key={person.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 font-bold text-slate-900">{person.name}</td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col items-center gap-2 no-print">
                        <div className="flex justify-center gap-2">
                          {(['حاضر', 'متأخر', 'غائب'] as AttendanceStatus[]).map(status => (
                            <button key={status} onClick={() => setStatus(person.id, status)} disabled={isReadOnly}
                              className={`min-w-[80px] px-4 py-2.5 rounded-xl text-xs font-black border transition-all ${localRecords[person.id]?.status === status ? (status === 'حاضر' ? 'bg-green-600 text-white' : status === 'متأخر' ? 'bg-orange-500 text-white' : 'bg-red-600 text-white') : 'bg-white text-slate-400'}`}>
                              {status}
                            </button>
                          ))}
                        </div>
                        {localRecords[person.id] && <div className="text-[10px] font-bold text-blue-600 flex items-center gap-1"><Clock size={10} /> {localRecords[person.id].time}</div>}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AttendanceTracker;

import React, { useState, useEffect } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2 } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const TrainingPlanner: React.FC<TrainingPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // Managers can edit everything, Coaches can edit their own category
  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const handleAddSession = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.location) return;

    const newSession: TrainingSession = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      date: formData.date,
      time: formData.time || '16:00',
      location: formData.location,
      objective: formData.objective || 'تدريب عام'
    };

    setState(prev => ({
      ...prev,
      sessions: [newSession, ...prev.sessions]
    }));
    setIsModalOpen(false);
  };

  const removeSession = (id: string) => {
    if (isReadOnly) return;
    setState(prev => ({
      ...prev,
      sessions: prev.sessions.filter(s => s.id !== id)
    }));
  };

  // Only show relevant sessions for restricted coaches
  const filteredSessions = restrictedCat 
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `الجدول الزمني لتدريبات فئة ${restrictedCat}` : 'الجدول الزمني لكافة التدريبات'}
        </h3>
        {canEdit && (
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-blue-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
          >
            <Plus size={20} />
            إضافة تمرين جديد
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative group overflow-hidden">
            {!isReadOnly && (
              <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={() => removeSession(session.id)} className="text-red-400 hover:text-red-600">
                  <Trash2 size={20} />
                </button>
              </div>
            )}

            <div className="flex items-center gap-3 mb-4">
              <div className="bg-orange-50 text-orange-600 p-3 rounded-xl">
                <Calendar size={24} />
              </div>
              <div>
                <span className="bg-blue-50 text-blue-700 text-xs px-2 py-1 rounded-md font-bold">{session.category}</span>
                <h4 className="font-bold text-lg text-slate-800 mt-1">{session.objective}</h4>
              </div>
            </div>

            <div className="space-y-3 mt-4 pt-4 border-t border-slate-50 text-sm">
              <div className="flex items-center gap-2 text-slate-600">
                <MapPin size={16} className="text-slate-400" />
                <span className="font-medium">{session.location}</span>
              </div>
              <div className="flex items-center gap-2 text-slate-600">
                <Clock size={16} className="text-slate-400" />
                <span className="font-medium font-mono">{session.date} | {session.time}</span>
              </div>
            </div>
          </div>
        ))}

        {filteredSessions.length === 0 && (
          <div className="col-span-full text-center py-20 bg-slate-100/50 rounded-2xl border-2 border-dashed border-slate-200">
