import React, { useState, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, Trash2, Banknote, Calendar as CalendarIcon } from 'lucide-react';
import { AppState, Match, Category } from '../types';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Match>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.opponent || !formData.location) return;

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      opponent: formData.opponent,
      location: formData.location,
      advancePayment: formData.advancePayment || '0',
      date: formData.date,
      time: formData.time || '16:00'
    };

    setState(prev => ({
      ...prev,
      matches: [newMatch, ...prev.matches]
    }));
    setIsModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال' });
  };

  const removeMatch = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذه المباراة؟')) {
      setState(prev => ({
        ...prev,
        matches: prev.matches.filter(m => m.id !== id)
      }));
    }
  };

  const filteredMatches = restrictedCat 
    ? state.matches.filter(m => m.category === restrictedCat)
    : state.matches;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول مباريات فئة ${restrictedCat}` : 'جدول كافة مباريات النادي'}
        </h3>
        {canEdit && (
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-lg shadow-orange-200"
          >
            <Plus size={20} />
            إضافة مباراة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMatches.map(match => (
          <div key={match.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 relative group overflow-hidden hover:border-orange-200 transition-colors">
            {!isReadOnly && (
              <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-opacity no-print">
                <button onClick={() => removeMatch(match.id)} className="text-red-400 hover:text-red-600">
                  <Trash2 size={20} />
                </button>
              </div>
            )}

            <div className="flex items-center gap-3 mb-4">
              <div className="bg-orange-50 text-orange-600 p-3 rounded-2xl">
                <Trophy size={24} />
              </div>
              <div>
                <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-0.5 rounded-lg font-black uppercase">{match.category}</span>
                <h4 className="font-black text-lg text-slate-800 mt-1">ضد: {match.opponent}</h4>
              </div>
            </div>

            <div className="space-y-3 mt-4 pt-4 border-t border-slate-50">
              <div className="flex items-center gap-2 text-slate-600 text-sm">
                <MapPin size={16} className="text-slate-400" />
                <span className="font-bold">{match.location}</span>
              </div>
              <div className="flex items-center gap-2 text-slate-600 text-sm">
                <CalendarIcon size={16} className="text-slate-400" />
                <span className="font-bold font-mono">{match.date} | {match.time}</span>
              </div>
              <div className="flex items-center gap-2 text-emerald-600 text-sm bg-emerald-50 p-2 rounded-xl border border-emerald-100 mt-2">
                <Banknote size={18} />
                <span className="font-black">السلفة: {match.advancePayment} ل.س</span>
              </div>
            </div>
          </div>
        ))}

        {filteredMatches.length === 0 && (
          <div className="col-span-full text-center py-24 bg-slate-50 rounded-[2.5rem] border-2 border-dashed border-slate-200">
            <Trophy size={64} className="mx-auto text-slate-200 mb-4" />
            <p className="text-slate-400 font-black text-lg">لا توجد مباريات مجدولة حالياً</p>
          </div>
        )}
      </div>

      {isModalOpen && !isReadOnly && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">إضافة مباراة جديدة</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleAddMatch} className="p-8 space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الفئة</label>
                  <select 
                    className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold disabled:opacity-70"
                    value={formData.category}
                    disabled={!!restrictedCat}
