              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">التاريخ</label>
                  <input type="date" required className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الوقت</label>
                  <input type="time" required className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-1">السلفة المالية (ل.س)</label>
                <div className="relative">
                  <Banknote className="absolute right-4 top-4 text-slate-400" size={20} />
                  <input type="text" placeholder="0" className="w-full bg-slate-100 rounded-2xl py-4 pr-12 pl-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, advancePayment: e.target.value })} />
                </div>
              </div>

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl shadow-xl mt-4">حفظ المباراة</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

