export default Login;

import React, { useState, useEffect } from 'react';
import { 
  Users, 
  Calendar, 
  ClipboardCheck, 
  LayoutDashboard, 
  Settings, 
  LogOut, 
  Menu,
  X,
  Trophy
} from 'lucide-react';
import { 
  AppUser, 
  AppState,
  Category 
} from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_data');
    if (saved) {
      const parsed = JSON.parse(saved);
      // Ensure matches exist in legacy data
      if (!parsed.matches) parsed.matches = [];
      return parsed;
    }

    const admins = Array.from({ length: 10 }, (_, i) => ({
      id: `admin-${i + 1}`,
      username: `admin${i + 1}`,
      role: 'مدير' as const
    }));

    const categoryUsers: AppUser[] = [
      { id: 'u-men', username: 'Men', role: 'مدرب', restrictedCategory: 'رجال' },
      { id: 'u-u18', username: 'U18', role: 'مدرب', restrictedCategory: 'شباب' },
      { id: 'u-u16', username: 'U16', role: 'مدرب', restrictedCategory: 'ناشئين' },
      { id: 'u-u14', username: 'U14', role: 'مدرب', restrictedCategory: 'أشبال' }
    ];

    return {
      people: [],
      attendance: [],
      sessions: [],
      matches: [],
      users: [...admins, ...categoryUsers],
      currentUser: null
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('alkaramah_data', JSON.stringify(state));
  }, [state]);

  const handleLogin = (user: AppUser) => {
    setState(prev => ({ ...prev, currentUser: user }));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} />;
      case 'squad': return <SquadManagement state={state} setState={setState} />;
      case 'attendance': return <AttendanceTracker state={state} setState={setState} />;
      case 'training': return <TrainingPlanner state={state} setState={setState} />;
      case 'matches': return <MatchPlanner state={state} setState={setState} />;
      case 'settings': return <SettingsView state={state} setState={setState} />;
      default: return <Dashboard state={state} />;
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'الفئات واللاعبين', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'جدول التمارين', icon: Calendar },
    { id: 'matches', label: 'جدول المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings, adminOnly: true },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-['Tajawal'] text-right" dir="rtl">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-blue-900 text-white transition-transform duration-300 transform md:relative md:translate-x-0 md:w-64 flex flex-col no-print ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex items-center justify-between border-b border-blue-800/50">
          <div className="flex items-center gap-3">
            <div className="bg-white p-1 rounded-xl shadow-lg">
              <ClubLogo size={42} />
            </div>
            <div className="overflow-hidden whitespace-nowrap">
              <h1 className="font-black text-lg leading-tight">نادي الكرامة</h1>
              <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">مكتب كرة القدم</p>
            </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="md:hidden text-blue-200"><X size={24} /></button>
        </div>

        <nav className="flex-1 mt-6 px-4 space-y-2 overflow-y-auto">
          {menuItems.map((item) => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/40' : 'hover:bg-blue-800 text-blue-100'}`}>
                <Icon size={22} /><span className="font-bold">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-6 border-t border-blue-800">
          <button onClick={handleLogout} className="w-full flex items-center gap-4 p-4 rounded-2xl text-red-300 hover:bg-red-900/30 transition-all font-bold">
            <LogOut size={22} /><span>تسجيل الخروج</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden w-full">
        <header className="bg-white border-b px-4 md:px-8 py-4 flex items-center justify-between no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="p-2 hover:bg-slate-100 rounded-xl text-slate-600 md:hidden"><Menu size={24} /></button>
            <h2 className="text-lg md:text-xl font-black text-slate-800 truncate">{menuItems.find(m => m.id === activeTab)?.label}</h2>
          </div>
          <div className="flex items-center gap-3">
            <div className="hidden sm:flex flex-col text-left items-end">
              <span className="font-black text-sm text-slate-700">{state.currentUser?.username}</span>
              <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded-full text-slate-500 font-bold">{state.currentUser?.role} {state.currentUser?.restrictedCategory ? `(${state.currentUser.restrictedCategory})` : ''}</span>
            </div>
            <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center font-black shadow-sm border border-orange-200 uppercase">{state.currentUser?.username?.charAt(0)}</div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">{renderContent()}</div>
        </section>
      </main>
    </div>
  );
};

export default App;

export type Category = 'رجال' | 'شباب' | 'ناشئين' | 'أشبال';
export type Role = 'لاعب' | 'مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب' | 'مشاهد';

export interface Person {
  id: string;
  name: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface Match {
  id: string;
  category: Category;
  opponent: string;
  location: string;
  advancePayment: string;
  date: string;
  time: string;
  // تفاصيل بعد المباراة
  isCompleted?: boolean;
  score?: string; // مثال: "2 - 1"
  scorers?: string;
  cards?: string;
  lineup?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  currentUser: AppUser | null;
}

import React, { useState, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, Trash2, Banknote, Calendar as CalendarIcon, Edit3, ClipboardList, Target, AlertTriangle } from 'lucide-react';
import { AppState, Match, Category } from '../types';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);

  const [formData, setFormData] = useState<Partial<Match>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.opponent || !formData.location) return;

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      opponent: formData.opponent,
      location: formData.location,
      advancePayment: formData.advancePayment || '0',
      date: formData.date,
      time: formData.time || '16:00',
      isCompleted: false
    };

    setState(prev => ({
      ...prev,
      matches: [newMatch, ...prev.matches]
    }));
    setIsAddModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال' });
  };

  const handleUpdateResult = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMatch || isReadOnly) return;

    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === selectedMatch.id ? { ...selectedMatch, isCompleted: true } : m)
    }));
    setIsResultModalOpen(false);
    setSelectedMatch(null);
  };

  const removeMatch = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذه المباراة؟')) {
      setState(prev => ({
        ...prev,
        matches: prev.matches.filter(m => m.id !== id)
      }));
    }
  };

  const openResultModal = (match: Match) => {
    setSelectedMatch({ ...match });
    setIsResultModalOpen(true);
  };

  const filteredMatches = restrictedCat 
    ? state.matches.filter(m => m.category === restrictedCat)
    : state.matches;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول مباريات فئة ${restrictedCat}` : 'جدول كافة مباريات النادي'}
        </h3>
        {canEdit && (
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-lg shadow-orange-200"
          >
            <Plus size={20} />
            إضافة مباراة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6">
        {filteredMatches.map(match => (
          <div key={match.id} className={`bg-white rounded-[2.5rem] shadow-sm border ${match.isCompleted ? 'border-emerald-100' : 'border-slate-100'} relative group overflow-hidden transition-all hover:shadow-md`}>
            {/* Header Badge */}
            <div className={`absolute top-6 left-6 px-4 py-1.5 rounded-full text-[10px] font-black uppercase ${match.isCompleted ? 'bg-emerald-100 text-emerald-700' : 'bg-blue-100 text-blue-700'}`}>
              {match.isCompleted ? 'مباراة منتهية' : 'مباراة قادمة'}
            </div>

            <div className="p-8">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
                <div className="flex items-center gap-4">
                  <div className={`p-4 rounded-[1.5rem] ${match.isCompleted ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
                    <Trophy size={32} />
                  </div>
                  <div>
                    <span className="text-xs font-black text-slate-400 uppercase tracking-widest">{match.category}</span>
                    <h4 className="font-black text-2xl text-slate-800">نادي الكرامة <span className="text-orange-500 mx-2">VS</span> {match.opponent}</h4>
                  </div>
                </div>

                {match.isCompleted && (
                  <div className="bg-slate-900 text-white px-8 py-4 rounded-3xl flex items-center gap-4 shadow-xl">
                    <span className="text-3xl font-black">{match.score || '0 - 0'}</span>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-6 border-t border-slate-50">
                <div className="space-y-3">
                  <div className="flex items-center gap-3 text-slate-600">
                    <MapPin size={18} className="text-slate-400" />
                    <span className="font-bold">{match.location}</span>
                  </div>
                  <div className="flex items-center gap-3 text-slate-600">
                    <CalendarIcon size={18} className="text-slate-400" />
                    <span className="font-bold">{match.date}</span>
                  </div>
                  <div className="flex items-center gap-3 text-slate-600">
                    <Clock size={18} className="text-slate-400" />
                    <span className="font-bold">{match.time}</span>
                  </div>
                </div>

                <div className="space-y-3">
                  <div className="bg-emerald-50 p-3 rounded-2xl flex items-center justify-between">
                    <div className="flex items-center gap-2 text-emerald-700">
                      <Banknote size={18} />
                      <span className="text-xs font-black">السلفة المالية:</span>
                    </div>
                    <span className="font-black text-emerald-800">{match.advancePayment} ل.س</span>
                  </div>

                  {!isReadOnly && (
                    <div className="flex gap-2 no-print">
                      <button 
                        onClick={() => openResultModal(match)}
                        className="flex-1 bg-slate-100 text-slate-700 py-3 rounded-2xl font-black text-xs hover:bg-slate-200 transition-all flex items-center justify-center gap-2"
                      >
                        <Edit3 size={16} /> {match.isCompleted ? 'تعديل النتيجة' : 'تسجيل النتيجة'}
                      </button>
                      <button 
                        onClick={() => removeMatch(match.id)}
                        className="bg-red-50 text-red-600 p-3 rounded-2xl hover:bg-red-100 transition-all"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  )}
                </div>
              </div>

              {/* Match Details Section (If Completed) */}
              {match.isCompleted && (
                <div className="mt-8 grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-top-4 duration-500">
                  <div className="bg-slate-50 p-5 rounded-3xl border border-slate-100">
                    <h5 className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase mb-3"><Target size={14} className="text-orange-500" /> الهدافون</h5>
                    <p className="text-sm font-bold text-slate-700">{match.scorers || 'لا يوجد'}</p>
                  </div>
                  <div className="bg-slate-50 p-5 rounded-3xl border border-slate-100">
                    <h5 className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase mb-3"><AlertTriangle size={14} className="text-yellow-500" /> البطاقات</h5>
                    <p className="text-sm font-bold text-slate-700">{match.cards || 'لا يوجد'}</p>
                  </div>
                  <div className="bg-slate-50 p-5 rounded-3xl border border-slate-100">
                    <h5 className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase mb-3"><ClipboardList size={14} className="text-blue-500" /> التشكيلة</h5>
                    <p className="text-sm font-bold text-slate-700 line-clamp-2">{match.lineup || 'غير محددة'}</p>
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {filteredMatches.length === 0 && (
          <div className="col-span-full text-center py-32 bg-slate-50 rounded-[3.5rem] border-2 border-dashed border-slate-200">
            <Trophy size={80} className="mx-auto text-slate-200 mb-4" />
            <p className="text-slate-400 font-black text-xl">بانتظار جدول المباريات الجديد...</p>
          </div>
        )}
      </div>

      {/* Modal: Add Match */}
      {isAddModalOpen && !isReadOnly && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">إضافة مباراة جديدة</h3>
              <button onClick={() => setIsAddModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleAddMatch} className="p-8 space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الفئة</label>
                  <select 
                    className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold disabled:opacity-70"
                    value={formData.category}
                    disabled={!!restrictedCat}
                    onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                  >
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الفريق المنافس</label>
                  <input type="text" required placeholder="اسم النادي الآخر" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, opponent: e.target.value })} />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-1">مكان المباراة (الملعب)</label>
                <input type="text" required placeholder="مثال: ملعب نادي الكرامة" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">التاريخ</label>
                  <input type="date" required className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الوقت</label>
                  <input type="time" required className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-1">السلفة المالية (ل.س)</label>
                <input type="text" placeholder="0" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, advancePayment: e.target.value })} />
              </div>

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-[1.5rem] shadow-xl mt-4">حفظ المباراة</button>
            </form>
          </div>
        </div>
      )}

      {/* Modal: Record Result */}
      {isResultModalOpen && selectedMatch && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md flex items-center justify-center z-[110] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3.5rem] w-full max-w-2xl shadow-2xl overflow-hidden my-auto">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black text-slate-800">تسجيل تفاصيل المباراة</h3>
                <p className="text-xs text-slate-500 font-bold mt-1">ضد نادي {selectedMatch.opponent}</p>
              </div>
              <button onClick={() => setIsResultModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleUpdateResult} className="p-10 space-y-6">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 mr-1 uppercase">النتيجة النهائية (نادي الكرامة - الخصم)</label>
                <div className="flex items-center gap-4">
                  <input 
                    type="text" 
                    placeholder="2 - 1" 
                    className="w-full bg-slate-100 rounded-[1.5rem] p-5 text-center text-2xl font-black outline-none border-2 border-transparent focus:border-blue-500 transition-all"
                    value={selectedMatch.score || ''}
                    onChange={e => setSelectedMatch({ ...selectedMatch, score: e.target.value })}
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 mr-1 flex items-center gap-2"><Target size={14} className="text-orange-500" /> من سجل الأهداف</label>
                  <textarea 
                    rows={3}
                    placeholder="مثال: أحمد (2), محمد (1)" 
                    className="w-full bg-slate-50 rounded-2xl p-4 outline-none font-bold text-slate-900 border border-slate-100 resize-none"
                    value={selectedMatch.scorers || ''}
                    onChange={e => setSelectedMatch({ ...selectedMatch, scorers: e.target.value })}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 mr-1 flex items-center gap-2"><AlertTriangle size={14} className="text-yellow-500" /> البطاقات</label>
                  <textarea 
                    rows={3}
                    placeholder="مثال: بطاقة صفراء لخالد د.30" 
                    className="w-full bg-slate-50 rounded-2xl p-4 outline-none font-bold text-slate-900 border border-slate-100 resize-none"
                    value={selectedMatch.cards || ''}
                    onChange={e => setSelectedMatch({ ...selectedMatch, cards: e.target.value })}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 mr-1 flex items-center gap-2"><ClipboardList size={14} className="text-blue-500" /> التشكيلة التي شاركت</label>
                <textarea 
                  rows={4}
                  placeholder="أسماء اللاعبين الأساسيين والبدلاء..." 
                  className="w-full bg-slate-50 rounded-[1.5rem] p-5 outline-none font-bold text-slate-900 border border-slate-100"
                  value={selectedMatch.lineup || ''}
                  onChange={e => setSelectedMatch({ ...selectedMatch, lineup: e.target.value })}
                />
              </div>

              <div className="flex gap-4 pt-4">
                <button type="submit" className="flex-1 bg-emerald-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all">حفظ البيانات وإنهاء المباراة</button>
                <button type="button" onClick={() => setIsResultModalOpen(false)} className="flex-1 bg-slate-100 text-slate-600 font-black py-4 rounded-2xl hover:bg-slate-200 transition-all">إلغاء</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

export type Category = 'رجال' | 'شباب' | 'ناشئين' | 'أشبال';
export type Role = 'لاعب' | 'مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب' | 'مشاهد';

export interface Person {
  id: string;
  name: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface MatchLineup {
  starters: string[];
  subs: string[];
  captain: string;
  substitutions: string;
}

export interface Match {
  id: string;
  category: Category;
  opponent: string;
  location: string;
  advancePayment: string;
  date: string;
  time: string;
  isCompleted?: boolean;
  ourScore?: string;
  opponentScore?: string;
  scorers?: string;
  cards?: string;
  lineupDetails?: MatchLineup;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  currentUser: AppUser | null;
}

import React, { useState, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, Trash2, Banknote, Calendar as CalendarIcon, Edit3, ClipboardList, Target, AlertTriangle, User, UserCheck } from 'lucide-react';
import { AppState, Match, Category, MatchLineup } from '../types';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);

  const [formData, setFormData] = useState<Partial<Match>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.opponent || !formData.location) return;

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      opponent: formData.opponent,
      location: formData.location,
      advancePayment: formData.advancePayment || '0',
      date: formData.date,
      time: formData.time || '16:00',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      lineupDetails: {
        starters: Array(11).fill(''),
        subs: Array(11).fill(''),
        captain: '',
        substitutions: ''
      }
    };

    setState(prev => ({
      ...prev,
      matches: [newMatch, ...prev.matches]
    }));
    setIsAddModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال' });
  };

  const handleUpdateResult = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMatch || isReadOnly) return;

    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === selectedMatch.id ? { ...selectedMatch, isCompleted: true } : m)
    }));
    setIsResultModalOpen(false);
    setSelectedMatch(null);
  };

  const removeMatch = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذه المباراة؟')) {
      setState(prev => ({
        ...prev,
        matches: prev.matches.filter(m => m.id !== id)
      }));
    }
  };

  const openResultModal = (match: Match) => {
    const defaultLineup: MatchLineup = match.lineupDetails || {
      starters: Array(11).fill(''),
      subs: Array(11).fill(''),
      captain: '',
      substitutions: ''
    };
    setSelectedMatch({ ...match, lineupDetails: defaultLineup });
    setIsResultModalOpen(true);
  };

  const updateLineup = (type: 'starters' | 'subs', index: number, value: string) => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const newLineup = { ...selectedMatch.lineupDetails };
    newLineup[type][index] = value;
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const filteredMatches = restrictedCat 
    ? state.matches.filter(m => m.category === restrictedCat)
    : state.matches;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول مباريات فئة ${restrictedCat}` : 'جدول كافة مباريات النادي'}
        </h3>
        {canEdit && (
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-lg shadow-orange-200"
          >
            <Plus size={20} />
            إضافة مباراة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8">
        {filteredMatches.map(match => (
          <div key={match.id} className={`bg-white rounded-[3rem] shadow-sm border ${match.isCompleted ? 'border-emerald-100' : 'border-slate-100'} overflow-hidden transition-all hover:shadow-xl`}>
            {/* Header Badge */}
            <div className={`px-8 py-3 flex justify-between items-center ${match.isCompleted ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-700'}`}>
              <span className="text-xs font-black uppercase tracking-widest">{match.category}</span>
              <span className="text-[10px] font-black uppercase">{match.isCompleted ? 'مباراة منتهية' : 'مباراة قادمة'}</span>
            </div>

            <div className="p-8">
              {/* Score Dashboard */}
              <div className="flex flex-col md:flex-row items-center justify-between gap-12 mb-12">
                {/* Our Team */}
                <div className="flex-1 text-center">
                  <div className="w-20 h-20 bg-blue-900 rounded-[2rem] flex items-center justify-center mx-auto mb-4 shadow-lg">
                    <Trophy className="text-white" size={32} />
                  </div>
                  <h4 className="font-black text-xl text-slate-800">نادي الكرامة</h4>
                  {match.isCompleted && (
                    <div className="mt-2 text-5xl font-black text-blue-900">{match.ourScore}</div>
                  )}
                </div>

                {/* VS Separator */}
                <div className="flex flex-col items-center">
                  <div className="text-orange-500 font-black text-2xl mb-2">VS</div>
                  <div className="h-12 w-px bg-slate-100"></div>
                </div>

                {/* Opponent Team */}
                <div className="flex-1 text-center">
                  <div className="w-20 h-20 bg-slate-100 rounded-[2rem] flex items-center justify-center mx-auto mb-4 border border-slate-200">
                    <Trophy className="text-slate-400" size={32} />
                  </div>
                  <h4 className="font-black text-xl text-slate-800">{match.opponent}</h4>
                  {match.isCompleted && (
                    <div className="mt-2 text-5xl font-black text-slate-400">{match.opponentScore}</div>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-8 border-t border-slate-50">
                <div className="space-y-4">
                  <div className="flex items-center gap-4 text-slate-600">
                    <MapPin size={20} className="text-orange-500" />
                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase">الموقع</p>
                      <span className="font-bold">{match.location}</span>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 text-slate-600">
                    <CalendarIcon size={20} className="text-blue-500" />
                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase">التاريخ والوقت</p>
                      <span className="font-bold">{match.date} | {match.time}</span>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="bg-emerald-50 p-4 rounded-3xl flex items-center justify-between border border-emerald-100">
                    <div className="flex items-center gap-3 text-emerald-700">
                      <Banknote size={24} />
                      <span className="text-xs font-black">السلفة المالية:</span>
                    </div>
                    <span className="text-lg font-black text-emerald-800">{match.advancePayment} ل.س</span>
                  </div>

                  {!isReadOnly && (
                    <div className="flex gap-3 no-print">
                      <button 
                        onClick={() => openResultModal(match)}
                        className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black text-sm hover:bg-black transition-all flex items-center justify-center gap-2 shadow-lg"
                      >
                        <Edit3 size={18} /> {match.isCompleted ? 'تعديل النتيجة والتشكيلة' : 'تسجيل النتيجة والتشكيلة'}
                      </button>
                      <button 
                        onClick={() => removeMatch(match.id)}
                        className="bg-red-50 text-red-600 px-6 rounded-2xl hover:bg-red-100 transition-all border border-red-100"
                      >
                        <Trash2 size={20} />
                      </button>
                    </div>
                  )}
                </div>
              </div>

              {/* Advanced Match Details Section (If Completed) */}
              {match.isCompleted && (
                <div className="mt-12 space-y-8 animate-in fade-in slide-in-from-top-4 duration-500">
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="bg-orange-50 p-6 rounded-[2rem] border border-orange-100">
                        <h5 className="flex items-center gap-2 text-xs font-black text-orange-700 uppercase mb-4"><Target size={16} /> الهدافون</h5>
                        <p className="text-sm font-bold text-slate-800 leading-relaxed">{match.scorers || 'لم يتم تسجيل أهداف'}</p>
                      </div>
                      <div className="bg-yellow-50 p-6 rounded-[2rem] border border-yellow-100">
                        <h5 className="flex items-center gap-2 text-xs font-black text-yellow-700 uppercase mb-4"><AlertTriangle size={16} /> البطاقات</h5>
                        <p className="text-sm font-bold text-slate-800 leading-relaxed">{match.cards || 'لا يوجد بطاقات'}</p>
                      </div>
                   </div>

                   {match.lineupDetails && (
                     <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100">
                        <div className="flex items-center justify-between mb-8">
                           <h5 className="flex items-center gap-3 text-lg font-black text-slate-800"><ClipboardList size={24} className="text-blue-600" /> تشكيلة المباراة</h5>
                           <div className="flex items-center gap-2 bg-white px-4 py-2 rounded-xl border border-slate-200">
                              <UserCheck size={16} className="text-blue-600" />
                              <span className="text-xs font-black text-slate-600">الكابتن: {match.lineupDetails.captain || 'غير محدد'}</span>
                           </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                           {/* Starters Table */}
                           <div>
                              <div className="bg-blue-900 text-white px-5 py-3 rounded-t-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2">
                                 <div className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse"></div>
                                 التشكيلة الأساسية (11)
                              </div>
                              <div className="bg-white border-x border-b border-slate-200 rounded-b-2xl overflow-hidden shadow-sm">
                                 <table className="w-full text-right text-sm">
                                    <tbody>
                                       {match.lineupDetails.starters.map((player, idx) => (
                                          <tr key={idx} className={idx % 2 === 0 ? 'bg-slate-50/50' : 'bg-white'}>
                                             <td className="px-5 py-3 border-l border-slate-100 w-12 text-slate-400 font-mono font-black">{idx + 1}</td>
                                             <td className="px-5 py-3 font-bold text-slate-800">{player || '-'}</td>
                                          </tr>
                                       ))}
                                    </tbody>
                                 </table>
                              </div>
                           </div>

                           {/* Subs Table */}
                           <div>
                              <div className="bg-slate-800 text-white px-5 py-3 rounded-t-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2">
                                 <div className="w-2 h-2 bg-orange-400 rounded-full"></div>
                                 دكة الاحتياط (11)
                              </div>
                              <div className="bg-white border-x border-b border-slate-200 rounded-b-2xl overflow-hidden shadow-sm">
                                 <table className="w-full text-right text-sm">
                                    <tbody>
                                       {match.lineupDetails.subs.map((player, idx) => (
                                          <tr key={idx} className={idx % 2 === 0 ? 'bg-slate-50/50' : 'bg-white'}>
                                             <td className="px-5 py-3 border-l border-slate-100 w-12 text-slate-400 font-mono font-black">{idx + 12}</td>
                                             <td className="px-5 py-3 font-bold text-slate-800">{player || '-'}</td>
                                          </tr>
                                       ))}
                                    </tbody>
                                 </table>
                              </div>

                              <div className="mt-6 bg-white p-5 rounded-3xl border border-slate-200 shadow-sm">
                                 <h6 className="text-[10px] font-black text-slate-400 uppercase mb-2">التبديلات التي حدثت</h6>
                                 <p className="text-sm font-bold text-slate-700 italic">{match.lineupDetails.substitutions || 'لم يتم تسجيل تبديلات'}</p>
                              </div>
                           </div>
                        </div>
                     </div>
                   )}
                </div>
              )}
            </div>
          </div>
        ))}

        {filteredMatches.length === 0 && (
          <div className="text-center py-40 bg-slate-50 rounded-[4rem] border-2 border-dashed border-slate-200">
            <Trophy size={100} className="mx-auto text-slate-100 mb-6" />
            <p className="text-slate-400 font-black text-2xl">بانتظار انطلاق صافرة البداية...</p>
          </div>
        )}
      </div>

      {/* Modal: Add Match */}
      {isAddModalOpen && !isReadOnly && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">إضافة مباراة جديدة</h3>
              <button onClick={() => setIsAddModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleAddMatch} className="p-8 space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الفئة</label>
                  <select 
                    className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold disabled:opacity-70"
                    value={formData.category}
                    disabled={!!restrictedCat}
                    onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                  >
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الفريق المنافس</label>
                  <input type="text" required placeholder="اسم النادي الآخر" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, opponent: e.target.value })} />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-1">مكان المباراة (الملعب)</label>
                <input type="text" required placeholder="مثال: ملعب نادي الكرامة" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">التاريخ</label>
                  <input type="date" required className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الوقت</label>
                  <input type="time" required className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-1">السلفة المالية (ل.س)</label>
                <input type="text" placeholder="0" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, advancePayment: e.target.value })} />
              </div>

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-[1.5rem] shadow-xl mt-4">حفظ المباراة</button>
            </form>
          </div>
        </div>
      )}

      {/* Modal: Record Result & Lineup */}
      {isResultModalOpen && selectedMatch && selectedMatch.lineupDetails && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[110] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3.5rem] w-full max-w-5xl shadow-2xl overflow-hidden my-auto max-h-[90vh] flex flex-col">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center shrink-0">
              <div>
                <h3 className="text-xl font-black text-slate-800">تقرير المباراة والتشكيلة</h3>
                <p className="text-xs text-slate-500 font-bold mt-1">ضد نادي {selectedMatch.opponent} - فئة {selectedMatch.category}</p>
              </div>
              <button onClick={() => setIsResultModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800 transition-transform hover:rotate-90"><Plus className="rotate-45" /></button>
            </div>

            <form onSubmit={handleUpdateResult} className="flex-1 overflow-y-auto p-10 space-y-12">
              {/* Scores Section */}
              <div className="space-y-6">
                <h4 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100 pb-2">النتيجة النهائية</h4>
                <div className="grid grid-cols-2 gap-8">
                  <div className="space-y-2 text-center">
                    <label className="text-xs font-black text-blue-900 block">نادي الكرامة</label>
                    <input 
                      type="number" 
                      placeholder="0" 
                      className="w-full bg-blue-50 rounded-[2rem] p-6 text-center text-4xl font-black outline-none border-4 border-transparent focus:border-blue-900 transition-all text-blue-900"
                      value={selectedMatch.ourScore || '0'}
                      onChange={e => setSelectedMatch({ ...selectedMatch, ourScore: e.target.value })}
                    />
                  </div>
                  <div className="space-y-2 text-center">
                    <label className="text-xs font-black text-slate-500 block">{selectedMatch.opponent}</label>
                    <input 
                      type="number" 
                      placeholder="0" 
                      className="w-full bg-slate-50 rounded-[2rem] p-6 text-center text-4xl font-black outline-none border-4 border-transparent focus:border-slate-300 transition-all text-slate-600"
                      value={selectedMatch.opponentScore || '0'}
                      onChange={e => setSelectedMatch({ ...selectedMatch, opponentScore: e.target.value })}
                    />
                  </div>
                </div>
              </div>

              {/* Lineup Section (The Table) */}
              <div className="space-y-6">
                 <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                    <h4 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">تشكيلة الفريق (22 لاعب)</h4>
                    <div className="relative">
                       <UserCheck className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-600" size={18} />
                       <input 
                          type="text"
                          placeholder="اسم كابتن الفريق..."
                          className="bg-blue-50 border-none rounded-xl py-2 pr-12 pl-4 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600 w-64"
                          value={selectedMatch.lineupDetails.captain}
                          onChange={e => setSelectedMatch({ ...selectedMatch, lineupDetails: { ...selectedMatch.lineupDetails!, captain: e.target.value } })}
                       />
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    {/* Starters Inputs */}
                    <div className="space-y-4">
                       <div className="bg-blue-900 text-white p-3 rounded-xl text-xs font-black text-center uppercase">الأساسيون (11)</div>
                       <div className="space-y-2">
                          {selectedMatch.lineupDetails.starters.map((player, idx) => (
                             <div key={idx} className="flex items-center gap-3">
                                <span className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center text-[10px] font-black text-slate-400 shrink-0">{idx + 1}</span>
                                <input 
                                   type="text" 
                                   placeholder={`اسم اللاعب رقم ${idx + 1}`}
                                   className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-blue-500"
                                   value={player}
                                   onChange={e => updateLineup('starters', idx, e.target.value)}
                                />
                             </div>
                          ))}
                       </div>
                    </div>

                    {/* Subs Inputs */}
                    <div className="space-y-4">
                       <div className="bg-slate-800 text-white p-3 rounded-xl text-xs font-black text-center uppercase">الاحتياط (11)</div>
                       <div className="space-y-2">
                          {selectedMatch.lineupDetails.subs.map((player, idx) => (
                             <div key={idx} className="flex items-center gap-3">
                                <span className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center text-[10px] font-black text-slate-400 shrink-0">{idx + 12}</span>
                                <input 
                                   type="text" 
                                   placeholder={`اسم اللاعب رقم ${idx + 12}`}
                                   className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-slate-500"
                                   value={player}
                                   onChange={e => updateLineup('subs', idx, e.target.value)}
                                />
                             </div>
                          ))}
                       </div>

                       <div className="pt-4 space-y-2">
                          <label className="text-xs font-black text-slate-500 flex items-center gap-2"><ClipboardList size={14} /> ملاحظات التبديلات</label>
                          <textarea 
                             rows={3}
                             placeholder="مثال: دخول أحمد بدلاً من خالد د.60..." 
                             className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                             value={selectedMatch.lineupDetails.substitutions}
                             onChange={e => setSelectedMatch({ ...selectedMatch, lineupDetails: { ...selectedMatch.lineupDetails!, substitutions: e.target.value } })}
                          />
                       </div>
                    </div>
                 </div>
              </div>

              {/* Stats Section */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-4">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><Target size={18} className="text-orange-500" /> مسجلو الأهداف</label>
                  <textarea 
                    rows={4}
                    placeholder="مثال: \nمحمد د.15 (رأسية)\nعلي د.80 (ضربة جزاء)" 
                    className="w-full bg-slate-50 rounded-[2rem] p-6 outline-none font-bold text-slate-900 border border-slate-100 focus:ring-2 focus:ring-orange-500"
                    value={selectedMatch.scorers || ''}
                    onChange={e => setSelectedMatch({ ...selectedMatch, scorers: e.target.value })}
                  />
                </div>
                <div className="space-y-4">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><AlertTriangle size={18} className="text-yellow-500" /> الإنذارات والبطاقات</label>
                  <textarea 
                    rows={4}
                    placeholder="مثال:\nبطاقة صفراء لعامر د.45\nبطاقة حمراء لسمير د.88" 
                    className="w-full bg-slate-50 rounded-[2rem] p-6 outline-none font-bold text-slate-900 border border-slate-100 focus:ring-2 focus:ring-yellow-500"
                    value={selectedMatch.cards || ''}
                    onChange={e => setSelectedMatch({ ...selectedMatch, cards: e.target.value })}
                  />
                </div>
              </div>

              <div className="flex gap-4 pt-8 sticky bottom-0 bg-white border-t border-slate-100 pb-4">
                <button type="submit" className="flex-1 bg-emerald-600 text-white font-black py-5 rounded-3xl shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all text-lg">حفظ تقرير المباراة النهائي</button>
                <button type="button" onClick={() => setIsResultModalOpen(false)} className="bg-slate-100 text-slate-600 font-black py-5 px-12 rounded-3xl hover:bg-slate-200 transition-all">إلغاء</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

export type Category = 'رجال' | 'شباب' | 'ناشئين' | 'أشبال';
export type Role = 'لاعب' | 'مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب' | 'مشاهد';

export interface Person {
  id: string;
  name: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface GoalRecord {
  player: string;
  time: string;
}

export interface CardRecord {
  player: string;
  time: string;
  type: 'صفراء' | 'حمراء';
}

export interface SubstitutionRecord {
  playerIn: string;
  playerOut: string;
  time: string;
}

export interface MatchLineup {
  starters: string[];
  subs: string[];
  captain: string;
  substitutionList: SubstitutionRecord[];
}

export interface Match {
  id: string;
  category: Category;
  opponent: string;
  location: string;
  advancePayment: string;
  date: string;
  time: string;
  isCompleted?: boolean;
  ourScore?: string;
  opponentScore?: string;
  goalList: GoalRecord[];
  cardList: CardRecord[];
  lineupDetails?: MatchLineup;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  currentUser: AppUser | null;
}

import React, { useState, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, Trash2, Banknote, Calendar as CalendarIcon, Edit3, ClipboardList, Target, AlertTriangle, User, UserCheck, Repeat } from 'lucide-react';
import { AppState, Match, Category, MatchLineup, GoalRecord, CardRecord, SubstitutionRecord } from '../types';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);

  const [formData, setFormData] = useState<Partial<Match>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.opponent || !formData.location) return;

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      opponent: formData.opponent,
      location: formData.location,
      advancePayment: formData.advancePayment || '0',
      date: formData.date,
      time: formData.time || '16:00',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      goalList: [],
      cardList: [],
      lineupDetails: {
        starters: Array(11).fill(''),
        subs: Array(11).fill(''),
        captain: '',
        substitutionList: []
      }
    };

    setState(prev => ({
      ...prev,
      matches: [newMatch, ...prev.matches]
    }));
    setIsAddModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال' });
  };

  const handleUpdateResult = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMatch || isReadOnly) return;

    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === selectedMatch.id ? { ...selectedMatch, isCompleted: true } : m)
    }));
    setIsResultModalOpen(false);
    setSelectedMatch(null);
  };

  const removeMatch = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذه المباراة؟')) {
      setState(prev => ({
        ...prev,
        matches: prev.matches.filter(m => m.id !== id)
      }));
    }
  };

  const openResultModal = (match: Match) => {
    const defaultLineup: MatchLineup = match.lineupDetails || {
      starters: Array(11).fill(''),
      subs: Array(11).fill(''),
      captain: '',
      substitutionList: []
    };
    setSelectedMatch({ 
      ...match, 
      lineupDetails: defaultLineup,
      goalList: match.goalList || [],
      cardList: match.cardList || []
    });
    setIsResultModalOpen(true);
  };

  const updateLineup = (type: 'starters' | 'subs', index: number, value: string) => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const newLineup = { ...selectedMatch.lineupDetails };
    newLineup[type][index] = value;
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const addGoalRow = () => {
    if (!selectedMatch) return;
    setSelectedMatch({
      ...selectedMatch,
      goalList: [...selectedMatch.goalList, { player: '', time: '' }]
    });
  };

  const addCardRow = () => {
    if (!selectedMatch) return;
    setSelectedMatch({
      ...selectedMatch,
      cardList: [...selectedMatch.cardList, { player: '', time: '', type: 'صفراء' }]
    });
  };

  const addSubstitutionRow = () => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const newLineup = { ...selectedMatch.lineupDetails };
    newLineup.substitutionList = [...newLineup.substitutionList, { playerIn: '', playerOut: '', time: '' }];
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const filteredMatches = restrictedCat 
    ? state.matches.filter(m => m.category === restrictedCat)
    : state.matches;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول مباريات فئة ${restrictedCat}` : 'جدول كافة مباريات النادي'}
        </h3>
        {canEdit && (
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-lg shadow-orange-200"
          >
            <Plus size={20} />
            إضافة مباراة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8">
        {filteredMatches.map(match => (
          <div key={match.id} className={`bg-white rounded-[3rem] shadow-sm border ${match.isCompleted ? 'border-emerald-100' : 'border-slate-100'} overflow-hidden transition-all hover:shadow-xl`}>
            {/* Header Badge */}
            <div className={`px-8 py-3 flex justify-between items-center ${match.isCompleted ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-700'}`}>
              <span className="text-xs font-black uppercase tracking-widest">{match.category}</span>
              <span className="text-[10px] font-black uppercase">{match.isCompleted ? 'مباراة منتهية' : 'مباراة قادمة'}</span>
            </div>

            <div className="p-8">
              {/* Score Dashboard */}
              <div className="flex flex-col md:flex-row items-center justify-between gap-12 mb-12">
                <div className="flex-1 text-center">
                  <div className="w-20 h-20 bg-blue-900 rounded-[2rem] flex items-center justify-center mx-auto mb-4 shadow-lg">
                    <Trophy className="text-white" size={32} />
                  </div>
                  <h4 className="font-black text-xl text-slate-800">نادي الكرامة</h4>
                  {match.isCompleted && <div className="mt-2 text-5xl font-black text-blue-900">{match.ourScore}</div>}
                </div>
                <div className="flex flex-col items-center">
                  <div className="text-orange-500 font-black text-2xl mb-2">VS</div>
                  <div className="h-12 w-px bg-slate-100"></div>
                </div>
                <div className="flex-1 text-center">
                  <div className="w-20 h-20 bg-slate-100 rounded-[2rem] flex items-center justify-center mx-auto mb-4 border border-slate-200">
                    <Trophy className="text-slate-400" size={32} />
                  </div>
                  <h4 className="font-black text-xl text-slate-800">{match.opponent}</h4>
                  {match.isCompleted && <div className="mt-2 text-5xl font-black text-slate-400">{match.opponentScore}</div>}
                </div>
              </div>

              {/* Basic Info */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-8 border-t border-slate-50">
                <div className="space-y-4">
                  <div className="flex items-center gap-4 text-slate-600">
                    <MapPin size={20} className="text-orange-500" />
                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase">الموقع</p>
                      <span className="font-bold">{match.location}</span>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 text-slate-600">
                    <CalendarIcon size={20} className="text-blue-500" />
                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase">التاريخ والوقت</p>
                      <span className="font-bold">{match.date} | {match.time}</span>
                    </div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="bg-emerald-50 p-4 rounded-3xl flex items-center justify-between border border-emerald-100">
                    <div className="flex items-center gap-3 text-emerald-700">
                      <Banknote size={24} />
                      <span className="text-xs font-black">السلفة المالية:</span>
                    </div>
                    <span className="text-lg font-black text-emerald-800">{match.advancePayment} ل.س</span>
                  </div>
                  {!isReadOnly && (
                    <div className="flex gap-3 no-print">
                      <button onClick={() => openResultModal(match)} className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black text-sm hover:bg-black transition-all flex items-center justify-center gap-2 shadow-lg">
                        <Edit3 size={18} /> تسجيل التقرير التفصيلي
                      </button>
                      <button onClick={() => removeMatch(match.id)} className="bg-red-50 text-red-600 px-6 rounded-2xl hover:bg-red-100 transition-all border border-red-100">
                        <Trash2 size={20} />
                      </button>
                    </div>
                  )}
                </div>
              </div>

              {/* Detailed Tables (If Completed) */}
              {match.isCompleted && (
                <div className="mt-12 space-y-10 animate-in fade-in slide-in-from-top-4 duration-500">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Goals Table */}
                    <div className="bg-orange-50 p-6 rounded-[2rem] border border-orange-100">
                      <h5 className="flex items-center gap-2 text-xs font-black text-orange-700 uppercase mb-4"><Target size={16} /> جدول الأهداف</h5>
                      {match.goalList?.length > 0 ? (
                        <div className="overflow-hidden rounded-xl bg-white border border-orange-200">
                          <table className="w-full text-right text-xs">
                            <thead className="bg-orange-100 text-orange-800">
                              <tr>
                                <th className="px-4 py-2">اللاعب</th>
                                <th className="px-4 py-2 text-center">الوقت</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-orange-50">
                              {match.goalList.map((g, i) => (
                                <tr key={i} className="hover:bg-orange-50/50">
                                  <td className="px-4 py-2 font-bold">{g.player}</td>
                                  <td className="px-4 py-2 text-center font-mono">{g.time}'</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      ) : <p className="text-xs font-bold text-slate-400">لا يوجد أهداف مسجلة</p>}
                    </div>

                    {/* Cards Table */}
                    <div className="bg-yellow-50 p-6 rounded-[2rem] border border-yellow-100">
                      <h5 className="flex items-center gap-2 text-xs font-black text-yellow-700 uppercase mb-4"><AlertTriangle size={16} /> جدول البطاقات</h5>
                      {match.cardList?.length > 0 ? (
                        <div className="overflow-hidden rounded-xl bg-white border border-yellow-200">
                          <table className="w-full text-right text-xs">
                            <thead className="bg-yellow-100 text-yellow-800">
                              <tr>
                                <th className="px-4 py-2">اللاعب</th>
                                <th className="px-4 py-2 text-center">النوع</th>
                                <th className="px-4 py-2 text-center">الوقت</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-yellow-50">
                              {match.cardList.map((c, i) => (
                                <tr key={i} className="hover:bg-yellow-50/50">
                                  <td className="px-4 py-2 font-bold">{c.player}</td>
                                  <td className="px-4 py-2 text-center">
                                    <span className={`px-2 py-0.5 rounded-md text-[10px] font-black ${c.type === 'صفراء' ? 'bg-yellow-400 text-yellow-900' : 'bg-red-600 text-white'}`}>{c.type}</span>
                                  </td>
                                  <td className="px-4 py-2 text-center font-mono">{c.time}'</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      ) : <p className="text-xs font-bold text-slate-400">لا يوجد بطاقات مسجلة</p>}
                    </div>
                  </div>

                  {/* Lineup & Subs Section */}
                  {match.lineupDetails && (
                    <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100">
                      <div className="flex items-center justify-between mb-8">
                        <h5 className="flex items-center gap-3 text-lg font-black text-slate-800"><ClipboardList size={24} className="text-blue-600" /> تشكيلة المباراة</h5>
                        <div className="flex items-center gap-2 bg-white px-4 py-2 rounded-xl border border-slate-200">
                          <UserCheck size={16} className="text-blue-600" />
                          <span className="text-xs font-black text-slate-600">الكابتن: {match.lineupDetails.captain || 'غير محدد'}</span>
                        </div>
                      </div>

                      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                        {/* Starters Table */}
                        <div>
                          <div className="bg-blue-900 text-white px-5 py-3 rounded-t-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2">التشكيلة الأساسية (11)</div>
                          <div className="bg-white border-x border-b border-slate-200 rounded-b-2xl overflow-hidden shadow-sm">
                            <table className="w-full text-right text-sm">
                              <tbody>
                                {match.lineupDetails.starters.map((player, idx) => (
                                  <tr key={idx} className={idx % 2 === 0 ? 'bg-slate-50/50' : 'bg-white'}>
                                    <td className="px-5 py-3 border-l border-slate-100 w-12 text-slate-400 font-mono font-black">{idx + 1}</td>
                                    <td className="px-5 py-3 font-bold text-slate-800">{player || '-'}</td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        </div>

                        {/* Substitutions Table */}
                        <div className="space-y-6">
                           <div className="bg-slate-800 text-white px-5 py-3 rounded-t-2xl text-xs font-black uppercase tracking-widest flex items-center gap-2">جدول التبديلات</div>
                           <div className="bg-white border-x border-b border-slate-200 rounded-b-2xl overflow-hidden shadow-sm">
                              <table className="w-full text-right text-xs">
                                 <thead className="bg-slate-100 text-slate-600">
                                    <tr>
                                       <th className="px-4 py-3">اللاعب الخارج</th>
                                       <th className="px-4 py-3">اللاعب الداخل</th>
                                       <th className="px-4 py-3 text-center">الوقت</th>
                                    </tr>
                                 </thead>
                                 <tbody className="divide-y divide-slate-100">
                                    {match.lineupDetails.substitutionList.map((s, idx) => (
                                       <tr key={idx} className="hover:bg-slate-50">
                                          <td className="px-4 py-3 font-bold text-red-600">{s.playerOut}</td>
                                          <td className="px-4 py-3 font-bold text-emerald-600">{s.playerIn}</td>
                                          <td className="px-4 py-3 text-center font-mono">{s.time}'</td>
                                       </tr>
                                    ))}
                                    {match.lineupDetails.substitutionList.length === 0 && (
                                       <tr><td colSpan={3} className="px-4 py-6 text-center text-slate-400 font-bold italic">لا يوجد تبديلات مسجلة</td></tr>
                                    )}
                                 </tbody>
                              </table>
                           </div>

                           <div className="bg-white p-6 rounded-3xl border border-slate-200">
                              <h6 className="text-[10px] font-black text-slate-400 uppercase mb-3">دكة الاحتياط (11)</h6>
                              <div className="grid grid-cols-2 gap-x-6 gap-y-2">
                                 {match.lineupDetails.subs.map((p, i) => (
                                    <div key={i} className="text-xs font-bold text-slate-600 flex gap-2">
                                       <span className="text-slate-300 w-4">{i + 12}</span> {p || '-'}
                                    </div>
                                 ))}
                              </div>
                           </div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        ))}

        {filteredMatches.length === 0 && (
          <div className="text-center py-40 bg-slate-50 rounded-[4rem] border-2 border-dashed border-slate-200">
            <Trophy size={100} className="mx-auto text-slate-100 mb-6" />
            <p className="text-slate-400 font-black text-2xl">بانتظار المباراة القادمة...</p>
          </div>
        )}
      </div>

      {/* Add Match Modal */}
      {isAddModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">إضافة مباراة جديدة</h3>
              <button onClick={() => setIsAddModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleAddMatch} className="p-8 space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الفئة</label>
                  <select 
                    className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold disabled:opacity-70"
                    value={formData.category}
                    disabled={!!restrictedCat}
                    onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                  >
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الفريق المنافس</label>
                  <input type="text" required placeholder="اسم النادي الآخر" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, opponent: e.target.value })} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-1">مكان المباراة</label>
                <input type="text" required placeholder="اسم الملعب" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">التاريخ</label>
                  <input type="date" required className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-1">الوقت</label>
                  <input type="time" required className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-1">السلفة المالية</label>
                <input type="text" placeholder="0" className="w-full bg-slate-100 rounded-2xl p-4 outline-none text-slate-900 font-bold" onChange={e => setFormData({ ...formData, advancePayment: e.target.value })} />
              </div>
              <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-[1.5rem] shadow-xl mt-4">حفظ المباراة</button>
            </form>
          </div>
        </div>
      )}

      {/* Record Result Modal */}
      {isResultModalOpen && selectedMatch && selectedMatch.lineupDetails && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[110] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3.5rem] w-full max-w-5xl shadow-2xl overflow-hidden my-auto max-h-[90vh] flex flex-col">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center shrink-0">
              <h3 className="text-xl font-black text-slate-800">تقرير المباراة التفصيلي</h3>
              <button onClick={() => setIsResultModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800 transition-transform hover:rotate-90"><Plus className="rotate-45" /></button>
            </div>

            <form onSubmit={handleUpdateResult} className="flex-1 overflow-y-auto p-10 space-y-12">
              {/* Scores */}
              <div className="grid grid-cols-2 gap-8 bg-slate-50 p-8 rounded-[3rem]">
                <div className="space-y-2 text-center">
                  <label className="text-xs font-black text-blue-900">نادي الكرامة</label>
                  <input type="number" className="w-full bg-white rounded-2xl p-6 text-center text-4xl font-black outline-none border-2 border-slate-200" value={selectedMatch.ourScore} onChange={e => setSelectedMatch({ ...selectedMatch, ourScore: e.target.value })} />
                </div>
                <div className="space-y-2 text-center">
                  <label className="text-xs font-black text-slate-500">{selectedMatch.opponent}</label>
                  <input type="number" className="w-full bg-white rounded-2xl p-6 text-center text-4xl font-black outline-none border-2 border-slate-200" value={selectedMatch.opponentScore} onChange={e => setSelectedMatch({ ...selectedMatch, opponentScore: e.target.value })} />
                </div>
              </div>

              {/* Goals, Cards, Substitutions Tables in Modal */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                {/* Goals Form */}
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <h4 className="text-sm font-black text-orange-700 uppercase flex items-center gap-2"><Target size={16} /> جدول الأهداف</h4>
                    <button type="button" onClick={addGoalRow} className="text-xs bg-orange-100 text-orange-700 px-3 py-1 rounded-lg font-black">+ أضف هدف</button>
                  </div>
                  <div className="space-y-3">
                    {selectedMatch.goalList.map((g, i) => (
                      <div key={i} className="flex gap-2">
                        <input type="text" placeholder="اسم المسجل" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold" value={g.player} onChange={e => {
                          const newList = [...selectedMatch.goalList];
                          newList[i].player = e.target.value;
                          setSelectedMatch({...selectedMatch, goalList: newList});
                        }} />
                        <input type="text" placeholder="الوقت" className="w-20 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-center" value={g.time} onChange={e => {
                          const newList = [...selectedMatch.goalList];
                          newList[i].time = e.target.value;
                          setSelectedMatch({...selectedMatch, goalList: newList});
                        }} />
                        <button type="button" onClick={() => setSelectedMatch({...selectedMatch, goalList: selectedMatch.goalList.filter((_, idx) => idx !== i)})} className="text-red-400 p-2"><Trash2 size={16}/></button>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Cards Form */}
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <h4 className="text-sm font-black text-yellow-700 uppercase flex items-center gap-2"><AlertTriangle size={16} /> جدول البطاقات</h4>
                    <button type="button" onClick={addCardRow} className="text-xs bg-yellow-100 text-yellow-700 px-3 py-1 rounded-lg font-black">+ أضف بطاقة</button>
                  </div>
                  <div className="space-y-3">
                    {selectedMatch.cardList.map((c, i) => (
                      <div key={i} className="flex gap-2">
                        <input type="text" placeholder="اسم اللاعب" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold" value={c.player} onChange={e => {
                          const newList = [...selectedMatch.cardList];
                          newList[i].player = e.target.value;
                          setSelectedMatch({...selectedMatch, cardList: newList});
                        }} />
                        <select className="bg-white border border-slate-200 rounded-xl px-2 py-2 text-xs font-bold" value={c.type} onChange={e => {
                          const newList = [...selectedMatch.cardList];
                          newList[i].type = e.target.value as 'صفراء' | 'حمراء';
                          setSelectedMatch({...selectedMatch, cardList: newList});
                        }}>
                          <option value="صفراء">صفراء</option>
                          <option value="حمراء">حمراء</option>
                        </select>
                        <input type="text" placeholder="الوقت" className="w-20 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-center" value={c.time} onChange={e => {
                          const newList = [...selectedMatch.cardList];
                          newList[i].time = e.target.value;
                          setSelectedMatch({...selectedMatch, cardList: newList});
                        }} />
                        <button type="button" onClick={() => setSelectedMatch({...selectedMatch, cardList: selectedMatch.cardList.filter((_, idx) => idx !== i)})} className="text-red-400 p-2"><Trash2 size={16}/></button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Lineup Form */}
              <div className="space-y-8 pt-8 border-t">
                <div className="flex items-center justify-between">
                  <h4 className="text-sm font-black text-slate-400 uppercase tracking-widest">تشكيلة الفريق (22 لاعب)</h4>
                  <input type="text" placeholder="كابتن الفريق" className="bg-blue-50 rounded-xl py-2 px-6 text-xs font-bold" value={selectedMatch.lineupDetails.captain} onChange={e => setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, captain: e.target.value}})} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                   <div>
                      <p className="bg-blue-900 text-white text-center p-2 rounded-xl text-xs font-black mb-4">الأساسيون (11)</p>
                      <div className="space-y-2">
                        {selectedMatch.lineupDetails.starters.map((p, i) => (
                          <div key={i} className="flex items-center gap-3">
                            <span className="text-[10px] text-slate-400 w-4">{i+1}</span>
                            <input type="text" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold" value={p} onChange={e => updateLineup('starters', i, e.target.value)} />
                          </div>
                        ))}
                      </div>
                   </div>
                   <div>
                      <p className="bg-slate-800 text-white text-center p-2 rounded-xl text-xs font-black mb-4">الاحتياط (11)</p>
                      <div className="space-y-2">
                        {selectedMatch.lineupDetails.subs.map((p, i) => (
                          <div key={i} className="flex items-center gap-3">
                            <span className="text-[10px] text-slate-400 w-4">{i+12}</span>
                            <input type="text" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold" value={p} onChange={e => updateLineup('subs', i, e.target.value)} />
                          </div>
                        ))}
                      </div>
                   </div>
                </div>
              </div>

              {/* Substitutions Form */}
              <div className="space-y-4 pt-8 border-t">
                <div className="flex justify-between items-center">
                  <h4 className="text-sm font-black text-slate-700 uppercase flex items-center gap-2"><Repeat size={16} /> جدول التبديلات</h4>
                  <button type="button" onClick={addSubstitutionRow} className="text-xs bg-slate-100 text-slate-700 px-3 py-1 rounded-lg font-black">+ أضف تبديل</button>
                </div>
                <div className="space-y-3">
                  {selectedMatch.lineupDetails.substitutionList.map((s, i) => (
                    <div key={i} className="flex gap-2">
                      <input type="text" placeholder="اللاعب الخارج" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-red-600" value={s.playerOut} onChange={e => {
                        const newList = [...selectedMatch.lineupDetails!.substitutionList];
                        newList[i].playerOut = e.target.value;
                        setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, substitutionList: newList}});
                      }} />
                      <input type="text" placeholder="اللاعب الداخل" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-emerald-600" value={s.playerIn} onChange={e => {
                        const newList = [...selectedMatch.lineupDetails!.substitutionList];
                        newList[i].playerIn = e.target.value;
                        setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, substitutionList: newList}});
                      }} />
                      <input type="text" placeholder="الوقت" className="w-20 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-center" value={s.time} onChange={e => {
                        const newList = [...selectedMatch.lineupDetails!.substitutionList];
                        newList[i].time = e.target.value;
                        setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, substitutionList: newList}});
                      }} />
                      <button type="button" onClick={() => {
                        const newList = selectedMatch.lineupDetails!.substitutionList.filter((_, idx) => idx !== i);
                        setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, substitutionList: newList}});
                      }} className="text-red-400 p-2"><Trash2 size={16}/></button>
                    </div>
                  ))}
                </div>
              </div>

              <div className="sticky bottom-0 bg-white border-t p-6 flex gap-4">
                <button type="submit" className="flex-1 bg-emerald-600 text-white font-black py-4 rounded-3xl shadow-xl">حفظ تقرير المباراة</button>
                <button type="button" onClick={() => setIsResultModalOpen(false)} className="bg-slate-100 px-10 rounded-3xl font-black">إلغاء</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Users, Search, X } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const isReadOnly = currentUser?.role === 'مشاهد' || currentUser?.role === 'مدرب';
  const restrictedCat = currentUser?.restrictedCategory;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || 'رجال',
    role: 'لاعب'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
      setFormData(prev => ({ ...prev, category: restrictedCat }));
    }
  }, [restrictedCat]);

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleAddPerson = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.name) return;

    const newPerson: Person = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name,
      category: formData.category as Category,
      role: formData.role as Role,
      number: formData.number,
      phone: formData.phone,
      joinDate: new Date().toISOString().split('T')[0]
    };

    setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    setIsModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال', role: 'لاعب' });
  };

  const removePerson = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({ ...prev, people: prev.people.filter(p => p.id !== id) }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 md:p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث عن لاعب بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black" />
            {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><X size={18} /></button>}
          </div>

          {!isReadOnly && (
            <button onClick={() => setIsModalOpen(true)}
              className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
              <UserPlus size={20} />إضافة عضو
            </button>
          )}
        </div>

        {!restrictedCat && (
          <div className="overflow-x-auto pb-2 -mx-2 px-2 no-scrollbar">
            <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max">
              <button onClick={() => setSelectedCategory('الكل')}
                className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}>الكل</button>
              {categories.map(cat => (
                <button key={cat} onClick={() => setSelectedCategory(cat)}
                  className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}>{cat}</button>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[800px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الاسم</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الفئة</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الدور</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">رقم القميص</th>
                {!isReadOnly && <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase text-center">الإجراءات</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4 font-bold text-black">{person.name}</td>
                  <td className="px-6 py-4"><span className="px-3 py-1 bg-blue-50 text-blue-700 rounded-lg text-xs font-black">{person.category}</span></td>
                  <td className="px-6 py-4"><span className={`px-3 py-1 rounded-lg text-xs font-black ${person.role === 'لاعب' ? 'bg-orange-50 text-orange-700' : 'bg-slate-100 text-slate-600'}`}>{person.role}</span></td>
                  <td className="px-6 py-4 text-black font-mono font-black">{person.number || '-'}</td>
                  {!isReadOnly && (
                    <td className="px-6 py-4 text-center">
                      <button onClick={() => removePerson(person.id)} className="text-slate-300 hover:text-red-600 p-2 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
          {filteredPeople.length === 0 && (
            <div className="text-center py-24 bg-slate-50/30">
              <Users size={64} className="mx-auto text-slate-200 mb-4" />
              <p className="text-slate-400 font-black text-lg">لم يتم العثور على أي نتائج</p>
            </div>
          )}
        </div>
      </div>

      {isModalOpen && !isReadOnly && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-end sm:items-center justify-center z-[100] p-0 sm:p-4">
          <div className="bg-white rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in slide-in-from-bottom duration-300">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50/50">
              <h3 className="text-xl font-black text-slate-800">إضافة عضو جديد</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><X size={20} /></button>
            </div>
            <form onSubmit={handleAddPerson} className="p-8 space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div className="sm:col-span-2 space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الاسم الكامل</label>
                  <input required type="text" onChange={e => setFormData({ ...formData, name: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="الاسم الكامل" />
                </div>
                {!restrictedCat && (
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">الفئة</label>
