            </div>
            <form onSubmit={handleAddSession} className="p-6 space-y-4">
              <div className="space-y-1">
                <label className="text-sm font-bold text-slate-700">الفئة المستهدفة</label>
                <select 
                  className="w-full bg-slate-100 rounded-xl p-3 outline-none text-black font-bold disabled:opacity-70"
                  value={formData.category}
                  disabled={!!restrictedCat}
                  onChange={e => setFormData({ ...formData, category: e.target.value as Category })}
                >
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
