                                  <td className="px-4 py-2 text-center font-mono text-black">{c.time}'</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      ) : <p className="text-xs font-bold text-slate-400">لا يوجد بطاقات مسجلة</p>}
                    </div>
                  </div>

                  {/* Lineup & Subs Section */}
                  {match.lineupDetails && (
