                      <div className="flex items-center justify-between mb-8">
                        <h5 className="flex items-center gap-3 text-lg font-black text-slate-800"><ClipboardList size={24} className="text-blue-600" /> تشكيلة المباراة</h5>
                        <div className="flex items-center gap-2 bg-white px-4 py-2 rounded-xl border border-slate-200">
                          <UserCheck size={16} className="text-blue-600" />
                          <span className="text-xs font-black text-slate-600">الكابتن: {match.lineupDetails.captain || 'غير محدد'}</span>
