              {/* Scores */}
              <div className="grid grid-cols-2 gap-8 bg-slate-50 p-8 rounded-[3rem]">
                <div className="space-y-2 text-center">
                  <label className="text-xs font-black text-blue-900">نادي الكرامة</label>
                  <input type="number" className="w-full bg-white rounded-2xl p-6 text-center text-4xl font-black outline-none border-2 border-slate-200 text-black" value={selectedMatch.ourScore} onChange={e => setSelectedMatch({ ...selectedMatch, ourScore: e.target.value })} />
                </div>
                <div className="space-y-2 text-center">
                  <label className="text-xs font-black text-slate-500">{selectedMatch.opponent}</label>
                  <input type="number" className="w-full bg-white rounded-2xl p-6 text-center text-4xl font-black outline-none border-2 border-slate-200 text-black" value={selectedMatch.opponentScore} onChange={e => setSelectedMatch({ ...selectedMatch, opponentScore: e.target.value })} />
                </div>
              </div>

              {/* Goals, Cards, Substitutions Tables in Modal */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
