                   </div>
                   <div>
                      <p className="bg-slate-800 text-white text-center p-2 rounded-xl text-xs font-black mb-4">الاحتياط (11)</p>
                      <div className="space-y-2">
                        {selectedMatch.lineupDetails.subs.map((p, i) => (
                          <div key={i} className="flex items-center gap-3">
                            <span className="text-[10px] text-slate-400 w-4">{i+12}</span>
                            <input type="text" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-black" value={p} onChange={e => updateLineup('subs', i, e.target.value)} />
                          </div>
                        ))}
                      </div>
                   </div>
                </div>
              </div>

              {/* Substitutions Form */}
              <div className="space-y-4 pt-8 border-t">
                <div className="flex justify-between items-center">
                  <h4 className="text-sm font-black text-slate-700 uppercase flex items-center gap-2"><Repeat size={16} /> جدول التبديلات</h4>
                  <button type="button" onClick={addSubstitutionRow} className="text-xs bg-slate-100 text-slate-700 px-3 py-1 rounded-lg font-black">+ أضف تبديل</button>
                </div>
                <div className="space-y-3">
                  {selectedMatch.lineupDetails.substitutionList.map((s, i) => (
                    <div key={i} className="flex gap-2">
                      <input type="text" placeholder="اللاعب الخارج" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-red-600" value={s.playerOut} onChange={e => {
                        const newList = [...selectedMatch.lineupDetails!.substitutionList];
                        newList[i].playerOut = e.target.value;
                        setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, substitutionList: newList}});
                      }} />
                      <input type="text" placeholder="اللاعب الداخل" className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-emerald-600" value={s.playerIn} onChange={e => {
                        const newList = [...selectedMatch.lineupDetails!.substitutionList];
                        newList[i].playerIn = e.target.value;
                        setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, substitutionList: newList}});
                      }} />
                      <input type="text" placeholder="الوقت" className="w-20 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-center text-black" value={s.time} onChange={e => {
                        const newList = [...selectedMatch.lineupDetails!.substitutionList];
                        newList[i].time = e.target.value;
                        setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, substitutionList: newList}});
                      }} />
                      <button type="button" onClick={() => {
                        const newList = selectedMatch.lineupDetails!.substitutionList.filter((_, idx) => idx !== i);
                        setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, substitutionList: newList}});
                      }} className="text-red-400 p-2"><Trash2 size={16}/></button>
                    </div>
                  ))}
                </div>
              </div>

              <div className="sticky bottom-0 bg-white border-t p-6 flex gap-4">
                <button type="submit" className="flex-1 bg-emerald-600 text-white font-black py-4 rounded-3xl shadow-xl">حفظ تقرير المباراة</button>
                <button type="button" onClick={() => setIsResultModalOpen(false)} className="bg-slate-100 px-10 rounded-3xl font-black">إلغاء</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState } from 'react';
import { Lock, User, ShieldCheck, UserCircle } from 'lucide-react';
import { AppUser, Category } from '../types';
import ClubLogo from './ClubLogo';

interface LoginProps {
  onLogin: (user: AppUser) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();

    // Admin Check: admin1 to admin10 -> admin123
    const adminMatch = username.match(/^admin(\d+)$/);
    if (adminMatch) {
      const num = parseInt(adminMatch[1]);
      if (num >= 1 && num <= 10 && password === 'admin123') {
        onLogin({ id: `admin-${num}`, username, role: 'مدير' });
        return;
      }
    }

    // Restricted Category Check: Men, U18, U16, U14 -> KSC2026
    const categoryMapping: Record<string, Category> = {
      'Men': 'رجال',
      'U18': 'شباب',
      'U16': 'ناشئين',
      'U14': 'أشبال'
    };

    if (categoryMapping[username] && password === 'KSC2026') {
      onLogin({ 
        id: `u-${username.toLowerCase()}`, 
        username, 
        role: 'مدرب', 
        restrictedCategory: categoryMapping[username] 
      });
      return;
    }

    setError('خطأ في اسم المستخدم أو كلمة المرور.');
  };

  const quickLogin = (type: 'admin' | 'cat', val: string) => {
    if (type === 'admin') {
      setUsername('admin1');
      setPassword('admin123');
    } else {
      setUsername(val);
      setPassword('KSC2026');
    }
  };

  return (
    <div className="min-h-screen bg-[#001F3F] flex items-center justify-center p-4 font-['Tajawal']" dir="rtl">
      <div className="max-w-md w-full bg-white rounded-[3.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-500 border border-slate-100">
        <div className="bg-gradient-to-br from-blue-900 to-blue-800 p-12 flex flex-col items-center relative overflow-hidden">
          <div className="absolute -top-12 -right-12 w-48 h-48 bg-orange-500/20 rounded-full blur-3xl"></div>
          <div className="absolute -bottom-12 -left-12 w-48 h-48 bg-blue-400/20 rounded-full blur-3xl"></div>

          <div className="bg-white p-4 rounded-[3rem] shadow-2xl mb-6 border border-white/20 transform hover:scale-105 transition-transform duration-500">
            <ClubLogo size={100} />
          </div>
          <h1 className="text-3xl font-black text-white text-center tracking-tight">نادي الكرامة الرياضي</h1>
          <p className="text-orange-400 font-black mt-1 text-sm uppercase tracking-[0.2em]">AL-KARAMAH SC</p>
        </div>

        <div className="p-10 space-y-6">
          <div className="grid grid-cols-2 gap-3 mb-2">
            <button onClick={() => quickLogin('admin', '')}
              className="flex items-center justify-center gap-2 bg-blue-50 text-blue-800 py-4 rounded-2xl text-xs font-black hover:bg-blue-100 transition-all border border-blue-100">
              <ShieldCheck size={18} />دخول الإدارة
            </button>
            <div className="relative group">
               <button className="w-full flex items-center justify-center gap-2 bg-orange-50 text-orange-800 py-4 rounded-2xl text-xs font-black hover:bg-orange-100 transition-all border border-orange-100">
                <UserCircle size={18} />دخول الفئات
              </button>
              <div className="absolute bottom-full left-0 w-full mb-2 bg-white rounded-2xl shadow-xl border border-slate-100 p-2 opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none group-hover:pointer-events-auto">
                {['Men', 'U18', 'U16', 'U14'].map(u => (
                  <button key={u} onClick={() => quickLogin('cat', u)}
                    className="w-full text-right px-4 py-2 hover:bg-orange-50 rounded-xl text-xs font-black text-slate-700">فئة {u}</button>
                ))}
              </div>
            </div>
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            {error && <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-xs font-black text-center border border-red-100">{error}</div>}

            <div className="space-y-1.5">
              <label className="text-xs font-black text-slate-500 mr-2">اسم المستخدم</label>
              <div className="relative">
                <User className="absolute right-4 top-4 text-slate-400" size={20} />
                <input type="text" value={username} onChange={e => setUsername(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 pr-12 pl-4 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
                  placeholder="admin1 أو اسم الفئة" />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-black text-slate-500 mr-2">كلمة المرور</label>
              <div className="relative">
                <Lock className="absolute right-4 top-4 text-slate-400" size={20} />
                <input type="password" value={password} onChange={e => setPassword(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 pr-12 pl-4 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
                  placeholder="كلمة المرور" />
              </div>
            </div>

            <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl hover:bg-black transition-all shadow-2xl shadow-blue-200 mt-2 text-lg">دخول للنظام</button>
          </form>
          <div className="pt-4 border-t border-slate-100 text-center">
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-loose">
              النظام المحاسبي والإداري المتكامل<br/>نادي الكرامة الرياضي - 2024
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

export type Category = 'رجال' | 'شباب' | 'ناشئين' | 'أشبال';
export type Role = 'لاعب' | 'مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب' | 'مشاهد';

export interface Person {
  id: string;
  name: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface GoalRecord {
  player: string;
  number: string;
  time: string;
}

export interface CardRecord {
  player: string;
  number: string;
  time: string;
  type: 'صفراء' | 'حمراء';
}

export interface SubstitutionRecord {
  playerIn: string;
  numberIn: string;
  playerOut: string;
  numberOut: string;
  time: string;
}

export interface LineupPlayer {
  name: string;
  number: string;
}

export interface MatchLineup {
  starters: LineupPlayer[];
  subs: LineupPlayer[];
  captain: string;
  substitutionList: SubstitutionRecord[];
}

export interface Match {
  id: string;
  category: Category;
  opponent: string;
  location: string;
  advancePayment: string;
  date: string;
  time: string;
  isCompleted?: boolean;
  ourScore?: string;
  opponentScore?: string;
  goalList: GoalRecord[];
  cardList: CardRecord[];
  lineupDetails?: MatchLineup;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  currentUser: AppUser | null;
}

import React, { useState, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, Trash2, Banknote, Calendar as CalendarIcon, Edit3, ClipboardList, Target, AlertTriangle, User, UserCheck, Repeat, FileText, Printer } from 'lucide-react';
import { AppState, Match, Category, MatchLineup, GoalRecord, CardRecord, SubstitutionRecord, LineupPlayer } from '../types';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);

  const [formData, setFormData] = useState<Partial<Match>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.opponent || !formData.location) return;

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      opponent: formData.opponent,
      location: formData.location,
      advancePayment: formData.advancePayment || '0',
      date: formData.date,
      time: formData.time || '16:00',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      goalList: [],
      cardList: [],
      lineupDetails: {
        starters: Array(11).fill({ name: '', number: '' }),
        subs: Array(11).fill({ name: '', number: '' }),
        captain: '',
        substitutionList: []
      }
    };

    setState(prev => ({
      ...prev,
      matches: [newMatch, ...prev.matches]
    }));
    setIsAddModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال' });
  };

  const handleUpdateResult = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMatch || isReadOnly) return;

    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === selectedMatch.id ? { ...selectedMatch, isCompleted: true } : m)
    }));
    setIsResultModalOpen(false);
    setSelectedMatch(null);
  };

  const removeMatch = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذه المباراة؟')) {
      setState(prev => ({
        ...prev,
        matches: prev.matches.filter(m => m.id !== id)
      }));
    }
  };

  const openResultModal = (match: Match) => {
    // Migration helper for legacy data that might have string arrays
    const defaultStarters = Array.isArray(match.lineupDetails?.starters) && typeof match.lineupDetails?.starters[0] === 'string'
      ? match.lineupDetails.starters.map((s: any) => ({ name: s, number: '' }))
      : match.lineupDetails?.starters || Array(11).fill({ name: '', number: '' });

    const defaultSubs = Array.isArray(match.lineupDetails?.subs) && typeof match.lineupDetails?.subs[0] === 'string'
      ? match.lineupDetails.subs.map((s: any) => ({ name: s, number: '' }))
      : match.lineupDetails?.subs || Array(11).fill({ name: '', number: '' });

    const defaultLineup: MatchLineup = {
      starters: defaultStarters,
      subs: defaultSubs,
      captain: match.lineupDetails?.captain || '',
      substitutionList: match.lineupDetails?.substitutionList || []
    };

    setSelectedMatch({ 
      ...match, 
      lineupDetails: defaultLineup,
      goalList: match.goalList || [],
      cardList: match.cardList || [],
      ourScore: match.ourScore || '0',
      opponentScore: match.opponentScore || '0'
    });
    setIsResultModalOpen(true);
  };

  const updateLineupPlayer = (type: 'starters' | 'subs', index: number, field: keyof LineupPlayer, value: string) => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const newLineup = { ...selectedMatch.lineupDetails };
    const players = [...newLineup[type]];
    players[index] = { ...players[index], [field]: value };
    newLineup[type] = players;
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const addGoalRow = () => {
    if (!selectedMatch) return;
    setSelectedMatch({
      ...selectedMatch,
      goalList: [...selectedMatch.goalList, { player: '', number: '', time: '' }]
    });
  };

  const addCardRow = () => {
    if (!selectedMatch) return;
    setSelectedMatch({
      ...selectedMatch,
      cardList: [...selectedMatch.cardList, { player: '', number: '', time: '', type: 'صفراء' }]
    });
  };

  const addSubstitutionRow = () => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const newLineup = { ...selectedMatch.lineupDetails };
    newLineup.substitutionList = [...newLineup.substitutionList, { playerIn: '', numberIn: '', playerOut: '', numberOut: '', time: '' }];
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const printReport = (match: Match) => {
    // We'll use window.print() and a print-only container
    window.print();
  };

  const filteredMatches = restrictedCat 
    ? state.matches.filter(m => m.category === restrictedCat)
    : state.matches;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول مباريات فئة ${restrictedCat}` : 'جدول كافة مباريات النادي'}
        </h3>
        {canEdit && (
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-lg shadow-orange-200"
          >
            <Plus size={20} />
            إضافة مباراة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8 no-print">
        {filteredMatches.map(match => (
          <div key={match.id} className={`bg-white rounded-[3rem] shadow-sm border ${match.isCompleted ? 'border-emerald-100' : 'border-slate-100'} overflow-hidden transition-all hover:shadow-xl`}>
            {/* Header Badge */}
            <div className={`px-8 py-3 flex justify-between items-center ${match.isCompleted ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-700'}`}>
              <span className="text-xs font-black uppercase tracking-widest">{match.category}</span>
              <div className="flex items-center gap-4">
                 {match.isCompleted && (
                   <button onClick={() => printReport(match)} className="text-xs font-black flex items-center gap-1 hover:underline">
                     <Printer size={14} /> طباعة التقرير
                   </button>
                 )}
                 <span className="text-[10px] font-black uppercase">{match.isCompleted ? 'مباراة منتهية' : 'مباراة قادمة'}</span>
              </div>
            </div>

            <div className="p-8">
              {/* Score Dashboard */}
              <div className="flex flex-col md:flex-row items-center justify-between gap-12 mb-12">
                <div className="flex-1 text-center">
                  <div className="w-20 h-20 bg-blue-900 rounded-[2rem] flex items-center justify-center mx-auto mb-4 shadow-lg">
                    <Trophy className="text-white" size={32} />
                  </div>
                  <h4 className="font-black text-xl text-slate-800">نادي الكرامة</h4>
                  {match.isCompleted && <div className="mt-2 text-5xl font-black text-blue-900">{match.ourScore}</div>}
                </div>
                <div className="flex flex-col items-center">
                  <div className="text-orange-500 font-black text-2xl mb-2">VS</div>
                  <div className="h-12 w-px bg-slate-100"></div>
                </div>
                <div className="flex-1 text-center">
                  <div className="w-20 h-20 bg-slate-100 rounded-[2rem] flex items-center justify-center mx-auto mb-4 border border-slate-200">
                    <Trophy className="text-slate-400" size={32} />
                  </div>
                  <h4 className="font-black text-xl text-slate-800">{match.opponent}</h4>
                  {match.isCompleted && <div className="mt-2 text-5xl font-black text-slate-400">{match.opponentScore}</div>}
                </div>
              </div>

              {/* Basic Info */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-8 border-t border-slate-50">
                <div className="space-y-4">
                  <div className="flex items-center gap-4 text-slate-600">
                    <MapPin size={20} className="text-orange-500" />
                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase">الموقع</p>
                      <span className="font-bold text-black">{match.location}</span>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 text-slate-600">
                    <CalendarIcon size={20} className="text-blue-500" />
                    <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase">التاريخ والوقت</p>
                      <span className="font-bold text-black">{match.date} | {match.time}</span>
                    </div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="bg-emerald-50 p-4 rounded-3xl flex items-center justify-between border border-emerald-100">
                    <div className="flex items-center gap-3 text-emerald-700">
                      <Banknote size={24} />
                      <span className="text-xs font-black">السلفة المالية:</span>
                    </div>
                    <span className="text-lg font-black text-emerald-800">{match.advancePayment} ل.س</span>
                  </div>
                  {!isReadOnly && (
                    <div className="flex gap-3 no-print">
                      <button onClick={() => openResultModal(match)} className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black text-sm hover:bg-black transition-all flex items-center justify-center gap-2 shadow-lg">
                        <Edit3 size={18} /> تسجيل التقرير التفصيلي
                      </button>
                      <button onClick={() => removeMatch(match.id)} className="bg-red-50 text-red-600 px-6 rounded-2xl hover:bg-red-100 transition-all border border-red-100">
                        <Trash2 size={20} />
                      </button>
                    </div>
                  )}
                </div>
              </div>

              {/* Detailed Tables (If Completed) */}
              {match.isCompleted && (
                <div className="mt-12 space-y-10 animate-in fade-in slide-in-from-top-4 duration-500">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Goals Table */}
                    <div className="bg-orange-50 p-6 rounded-[2rem] border border-orange-100">
                      <h5 className="flex items-center gap-2 text-xs font-black text-orange-700 uppercase mb-4"><Target size={16} /> جدول الأهداف</h5>
                      {match.goalList?.length > 0 ? (
                        <div className="overflow-hidden rounded-xl bg-white border border-orange-200">
                          <table className="w-full text-right text-xs">
                            <thead className="bg-orange-100 text-orange-800">
                              <tr>
                                <th className="px-4 py-2">اللاعب</th>
                                <th className="px-4 py-2 text-center">رقم</th>
                                <th className="px-4 py-2 text-center">الوقت</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-orange-50">
                              {match.goalList.map((g, i) => (
                                <tr key={i} className="hover:bg-orange-50/50">
                                  <td className="px-4 py-2 font-bold text-black">{g.player}</td>
                                  <td className="px-4 py-2 text-center font-black text-orange-600">#{g.number}</td>
                                  <td className="px-4 py-2 text-center font-mono text-black">{g.time}'</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      ) : <p className="text-xs font-bold text-slate-400">لا يوجد أهداف مسجلة</p>}
                    </div>

                    {/* Cards Table */}
                    <div className="bg-yellow-50 p-6 rounded-[2rem] border border-yellow-100">
