                          <div className="overflow-hidden rounded-xl bg-white border border-yellow-200">
                            <table className="w-full text-right text-xs">
                              <thead className="bg-yellow-100 text-yellow-800">
                                <tr>
                                  <th className="px-4 py-2">اللاعب</th>
                                  <th className="px-4 py-2 text-center">رقم</th>
                                  <th className="px-4 py-2 text-center">النوع</th>
                                  <th className="px-4 py-2 text-center">الوقت</th>
