                    <div className="relative">
                      <CalendarIcon className="absolute right-4 top-4 text-slate-400" size={18} />
                      <input type="date" required onChange={e => setFormData({ ...formData, birthDate: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl py-4 pr-12 pl-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">العمر الحالي (محسوب تلقائياً)</label>
                    <div className="w-full bg-blue-50 text-blue-900 border-2 border-blue-100 rounded-2xl p-4 font-black text-xl text-center">
                      {calculateAge(formData.birthDate)} سنة
                    </div>
                  </div>
                </div>
              </div>

