                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">الرقم الوطني</label>
                    <input type="text" onChange={e => setFormData({ ...formData, nationalId: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="الرقم من الهوية" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">رقم الهاتف</label>
                    <input type="tel" onChange={e => setFormData({ ...formData, phone: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="09xxxxxxxx" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">رقم القميص</label>
                    <input type="number" onChange={e => setFormData({ ...formData, number: parseInt(e.target.value) })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="0" />
                  </div>
                </div>
              </div>

              {/* القسم الرابع: الفئة الإدارية */}
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b pb-2">التصنيف الإداري</h4>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {!restrictedCat && (
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">الفئة</label>
                      <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none focus:ring-2 focus:ring-blue-500" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                        {categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  )}
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">الدور / الوظيفة</label>
                    <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none focus:ring-2 focus:ring-blue-500" value={formData.role} onChange={e => setFormData({ ...formData, role: e.target.value as Role })}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                </div>
              </div>

              <div className="pt-4">
                <button type="submit" className="w-full bg-blue-900 text-white font-black py-5 rounded-[1.5rem] shadow-xl shadow-blue-200 mt-4 transition-all hover:bg-black flex items-center justify-center gap-3">
                  <UserPlus size={22} />
                  اعتماد وحفظ العضو الجديد
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

