import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, FileText, History, Clock, Calendar as CalendarIcon, Filter, Lock } from 'lucide-react';
import { AppState, Category, AttendanceRecord, AttendanceStatus } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

interface LocalRecord {
  status: AttendanceStatus;
  time: string;
  fullDate: string;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // Managers can edit anything, Coaches can edit their own category
  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [selectedCategory, setSelectedCategory] = useState<Category>(restrictedCat || 'رجال');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [localRecords, setLocalRecords] = useState<Record<string, LocalRecord>>({});
  const [showHistory, setShowHistory] = useState(isReadOnly);
  const [statusFilter, setStatusFilter] = useState<AttendanceStatus | 'الكل'>('الكل');

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setSelectedCategory(restrictedCat);
  }, [restrictedCat]);

  const players = state.people.filter(p => p.category === selectedCategory);

  // Get base historical records for the selected date and category
  const historicalRecords = state.attendance.filter(r => 
    r.date === date && 
    state.people.find(p => p.id === r.personId)?.category === selectedCategory
  );

  // Apply status filter for history view
  const filteredHistoricalRecords = historicalRecords.filter(r => 
    statusFilter === 'الكل' ? true : r.status === statusFilter
  );

  const setStatus = (personId: string, status: AttendanceStatus) => {
    if (isReadOnly) return;

    // منع التعديل إذا تم الاختيار مسبقاً في الجلسة الحالية
    if (localRecords[personId]) return;

    // منع التعديل إذا كان هناك سجل محفوظ مسبقاً في قاعدة البيانات لهذا اليوم
    const alreadySaved = historicalRecords.some(r => r.personId === personId);
    if (alreadySaved) return;

    const now = new Date();
    const time = now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', hour12: true });
    const fullDate = now.toLocaleDateString('ar-EG', { year: 'numeric', month: '2-digit', day: '2-digit' });

    setLocalRecords(prev => ({ 
      ...prev, 
      [personId]: { status, time, fullDate } 
    }));
  };

  const saveAttendance = () => {
    if (isReadOnly) return;
    if (Object.keys(localRecords).length === 0) { alert('الرجاء تحديد حالة حضور واحدة على الأقل'); return; }

    const newRecords: AttendanceRecord[] = Object.entries(localRecords).map(([pid, record]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      date,
      time: record.time,
      status: record.status,
      note: `تم التسجيل في: ${record.fullDate} - ${record.time}`
    }));

    setState(prev => ({ ...prev, attendance: [...prev.attendance, ...newRecords] }));
    alert('تم حفظ الحضور بنجاح!');
    setLocalRecords({});
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 md:p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col xl:flex-row items-stretch xl:items-end justify-between gap-6 no-print">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 flex-1">
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-wider">اختيار الفئة</label>
            <select value={selectedCategory} disabled={!!restrictedCat}
              onChange={e => { setSelectedCategory(e.target.value as Category); setLocalRecords({}); }}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-black appearance-none disabled:opacity-70">
              {categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-wider">تاريخ التقرير</label>
            <input type="date" value={date} onChange={e => setDate(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-black" />
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <button onClick={() => setShowHistory(!showHistory)}
            className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3.5 rounded-2xl font-bold transition-all border ${showHistory ? 'bg-orange-100 border-orange-200 text-orange-700' : 'bg-slate-50 border-slate-200 text-slate-600'}`}>
            <History size={20} />{showHistory ? 'الرجوع للتسجيل' : 'عرض السجلات'}
          </button>
          <button onClick={() => window.print()} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-slate-900 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-black transition-all shadow-lg">
            <FileText size={20} />تقرير PDF
          </button>
          {!showHistory && canEdit && (
            <button onClick={saveAttendance} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-blue-600 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-xl shadow-blue-200">
              <Save size={20} />حفظ السجل
            </button>
          )}
        </div>
      </div>

      {showHistory && (
        <div className="bg-white px-6 py-4 rounded-3xl shadow-sm border border-slate-100 flex flex-wrap items-center gap-3 no-print">
          <div className="flex items-center gap-2 text-slate-500 ml-2">
            <Filter size={18} />
            <span className="text-xs font-black uppercase tracking-wider">تصفية حسب الحالة:</span>
          </div>
          <button 
            onClick={() => setStatusFilter('الكل')}
            className={`px-5 py-2 rounded-xl text-xs font-black border transition-all ${statusFilter === 'الكل' ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-white text-slate-500 border-slate-100 hover:border-slate-300'}`}
          >
            الكل ({historicalRecords.length})
          </button>
          <button 
            onClick={() => setStatusFilter('حاضر')}
            className={`px-5 py-2 rounded-xl text-xs font-black border transition-all ${statusFilter === 'حاضر' ? 'bg-green-600 text-white border-green-600 shadow-md shadow-green-100' : 'bg-white text-green-600 border-green-50 hover:bg-green-50'}`}
          >
            حاضر ({historicalRecords.filter(r => r.status === 'حاضر').length})
          </button>
          <button 
            onClick={() => setStatusFilter('متأخر')}
            className={`px-5 py-2 rounded-xl text-xs font-black border transition-all ${statusFilter === 'متأخر' ? 'bg-orange-500 text-white border-orange-500 shadow-md shadow-orange-100' : 'bg-white text-orange-600 border-orange-50 hover:bg-orange-50'}`}
          >
            متأخر ({historicalRecords.filter(r => r.status === 'متأخر').length})
          </button>
          <button 
            onClick={() => setStatusFilter('غائب')}
            className={`px-5 py-2 rounded-xl text-xs font-black border transition-all ${statusFilter === 'غائب' ? 'bg-red-600 text-white border-red-600 shadow-md shadow-red-100' : 'bg-white text-red-600 border-red-50 hover:bg-red-50'}`}
          >
            غائب ({historicalRecords.filter(r => r.status === 'غائب').length})
          </button>
        </div>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[800px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-600 font-bold">الاسم</th>
                <th className="px-6 py-5 text-slate-600 font-bold text-center">الحالة</th>
                <th className="px-6 py-5 text-slate-600 font-bold text-center">وقت وتاريخ التسجيل</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {showHistory ? (
                filteredHistoricalRecords.length > 0 ? filteredHistoricalRecords.map(record => (
                  <tr key={record.id} className="hover:bg-slate-50 animate-in fade-in duration-300">
                    <td className="px-6 py-4 font-bold text-black">{state.people.find(p => p.id === record.personId)?.name}</td>
                    <td className="px-6 py-4 text-center">
                      <span className={`px-4 py-1.5 rounded-xl text-xs font-black flex items-center justify-center gap-2 mx-auto w-max ${record.status === 'حاضر' ? 'bg-green-100 text-green-700' : record.status === 'متأخر' ? 'bg-orange-100 text-orange-700' : 'bg-red-100 text-red-700'}`}>
                        <Lock size={12} /> {record.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center">
                       <div className="flex flex-col items-center gap-1">
                          <span className="text-xs text-black font-bold flex items-center gap-1"><Clock size={14} className="text-blue-500" /> {record.time}</span>
                          <span className="text-[10px] text-slate-400 font-medium flex items-center gap-1"><CalendarIcon size={12} /> {record.date}</span>
                       </div>
                    </td>
                  </tr>
                )) : (
                  <tr>
                    <td colSpan={3} className="text-center py-20 text-slate-400 italic font-bold">
                      {historicalRecords.length === 0 
                        ? 'لا توجد سجلات محفوظة لهذا التاريخ' 
                        : 'لا توجد نتائج تطابق عامل التصفية المختار'}
                    </td>
                  </tr>
                )
              ) : (
                players.map(person => {
                  const alreadySaved = historicalRecords.find(r => r.personId === person.id);
                  const inLocal = localRecords[person.id];
                  const isLocked = !!alreadySaved || !!inLocal;
                  const currentStatus = alreadySaved?.status || inLocal?.status;

                  return (
                    <tr key={person.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4 font-bold text-black">{person.name}</td>
                      <td className="px-6 py-4">
                        <div className="flex justify-center gap-2 no-print">
                          {(['حاضر', 'متأخر', 'غائب'] as AttendanceStatus[]).map(status => (
                            <button 
                              key={status} 
                              onClick={() => setStatus(person.id, status)} 
                              disabled={isReadOnly || isLocked}
                              className={`min-w-[80px] px-4 py-2.5 rounded-xl text-xs font-black border transition-all 
                                ${currentStatus === status 
                                  ? (status === 'حاضر' ? 'bg-green-600 text-white border-green-600 shadow-lg shadow-green-100' : status === 'متأخر' ? 'bg-orange-500 text-white border-orange-500 shadow-lg shadow-orange-100' : 'bg-red-600 text-white border-red-600 shadow-lg shadow-red-100') 
                                  : (isLocked ? 'bg-slate-50 text-slate-300 border-slate-100 opacity-50 cursor-not-allowed' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300')
                                }`}
                            >
                              {status}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                         <div className="min-h-[40px] flex flex-col items-center justify-center gap-1">
                            {isLocked ? (
                              <div className="animate-in fade-in zoom-in-95 duration-300 flex flex-col items-center">
                                <div className="bg-blue-50 text-blue-700 px-3 py-1 rounded-lg text-xs font-black flex items-center gap-2 border border-blue-100">
                                  <Lock size={12} className="text-blue-400" />
                                  <Clock size={14} /> {alreadySaved?.time || inLocal?.time}
                                </div>
                                <div className="text-[10px] text-slate-400 font-bold mt-1 flex items-center gap-1">
                                  <CalendarIcon size={10} /> {alreadySaved?.date || inLocal?.fullDate}
                                </div>
                              </div>
                            ) : (
                              <span className="text-slate-300 text-[10px] font-bold">بانتظار التسجيل...</span>
                            )}
                         </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AttendanceTracker;

export type Category = 'رجال' | 'شباب' | 'ناشئين' | 'أشبال';
export type Role = 'لاعب' | 'مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب' | 'مشاهد';

export interface Person {
  id: string;
  name: string; // الاسم الثنائي
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  federalNumber?: string;
  nationalId?: string;
  birthDate?: string;
  fatherName?: string;
  motherName?: string;
  // حقول العقد لفئة الرجال
  contractValue?: string;
  contractDuration?: string;
  contractStart?: string;
  contractEnd?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface GoalRecord {
  player: string;
  number: string;
  time: string;
}

export interface CardRecord {
  player: string;
  number: string;
  time: string;
  type: 'صفراء' | 'حمراء';
}

export interface SubstitutionRecord {
  playerIn: string;
  numberIn: string;
  playerOut: string;
  numberOut: string;
  time: string;
}

export interface LineupPlayer {
  name: string;
  number: string;
}

export interface MatchLineup {
  starters: LineupPlayer[];
  subs: LineupPlayer[];
  captain: string;
  substitutionList: SubstitutionRecord[];
}

export interface Match {
  id: string;
  category: Category;
  opponent: string;
  location: string;
  advancePayment: string;
  date: string;
  time: string;
  isCompleted?: boolean;
  ourScore?: string;
  opponentScore?: string;
  goalList: GoalRecord[];
  cardList: CardRecord[];
  lineupDetails?: MatchLineup;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  currentUser: AppUser | null;
}

import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Users, Search, X, Calendar as CalendarIcon, Hash, Fingerprint, Phone, User as UserIcon, Banknote, History, Hourglass } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const isReadOnly = currentUser?.role === 'مشاهد' || currentUser?.role === 'مدرب';
  const restrictedCat = currentUser?.restrictedCategory;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || 'رجال',
    role: 'لاعب'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
      setFormData(prev => ({ ...prev, category: restrictedCat }));
    }
  }, [restrictedCat]);

  const calculateAge = (birthDate?: string) => {
    if (!birthDate) return '-';
    const birth = new Date(birthDate);
    const today = new Date();
    if (isNaN(birth.getTime())) return '-';

    let age = today.getFullYear() - birth.getFullYear();
    const monthDiff = today.getMonth() - birth.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    return age >= 0 ? age : 0;
  };

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleAddPerson = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.name) return;

    const newPerson: Person = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name,
      category: formData.category as Category,
      role: formData.role as Role,
      number: formData.number,
      phone: formData.phone,
      federalNumber: formData.federalNumber,
      nationalId: formData.nationalId,
      birthDate: formData.birthDate,
      fatherName: formData.fatherName,
      motherName: formData.motherName,
      joinDate: new Date().toISOString().split('T')[0],
      // حقول العقد
      contractValue: formData.contractValue,
      contractDuration: formData.contractDuration,
      contractStart: formData.contractStart,
      contractEnd: formData.contractEnd
    };

    setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    setIsModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال', role: 'لاعب' });
  };

  const removePerson = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({ ...prev, people: prev.people.filter(p => p.id !== id) }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 md:p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4 no-print">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث عن عضو بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black" />
            {searchTerm && <button onClick={() => setSearchTerm('')} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><X size={18} /></button>}
          </div>

          {!isReadOnly && (
            <button onClick={() => setIsModalOpen(true)}
              className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
              <UserPlus size={20} />إضافة عضو
            </button>
          )}
        </div>

        {!restrictedCat && (
          <div className="overflow-x-auto pb-2 -mx-2 px-2 no-scrollbar">
            <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max">
              <button onClick={() => setSelectedCategory('الكل')}
                className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}>الكل</button>
              {categories.map(cat => (
                <button key={cat} onClick={() => setSelectedCategory(cat)}
                  className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-white'}`}>{cat}</button>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[1200px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">المعلومات الأساسية</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">تاريخ الميلاد / العمر</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase text-center">رقم القميص</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الأرقام الرسمية</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">بيانات العقد (للرجال)</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase">الفئة والدور</th>
                {!isReadOnly && <th className="px-6 py-5 text-slate-500 font-black text-xs uppercase text-center no-print">الإجراءات</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-black text-base">{person.name}</span>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold">الأب: {person.fatherName || '-'}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold">الأم: {person.motherName || '-'}</span>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-sm font-black text-blue-900">{calculateAge(person.birthDate)} سنة</span>
                      <span className="text-[10px] font-mono text-slate-400 font-bold">{person.birthDate || '-'}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="inline-flex items-center justify-center w-10 h-10 rounded-full bg-slate-900 text-white text-sm font-black shadow-md">{person.number || '-'}</span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col gap-1.5">
                      <div className="flex items-center gap-2">
                        <Hash size={12} className="text-orange-500" />
                        <span className="text-[10px] font-black text-slate-400 uppercase w-14">اتحادي:</span>
                        <span className="text-xs font-bold text-black">{person.federalNumber || '-'}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <Fingerprint size={12} className="text-blue-500" />
                        <span className="text-[10px] font-black text-slate-400 uppercase w-14">وطني:</span>
                        <span className="text-xs font-bold text-black">{person.nationalId || '-'}</span>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    {person.category === 'رجال' && person.contractValue ? (
                      <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-2">
                          <Banknote size={12} className="text-emerald-600" />
                          <span className="text-xs font-black text-emerald-700">{person.contractValue} ل.س</span>
                        </div>
                        <div className="flex items-center gap-2">
                          <Hourglass size={12} className="text-blue-600" />
                          <span className="text-[10px] font-bold text-slate-600">{person.contractDuration} (من {person.contractStart || '-'})</span>
                        </div>
                      </div>
                    ) : (
                      <span className="text-[10px] text-slate-300 italic">لا ينطبق</span>
                    )}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-wrap gap-1.5">
                      <span className="px-3 py-1 bg-blue-50 text-blue-700 rounded-lg text-xs font-black">{person.category}</span>
                      <span className={`px-3 py-1 rounded-lg text-xs font-black ${person.role === 'لاعب' ? 'bg-orange-50 text-orange-700' : 'bg-slate-100 text-slate-600'}`}>{person.role}</span>
                    </div>
                  </td>
                  {!isReadOnly && (
                    <td className="px-6 py-4 text-center no-print">
                      <button onClick={() => removePerson(person.id)} className="text-slate-300 hover:text-red-600 p-2 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
          {filteredPeople.length === 0 && (
            <div className="text-center py-24 bg-slate-50/30">
              <Users size={64} className="mx-auto text-slate-200 mb-4" />
              <p className="text-slate-400 font-black text-lg">لا يوجد أعضاء في هذه الفئة</p>
            </div>
          )}
        </div>
      </div>

      {isModalOpen && !isReadOnly && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3.5rem] w-full max-w-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 my-auto">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50">
              <div className="flex items-center gap-4">
                <div className="bg-blue-900 p-3 rounded-2xl text-white shadow-lg"><UserPlus size={28} /></div>
                <div>
                  <h3 className="text-xl font-black text-slate-800">إضافة عضو جديد</h3>
                  <p className="text-xs text-slate-500 font-bold mt-1">تعبئة البيانات الشخصية والرياضية للعضو</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800 transition-transform hover:rotate-90"><X size={20} /></button>
            </div>

            <form onSubmit={handleAddPerson} className="p-8 space-y-8 max-h-[75vh] overflow-y-auto custom-scrollbar">
              {/* قسم التصنيف الرياضي (مقدم في الترتيب لضبط الحقول المشروطة) */}
              <div className="space-y-5">
                <div className="flex items-center gap-2 border-r-4 border-blue-900 pr-3">
                  <h4 className="text-sm font-black text-slate-700">التصنيف الرياضي</h4>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  {!restrictedCat && (
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">الفئة</label>
                      <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none focus:ring-2 focus:ring-blue-500" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                        {categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  )}
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">الدور / المركز</label>
                    <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none focus:ring-2 focus:ring-blue-500" value={formData.role} onChange={e => setFormData({ ...formData, role: e.target.value as Role })}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                </div>
              </div>

              {/* قسم الهوية الشخصية */}
              <div className="space-y-5">
                <div className="flex items-center gap-2 border-r-4 border-orange-500 pr-3">
                  <h4 className="text-sm font-black text-slate-700">بيانات الهوية الشخصية</h4>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div className="sm:col-span-2 space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">الاسم الثنائي</label>
                    <div className="relative">
                      <UserIcon className="absolute right-4 top-4 text-slate-400" size={18} />
                      <input required type="text" onChange={e => setFormData({ ...formData, name: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl py-4 pr-12 pl-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="الاسم والكنية" />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">اسم الأب</label>
                    <input type="text" onChange={e => setFormData({ ...formData, fatherName: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="اسم الأب" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">اسم الأم</label>
                    <input type="text" onChange={e => setFormData({ ...formData, motherName: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="اسم الأم" />
                  </div>
                </div>
              </div>

              {/* قسم الميلاد والسن */}
              <div className="space-y-5">
                <div className="flex items-center gap-2 border-r-4 border-blue-600 pr-3">
                  <h4 className="text-sm font-black text-slate-700">تاريخ الميلاد والعمر</h4>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">تاريخ الميلاد</label>
                    <div className="relative">
                      <CalendarIcon className="absolute right-4 top-4 text-slate-400" size={18} />
                      <input type="date" required onChange={e => setFormData({ ...formData, birthDate: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl py-4 pr-12 pl-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" />
                    </div>
