      // إذا كان مدير، نقوم بفلترة السجلات القديمة واستبدالها بالجديدة (تعديل)
      const filteredOldAttendance = prev.attendance.filter(a => 
        !(a.date === date && localRecords[a.personId])
      );

      return { 
        ...prev, 
        attendance: [...filteredOldAttendance, ...newRecords] 
      };
    });

    alert('تم تحديث سجل الحضور بنجاح!');
    setLocalRecords({});
  };

