          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase">تاريخ التسجيل</label>
            <input type="date" value={date} onChange={e => { setDate(e.target.value); setLocalRecords({}); }}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-black" />
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <button onClick={() => setShowHistory(!showHistory)}
            className={`flex items-center justify-center gap-2 px-6 py-3.5 rounded-2xl font-bold transition-all border ${showHistory ? 'bg-orange-100 border-orange-200 text-orange-700' : 'bg-slate-50 border-slate-200 text-slate-600'}`}>
            <History size={20} /> {showHistory ? 'إغلاق السجلات' : 'عرض السجل المحفوظ'}
          </button>
          {!showHistory && canEdit && (
            <button onClick={saveAttendance} className="bg-blue-600 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-xl shadow-blue-200 flex items-center justify-center gap-2">
              <Save size={20} /> حفظ / تعديل السجل
            </button>
          )}
          <button onClick={() => window.print()} className="bg-slate-900 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-black transition-all shadow-lg flex items-center justify-center gap-2">
            <FileText size={20} /> طباعة التقرير
          </button>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-slate-600 font-black">الاسم</th>
                <th className="px-8 py-5 text-slate-600 font-black text-center">الحالة</th>
                <th className="px-8 py-5 text-slate-600 font-black text-center">التوقيت</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {players.map(person => {
                const alreadySaved = historicalRecords.find(r => r.personId === person.id);
                const inLocal = localRecords[person.id];
                const currentStatus = inLocal?.status || alreadySaved?.status;
                const currentTime = inLocal?.time || alreadySaved?.time;

                // التحكم في إمكانية التعديل
                const isLockedForCoach = alreadySaved && !isManager;

                return (
                  <tr key={person.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-8 py-5">
                      <div className="flex flex-col">
                        <span className="font-bold text-slate-900 text-lg">{person.name}</span>
                        <span className="text-[10px] text-slate-400 font-black">{person.role}</span>
                      </div>
                    </td>
                    <td className="px-8 py-5">
                      <div className="flex justify-center gap-2">
                        {(['حاضر', 'متأخر', 'غائب'] as AttendanceStatus[]).map(status => (
                          <button 
                            key={status} 
                            onClick={() => setStatus(person.id, status)} 
                            disabled={isReadOnly || isLockedForCoach}
                            className={`px-5 py-2.5 rounded-xl text-xs font-black border transition-all
                              ${currentStatus === status 
                                ? (status === 'حاضر' ? 'bg-green-600 text-white border-green-600 shadow-lg' : status === 'متأخر' ? 'bg-orange-500 text-white border-orange-500 shadow-lg' : 'bg-red-600 text-white border-red-600 shadow-lg') 
                                : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'
                              } ${isLockedForCoach ? 'opacity-60 cursor-not-allowed' : ''}`}
                          >
                            {status}
                          </button>
                        ))}
                      </div>
                    </td>
                    <td className="px-8 py-5 text-center">
                      {currentTime ? (
                        <div className="inline-flex items-center gap-2 bg-blue-50 text-blue-700 px-4 py-1.5 rounded-full text-xs font-black border border-blue-100">
                          {isManager && <Unlock size={12} className="text-emerald-500" />}
                          {!isManager && alreadySaved && <Lock size={12} className="text-blue-400" />}
                          <Clock size={14} /> {currentTime}
                        </div>
                      ) : (
                        <span className="text-slate-300 text-[10px] font-bold">لم يسجل</span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {players.length === 0 && (
            <div className="py-20 text-center text-slate-400 font-bold italic">لا يوجد أعضاء في هذه الفئة</div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AttendanceTracker;

import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Users, Search, X, Calendar as CalendarIcon, Hash, Fingerprint, Phone, User as UserIcon, Banknote, Hourglass, Edit } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isReadOnly = !isManager && (currentUser?.role === 'مشاهد' || currentUser?.role === 'مدرب');
  const restrictedCat = currentUser?.restrictedCategory;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPersonId, setEditingPersonId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || 'رجال',
    role: 'لاعب'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
      setFormData(prev => ({ ...prev, category: restrictedCat }));
    }
  }, [restrictedCat]);

  const calculateAge = (birthDate?: string) => {
    if (!birthDate) return '-';
    const birth = new Date(birthDate);
    const today = new Date();
    if (isNaN(birth.getTime())) return '-';
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const formatDateDisplay = (dateStr?: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('ar-EG', { 
      year: 'numeric', month: '2-digit', day: '2-digit', numberingSystem: 'latn' 
    });
  };

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleOpenEdit = (person: Person) => {
    if (!isManager) return;
    setEditingPersonId(person.id);
    setFormData(person);
    setIsModalOpen(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.name) return;

    if (editingPersonId) {
      setState(prev => ({
        ...prev,
        people: prev.people.map(p => p.id === editingPersonId ? { ...p, ...formData } as Person : p)
      }));
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        joinDate: new Date().toISOString().split('T')[0],
        ...(formData as Person)
      };
      setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    }

    setIsModalOpen(false);
    setEditingPersonId(null);
    setFormData({ category: restrictedCat || 'رجال', role: 'لاعب' });
  };

  const removePerson = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({ ...prev, people: prev.people.filter(p => p.id !== id) }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4 no-print">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black" />
          </div>

          {!isReadOnly && (
            <button onClick={() => { setEditingPersonId(null); setFormData({ category: restrictedCat || 'رجال', role: 'لاعب' }); setIsModalOpen(true); }}
              className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
              <UserPlus size={20} /> إضافة عضو
            </button>
          )}
        </div>

        {!restrictedCat && (
          <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max max-w-full overflow-x-auto no-scrollbar">
            <button onClick={() => setSelectedCategory('الكل')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>الكل</button>
            {categories.map(cat => (
              <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>{cat}</button>
            ))}
          </div>
        )}
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[1000px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العضو</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العمر</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center">الرقم</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العقود (للرجال)</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">الفئة / الدور</th>
                {!isReadOnly && <th className="px-6 py-5 text-slate-500 font-black text-xs text-center no-print">الإجراءات</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-black text-base">{person.name}</span>
                      <span className="text-[10px] text-slate-400 font-black">{person.phone || 'بدون هاتف'}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-sm font-black text-blue-900">{calculateAge(person.birthDate)} سنة</span>
                    <p className="text-[10px] text-slate-400 font-bold">{formatDateDisplay(person.birthDate)}</p>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="inline-flex items-center justify-center w-9 h-9 rounded-xl bg-slate-900 text-white text-xs font-black">{person.number || '-'}</span>
                  </td>
                  <td className="px-6 py-4">
                    {person.category === 'رجال' && person.contractValue ? (
                      <div className="text-[11px] space-y-0.5">
                        <div className="font-black text-emerald-700">{person.contractValue} ل.س</div>
                        <div className="text-slate-500 font-bold">حتى: {formatDateDisplay(person.contractEnd)}</div>
                      </div>
                    ) : <span className="text-[10px] text-slate-300 italic">-</span>}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex gap-1.5">
                      <span className="px-3 py-1 bg-blue-50 text-blue-700 rounded-lg text-[10px] font-black">{person.category}</span>
                      <span className="px-3 py-1 bg-slate-100 text-slate-600 rounded-lg text-[10px] font-black">{person.role}</span>
                    </div>
                  </td>
                  {!isReadOnly && (
                    <td className="px-6 py-4 text-center no-print space-x-reverse space-x-2">
                      {isManager && (
                        <button onClick={() => handleOpenEdit(person)} className="text-blue-500 hover:bg-blue-50 p-2 rounded-xl transition-all"><Edit size={18} /></button>
                      )}
                      <button onClick={() => removePerson(person.id)} className="text-slate-300 hover:text-red-600 p-2 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl shadow-2xl overflow-hidden my-auto">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50">
              <h3 className="text-xl font-black text-slate-800">{editingPersonId ? 'تعديل بيانات العضو' : 'إضافة عضو جديد'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-6 max-h-[70vh] overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div className="sm:col-span-2 space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">الاسم الثنائي</label>
                  <input required type="text" value={formData.name || ''} onChange={e => setFormData({ ...formData, name: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl py-4 px-6 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="الاسم والكنية" />
                </div>
                {!restrictedCat && (
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">الفئة</label>
                    <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                )}
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">الدور</label>
                  <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none" value={formData.role} onChange={e => setFormData({ ...formData, role: e.target.value as Role })}>
                    {roles.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">تاريخ الميلاد</label>
                  <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({ ...formData, birthDate: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">رقم الهاتف</label>
                  <input type="tel" value={formData.phone || ''} onChange={e => setFormData({ ...formData, phone: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black" placeholder="09xxxxxxxx" />
                </div>
              </div>

              {formData.category === 'رجال' && (
                <div className="space-y-5 pt-6 border-t animate-in slide-in-from-top-2 duration-300">
                  <h4 className="text-sm font-black text-emerald-700 flex items-center gap-2"><Banknote size={18} /> بيانات العقد المالي</h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">قيمة العقد</label>
                      <input type="text" value={formData.contractValue || ''} onChange={e => setFormData({ ...formData, contractValue: e.target.value })}
                        className="w-full bg-emerald-50 border-emerald-100 border rounded-2xl p-4 font-bold text-black" placeholder="ل.س" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">المدة</label>
                      <input type="text" value={formData.contractDuration || ''} onChange={e => setFormData({ ...formData, contractDuration: e.target.value })}
                        className="w-full bg-blue-50 border-blue-100 border rounded-2xl p-4 font-bold text-black" placeholder="مثال: سنة واحدة" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">بداية العقد</label>
                      <input type="date" value={formData.contractStart || ''} onChange={e => setFormData({ ...formData, contractStart: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">نهاية العقد</label>
                      <input type="date" value={formData.contractEnd || ''} onChange={e => setFormData({ ...formData, contractEnd: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black" />
                    </div>
                  </div>
                </div>
              )}

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-5 rounded-[1.5rem] shadow-xl hover:bg-black transition-all">
                {editingPersonId ? 'حفظ التغييرات' : 'إضافة العضو'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState, useEffect } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const TrainingPlanner: React.FC<TrainingPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const canEdit = isManager || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const formatDateDisplay = (dateStr?: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('ar-EG', { 
      year: 'numeric', month: '2-digit', day: '2-digit', numberingSystem: 'latn' 
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.location) return;

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
    } else {
      const newSession: TrainingSession = {
        id: Math.random().toString(36).substr(2, 9),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تدريب عام'
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const handleOpenEdit = (session: TrainingSession) => {
    if (!isManager) return;
    setEditingSessionId(session.id);
    setFormData(session);
    setIsModalOpen(true);
  };

  const removeSession = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا التمرين؟')) {
      setState(prev => ({ ...prev, sessions: prev.sessions.filter(s => s.id !== id) }));
    }
  };

  const filteredSessions = restrictedCat 
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول تمارين فئة ${restrictedCat}` : 'جدول التدريبات'}
        </h3>
        {canEdit && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-blue-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200">
            <Plus size={20} /> إضافة تمرين جديد
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 relative group overflow-hidden">
            {!isReadOnly && (
              <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-all flex gap-2">
                {isManager && (
                  <button onClick={() => handleOpenEdit(session)} className="bg-blue-50 text-blue-600 p-2 rounded-lg"><Edit size={16} /></button>
                )}
                <button onClick={() => removeSession(session.id)} className="bg-red-50 text-red-600 p-2 rounded-lg"><Trash2 size={16} /></button>
              </div>
            )}

            <div className="flex items-center gap-3 mb-4">
              <div className="bg-orange-50 text-orange-600 p-3 rounded-2xl">
                <Calendar size={24} />
              </div>
              <div>
                <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-1 rounded-md font-black uppercase">{session.category}</span>
                <h4 className="font-bold text-lg text-slate-800 mt-1">{session.objective}</h4>
              </div>
            </div>

            <div className="space-y-3 mt-4 pt-4 border-t border-slate-50 text-sm">
              <div className="flex items-center gap-3 text-slate-500">
                <MapPin size={18} className="text-orange-500" />
                <span className="font-bold text-slate-700">{session.location}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-500">
                <Clock size={18} className="text-blue-500" />
                <span className="font-black text-slate-700">{formatDateDisplay(session.date)} | {session.time}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">{editingSessionId ? 'تعديل التمرين' : 'إضافة تمرين'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">الفئة</label>
                <select className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold disabled:opacity-70"
                  value={formData.category} disabled={!!restrictedCat} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">التاريخ</label>
                  <input type="date" required value={formData.date || ''} className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الوقت</label>
                  <input type="time" required value={formData.time || ''} className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">المكان</label>
                <input type="text" required value={formData.location || ''} placeholder="اسم الملعب" className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">موضوع التمرين</label>
                <input type="text" value={formData.objective || ''} placeholder="مثال: تكتيك هجومي" className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold" onChange={e => setFormData({ ...formData, objective: e.target.value })} />
              </div>
              <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl mt-4 shadow-xl">حفظ البيانات</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TrainingPlanner;

export type Category = 'رجال' | 'شباب' | 'ناشئين' | 'أشبال';
export type Role = 'لاعب' | 'مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب' | 'مشاهد';

export interface Person {
  id: string;
  name: string; // الاسم الثنائي
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  federalNumber?: string;
  nationalId?: string;
  birthDate?: string;
  fatherName?: string;
  motherName?: string;
  // حقول العقد لفئة الرجال
  contractValue?: string;
  contractDuration?: string;
  contractStart?: string;
  contractEnd?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId?: string; // ربط الحضور بتمرين معين
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface GoalRecord {
  player: string;
  number: string;
  time: string;
}

export interface CardRecord {
  player: string;
  number: string;
  time: string;
  type: 'صفراء' | 'حمراء';
}

export interface SubstitutionRecord {
  playerIn: string;
  numberIn: string;
  playerOut: string;
  numberOut: string;
  time: string;
}

export interface LineupPlayer {
  name: string;
  number: string;
}

export interface MatchLineup {
  starters: LineupPlayer[];
  subs: LineupPlayer[];
