}

import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, FileText, History, Clock, Calendar as CalendarIcon, Filter, Lock, Unlock, ChevronDown, Activity, Users, AlertCircle } from 'lucide-react';
import { AppState, Category, AttendanceRecord, AttendanceStatus, TrainingSession } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

interface LocalRecord {
  status: AttendanceStatus;
  time: string;
  fullDate: string;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const canEdit = isManager || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [selectedCategory, setSelectedCategory] = useState<Category>(restrictedCat || 'رجال');
  const [selectedSessionId, setSelectedSessionId] = useState<string>('');
  const [localRecords, setLocalRecords] = useState<Record<string, LocalRecord>>({});
  const [showHistory, setShowHistory] = useState(false);
  const [statusFilter, setStatusFilter] = useState<AttendanceStatus | 'الكل'>('الكل');

  useEffect(() => {
    if (restrictedCat) setSelectedCategory(restrictedCat);
  }, [restrictedCat]);

  // تمارين الفئة المختارة مرتبة من الأحدث
  const categorySessions = state.sessions
    .filter(s => s.category === selectedCategory)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  // التعيين التلقائي لآخر تمرين عند تغيير الفئة
  useEffect(() => {
    if (categorySessions.length > 0 && !selectedSessionId) {
      setSelectedSessionId(categorySessions[0].id);
    } else if (categorySessions.length === 0) {
      setSelectedSessionId('');
    }
  }, [selectedCategory, categorySessions]);

  const selectedSession = state.sessions.find(s => s.id === selectedSessionId);
  const players = state.people.filter(p => p.category === selectedCategory && p.role === 'لاعب');

  const sessionRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  // حساب الإحصائيات
  const totalPlayers = players.length;
  const presentCount = sessionRecords.filter(r => r.status === 'حاضر').length;
  const lateCount = sessionRecords.filter(r => r.status === 'متأخر').length;
  const absentCount = sessionRecords.filter(r => r.status === 'غائب').length;
  const recordedCount = sessionRecords.length;

  const stats = {
    present: totalPlayers ? Math.round((presentCount / totalPlayers) * 100) : 0,
    late: totalPlayers ? Math.round((lateCount / totalPlayers) * 100) : 0,
    absent: totalPlayers ? Math.round((absentCount / totalPlayers) * 100) : 0,
    completion: totalPlayers ? Math.round((recordedCount / totalPlayers) * 100) : 0
  };

  const setStatus = (personId: string, status: AttendanceStatus) => {
    if (isReadOnly || !selectedSessionId) return;

    if (!isManager) {
      const alreadySaved = sessionRecords.some(r => r.personId === personId);
      if (alreadySaved) return;
    }

    const now = new Date();
    const time = now.toLocaleTimeString('ar-EG', { 
      hour: '2-digit', minute: '2-digit', hour12: true, numberingSystem: 'latn' 
    });
    const fullDate = now.toLocaleDateString('ar-EG', { 
      year: 'numeric', month: '2-digit', day: '2-digit', numberingSystem: 'latn'
    });

    setLocalRecords(prev => ({ 
      ...prev, 
      [personId]: { status, time, fullDate } 
    }));
  };

  const saveAttendance = () => {
    if (isReadOnly || !selectedSessionId) return;
    const recordsToSave = Object.entries(localRecords);
    if (recordsToSave.length === 0) {
      alert('الرجاء تحديد حالة حضور واحدة على الأقل');
      return;
    }

    const newRecords: AttendanceRecord[] = recordsToSave.map(([pid, record]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      sessionId: selectedSessionId,
      date: selectedSession?.date || new Date().toISOString().split('T')[0],
      time: record.time,
      status: record.status,
      note: `سجل في: ${record.fullDate}`
    }));

    setState(prev => {
      const filteredOldAttendance = prev.attendance.filter(a => 
        !(a.sessionId === selectedSessionId && localRecords[a.personId])
      );
      return { ...prev, attendance: [...filteredOldAttendance, ...newRecords] };
    });

    alert('تم حفظ سجل الحضور للتمرين بنجاح!');
    setLocalRecords({});
  };

  const filteredHistory = sessionRecords.filter(r => 
    statusFilter === 'الكل' ? true : r.status === statusFilter
  );

  return (
    <div className="space-y-6">
      {/* Header & Session Selector */}
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col lg:flex-row items-stretch lg:items-end justify-between gap-6 no-print">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 flex-1">
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-widest">الفئة</label>
            <select value={selectedCategory} disabled={!!restrictedCat}
              onChange={e => { setSelectedCategory(e.target.value as Category); setSelectedSessionId(''); setLocalRecords({}); }}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-black appearance-none disabled:opacity-70">
              <option value="رجال">رجال</option>
              <option value="شباب">شباب</option>
              <option value="ناشئين">ناشئين</option>
              <option value="أشبال">أشبال</option>
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 px-1 uppercase tracking-widest">اختر التمرين</label>
            <div className="relative">
              <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 outline-none font-bold text-black appearance-none pr-10">
                <option value="">-- اختر من جدول التمارين --</option>
                {categorySessions.map(s => (
                  <option key={s.id} value={s.id}>{s.date} - {s.objective}</option>
                ))}
              </select>
              <ChevronDown className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={18} />
            </div>
          </div>
        </div>

        <div className="flex flex-wrap gap-3">
          <button onClick={() => setShowHistory(!showHistory)}
            className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3.5 rounded-2xl font-bold transition-all border ${showHistory ? 'bg-orange-100 border-orange-200 text-orange-700' : 'bg-slate-50 border-slate-200 text-slate-600'}`}>
            <History size={20} /> {showHistory ? 'إغلاق الإحصائيات' : 'عرض الإحصائيات'}
          </button>
          {!showHistory && canEdit && (
            <button onClick={saveAttendance} className="flex-1 sm:flex-none bg-blue-600 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-xl shadow-blue-200 flex items-center justify-center gap-2">
              <Save size={20} /> حفظ الحضور
            </button>
          )}
          <button onClick={() => window.print()} className="flex-1 sm:flex-none bg-slate-900 text-white px-8 py-3.5 rounded-2xl font-bold hover:bg-black transition-all shadow-lg flex items-center justify-center gap-2">
            <FileText size={20} /> تقرير PDF
          </button>
        </div>
      </div>

      {!selectedSessionId && (
        <div className="bg-orange-50 border border-orange-100 p-8 rounded-[2rem] text-center no-print">
          <AlertCircle size={48} className="mx-auto text-orange-500 mb-4" />
          <h3 className="text-xl font-black text-orange-800">تنبيه: يجب اختيار تمرين أولاً</h3>
          <p className="text-orange-600 font-bold mt-1">قم بإضافة تمرين في "جدول التمارين" ليظهر هنا وتتمكن من تسجيل الحضور عليه.</p>
        </div>
      )}

      {selectedSession && (
        <div className="space-y-6">
          {/* Session Info & Stats Card */}
          <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
            <div className="bg-blue-900 text-white p-6 md:p-8 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div>
                <div className="flex items-center gap-2 mb-2">
                  <span className="bg-orange-600 px-3 py-0.5 rounded-lg text-[10px] font-black uppercase tracking-widest">تمرين {selectedCategory}</span>
                  <span className="text-blue-300 font-bold text-sm">{selectedSession.date}</span>
                </div>
                <h2 className="text-2xl font-black">{selectedSession.objective}</h2>
                <div className="flex items-center gap-4 mt-2 text-blue-100 text-sm font-bold">
                  <span className="flex items-center gap-1"><Clock size={14} /> {selectedSession.time}</span>
                  <span className="flex items-center gap-1"><Users size={14} /> العدد الإجمالي: {totalPlayers}</span>
                </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 w-full md:w-auto">
                <div className="bg-white/10 backdrop-blur-md p-3 rounded-2xl text-center border border-white/10">
                  <p className="text-[10px] font-black uppercase text-blue-200">حضور</p>
                  <p className="text-xl font-black">{stats.present}%</p>
                </div>
                <div className="bg-white/10 backdrop-blur-md p-3 rounded-2xl text-center border border-white/10">
                  <p className="text-[10px] font-black uppercase text-blue-200">تأخير</p>
                  <p className="text-xl font-black text-orange-400">{stats.late}%</p>
                </div>
                <div className="bg-white/10 backdrop-blur-md p-3 rounded-2xl text-center border border-white/10">
                  <p className="text-[10px] font-black uppercase text-blue-200">غياب</p>
                  <p className="text-xl font-black text-red-400">{stats.absent}%</p>
                </div>
                <div className="bg-white/20 backdrop-blur-md p-3 rounded-2xl text-center border border-white/20">
                  <p className="text-[10px] font-black uppercase text-white">اكتمال</p>
                  <p className="text-xl font-black">{stats.completion}%</p>
                </div>
              </div>
            </div>

            {/* Attendance List */}
            <div className="overflow-x-auto">
              <table className="w-full text-right">
                <thead>
                  <tr className="bg-slate-50 border-b border-slate-100">
                    <th className="px-8 py-5 text-slate-500 font-black text-xs uppercase tracking-widest">اللاعب</th>
                    <th className="px-8 py-5 text-slate-500 font-black text-xs uppercase tracking-widest text-center">حالة الحضور</th>
                    <th className="px-8 py-5 text-slate-500 font-black text-xs uppercase tracking-widest text-center">التوقيت</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {players.map(person => {
                    const savedRecord = sessionRecords.find(r => r.personId === person.id);
                    const localRecord = localRecords[person.id];
                    const currentStatus = localRecord?.status || savedRecord?.status;
                    const isLocked = savedRecord && !isManager;

                    return (
                      <tr key={person.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-8 py-5">
                          <div className="flex flex-col">
                            <span className="font-bold text-slate-900 text-lg">{person.name}</span>
                            <span className="text-[10px] text-slate-400 font-black">#{person.number || '0'}</span>
                          </div>
                        </td>
                        <td className="px-8 py-5">
                          <div className="flex justify-center gap-2">
                            {(['حاضر', 'متأخر', 'غائب'] as AttendanceStatus[]).map(status => (
                              <button 
                                key={status} 
                                onClick={() => setStatus(person.id, status)} 
                                disabled={isReadOnly || isLocked}
                                className={`min-w-[85px] px-5 py-2.5 rounded-xl text-xs font-black border transition-all
                                  ${currentStatus === status 
                                    ? (status === 'حاضر' ? 'bg-green-600 text-white border-green-600 shadow-lg' : status === 'متأخر' ? 'bg-orange-500 text-white border-orange-500 shadow-lg' : 'bg-red-600 text-white border-red-600 shadow-lg') 
                                    : (isLocked ? 'bg-slate-50 text-slate-200 border-slate-100' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300')
                                  } ${isLocked ? 'cursor-not-allowed opacity-60' : ''}`}
                              >
                                {status}
                              </button>
                            ))}
                          </div>
                        </td>
                        <td className="px-8 py-5 text-center">
                          {(localRecord || savedRecord) ? (
                            <div className="inline-flex items-center gap-2 bg-blue-50 text-blue-700 px-4 py-1.5 rounded-full text-[10px] font-black border border-blue-100">
                              {savedRecord ? (isManager ? <Unlock size={10} className="text-emerald-500" /> : <Lock size={10} />) : <Activity size={10} className="animate-pulse" />}
                              <Clock size={12} /> {localRecord?.time || savedRecord?.time}
                            </div>
                          ) : <span className="text-slate-300 text-[10px] font-bold">بانتظار التسجيل</span>}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              {players.length === 0 && (
                <div className="py-20 text-center text-slate-400 font-bold italic">لا يوجد لاعبين مضافين لهذه الفئة</div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* PRINT VERSION (تقرير تفصيلي) */}
      <div className="hidden print:block fixed inset-0 bg-white z-[999] p-12 overflow-y-auto print-only">
        {selectedSession && (
          <div className="space-y-10">
            <div className="flex justify-between items-start border-b-4 border-blue-900 pb-8">
              <div className="flex items-center gap-6">
                <div className="w-20 h-20 bg-blue-900 rounded-2xl flex items-center justify-center text-white font-black text-2xl">ك</div>
                <div>
                  <h1 className="text-3xl font-black text-blue-900">نادي الكرامة الرياضي</h1>
                  <p className="text-lg font-bold text-orange-600">تقرير حضور تمرين - فئة {selectedCategory}</p>
                </div>
              </div>
              <div className="text-left font-bold text-slate-500">
                <p>التاريخ: {selectedSession.date}</p>
                <p>الموضوع: {selectedSession.objective}</p>
              </div>
            </div>

            <div className="grid grid-cols-4 gap-6 py-8 bg-slate-50 rounded-3xl border-2 border-slate-100 text-center">
               <div className="space-y-1">
                 <p className="text-xs font-black text-slate-400 uppercase">العدد الكلي</p>
                 <p className="text-3xl font-black text-slate-800">{totalPlayers}</p>
               </div>
               <div className="space-y-1">
                 <p className="text-xs font-black text-green-600 uppercase">حضور</p>
                 <p className="text-3xl font-black text-green-700">{stats.present}% ({presentCount})</p>
               </div>
               <div className="space-y-1">
                 <p className="text-xs font-black text-orange-600 uppercase">تأخير</p>
                 <p className="text-3xl font-black text-orange-700">{stats.late}% ({lateCount})</p>
               </div>
               <div className="space-y-1">
                 <p className="text-xs font-black text-red-600 uppercase">غياب</p>
                 <p className="text-3xl font-black text-red-700">{stats.absent}% ({absentCount})</p>
               </div>
            </div>

            <table className="w-full text-right border-collapse">
               <thead className="bg-slate-900 text-white">
                 <tr>
                   <th className="p-4 border border-slate-800">اللاعب</th>
                   <th className="p-4 border border-slate-800 text-center">الرقم</th>
                   <th className="p-4 border border-slate-800 text-center">الحالة</th>
                   <th className="p-4 border border-slate-800 text-center">وقت التحضير</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-200">
                 {players.map(p => {
                   const record = sessionRecords.find(r => r.personId === p.id);
                   return (
                     <tr key={p.id}>
                       <td className="p-4 font-bold border border-slate-100">{p.name}</td>
                       <td className="p-4 text-center font-black border border-slate-100">#{p.number || '-'}</td>
                       <td className={`p-4 text-center font-black border border-slate-100 ${record?.status === 'حاضر' ? 'text-green-600' : record?.status === 'متأخر' ? 'text-orange-600' : 'text-red-600'}`}>
                         {record?.status || 'لم يسجل'}
                       </td>
                       <td className="p-4 text-center font-mono border border-slate-100">{record?.time || '-'}</td>
                     </tr>
                   );
                 })}
               </tbody>
            </table>

            <div className="pt-12 grid grid-cols-3 text-center font-black">
              <div className="space-y-10">
                <p>توقيع المدرب</p>
                <div className="h-px w-32 bg-slate-300 mx-auto"></div>
              </div>
              <div className="space-y-10">
                <p>إداري الفئة</p>
                <div className="h-px w-32 bg-slate-300 mx-auto"></div>
              </div>
              <div className="space-y-10">
                <p>خاتم النادي</p>
                <div className="h-20 w-20 border-2 border-slate-200 rounded-full mx-auto flex items-center justify-center text-[8px] rotate-12">AL-KARAMAH SC</div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AttendanceTracker;

import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Users, Search, X, Calendar as CalendarIcon, Hash, Fingerprint, Phone, User as UserIcon, Banknote, Hourglass, Edit } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isReadOnly = !isManager && (currentUser?.role === 'مشاهد' || currentUser?.role === 'مدرب');
  const restrictedCat = currentUser?.restrictedCategory;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPersonId, setEditingPersonId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || 'رجال',
    role: 'لاعب'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
      setFormData(prev => ({ ...prev, category: restrictedCat }));
    }
  }, [restrictedCat]);

  const calculateAge = (birthDate?: string) => {
    if (!birthDate) return '-';
    const birth = new Date(birthDate);
    const today = new Date();
    if (isNaN(birth.getTime())) return '-';
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const formatDateDisplay = (dateStr?: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('ar-EG', { 
      year: 'numeric', month: '2-digit', day: '2-digit', numberingSystem: 'latn' 
    });
  };

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleOpenEdit = (person: Person) => {
    if (!isManager) return;
    setEditingPersonId(person.id);
    setFormData(person);
    setIsModalOpen(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.name) return;

    if (editingPersonId) {
      setState(prev => ({
        ...prev,
        people: prev.people.map(p => p.id === editingPersonId ? { ...p, ...formData } as Person : p)
      }));
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        joinDate: new Date().toISOString().split('T')[0],
        ...(formData as Person)
      };
      setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    }

    setIsModalOpen(false);
    setEditingPersonId(null);
    setFormData({ category: restrictedCat || 'رجال', role: 'لاعب' });
  };

  const removePerson = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({ ...prev, people: prev.people.filter(p => p.id !== id) }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4 no-print">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black" />
          </div>

          {!isReadOnly && (
            <button onClick={() => { setEditingPersonId(null); setFormData({ category: restrictedCat || 'رجال', role: 'لاعب' }); setIsModalOpen(true); }}
              className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
              <UserPlus size={20} /> إضافة عضو
            </button>
          )}
        </div>

        {!restrictedCat && (
          <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max max-w-full overflow-x-auto no-scrollbar">
            <button onClick={() => setSelectedCategory('الكل')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>الكل</button>
            {categories.map(cat => (
              <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>{cat}</button>
            ))}
          </div>
        )}
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[1000px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العضو</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العمر</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center">الرقم</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العقود (للرجال)</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">الفئة / الدور</th>
                {!isReadOnly && <th className="px-6 py-5 text-slate-500 font-black text-xs text-center no-print">الإجراءات</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-black text-base">{person.name}</span>
                      <span className="text-[10px] text-slate-400 font-black">{person.phone || 'بدون هاتف'}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-sm font-black text-blue-900">{calculateAge(person.birthDate)} سنة</span>
                    <p className="text-[10px] text-slate-400 font-bold">{formatDateDisplay(person.birthDate)}</p>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="inline-flex items-center justify-center w-10 h-10 rounded-xl bg-slate-900 text-white text-sm font-black border-2 border-orange-500/30">
                      {person.number || '-'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    {person.category === 'رجال' && person.contractValue ? (
                      <div className="text-[11px] space-y-0.5">
                        <div className="font-black text-emerald-700">{person.contractValue} ل.س</div>
                        <div className="text-slate-500 font-bold">حتى: {formatDateDisplay(person.contractEnd)}</div>
                      </div>
                    ) : <span className="text-[10px] text-slate-300 italic">-</span>}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex gap-1.5">
                      <span className="px-3 py-1 bg-blue-50 text-blue-700 rounded-lg text-[10px] font-black">{person.category}</span>
                      <span className="px-3 py-1 bg-slate-100 text-slate-600 rounded-lg text-[10px] font-black">{person.role}</span>
                    </div>
                  </td>
                  {!isReadOnly && (
                    <td className="px-6 py-4 text-center no-print space-x-reverse space-x-2">
                      {isManager && (
                        <button onClick={() => handleOpenEdit(person)} className="text-blue-500 hover:bg-blue-50 p-2 rounded-xl transition-all"><Edit size={18} /></button>
                      )}
                      <button onClick={() => removePerson(person.id)} className="text-slate-300 hover:text-red-600 p-2 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl shadow-2xl overflow-hidden my-auto">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="p-2 bg-blue-900 text-white rounded-xl"><UserIcon size={24} /></div>
                 <h3 className="text-xl font-black text-slate-800">{editingPersonId ? 'تعديل بيانات العضو' : 'إضافة عضو جديد'}</h3>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-6 max-h-[70vh] overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div className="sm:col-span-2 space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">الاسم الثنائي</label>
                  <input required type="text" value={formData.name || ''} onChange={e => setFormData({ ...formData, name: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl py-4 px-6 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="الاسم والكنية" />
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">رقم القميص</label>
                  <div className="relative">
                    <Hash className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input type="number" value={formData.number || ''} onChange={e => setFormData({ ...formData, number: parseInt(e.target.value) || undefined })}
                      className="w-full bg-slate-100 border-none rounded-2xl py-4 pr-12 pl-4 focus:ring-2 focus:ring-orange-500 font-bold text-black" placeholder="مثلاً: 10" />
                  </div>
                </div>

                {!restrictedCat && (
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">الفئة</label>
                    <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                )}
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">الدور</label>
                  <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none" value={formData.role} onChange={e => setFormData({ ...formData, role: e.target.value as Role })}>
                    {roles.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">تاريخ الميلاد</label>
                  <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({ ...formData, birthDate: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 font-bold text-black" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500 mr-2">رقم الهاتف</label>
                  <input type="tel" value={formData.phone || ''} onChange={e => setFormData({ ...formData, phone: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black" placeholder="09xxxxxxxx" />
                </div>
              </div>

              {formData.category === 'رجال' && (
                <div className="space-y-5 pt-6 border-t animate-in slide-in-from-top-2 duration-300">
                  <h4 className="text-sm font-black text-emerald-700 flex items-center gap-2"><Banknote size={18} /> بيانات العقد المالي (فريق الرجال)</h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">قيمة العقد</label>
                      <input type="text" value={formData.contractValue || ''} onChange={e => setFormData({ ...formData, contractValue: e.target.value })}
                        className="w-full bg-emerald-50 border-emerald-100 border rounded-2xl p-4 font-bold text-black" placeholder="ل.س" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">المدة</label>
                      <input type="text" value={formData.contractDuration || ''} onChange={e => setFormData({ ...formData, contractDuration: e.target.value })}
                        className="w-full bg-blue-50 border-blue-100 border rounded-2xl p-4 font-bold text-black" placeholder="مثال: سنة واحدة" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">بداية العقد</label>
                      <input type="date" value={formData.contractStart || ''} onChange={e => setFormData({ ...formData, contractStart: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-black text-slate-500 mr-2">نهاية العقد</label>
                      <input type="date" value={formData.contractEnd || ''} onChange={e => setFormData({ ...formData, contractEnd: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black" />
                    </div>
                  </div>
                </div>
              )}

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-5 rounded-[1.5rem] shadow-xl hover:bg-black transition-all">
                {editingPersonId ? 'حفظ التغييرات' : 'إضافة العضو للمكتب'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, Trash2, Banknote, Calendar as CalendarIcon, Edit3, ClipboardList, Target, AlertTriangle, User, UserCheck, Repeat, FileText, Printer, ChevronDown, ChevronUp, Maximize2, Minimize2 } from 'lucide-react';
import { AppState, Match, Category, MatchLineup, GoalRecord, CardRecord, SubstitutionRecord, LineupPlayer, Person } from '../types';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [expandedReports, setExpandedReports] = useState<Record<string, boolean>>({});

  const [formData, setFormData] = useState<Partial<Match>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const toggleReport = (id: string) => {
    setExpandedReports(prev => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.opponent || !formData.location) return;

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      opponent: formData.opponent,
      location: formData.location,
      advancePayment: formData.advancePayment || '0',
      date: formData.date,
      time: formData.time || '16:00',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      goalList: [],
      cardList: [],
      lineupDetails: {
        starters: Array(11).fill({ name: '', number: '' }),
        subs: Array(11).fill({ name: '', number: '' }),
        captain: '',
        substitutionList: []
      }
    };

    setState(prev => ({
      ...prev,
      matches: [newMatch, ...prev.matches]
    }));
    setIsAddModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال' });
  };

  const handleUpdateResult = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMatch || isReadOnly) return;

    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === selectedMatch.id ? { ...selectedMatch, isCompleted: true } : m)
    }));
    setIsResultModalOpen(false);
    setSelectedMatch(null);
    if (selectedMatch.id) {
      setExpandedReports(prev => ({ ...prev, [selectedMatch.id]: true }));
    }
  };

  const removeMatch = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذه المباراة؟')) {
      setState(prev => ({
        ...prev,
        matches: prev.matches.filter(m => m.id !== id)
      }));
    }
  };

  const openResultModal = (match: Match) => {
    setSelectedMatch({ 
      ...match, 
      lineupDetails: match.lineupDetails || {
        starters: Array(11).fill({ name: '', number: '' }),
        subs: Array(11).fill({ name: '', number: '' }),
        captain: '',
        substitutionList: []
      },
      goalList: match.goalList || [],
      cardList: match.cardList || [],
      ourScore: match.ourScore || '0',
      opponentScore: match.opponentScore || '0'
    });
    setIsResultModalOpen(true);
  };

  // وظيفة اختيار اللاعب من القائمة وتحديث الاسم والرقم
  const handlePlayerSelect = (type: 'starters' | 'subs', index: number, personId: string) => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const person = state.people.find(p => p.id === personId);
    if (!person) return;

    const newLineup = { ...selectedMatch.lineupDetails };
    const players = [...newLineup[type]];
    players[index] = { name: person.name, number: person.number?.toString() || '' };
    newLineup[type] = players;
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const updateLineupPlayerManual = (type: 'starters' | 'subs', index: number, field: keyof LineupPlayer, value: string) => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const newLineup = { ...selectedMatch.lineupDetails };
    const players = [...newLineup[type]];
    players[index] = { ...players[index], [field]: value };
    newLineup[type] = players;
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const addGoalRow = () => {
    if (!selectedMatch) return;
    setSelectedMatch({
      ...selectedMatch,
      goalList: [...selectedMatch.goalList, { player: '', number: '', time: '' }]
    });
  };

  const addCardRow = () => {
    if (!selectedMatch) return;
    setSelectedMatch({
      ...selectedMatch,
      cardList: [...selectedMatch.cardList, { player: '', number: '', time: '', type: 'صفراء' }]
    });
  };

  const addSubstitutionRow = () => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const newLineup = { ...selectedMatch.lineupDetails };
    newLineup.substitutionList = [...newLineup.substitutionList, { playerIn: '', numberIn: '', playerOut: '', numberOut: '', time: '' }];
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const printReport = (match: Match) => {
    window.print();
  };

  const filteredMatches = restrictedCat 
    ? state.matches.filter(m => m.category === restrictedCat)
    : state.matches;

  // جلب لاعبي الفريق الخاص بالمباراة الحالية
  const matchCategoryPlayers = selectedMatch 
    ? state.people.filter(p => p.category === selectedMatch.category && p.role === 'لاعب')
    : [];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول مباريات فئة ${restrictedCat}` : 'جدول كافة مباريات النادي'}
        </h3>
        {canEdit && (
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-lg shadow-orange-200"
          >
            <Plus size={20} />
            إضافة مباراة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8 no-print">
        {filteredMatches.map(match => {
          const isExpanded = expandedReports[match.id];
          return (
            <div key={match.id} className={`bg-white rounded-[3rem] shadow-sm border ${match.isCompleted ? 'border-emerald-100' : 'border-slate-100'} overflow-hidden transition-all hover:shadow-xl`}>
              <div className={`px-8 py-3 flex justify-between items-center ${match.isCompleted ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-700'}`}>
                <div className="flex items-center gap-3">
                  <span className="text-xs font-black uppercase tracking-widest">{match.category}</span>
                </div>
                <div className="flex items-center gap-4">
                  {match.isCompleted && (
                    <>
                      <button 
                        onClick={() => toggleReport(match.id)} 
                        className={`text-xs font-black flex items-center gap-1.5 px-3 py-1 rounded-lg transition-colors ${isExpanded ? 'bg-emerald-100 text-emerald-800' : 'bg-white/50 hover:bg-white'}`}
                      >
                        {isExpanded ? (
                          <> <Minimize2 size={14} /> تصغير التقرير </>
                        ) : (
                          <> <Maximize2 size={14} /> عرض التقرير التفصيلي </>
                        )}
                      </button>
                      <button onClick={() => printReport(match)} className="text-xs font-black flex items-center gap-1 hover:underline">
                        <Printer size={14} /> طباعة
                      </button>
                    </>
                  )}
                  <span className="text-[10px] font-black uppercase">{match.isCompleted ? 'مباراة منتهية' : 'مباراة قادمة'}</span>
                </div>
              </div>

              <div className="p-8">
                <div className="flex flex-col md:flex-row items-center justify-between gap-12 mb-12">
                  <div className="flex-1 text-center">
                    <div className="w-20 h-20 bg-blue-900 rounded-[2rem] flex items-center justify-center mx-auto mb-4 shadow-lg">
                      <ClubLogo size={32} />
                    </div>
                    <h4 className="font-black text-xl text-slate-800">نادي الكرامة</h4>
                    {match.isCompleted && <div className="mt-2 text-5xl font-black text-blue-900">{match.ourScore}</div>}
                  </div>
                  <div className="flex flex-col items-center">
                    <div className="text-orange-500 font-black text-2xl mb-2">VS</div>
                    <div className="h-12 w-px bg-slate-100"></div>
                  </div>
