interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'مدرب'
  });

  const roles: UserRole[] = ['مدير', 'مدرب', 'مشاهد'];
  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.username) return;

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...formData } as AppUser : u)
      }));
    } else {
      const newUser: AppUser = {
        id: Math.random().toString(36).substr(2, 9),
        username: formData.username!,
        role: formData.role as UserRole,
        restrictedCategory: formData.role === 'مدير' ? undefined : formData.restrictedCategory
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
    }

    setIsModalOpen(false);
    setEditingUserId(null);
    setFormData({ username: '', role: 'مدرب' });
  };

  const deleteUser = (id: string, username: string) => {
    if (username === 'DR.MF.KALO' || id === state.currentUser?.id) {
      alert('لا يمكن حذف المدير الرئيسي أو حسابك الحالي.');
      return;
    }
    if (confirm(`هل أنت متأكد من حذف المستخدم ${username}؟`)) {
      setState(prev => ({ ...prev, users: prev.users.filter(u => u.id !== id) }));
    }
  };

  const exportToDrive = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();

    alert('تم تجهيز ملف النسخة الاحتياطية. يمكنك رفعه الآن إلى حسابك في Google Drive لضمان أمان البيانات.');
  };

  const resetData = () => {
    if (confirm('هل أنت متأكد من مسح جميع البيانات؟ لا يمكن التراجع عن هذا الإجراء.')) {
      localStorage.removeItem('alkaramah_data');
      window.location.reload();
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-8 pb-20">
      <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-8">
          <h3 className="text-xl font-black text-slate-800 flex items-center gap-3">
            <ShieldCheck className="text-blue-600" size={28} />
            إدارة صلاحيات المستخدمين
          </h3>
          <button 
            onClick={() => { setEditingUserId(null); setFormData({ username: '', role: 'مدرب' }); setIsModalOpen(true); }}
            className="bg-blue-900 text-white px-6 py-2 rounded-2xl font-black text-sm flex items-center gap-2 hover:bg-black transition-all shadow-lg shadow-blue-200"
          >
            <UserPlus size={18} /> إضافة مستخدم
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {state.users.map(user => (
            <div key={user.id} className="group flex items-center justify-between p-5 bg-slate-50 rounded-[2rem] border border-transparent hover:border-blue-200 hover:bg-white transition-all">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg ${user.role === 'مدير' ? 'bg-orange-600 text-white' : 'bg-blue-100 text-blue-600'}`}>
                  {user.username.charAt(0).toUpperCase()}
                </div>
                <div>
                  <p className="font-black text-slate-800">{user.username}</p>
                  <div className="flex items-center gap-2">
                    <span className={`text-[10px] font-black px-2 py-0.5 rounded-full ${user.role === 'مدير' ? 'bg-orange-100 text-orange-700' : 'bg-blue-50 text-blue-700'}`}>
                      {user.role}
                    </span>
                    {user.restrictedCategory && (
                      <span className="text-[10px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full font-bold">
                        فئة: {user.restrictedCategory}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={() => { setEditingUserId(user.id); setFormData(user); setIsModalOpen(true); }}
                  className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
                >
                  <Edit2 size={18} />
                </button>
                {user.username !== 'DR.MF.KALO' && (
                  <button 
                    onClick={() => deleteUser(user.id, user.username)}
                    className="p-2 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
                  >
                    <Trash2 size={18} />
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100">
        <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-3">
          <CloudUpload className="text-orange-600" size={28} />
          التخزين السحابي والنسخ الاحتياطي
        </h3>
        <div className="bg-blue-50 p-6 rounded-[2rem] border border-blue-100 flex gap-4 mb-8">
          <Info className="text-blue-600 shrink-0" size={24} />
          <p className="text-sm text-blue-800 font-bold leading-relaxed">
            للتخزين على حسابك في Google Drive: يرجى تصدير البيانات كملف JSON ورفعه يدوياً لضمان المزامنة والأمان. 
            يُنصح بالاحتفاظ بنسخة احتياطية أسبوعية على الأقل لجميع بيانات اللاعبين وسجلات الحضور.
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4">
          <button 
            onClick={exportToDrive}
            className="flex-1 bg-orange-600 text-white font-black py-5 rounded-[2rem] hover:bg-orange-700 transition-all shadow-xl shadow-orange-200 flex items-center justify-center gap-3 text-lg"
          >
            <CloudUpload size={24} />
            تصدير ملف النسخة الاحتياطية (JSON)
          </button>
          <button 
            onClick={resetData}
            className="sm:w-1/3 bg-red-50 text-red-600 font-black py-5 rounded-[2rem] hover:bg-red-100 transition-all flex items-center justify-center gap-2"
          >
            <ShieldAlert size={20} />
            تصفير النظام
          </button>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print">
          <div className="bg-white rounded-[3.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">
                {editingUserId ? 'تعديل صلاحيات المستخدم' : 'إضافة مستخدم جديد'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800 transition-transform hover:rotate-90">
                <X size={20} />
              </button>
            </div>
            <form onSubmit={handleSaveUser} className="p-8 space-y-6">
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-2">اسم المستخدم</label>
                <input 
                  required 
                  type="text" 
                  disabled={formData.username === 'DR.MF.KALO'}
                  value={formData.username || ''} 
                  onChange={e => setFormData({ ...formData, username: e.target.value })}
                  className="w-full bg-slate-100 border-none rounded-2xl py-4 px-6 focus:ring-2 focus:ring-blue-500 font-bold text-black disabled:opacity-50" 
                  placeholder="مثال: admin_kalo" 
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-2">نوع الصلاحية (الدور)</label>
                <select 
                  className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none"
                  value={formData.role}
                  onChange={e => setFormData({ ...formData, role: e.target.value as UserRole, restrictedCategory: e.target.value === 'مدير' ? undefined : formData.restrictedCategory })}
                >
                  {roles.map(r => <option key={r} value={r}>{r}</option>)}
                </select>
              </div>

              {formData.role !== 'مدير' && (
                <div className="space-y-1.5 animate-in slide-in-from-top-2 duration-300">
                  <label className="text-xs font-black text-slate-500 mr-2">الفئة المسؤولة (اختياري)</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none"
                    value={formData.restrictedCategory || ''}
                    onChange={e => setFormData({ ...formData, restrictedCategory: e.target.value as Category || undefined })}
                  >
                    <option value="">جميع الفئات</option>
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <p className="text-[10px] text-slate-400 font-bold mt-1 px-2">* سيتمكن المستخدم من رؤية وتعديل بيانات هذه الفئة فقط.</p>
                </div>
              )}

              <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100 flex gap-3">
                <Key className="text-orange-500 shrink-0" size={18} />
                <p className="text-[10px] text-orange-800 font-bold leading-relaxed">
                  ملاحظة: كلمات المرور افتراضية.<br/>
                  المدير: KSC@2026 | المدرب/المشاهد: KSC2026
                </p>
              </div>

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-5 rounded-[1.5rem] shadow-xl hover:bg-black transition-all">
                {editingUserId ? 'تحديث البيانات' : 'إنشاء الحساب'}
              </button>
            </form>
          </div>
        </div>
      )}

      <div className="bg-slate-100 p-8 rounded-[3rem] text-center">
        <p className="text-slate-500 text-sm font-black uppercase tracking-widest">نظام إدارة مكتب كرة القدم - نادي الكرامة الرياضي</p>
        <p className="text-slate-400 text-xs mt-1 font-bold">نسخة الإدارة الاحترافية 1.2.0 © 2024</p>
      </div>
    </div>
  );
};

export default SettingsView;

export type Category = 'رجال' | 'شباب' | 'ناشئين' | 'أشبال';
export type Role = 'لاعب' | 'مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب' | 'مشاهد';

export interface AppNotification {
  id: string;
  message: string;
  type: 'info' | 'success' | 'warning';
  timestamp: number;
}

export interface Person {
  id: string;
  name: string; // الاسم الثنائي
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  federalNumber?: string;
  nationalId?: string;
  birthDate?: string;
  birthPlace?: string; // مكان الميلاد
  fatherName?: string;
  motherName?: string;
  nationality?: string; // الجنسية
  khana?: string; // الخانة (القيد المدني)
  // حقول العقد لفئة الرجال
  contractValue?: string;
  contractDuration?: string;
  contractStart?: string;
  contractEnd?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId?: string; // ربط الحضور بتمرين معين
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface GoalRecord {
  player: string;
  number: string;
  time: string;
}

export interface CardRecord {
  player: string;
  number: string;
  time: string;
  type: 'صفراء' | 'حمراء';
}

export interface SubstitutionRecord {
  playerIn: string;
  numberIn: string;
  playerOut: string;
  numberOut: string;
  time: string;
}

export interface LineupPlayer {
  name: string;
  number: string;
}

export interface MatchLineup {
  starters: LineupPlayer[];
  subs: LineupPlayer[];
  captain: string;
  substitutionList: SubstitutionRecord[];
}

export interface Match {
  id: string;
  category: Category;
  opponent: string;
  location: string;
  advancePayment: string;
  date: string;
  time: string;
  isCompleted?: boolean;
  ourScore?: string;
  opponentScore?: string;
  goalList: GoalRecord[];
  cardList: CardRecord[];
  lineupDetails?: MatchLineup;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
}

import React, { useState, useEffect } from 'react';
import { 
  Users, 
  Calendar, 
  ClipboardCheck, 
  LayoutDashboard, 
  Settings, 
  LogOut, 
  Menu,
  X,
  Trophy,
  Bell,
  CheckCircle,
  AlertCircle
} from 'lucide-react';
import { 
  AppUser, 
  AppState,
  Category,
  AppNotification
} from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_data');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.matches) parsed.matches = [];
      if (!parsed.users) parsed.users = [];
      if (!parsed.notifications) parsed.notifications = [];

      const hasMainAdmin = parsed.users.some((u: AppUser) => u.username === 'DR.MF.KALO');
      if (!hasMainAdmin) {
        parsed.users.push({ id: 'admin-main', username: 'DR.MF.KALO', role: 'مدير' });
      }

      return parsed;
    }

    const mainAdmin: AppUser = { id: 'admin-main', username: 'DR.MF.KALO', role: 'مدير' };

    const admins = Array.from({ length: 5 }, (_, i) => ({
      id: `admin-${i + 1}`,
      username: `admin${i + 1}`,
      role: 'مدير' as const
    }));

    const categoryUsers: AppUser[] = [
      { id: 'u-men', username: 'MEN', role: 'مدرب', restrictedCategory: 'رجال' },
      { id: 'u-u18', username: 'U18', role: 'مدرب', restrictedCategory: 'شباب' },
      { id: 'u-u16', username: 'U16', role: 'مدرب', restrictedCategory: 'ناشئين' },
      { id: 'u-u14', username: 'U14', role: 'مدرب', restrictedCategory: 'أشبال' }
    ];

    return {
      people: [],
      attendance: [],
      sessions: [],
      matches: [],
      users: [mainAdmin, ...admins, ...categoryUsers],
      currentUser: null,
      notifications: []
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('alkaramah_data', JSON.stringify(state));
  }, [state]);

  // حذف الإشعارات القديمة تلقائياً بعد 5 ثوانٍ
  useEffect(() => {
    if (state.notifications.length > 0) {
      const timer = setTimeout(() => {
        setState(prev => ({
          ...prev,
          notifications: prev.notifications.slice(1)
        }));
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [state.notifications]);

  const handleLogin = (user: AppUser) => {
    setState(prev => ({ ...prev, currentUser: user }));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} state={state} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} />;
      case 'squad': return <SquadManagement state={state} setState={setState} />;
      case 'attendance': return <AttendanceTracker state={state} setState={setState} />;
      case 'training': return <TrainingPlanner state={state} setState={setState} />;
      case 'matches': return <MatchPlanner state={state} setState={setState} />;
      case 'settings': return <SettingsView state={state} setState={setState} />;
      default: return <Dashboard state={state} />;
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'الفئات واللاعبين', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'جدول التمارين', icon: Calendar },
    { id: 'matches', label: 'جدول المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات والمستخدمين', icon: Settings, adminOnly: true },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-['Tajawal'] text-right" dir="rtl">
      {/* Notifications Toast System */}
      <div className="fixed top-6 left-6 z-[200] space-y-3 pointer-events-none">
        {state.notifications.map((notif) => (
          <div key={notif.id} className="pointer-events-auto animate-in slide-in-from-left-8 duration-300">
            <div className={`flex items-center gap-4 px-6 py-4 rounded-[1.5rem] shadow-2xl border-2 backdrop-blur-md 
              ${notif.type === 'success' ? 'bg-emerald-50/90 border-emerald-100 text-emerald-800' : 'bg-blue-50/90 border-blue-100 text-blue-800'}`}>
              {notif.type === 'success' ? <CheckCircle size={24} className="text-emerald-500" /> : <Bell size={24} className="text-blue-500" />}
              <span className="font-black text-sm">{notif.message}</span>
              <button onClick={() => setState(prev => ({ ...prev, notifications: prev.notifications.filter(n => n.id !== notif.id) }))}
                className="hover:bg-black/5 p-1 rounded-lg transition-colors mr-2">
                <X size={16} />
              </button>
            </div>
          </div>
        ))}
      </div>

      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-blue-900 text-white transition-transform duration-300 transform md:relative md:translate-x-0 md:w-64 flex flex-col no-print ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex items-center justify-between border-b border-blue-800/50">
          <div className="flex items-center gap-3">
            <div className="bg-white p-1 rounded-xl shadow-lg">
              <ClubLogo size={42} />
            </div>
            <div className="overflow-hidden whitespace-nowrap">
              <h1 className="font-black text-lg leading-tight">نادي الكرامة</h1>
              <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">مكتب كرة القدم</p>
            </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="md:hidden text-blue-200"><X size={24} /></button>
        </div>

        <nav className="flex-1 mt-6 px-4 space-y-2 overflow-y-auto">
          {menuItems.map((item) => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/40' : 'hover:bg-blue-800 text-blue-100'}`}>
                <Icon size={22} /><span className="font-bold">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-6 border-t border-blue-800">
          <button onClick={handleLogout} className="w-full flex items-center gap-4 p-4 rounded-2xl text-red-300 hover:bg-red-900/30 transition-all font-bold">
            <LogOut size={22} /><span>تسجيل الخروج</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden w-full">
        <header className="bg-white border-b px-4 md:px-8 py-4 flex items-center justify-between no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="p-2 hover:bg-slate-100 rounded-xl text-slate-600 md:hidden"><Menu size={24} /></button>
            <h2 className="text-lg md:text-xl font-black text-slate-800 truncate">{menuItems.find(m => m.id === activeTab)?.label}</h2>
          </div>
          <div className="flex items-center gap-3">
            <div className="hidden sm:flex flex-col text-left items-end">
              <span className="font-black text-sm text-slate-700">{state.currentUser?.username}</span>
              <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded-full text-slate-500 font-bold">{state.currentUser?.role} {state.currentUser?.restrictedCategory ? `(${state.currentUser.restrictedCategory})` : ''}</span>
            </div>
            <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center font-black shadow-sm border border-orange-200 uppercase">{state.currentUser?.username?.charAt(0)}</div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">{renderContent()}</div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit } from 'lucide-react';
import { AppState, TrainingSession, Category, AppNotification } from '../types';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const TrainingPlanner: React.FC<TrainingPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const canEdit = isManager || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const formatDateDisplay = (dateStr?: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('ar-EG', { 
      year: 'numeric', month: '2-digit', day: '2-digit', numberingSystem: 'latn' 
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.location) return;

    const newNotif: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message: editingSessionId ? `تم تعديل التمرين بنجاح` : `تمت إضافة تمرين جديد لفئة ${formData.category}`,
      type: 'success',
      timestamp: Date.now()
    };

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s),
        notifications: [newNotif, ...prev.notifications]
      }));
    } else {
      const newSession: TrainingSession = {
        id: Math.random().toString(36).substr(2, 9),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تدريب عام'
      };
      setState(prev => ({ 
        ...prev, 
        sessions: [newSession, ...prev.sessions],
        notifications: [newNotif, ...prev.notifications]
      }));
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const handleOpenEdit = (session: TrainingSession) => {
    if (!isManager) return;
    setEditingSessionId(session.id);
    setFormData(session);
    setIsModalOpen(true);
  };

  const removeSession = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا التمرين؟')) {
      setState(prev => ({ ...prev, sessions: prev.sessions.filter(s => s.id !== id) }));
    }
  };

  const filteredSessions = restrictedCat 
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول تمارين فئة ${restrictedCat}` : 'جدول التدريبات'}
        </h3>
        {canEdit && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-blue-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200">
            <Plus size={20} /> إضافة تمرين جديد
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 relative group overflow-hidden">
            {!isReadOnly && (
              <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-all flex gap-2">
                {isManager && (
                  <button onClick={() => handleOpenEdit(session)} className="bg-blue-50 text-blue-600 p-2 rounded-lg"><Edit size={16} /></button>
                )}
                <button onClick={() => removeSession(session.id)} className="bg-red-50 text-red-600 p-2 rounded-lg"><Trash2 size={16} /></button>
              </div>
            )}

            <div className="flex items-center gap-3 mb-4">
              <div className="bg-orange-50 text-orange-600 p-3 rounded-2xl">
                <Calendar size={24} />
              </div>
              <div>
                <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-1 rounded-md font-black uppercase">{session.category}</span>
                <h4 className="font-bold text-lg text-slate-800 mt-1">{session.objective}</h4>
              </div>
            </div>

            <div className="space-y-3 mt-4 pt-4 border-t border-slate-50 text-sm">
              <div className="flex items-center gap-3 text-slate-500">
                <MapPin size={18} className="text-orange-500" />
                <span className="font-bold text-slate-700">{session.location}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-500">
                <Clock size={18} className="text-blue-500" />
                <span className="font-black text-slate-700">{formatDateDisplay(session.date)} | {session.time}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">{editingSessionId ? 'تعديل التمرين' : 'إضافة تمرين'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">الفئة</label>
                <select className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold disabled:opacity-70"
                  value={formData.category} disabled={!!restrictedCat} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">التاريخ</label>
                  <input type="date" required value={formData.date || ''} className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الوقت</label>
                  <input type="time" required value={formData.time || ''} className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">المكان</label>
                <input type="text" required value={formData.location || ''} placeholder="اسم الملعب" className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">موضوع التمرين</label>
                <input type="text" value={formData.objective || ''} placeholder="مثال: تكتيك هجومي" className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold" onChange={e => setFormData({ ...formData, objective: e.target.value })} />
              </div>
              <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl mt-4 shadow-xl">حفظ البيانات</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

