const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_data');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.matches) parsed.matches = [];
      if (!parsed.users) parsed.users = [];
      if (!parsed.notifications) parsed.notifications = [];

      const hasMainAdmin = parsed.users.some((u: AppUser) => u.username === 'DR.MF.KALO');
      if (!hasMainAdmin) {
        parsed.users.push({ id: 'admin-main', username: 'DR.MF.KALO', role: 'مدير' });
      }

      return parsed;
    }

    const mainAdmin: AppUser = { id: 'admin-main', username: 'DR.MF.KALO', role: 'مدير' };

    const admins = Array.from({ length: 5 }, (_, i) => ({
      id: `admin-${i + 1}`,
      username: `admin${i + 1}`,
      role: 'مدير' as const
    }));

    const categoryUsers: AppUser[] = [
      { id: 'u-men', username: 'MEN', role: 'مدرب', restrictedCategory: 'رجال' },
      { id: 'u-u18', username: 'U18', role: 'مدرب', restrictedCategory: 'شباب' },
      { id: 'u-u16', username: 'U16', role: 'مدرب', restrictedCategory: 'ناشئين' },
      { id: 'u-u14', username: 'U14', role: 'مدرب', restrictedCategory: 'أشبال' }
    ];

    return {
      people: [],
      attendance: [],
      sessions: [],
      matches: [],
      users: [mainAdmin, ...admins, ...categoryUsers],
      currentUser: null,
      notifications: []
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [selectedPlayerForReport, setSelectedPlayerForReport] = useState<Person | null>(null);

  useEffect(() => {
    localStorage.setItem('alkaramah_data', JSON.stringify(state));
  }, [state]);

  useEffect(() => {
    if (state.notifications.length > 0) {
      const timer = setTimeout(() => {
        setState(prev => ({
          ...prev,
          notifications: prev.notifications.slice(1)
        }));
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [state.notifications]);

  const handleLogin = (user: AppUser) => {
    setState(prev => ({ ...prev, currentUser: user }));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
  };

  const openPlayerReport = (player: Person) => {
    setSelectedPlayerForReport(player);
    setActiveTab('player-report');
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} state={state} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} />;
      case 'squad': return <SquadManagement state={state} setState={setState} onOpenReport={openPlayerReport} />;
      case 'attendance': return <AttendanceTracker state={state} setState={setState} />;
      case 'training': return <TrainingPlanner state={state} setState={setState} />;
      case 'matches': return <MatchPlanner state={state} setState={setState} />;
      case 'settings': return <SettingsView state={state} setState={setState} />;
      case 'player-report': return <PlayerReport state={state} player={selectedPlayerForReport} onBack={() => setActiveTab('squad')} />;
      default: return <Dashboard state={state} />;
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'الفئات واللاعبين', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'جدول التمارين', icon: Calendar },
    { id: 'matches', label: 'جدول المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات والمستخدمين', icon: Settings, adminOnly: true },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-['Tajawal'] text-right" dir="rtl">
      <div className="fixed top-6 left-6 z-[200] space-y-3 pointer-events-none">
        {state.notifications.map((notif) => (
          <div key={notif.id} className="pointer-events-auto animate-in slide-in-from-left-8 duration-300">
            <div className={`flex items-center gap-4 px-6 py-4 rounded-[1.5rem] shadow-2xl border-2 backdrop-blur-md 
              ${notif.type === 'success' ? 'bg-emerald-50/90 border-emerald-100 text-emerald-800' : 'bg-blue-50/90 border-blue-100 text-blue-800'}`}>
              {notif.type === 'success' ? <CheckCircle size={24} className="text-emerald-500" /> : <Bell size={24} className="text-blue-500" />}
              <span className="font-black text-sm">{notif.message}</span>
              <button onClick={() => setState(prev => ({ ...prev, notifications: prev.notifications.filter(n => n.id !== notif.id) }))}
                className="hover:bg-black/5 p-1 rounded-lg transition-colors mr-2">
                <X size={16} />
              </button>
            </div>
          </div>
        ))}
      </div>

      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-blue-900 text-white transition-transform duration-300 transform md:relative md:translate-x-0 md:w-64 flex flex-col no-print ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex items-center justify-between border-b border-blue-800/50">
          <div className="flex items-center gap-3">
            <div className="bg-white p-1 rounded-xl shadow-lg">
              <ClubLogo size={42} />
            </div>
            <div className="overflow-hidden whitespace-nowrap">
              <h1 className="font-black text-lg leading-tight">نادي الكرامة</h1>
              <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">مكتب كرة القدم</p>
            </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="md:hidden text-blue-200"><X size={24} /></button>
        </div>

        <nav className="flex-1 mt-6 px-4 space-y-2 overflow-y-auto">
          {menuItems.map((item) => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); setSelectedPlayerForReport(null); }}
                className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/40' : 'hover:bg-blue-800 text-blue-100'}`}>
                <Icon size={22} /><span className="font-bold">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-6 border-t border-blue-800">
          <button onClick={handleLogout} className="w-full flex items-center gap-4 p-4 rounded-2xl text-red-300 hover:bg-red-900/30 transition-all font-bold">
            <LogOut size={22} /><span>تسجيل الخروج</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden w-full">
        <header className="bg-white border-b px-4 md:px-8 py-4 flex items-center justify-between no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="p-2 rounded-xl text-slate-600 md:hidden"><Menu size={24} /></button>
            <h2 className="text-lg md:text-xl font-black text-slate-800 truncate">
              {activeTab === 'player-report' ? `تقرير اللاعب: ${selectedPlayerForReport?.name}` : menuItems.find(m => m.id === activeTab)?.label}
            </h2>
          </div>
          <div className="flex items-center gap-3">
            <div className="hidden sm:flex flex-col text-left items-end">
              <span className="font-black text-sm text-slate-700">{state.currentUser?.username}</span>
              <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded-full text-slate-500 font-bold">{state.currentUser?.role} {state.currentUser?.restrictedCategory ? `(${state.currentUser.restrictedCategory})` : ''}</span>
            </div>
            <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center font-black shadow-sm border border-orange-200 uppercase">{state.currentUser?.username?.charAt(0)}</div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">{renderContent()}</div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Users, Search, X, Calendar as CalendarIcon, Hash, Fingerprint, Phone, User as UserIcon, Banknote, Hourglass, Edit, MapPin, CreditCard, Shield, Globe, BookOpen, FileBarChart } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport }) => {
  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const restrictedCat = currentUser?.restrictedCategory;

  const canModify = isManager || !!restrictedCat;
  const isReadOnly = !canModify;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPersonId, setEditingPersonId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || 'رجال',
    role: 'لاعب',
    nationality: 'سوري'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
      setFormData(prev => ({ ...prev, category: restrictedCat }));
    }
  }, [restrictedCat]);

  const calculateAge = (birthDate?: string) => {
    if (!birthDate) return null;
    const birth = new Date(birthDate);
    const today = new Date();
    if (isNaN(birth.getTime())) return null;
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const formatDateDisplay = (dateStr?: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('ar-EG', { 
      year: 'numeric', month: '2-digit', day: '2-digit', numberingSystem: 'latn' 
    });
  };

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleOpenEdit = (person: Person) => {
    if (!isManager && restrictedCat && person.category !== restrictedCat) return;
    setEditingPersonId(person.id);
    setFormData(person);
    setIsModalOpen(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.name) return;

    const finalCategory = restrictedCat || (formData.category as Category);

    if (editingPersonId) {
      setState(prev => ({
        ...prev,
        people: prev.people.map(p => p.id === editingPersonId ? { ...p, ...formData, category: finalCategory } as Person : p)
      }));
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        joinDate: new Date().toISOString().split('T')[0],
        ...(formData as Person),
        category: finalCategory
      };
      setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    }

    setIsModalOpen(false);
    setEditingPersonId(null);
    setFormData({ category: restrictedCat || 'رجال', role: 'لاعب', nationality: 'سوري' });
  };

  const removePerson = (id: string) => {
    if (isReadOnly) return;
    const person = state.people.find(p => p.id === id);
    if (!isManager && restrictedCat && person?.category !== restrictedCat) return;

    if (confirm('هل أنت متأكد من حذف هذا العضو؟')) {
      setState(prev => ({ ...prev, people: prev.people.filter(p => p.id !== id) }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4 no-print">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black" />
          </div>

          {!isReadOnly && (
            <button onClick={() => { setEditingPersonId(null); setFormData({ category: restrictedCat || 'رجال', role: 'لاعب', nationality: 'سوري' }); setIsModalOpen(true); }}
              className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
              <UserPlus size={20} /> إضافة عضو جديد
            </button>
          )}
        </div>

        {!restrictedCat && (
          <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max max-w-full overflow-x-auto no-scrollbar">
            <button onClick={() => setSelectedCategory('الكل')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>الكل</button>
            {categories.map(cat => (
              <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>{cat}</button>
            ))}
          </div>
        )}
        {restrictedCat && (
          <div className="bg-blue-50 px-6 py-3 rounded-2xl border border-blue-100 inline-block">
            <span className="text-blue-700 font-black text-sm flex items-center gap-2">
               <Shield size={16} /> أنت تدير فئة: {restrictedCat}
            </span>
          </div>
        )}
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[1300px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العضو والتفاصيل الشخصية</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العمر والميلاد</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center">الرقم</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">بيانات الهوية والقيد</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">الفئة / الدور</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center no-print">الإجراءات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => {
                const canEditThisPerson = isManager || (restrictedCat === person.category);

                return (
                  <tr key={person.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="font-bold text-black text-base">{person.name}</span>
                        <div className="flex gap-3 text-[10px] text-slate-400 font-black mt-0.5">
                          {person.fatherName && <span>الأب: {person.fatherName}</span>}
                          {person.motherName && <span>الأم: {person.motherName}</span>}
                        </div>
                        <div className="flex items-center gap-2 mt-1">
                          <span className="text-[10px] text-blue-600 font-black">{person.phone || 'بدون هاتف'}</span>
                          {person.nationality && (
                            <span className="flex items-center gap-1 text-[9px] bg-slate-100 px-1.5 py-0.5 rounded text-slate-500 font-bold">
                              <Globe size={10} /> {person.nationality}
                            </span>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="text-sm font-black text-blue-900">{calculateAge(person.birthDate) ?? '-'} سنة</span>
                        <p className="text-[10px] text-slate-400 font-bold">{formatDateDisplay(person.birthDate)}</p>
                        {person.birthPlace && <p className="text-[9px] text-slate-500 font-black flex items-center gap-1 mt-0.5"><MapPin size={10}/> {person.birthPlace}</p>}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <span className="inline-flex items-center justify-center w-10 h-10 rounded-xl bg-slate-900 text-white text-sm font-black border-2 border-orange-500/30">
                        {person.number || '-'}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-[10px] space-y-1">
                        {person.nationalId && <div className="flex items-center gap-1 text-slate-600 font-black"><CreditCard size={12} className="text-slate-400"/> الوطني: {person.nationalId}</div>}
                        {person.khana && <div className="flex items-center gap-1 text-slate-600 font-black"><BookOpen size={12} className="text-slate-400"/> الخانة: {person.khana}</div>}
                        {person.federalNumber && <div className="flex items-center gap-1 text-blue-700 font-black"><Shield size={12} className="text-blue-300"/> الاتحادي: {person.federalNumber}</div>}
                        {!person.nationalId && !person.federalNumber && !person.khana && <span className="text-slate-300 italic">غير مسجل</span>}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex gap-1.5">
                        <span className="px-3 py-1 bg-blue-50 text-blue-700 rounded-lg text-[10px] font-black">{person.category}</span>
                        <span className="px-3 py-1 bg-slate-100 text-slate-600 rounded-lg text-[10px] font-black">{person.role}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center no-print space-x-reverse space-x-2">
                      <div className="flex items-center justify-center gap-2">
                        {person.role === 'لاعب' && onOpenReport && (
                          <button 
                            onClick={() => onOpenReport(person)} 
                            title="عرض تقرير اللاعب"
                            className="text-emerald-600 hover:bg-emerald-50 p-2 rounded-xl transition-all"
                          >
                            <FileBarChart size={18} />
                          </button>
                        )}
                        {canEditThisPerson && (
                          <>
                            <button onClick={() => handleOpenEdit(person)} className="text-blue-500 hover:bg-blue-50 p-2 rounded-xl transition-all"><Edit size={18} /></button>
                            {!isReadOnly && <button onClick={() => removePerson(person.id)} className="text-slate-300 hover:text-red-600 p-2 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>}
                          </>
                        )}
                        {!canEditThisPerson && <Shield size={16} className="text-slate-200" />}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl shadow-2xl overflow-hidden my-auto">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50">
              <div className="flex items-center gap-3">
                 <div className="p-2 bg-blue-900 text-white rounded-xl"><UserIcon size={24} /></div>
                 <h3 className="text-xl font-black text-slate-800">{editingPersonId ? 'تعديل بيانات العضو' : 'إضافة عضو جديد للمكتب'}</h3>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-8 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <div className="space-y-4">
                <h4 className="text-xs font-black text-blue-900 uppercase tracking-widest flex items-center gap-2">
                  <span className="w-1.5 h-4 bg-orange-500 rounded-full"></span>
                  المعلومات الشخصية الأساسية
                </h4>
                <div className="grid grid-cols-1 sm:grid-cols-4 gap-5">
                  <div className="sm:col-span-3 space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">الاسم الثنائي (اللاعب)</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({ ...formData, name: e.target.value })}
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl py-4 px-6 focus:ring-2 focus:ring-blue-500 font-bold text-black" placeholder="الاسم والكنية" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">رقم القميص</label>
                    <div className="relative">
                      <Hash className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input type="number" value={formData.number || ''} onChange={e => setFormData({ ...formData, number: parseInt(e.target.value) || undefined })}
                        className="w-full bg-slate-50 border border-slate-200 rounded-2xl py-4 pr-12 pl-4 focus:ring-2 focus:ring-orange-500 font-bold text-black" placeholder="10" />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">اسم الأب</label>
                    <input type="text" value={formData.fatherName || ''} onChange={e => setFormData({ ...formData, fatherName: e.target.value })}
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold text-black" placeholder="اسم الأب" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">اسم الأم</label>
                    <input type="text" value={formData.motherName || ''} onChange={e => setFormData({ ...formData, motherName: e.target.value })}
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold text-black" placeholder="اسم الأم" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">الجنسية</label>
                    <div className="relative">
                      <Globe className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="text" value={formData.nationality || ''} onChange={e => setFormData({ ...formData, nationality: e.target.value })}
                        className="w-full bg-slate-50 border border-slate-200 rounded-2xl py-4 pr-11 pl-4 font-bold text-black" placeholder="سوري" />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500 mr-2">رقم الهاتف</label>
                    <div className="relative">
                      <Phone className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="tel" value={formData.phone || ''} onChange={e => setFormData({ ...formData, phone: e.target.value })}
                        className="w-full bg-slate-50 border border-slate-200 rounded-2xl py-4 pr-11 pl-4 font-bold text-black" placeholder="09xxxxxxxx" />
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-4 border-t border-slate-100">
                <h4 className="text-xs font-black text-blue-900 uppercase tracking-widest flex items-center gap-2">
                  <span className="w-1.5 h-4 bg-blue-500 rounded-full"></span>
                  الميلاد والعمر
                </h4>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-5 items-end">
