import React, { useState, useEffect } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit } from 'lucide-react';
import { AppState, TrainingSession, Category, AppNotification } from '../types';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const TrainingPlanner: React.FC<TrainingPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const canEdit = isManager || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const formatDateDisplay = (dateStr?: string) => {
    if (!dateStr) return '-';
    return new Date(dateStr).toLocaleDateString('ar-EG', { 
      year: 'numeric', month: '2-digit', day: '2-digit', numberingSystem: 'latn' 
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.location) return;

    const newNotif: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message: editingSessionId ? `تم تعديل التمرين بنجاح` : `تمت إضافة تمرين جديد لفئة ${formData.category}`,
      type: 'success',
      timestamp: Date.now()
    };

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s),
        notifications: [newNotif, ...prev.notifications]
      }));
    } else {
      const newSession: TrainingSession = {
        id: Math.random().toString(36).substr(2, 9),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تدريب عام'
      };
      setState(prev => ({ 
        ...prev, 
        sessions: [newSession, ...prev.sessions],
        notifications: [newNotif, ...prev.notifications]
      }));
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const handleOpenEdit = (session: TrainingSession) => {
    if (!isManager) return;
    setEditingSessionId(session.id);
    setFormData(session);
    setIsModalOpen(true);
  };

  const removeSession = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذا التمرين؟')) {
      setState(prev => ({ ...prev, sessions: prev.sessions.filter(s => s.id !== id) }));
    }
  };

  const filteredSessions = restrictedCat 
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول تمارين فئة ${restrictedCat}` : 'جدول التدريبات'}
        </h3>
        {canEdit && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-blue-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200">
            <Plus size={20} /> إضافة تمرين جديد
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 relative group overflow-hidden">
            {!isReadOnly && (
              <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-all flex gap-2">
                {isManager && (
                  <button onClick={() => handleOpenEdit(session)} className="bg-blue-50 text-blue-600 p-2 rounded-lg"><Edit size={16} /></button>
                )}
                <button onClick={() => removeSession(session.id)} className="bg-red-50 text-red-600 p-2 rounded-lg"><Trash2 size={16} /></button>
              </div>
            )}

            <div className="flex items-center gap-3 mb-4">
              <div className="bg-orange-50 text-orange-600 p-3 rounded-2xl">
                <Calendar size={24} />
              </div>
              <div>
                <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-1 rounded-md font-black uppercase">{session.category}</span>
                <h4 className="font-bold text-lg text-slate-800 mt-1">{session.objective}</h4>
              </div>
            </div>

            <div className="space-y-3 mt-4 pt-4 border-t border-slate-50 text-sm">
              <div className="flex items-center gap-3 text-slate-500">
                <MapPin size={18} className="text-orange-500" />
                <span className="font-bold text-slate-900">{session.location}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-500">
                <Clock size={18} className="text-blue-500" />
                <span className="font-black text-slate-900">{formatDateDisplay(session.date)} | {session.time}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">{editingSessionId ? 'تعديل التمرين' : 'إضافة تمرين'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600"><Plus className="rotate-45" /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">الفئة</label>
                <select className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold text-slate-950 disabled:opacity-70"
                  value={formData.category} disabled={!!restrictedCat} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">التاريخ</label>
                  <input type="date" required value={formData.date || ''} className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold text-slate-950" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الوقت</label>
                  <input type="time" required value={formData.time || ''} className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold text-slate-950" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">المكان</label>
                <input type="text" required value={formData.location || ''} placeholder="اسم الملعب" className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold text-slate-950" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">موضوع التمرين</label>
                <input type="text" value={formData.objective || ''} placeholder="مثال: تكتيك هجومي" className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold text-slate-950" onChange={e => setFormData({ ...formData, objective: e.target.value })} />
              </div>
              <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl mt-4 shadow-xl">حفظ البيانات</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TrainingPlanner;

import React, { useState, useEffect } from 'react';
import { Trophy, MapPin, Clock, Plus, Trash2, Banknote, Calendar as CalendarIcon, Edit3, ClipboardList, Target, AlertTriangle, User, UserCheck, Repeat, FileText, Printer, ChevronDown, ChevronUp, Maximize2, Minimize2 } from 'lucide-react';
import { AppState, Match, Category, MatchLineup, GoalRecord, CardRecord, SubstitutionRecord, LineupPlayer, Person, AppNotification } from '../types';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);
  const [expandedReports, setExpandedReports] = useState<Record<string, boolean>>({});

  const [formData, setFormData] = useState<Partial<Match>>({
    category: restrictedCat || 'رجال'
  });

  const categories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

  useEffect(() => {
    if (restrictedCat) setFormData(prev => ({ ...prev, category: restrictedCat }));
  }, [restrictedCat]);

  const toggleReport = (id: string) => {
    setExpandedReports(prev => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly || !formData.date || !formData.opponent || !formData.location) return;

    const newNotif: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message: `تمت جدولة مباراة جديدة ضد ${formData.opponent} لفئة ${formData.category}`,
      type: 'success',
      timestamp: Date.now()
    };

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      opponent: formData.opponent,
      location: formData.location,
      advancePayment: formData.advancePayment || '0',
      date: formData.date,
      time: formData.time || '16:00',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      goalList: [],
      cardList: [],
      lineupDetails: {
        starters: Array(11).fill({ name: '', number: '' }),
        subs: Array(11).fill({ name: '', number: '' }),
        captain: '',
        substitutionList: []
      }
    };

    setState(prev => ({
      ...prev,
      matches: [newMatch, ...prev.matches],
      notifications: [newNotif, ...prev.notifications]
    }));
    setIsAddModalOpen(false);
    setFormData({ category: restrictedCat || 'رجال' });
  };

  const handleUpdateResult = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMatch || isReadOnly) return;

    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === selectedMatch.id ? { ...selectedMatch, isCompleted: true } : m)
    }));
    setIsResultModalOpen(false);
    setSelectedMatch(null);
    if (selectedMatch.id) {
      setExpandedReports(prev => ({ ...prev, [selectedMatch.id]: true }));
    }
  };

  const removeMatch = (id: string) => {
    if (isReadOnly) return;
    if (confirm('هل أنت متأكد من حذف هذه المباراة؟')) {
      setState(prev => ({
        ...prev,
        matches: prev.matches.filter(m => m.id !== id)
      }));
    }
  };

  const openResultModal = (match: Match) => {
    setSelectedMatch({ 
      ...match, 
      lineupDetails: match.lineupDetails || {
        starters: Array(11).fill({ name: '', number: '' }),
        subs: Array(11).fill({ name: '', number: '' }),
        captain: '',
        substitutionList: []
      },
      goalList: match.goalList || [],
      cardList: match.cardList || [],
      ourScore: match.ourScore || '0',
      opponentScore: match.opponentScore || '0'
    });
    setIsResultModalOpen(true);
  };

  const handlePlayerSelect = (type: 'starters' | 'subs', index: number, personId: string) => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const person = state.people.find(p => p.id === personId);
    if (!person) return;

    const newLineup = { ...selectedMatch.lineupDetails };
    const players = [...newLineup[type]];
    players[index] = { name: person.name, number: person.number?.toString() || '' };
    newLineup[type] = players;
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const addGoalRow = () => {
    if (!selectedMatch) return;
    setSelectedMatch({
      ...selectedMatch,
      goalList: [...selectedMatch.goalList, { player: '', number: '', time: '' }]
    });
  };

  const addCardRow = () => {
    if (!selectedMatch) return;
    setSelectedMatch({
      ...selectedMatch,
      cardList: [...selectedMatch.cardList, { player: '', number: '', time: '', type: 'صفراء' }]
    });
  };

  const addSubstitutionRow = () => {
    if (!selectedMatch || !selectedMatch.lineupDetails) return;
    const newLineup = { ...selectedMatch.lineupDetails };
    newLineup.substitutionList = [...newLineup.substitutionList, { playerIn: '', numberIn: '', playerOut: '', numberOut: '', time: '' }];
    setSelectedMatch({ ...selectedMatch, lineupDetails: newLineup });
  };

  const printReport = (match: Match) => {
    window.print();
  };

  const filteredMatches = restrictedCat 
    ? state.matches.filter(m => m.category === restrictedCat)
    : state.matches;

  const matchCategoryPlayers = selectedMatch 
    ? state.people.filter(p => p.category === selectedMatch.category && p.role === 'لاعب')
    : [];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">
          {restrictedCat ? `جدول مباريات فئة ${restrictedCat}` : 'جدول كافة مباريات النادي'}
        </h3>
        {canEdit && (
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold hover:bg-orange-700 transition-all shadow-lg shadow-orange-200"
          >
            <Plus size={20} />
            إضافة مباراة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-8 no-print">
        {filteredMatches.map(match => {
          const isExpanded = expandedReports[match.id];
          return (
            <div key={match.id} className={`bg-white rounded-[3rem] shadow-sm border ${match.isCompleted ? 'border-emerald-100' : 'border-slate-100'} overflow-hidden transition-all hover:shadow-xl`}>
              <div className={`px-8 py-3 flex justify-between items-center ${match.isCompleted ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-700'}`}>
                <div className="flex items-center gap-3">
                  <span className="text-xs font-black uppercase tracking-widest">{match.category}</span>
                </div>
                <div className="flex items-center gap-4">
                  {match.isCompleted && (
                    <>
                      <button 
                        onClick={() => toggleReport(match.id)} 
                        className={`text-xs font-black flex items-center gap-1.5 px-3 py-1 rounded-lg transition-colors ${isExpanded ? 'bg-emerald-100 text-emerald-800' : 'bg-white/50 hover:bg-white'}`}
                      >
                        {isExpanded ? (
                          <> <Minimize2 size={14} /> تصغير التقرير </>
                        ) : (
                          <> <Maximize2 size={14} /> عرض التقرير التفصيلي </>
