                    <input type="text" placeholder="المدة" className="bg-blue-50 border-blue-100 border rounded-2xl p-4 font-bold text-slate-950" value={formData.contractDuration || ''} onChange={e => setFormData({...formData, contractDuration: e.target.value})} />
