import ClubLogo from './components/ClubLogo';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_data');
    const defaultCategories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.matches) parsed.matches = [];
      if (!parsed.users) parsed.users = [];
      if (!parsed.notifications) parsed.notifications = [];
      if (!parsed.categories) parsed.categories = defaultCategories;

      const hasMainAdmin = parsed.users.some((u: AppUser) => u.username === 'DR.MF.KALO');
      if (!hasMainAdmin) {
        parsed.users.push({ id: 'admin-main', username: 'DR.MF.KALO', role: 'مدير' });
      }

      return parsed;
    }

    const mainAdmin: AppUser = { id: 'admin-main', username: 'DR.MF.KALO', role: 'مدير' };

    const admins = Array.from({ length: 5 }, (_, i) => ({
      id: `admin-${i + 1}`,
      username: `admin${i + 1}`,
      role: 'مدير' as const
    }));

    const categoryUsers: AppUser[] = [
      { id: 'u-men', username: 'MEN', role: 'مدرب', restrictedCategory: 'رجال' },
      { id: 'u-u18', username: 'U18', role: 'مدرب', restrictedCategory: 'شباب' },
      { id: 'u-u16', username: 'U16', role: 'مدرب', restrictedCategory: 'ناشئين' },
      { id: 'u-u14', username: 'U14', role: 'مدرب', restrictedCategory: 'أشبال' }
    ];

    return {
      people: [],
      attendance: [],
      sessions: [],
      matches: [],
      categories: defaultCategories,
      users: [mainAdmin, ...admins, ...categoryUsers],
      currentUser: null,
      notifications: []
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [selectedPlayerForReport, setSelectedPlayerForReport] = useState<Person | null>(null);

  useEffect(() => {
    localStorage.setItem('alkaramah_data', JSON.stringify(state));
  }, [state]);

  useEffect(() => {
    if (state.notifications.length > 0) {
      const timer = setTimeout(() => {
        setState(prev => ({
          ...prev,
          notifications: prev.notifications.slice(1)
        }));
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [state.notifications]);

  const handleLogin = (user: AppUser) => {
    setState(prev => ({ ...prev, currentUser: user }));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
  };

  const openPlayerReport = (player: Person) => {
    setSelectedPlayerForReport(player);
    setActiveTab('player-report');
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} state={state} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} />;
      case 'squad': return <SquadManagement state={state} setState={setState} onOpenReport={openPlayerReport} />;
      case 'attendance': return <AttendanceTracker state={state} setState={setState} />;
      case 'training': return <TrainingPlanner state={state} setState={setState} />;
      case 'matches': return <MatchPlanner state={state} setState={setState} />;
      case 'settings': return <SettingsView state={state} setState={setState} />;
      case 'player-report': return <PlayerReport state={state} player={selectedPlayerForReport} onBack={() => setActiveTab('squad')} />;
      default: return <Dashboard state={state} />;
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'الفئات واللاعبين', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'جدول التمارين', icon: Calendar },
    { id: 'matches', label: 'جدول المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات والمستخدمين', icon: Settings, adminOnly: true },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-['Tajawal'] text-right" dir="rtl">
      <div className="fixed top-6 left-6 z-[200] space-y-3 pointer-events-none">
        {state.notifications.map((notif) => (
          <div key={notif.id} className="pointer-events-auto animate-in slide-in-from-left-8 duration-300">
            <div className={`flex items-center gap-4 px-6 py-4 rounded-[1.5rem] shadow-2xl border-2 backdrop-blur-md 
              ${notif.type === 'success' ? 'bg-emerald-50/90 border-emerald-100 text-emerald-800' : 'bg-blue-50/90 border-blue-100 text-blue-800'}`}>
              {notif.type === 'success' ? <CheckCircle size={24} className="text-emerald-500" /> : <Bell size={24} className="text-blue-500" />}
              <span className="font-black text-sm">{notif.message}</span>
              <button onClick={() => setState(prev => ({ ...prev, notifications: prev.notifications.filter(n => n.id !== notif.id) }))}
                className="hover:bg-black/5 p-1 rounded-lg transition-colors mr-2">
                <X size={16} />
              </button>
            </div>
          </div>
        ))}
      </div>

      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-blue-900 text-white transition-transform duration-300 transform md:relative md:translate-x-0 md:w-64 flex flex-col no-print ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex items-center justify-between border-b border-blue-800/50">
          <div className="flex items-center gap-3">
            <div className="bg-white p-1 rounded-xl shadow-lg">
              <ClubLogo size={42} />
            </div>
            <div className="overflow-hidden whitespace-nowrap">
              <h1 className="font-black text-lg leading-tight">نادي الكرامة</h1>
              <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">مكتب كرة القدم</p>
            </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="md:hidden text-blue-200"><X size={24} /></button>
        </div>

        <nav className="flex-1 mt-6 px-4 space-y-2 overflow-y-auto">
          {menuItems.map((item) => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); setSelectedPlayerForReport(null); }}
                className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/40' : 'hover:bg-blue-800 text-blue-100'}`}>
                <Icon size={22} /><span className="font-bold">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-6 border-t border-blue-800">
          <button onClick={handleLogout} className="w-full flex items-center gap-4 p-4 rounded-2xl text-red-300 hover:bg-red-900/30 transition-all font-bold">
            <LogOut size={22} /><span>تسجيل الخروج</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden w-full">
        <header className="bg-white border-b px-4 md:px-8 py-4 flex items-center justify-between no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="p-2 rounded-xl text-slate-600 md:hidden"><Menu size={24} /></button>
            <h2 className="text-lg md:text-xl font-black text-slate-800 truncate">
              {activeTab === 'player-report' ? `تقرير اللاعب: ${selectedPlayerForReport?.name}` : menuItems.find(m => m.id === activeTab)?.label}
            </h2>
          </div>
          <div className="flex items-center gap-3">
            <div className="hidden sm:flex flex-col text-left items-end">
              <span className="font-black text-sm text-slate-700">{state.currentUser?.username}</span>
              <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded-full text-slate-500 font-bold">{state.currentUser?.role} {state.currentUser?.restrictedCategory ? `(${state.currentUser.restrictedCategory})` : ''}</span>
            </div>
            <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center font-black shadow-sm border border-orange-200 uppercase">{state.currentUser?.username?.charAt(0)}</div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 md:p-8 flex flex-col">
          <div className="max-w-7xl mx-auto flex-1 w-full">
            {renderContent()}
          </div>

          <footer className="mt-12 py-8 border-t border-slate-200 text-center no-print">
            <p className="text-slate-500 text-sm font-black uppercase tracking-widest">
              نظام إدارة مكتب كرة القدم - نادي الكرامة الرياضي
            </p>
            <p className="text-slate-400 text-xs mt-2 font-bold">
              Izzat Amer Alshikha 2026
            </p>
          </footer>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Search, X, Hash, Phone, User as UserIcon, Banknote, Edit, MapPin, CreditCard, Shield, Globe, BookOpen, FileBarChart, Layers, Plus } from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport }) => {
  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const restrictedCat = currentUser?.restrictedCategory;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [editingPersonId, setEditingPersonId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'رجال'),
    role: 'لاعب',
    nationality: 'سوري'
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'إداري', 'طبيب'];

  const calculateAge = (birthDate?: string) => {
    if (!birthDate) return null;
    const birth = new Date(birthDate);
    const today = new Date();
    if (isNaN(birth.getTime())) return null;
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const finalCategory = restrictedCat || (formData.category as Category);

    if (editingPersonId) {
      setState(prev => ({
        ...prev,
        people: prev.people.map(p => p.id === editingPersonId ? { ...p, ...formData, category: finalCategory } as Person : p)
      }));
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        joinDate: new Date().toISOString().split('T')[0],
        ...(formData as Person),
        category: finalCategory
      };
      setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    }

    setIsModalOpen(false);
    setEditingPersonId(null);
    setFormData({ category: restrictedCat || (state.categories[0] || 'رجال'), role: 'لاعب', nationality: 'سوري' });
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) {
      alert('هذه الفئة موجودة مسبقاً');
      return;
    }

    setState(prev => ({
      ...prev,
      categories: [...prev.categories, newCatName.trim()],
      notifications: [{
        id: Math.random().toString(36).substr(2, 9),
        message: `تمت إضافة فئة "${newCatName}" بنجاح`,
        type: 'success',
        timestamp: Date.now()
      }]
    }));
    setNewCatName('');
    setIsCatModalOpen(false);
  };

  const deleteCategory = (cat: Category) => {
    if (state.people.some(p => p.category === cat)) {
      alert('لا يمكن حذف الفئة لأنها تحتوي على لاعبين أو كوادر. يرجى نقلهم أو حذفهم أولاً.');
      return;
    }
    if (confirm(`هل أنت متأكد من حذف فئة ${cat}؟`)) {
      setState(prev => ({
        ...prev,
        categories: prev.categories.filter(c => c !== cat)
      }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4 no-print">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-950" />
          </div>

          <div className="flex gap-2">
            {isManager && (
              <button onClick={() => setIsCatModalOpen(true)}
                className="bg-blue-100 text-blue-700 px-6 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-blue-200 transition-all">
                <Layers size={20} /> إضافة فئة
              </button>
            )}
            {(isManager || !!restrictedCat) && (
              <button onClick={() => { setEditingPersonId(null); setIsModalOpen(true); }}
                className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
                <UserPlus size={20} /> إضافة عضو
              </button>
            )}
          </div>
        </div>

        {!restrictedCat && (
          <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max max-w-full overflow-x-auto no-scrollbar">
            <button onClick={() => setSelectedCategory('الكل')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>الكل</button>
            {state.categories.map(cat => (
              <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>{cat}</button>
            ))}
          </div>
        )}
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[1200px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs">الاسم والتفاصيل</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العمر والميلاد</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center">الرقم</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">بيانات القيد</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center no-print">تقرير فني</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center no-print">تحكم</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <span className="font-bold text-slate-950 text-base block">{person.name}</span>
                    <span className="text-[10px] text-slate-400 font-black block">{person.phone || 'بدون هاتف'}</span>
                    <span className="text-[9px] text-blue-600 font-bold">{person.category}</span>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-sm font-black text-blue-900 block">{calculateAge(person.birthDate) ?? '-'} سنة</span>
                    <span className="text-[10px] text-slate-400 font-bold">{person.birthDate}</span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="inline-flex items-center justify-center w-10 h-10 rounded-xl bg-slate-900 text-white text-sm font-black border-2 border-orange-500/30">
                      {person.number || '-'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-[10px] space-y-1 font-black">
                      <div className="flex items-center gap-1 text-slate-700"><CreditCard size={12}/> {person.nationalId || 'لا يوجد'}</div>
                      <div className="flex items-center gap-1 text-blue-800"><Shield size={12}/> {person.federalNumber || 'لا يوجد'}</div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center no-print">
                    {person.role === 'لاعب' && onOpenReport && (
                      <button onClick={() => onOpenReport(person)} 
                        className="bg-emerald-50 text-emerald-600 p-3 rounded-2xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm">
                        <FileBarChart size={20} />
                      </button>
                    )}
                  </td>
                  <td className="px-6 py-4 text-center no-print">
                    <div className="flex items-center justify-center gap-2">
                       {(isManager || restrictedCat === person.category) && (
                         <>
                           <button onClick={() => { setEditingPersonId(person.id); setFormData(person); setIsModalOpen(true); }} className="text-blue-500 p-2 hover:bg-blue-50 rounded-xl"><Edit size={18} /></button>
                           <button onClick={() => { if(confirm('حذف؟')) setState(prev => ({...prev, people: prev.people.filter(p => p.id !== person.id)})); }} className="text-red-400 p-2 hover:bg-red-50 rounded-xl"><Trash2 size={18} /></button>
                         </>
                       )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* مودال إدارة الفئات */}
      {isCatModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[150] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden my-auto">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50">
               <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Layers size={22} className="text-blue-600"/> إدارة الفئات الرياضية</h3>
               <button onClick={() => setIsCatModalOpen(false)} className="bg-slate-200 p-2 rounded-xl"><X size={20} /></button>
            </div>
            <div className="p-8 space-y-6">
              <form onSubmit={handleAddCategory} className="flex gap-2">
                <input required type="text" value={newCatName} onChange={e => setNewCatName(e.target.value)}
                  placeholder="اسم الفئة الجديدة..."
                  className="flex-1 bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950 placeholder:text-slate-400" />
                <button type="submit" className="bg-blue-900 text-white px-6 rounded-2xl font-black">إضافة</button>
              </form>

              <div className="space-y-2">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-2">الفئات الحالية</p>
                <div className="grid grid-cols-1 gap-2">
                  {state.categories.map(cat => (
                    <div key={cat} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <span className="font-black text-slate-800">{cat}</span>
                      <button onClick={() => deleteCategory(cat)} className="text-red-400 hover:text-red-600 p-1"><Trash2 size={16}/></button>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl shadow-2xl overflow-hidden my-auto">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50">
               <h3 className="text-xl font-black text-slate-800">{editingPersonId ? 'تعديل البيانات' : 'إضافة عضو جديد'}</h3>
               <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="md:col-span-2 space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الاسم الثنائي</label>
                  <input required type="text" value={formData.name || ''} onChange={e => setFormData({ ...formData, name: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">رقم القميص</label>
                  <input type="number" value={formData.number || ''} onChange={e => setFormData({ ...formData, number: parseInt(e.target.value) || undefined })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">تاريخ الميلاد</label>
                  <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({ ...formData, birthDate: e.target.value })}
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950" />
                </div>
                <div className="space-y-1.5">
                   <label className="text-xs font-black text-slate-500">الفئة</label>
                   <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950 outline-none" 
                     value={formData.category} disabled={!!restrictedCat} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                     {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                   </select>
                </div>
                <div className="space-y-1.5">
                   <label className="text-xs font-black text-slate-500">الدور</label>
                   <select className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950 outline-none" 
                     value={formData.role} onChange={e => setFormData({ ...formData, role: e.target.value as Role })}>
                     {roles.map(r => <option key={r} value={r}>{r}</option>)}
                   </select>
                </div>
              </div>

              {(formData.category === 'رجال') && (
                <div className="space-y-4 pt-6 border-t animate-in slide-in-from-top-2">
                  <h4 className="text-sm font-black text-emerald-800 flex items-center gap-2"><Banknote size={18} /> بيانات العقد (فئة الرجال)</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input type="text" placeholder="قيمة العقد" className="bg-emerald-50 border-emerald-100 border rounded-2xl p-4 font-bold text-slate-950" value={formData.contractValue || ''} onChange={e => setFormData({...formData, contractValue: e.target.value})} />
                    <input type="text" placeholder="المدة" className="bg-blue-50 border-blue-100 border rounded-2xl p-4 font-bold text-slate-950" value={formData.contractDuration || ''} onChange={e => setFormData({...formData, contractDuration: e.target.value})} />
                  </div>
                </div>
              )}

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-5 rounded-[1.5rem] shadow-xl hover:bg-black transition-all">
                {editingPersonId ? 'حفظ التغييرات' : 'تسجيل العضو رسمياً'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState } from 'react';
import { ShieldCheck, CloudUpload, Trash2, Key, Info, UserPlus, X, Edit2, ShieldAlert } from 'lucide-react';
import { AppState, AppUser, UserRole, Category } from '../types';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'مدرب'
  });

  const roles: UserRole[] = ['مدير', 'مدرب', 'مشاهد'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.username) return;

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...formData } as AppUser : u)
      }));
    } else {
      const newUser: AppUser = {
        id: Math.random().toString(36).substr(2, 9),
        username: formData.username!,
        role: formData.role as UserRole,
        restrictedCategory: formData.role === 'مدير' ? undefined : formData.restrictedCategory
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
    }

    setIsModalOpen(false);
    setEditingUserId(null);
    setFormData({ username: '', role: 'مدرب' });
  };

  const deleteUser = (id: string, username: string) => {
    if (username === 'DR.MF.KALO' || id === state.currentUser?.id) {
      alert('لا يمكن حذف المدير الرئيسي أو حسابك الحالي.');
      return;
    }
    if (confirm(`هل أنت متأكد من حذف المستخدم ${username}؟`)) {
      setState(prev => ({ ...prev, users: prev.users.filter(u => u.id !== id) }));
    }
  };

  const exportToDrive = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();

    alert('تم تجهيز ملف النسخة الاحتياطية. يمكنك رفعه الآن إلى حسابك في Google Drive لضمان أمان البيانات.');
  };

  const resetData = () => {
    if (confirm('هل أنت متأكد من مسح جميع البيانات؟ لا يمكن التراجع عن هذا الإجراء.')) {
      localStorage.removeItem('alkaramah_data');
      window.location.reload();
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-8 pb-20">
      <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-8">
          <h3 className="text-xl font-black text-slate-800 flex items-center gap-3">
            <ShieldCheck className="text-blue-600" size={28} />
            إدارة صلاحيات المستخدمين
          </h3>
          <button 
            onClick={() => { setEditingUserId(null); setFormData({ username: '', role: 'مدرب' }); setIsModalOpen(true); }}
            className="bg-blue-900 text-white px-6 py-2 rounded-2xl font-black text-sm flex items-center gap-2 hover:bg-black transition-all shadow-lg shadow-blue-200"
          >
            <UserPlus size={18} /> إضافة مستخدم
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {state.users.map(user => (
            <div key={user.id} className="group flex items-center justify-between p-5 bg-slate-50 rounded-[2rem] border border-transparent hover:border-blue-200 hover:bg-white transition-all">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg ${user.role === 'مدير' ? 'bg-orange-600 text-white' : 'bg-blue-100 text-blue-600'}`}>
                  {user.username.charAt(0).toUpperCase()}
                </div>
                <div>
                  <p className="font-black text-slate-800">{user.username}</p>
                  <div className="flex items-center gap-2">
                    <span className={`text-[10px] font-black px-2 py-0.5 rounded-full ${user.role === 'مدير' ? 'bg-orange-100 text-orange-700' : 'bg-blue-50 text-blue-700'}`}>
                      {user.role}
                    </span>
                    {user.restrictedCategory && (
                      <span className="text-[10px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full font-bold">
                        فئة: {user.restrictedCategory}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={() => { setEditingUserId(user.id); setFormData(user); setIsModalOpen(true); }}
                  className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
                >
                  <Edit2 size={18} />
                </button>
                {user.username !== 'DR.MF.KALO' && (
                  <button 
                    onClick={() => deleteUser(user.id, user.username)}
                    className="p-2 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
                  >
                    <Trash2 size={18} />
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100">
        <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-3">
          <CloudUpload className="text-orange-600" size={28} />
          التخزين السحابي والنسخ الاحتياطي
        </h3>
        <div className="bg-blue-50 p-6 rounded-[2rem] border border-blue-100 flex gap-4 mb-8">
          <Info className="text-blue-600 shrink-0" size={24} />
          <p className="text-sm text-blue-800 font-bold leading-relaxed">
            للتخزين على حسابك في Google Drive: يرجى تصدير البيانات كملف JSON ورفعه يدوياً لضمان المزامنة والأمان. 
            يُنصح بالاحتفاظ بنسخة احتياطية أسبوعية على الأقل لجميع بيانات اللاعبين وسجلات الحضور.
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4">
          <button 
            onClick={exportToDrive}
            className="flex-1 bg-orange-600 text-white font-black py-5 rounded-[2rem] hover:bg-orange-700 transition-all shadow-xl shadow-orange-200 flex items-center justify-center gap-3 text-lg"
          >
            <CloudUpload size={24} />
            تصدير ملف النسخة الاحتياطية (JSON)
          </button>
          <button 
            onClick={resetData}
            className="sm:w-1/3 bg-red-50 text-red-600 font-black py-5 rounded-[2rem] hover:bg-red-100 transition-all flex items-center justify-center gap-2"
          >
            <ShieldAlert size={20} />
            تصفير النظام
          </button>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print">
          <div className="bg-white rounded-[3.5rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">
                {editingUserId ? 'تعديل صلاحيات المستخدم' : 'إضافة مستخدم جديد'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-slate-800 transition-transform hover:rotate-90">
                <X size={20} />
              </button>
            </div>
            <form onSubmit={handleSaveUser} className="p-8 space-y-6">
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-2">اسم المستخدم</label>
                <input 
                  required 
                  type="text" 
                  disabled={formData.username === 'DR.MF.KALO'}
                  value={formData.username || ''} 
                  onChange={e => setFormData({ ...formData, username: e.target.value })}
                  className="w-full bg-slate-100 border-none rounded-2xl py-4 px-6 focus:ring-2 focus:ring-blue-500 font-bold text-black disabled:opacity-50" 
                  placeholder="مثال: admin_kalo" 
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500 mr-2">نوع الصلاحية (الدور)</label>
                <select 
                  className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none"
                  value={formData.role}
                  onChange={e => setFormData({ ...formData, role: e.target.value as UserRole, restrictedCategory: e.target.value === 'مدير' ? undefined : formData.restrictedCategory })}
                >
                  {roles.map(r => <option key={r} value={r}>{r}</option>)}
                </select>
              </div>

              {formData.role !== 'مدير' && (
                <div className="space-y-1.5 animate-in slide-in-from-top-2 duration-300">
                  <label className="text-xs font-black text-slate-500 mr-2">الفئة المسؤولة (اختياري)</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-black outline-none"
                    value={formData.restrictedCategory || ''}
                    onChange={e => setFormData({ ...formData, restrictedCategory: e.target.value as Category || undefined })}
                  >
                    <option value="">جميع الفئات</option>
                    {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <p className="text-[10px] text-slate-400 font-bold mt-1 px-2">* سيتمكن المستخدم من رؤية وتعديل بيانات هذه الفئة فقط.</p>
                </div>
              )}

              <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100 flex gap-3">
                <Key className="text-orange-500 shrink-0" size={18} />
                <p className="text-[10px] text-orange-800 font-bold leading-relaxed">
                  ملاحظة: كلمات المرور افتراضية.<br/>
                  المدير: KSC@2026 | المدرب/المشاهد: KSC2026
                </p>
              </div>

              <button type="submit" className="w-full bg-blue-900 text-white font-black py-5 rounded-[1.5rem] shadow-xl hover:bg-black transition-all">
                {editingUserId ? 'تحديث البيانات' : 'إنشاء الحساب'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SettingsView;

import React from 'react';
import { Users, Calendar, AlertCircle, TrendingUp, Trophy } from 'lucide-react';
import { AppState, Category } from '../types';

interface DashboardProps {
  state: AppState;
}

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // Filter data based on user restriction
  const filteredPeople = restrictedCat 
    ? state.people.filter(p => p.category === restrictedCat)
    : state.people;

  const filteredSessions = restrictedCat
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions;

  const filteredMatches = restrictedCat
    ? state.matches.filter(m => m.category === restrictedCat)
    : state.matches;

  const filteredAttendance = restrictedCat
    ? state.attendance.filter(a => {
        const person = state.people.find(p => p.id === a.personId);
        return person?.category === restrictedCat;
      })
    : state.attendance;

  const categories: Category[] = restrictedCat ? [restrictedCat] : state.categories;

  // Calculate attendance percentage for the filtered data
  const presentCount = filteredAttendance.filter(a => a.status === 'حاضر').length;
  const attendanceRate = filteredAttendance.length > 0 
    ? Math.round((presentCount / filteredAttendance.length) * 100) 
    : 0;

  const stats = [
    { label: restrictedCat ? `كوادر ${restrictedCat}` : 'إجمالي الكوادر', value: filteredPeople.length, icon: Users, color: 'blue' },
    { label: 'تمارين مجدولة', value: filteredSessions.length, icon: Calendar, color: 'orange' },
    { label: 'مباريات قادمة', value: filteredMatches.length, icon: Trophy, color: 'emerald' },
    { label: 'نسبة الحضور', value: `${attendanceRate}%`, icon: TrendingUp, color: 'green' },
  ];

  return (
    <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Header Info for Restricted Users */}
      {restrictedCat && (
        <div className="bg-gradient-to-l from-blue-900 to-blue-700 p-6 rounded-[2rem] shadow-xl text-white flex items-center justify-between overflow-hidden relative">
          <div className="relative z-10">
            <h2 className="text-xl md:text-2xl font-black">لوحة تحكم فئة {restrictedCat}</h2>
            <p className="text-blue-200 text-sm mt-1 font-bold">مرحباً بك كابتن {currentUser?.username} في نظام الإدارة الخاص بك</p>
          </div>
          <Trophy size={80} className="text-orange-500/20 absolute -left-4 -bottom-4 rotate-12" />
        </div>
      )}

      {/* Stat Cards Grid */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        {stats.map((stat, idx) => {
          const Icon = stat.icon;
          const colors: Record<string, string> = {
            blue: 'bg-blue-50 text-blue-600',
            orange: 'bg-orange-50 text-orange-600',
            emerald: 'bg-emerald-50 text-emerald-600',
            green: 'bg-emerald-50 text-emerald-600',
          };

          return (
            <div key={idx} className="bg-white p-4 md:p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center sm:items-start text-center sm:text-right hover:shadow-md transition-shadow">
              <div className={`p-3 rounded-2xl ${colors[stat.color] || 'bg-slate-50'} mb-4`}>
                <Icon size={24} className="md:w-7 md:h-7" />
              </div>
              <h3 className="text-slate-500 text-[10px] md:text-sm font-black uppercase tracking-wider">{stat.label}</h3>
              <p className="text-xl md:text-3xl font-black text-slate-900 mt-1">{stat.value}</p>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8">
        {/* Category/Staff Distribution */}
        <div className="bg-white p-6 md:p-8 rounded-[2rem] shadow-sm border border-slate-100">
          <h3 className="text-lg font-black text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-1.5 h-6 bg-blue-600 rounded-full"></span>
            {restrictedCat ? `توزيع كوادر ${restrictedCat}` : 'توزيع الفئات'}
          </h3>
          <div className="space-y-6">
            {categories.map(cat => {
              const count = state.people.filter(p => p.category === cat).length;
              const total = restrictedCat ? filteredPeople.length : state.people.length;
              const percentage = total ? (count / total) * 100 : 0;

              if (restrictedCat) {
                // For restricted category, show breakdown by role
                const roles = ['لاعب', 'مدرب', 'إداري', 'طبيب'];
                return (
                  <div key="restricted-breakdown" className="space-y-5">
                    {roles.map(role => {
                      const roleCount = filteredPeople.filter(p => p.role === role).length;
                      const rolePercent = filteredPeople.length ? (roleCount / filteredPeople.length) * 100 : 0;
                      return (
                        <div key={role} className="space-y-2">
                          <div className="flex justify-between text-sm">
                            <span className="font-black text-slate-700">{role}</span>
                            <span className="text-blue-600 font-bold">{roleCount}</span>
                          </div>
                          <div className="h-2 bg-slate-50 rounded-full overflow-hidden border border-slate-100">
                            <div 
                              className="h-full bg-blue-600 rounded-full shadow-sm transition-all duration-1000" 
                              style={{ width: `${rolePercent}%` }}
                            />
                          </div>
                        </div>
                      );
                    })}
                  </div>
                );
              }

              return (
                <div key={cat} className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="font-black text-slate-700">{cat}</span>
                    <span className="text-blue-600 font-bold">{count} عضو</span>
                  </div>
                  <div className="h-3 bg-slate-50 rounded-full overflow-hidden border border-slate-100">
                    <div 
                      className="h-full bg-blue-600 rounded-full shadow-sm transition-all duration-1000" 
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Recent Matches & Training Combined View */}
        <div className="bg-white p-6 md:p-8 rounded-[2rem] shadow-sm border border-slate-100">
          <h3 className="text-lg font-black text-slate-800 mb-6 flex items-center gap-2">
            <span className="w-1.5 h-6 bg-emerald-500 rounded-full"></span>
            آخر الفعاليات {restrictedCat && `(فئة ${restrictedCat})`}
          </h3>
          <div className="space-y-4">
            {filteredMatches.slice(0, 2).map(match => (
              <div key={match.id} className="flex items-center gap-4 p-4 rounded-2xl bg-emerald-50 border border-emerald-100 hover:bg-white hover:shadow-md transition-all cursor-default">
                <div className="bg-white p-3 rounded-xl border border-emerald-100 shadow-sm text-emerald-600 hidden sm:block">
                  <Trophy size={20} />
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="font-bold text-slate-800 truncate">مباراة ضد {match.opponent}</h4>
                  <p className="text-xs text-slate-500 mt-0.5">{match.date} | {match.location}</p>
                </div>
                <span className="px-3 py-1 rounded-full bg-emerald-600 text-white text-[10px] font-black whitespace-nowrap">
                  مباراة
                </span>
              </div>
            ))}
            {filteredSessions.slice(0, 2).map(session => (
              <div key={session.id} className="flex items-center gap-4 p-4 rounded-2xl bg-slate-50 border border-slate-100 hover:bg-white hover:shadow-md transition-all cursor-default">
                <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm text-blue-600 hidden sm:block">
                  <Calendar size={20} />
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="font-bold text-slate-800 truncate">{session.objective}</h4>
                  <p className="text-xs text-slate-500 mt-0.5">{session.date} | {session.location}</p>
                </div>
                <span className="px-3 py-1 rounded-full bg-blue-100 text-blue-700 text-[10px] font-black whitespace-nowrap">
                  تمرين
                </span>
              </div>
            ))}
            {filteredMatches.length === 0 && filteredSessions.length === 0 && (
              <div className="text-center py-12 text-slate-400 italic bg-slate-50 rounded-2xl border border-dashed">
                لا توجد فعاليات مجدولة حالياً
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const TrainingPlanner: React.FC<TrainingPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const canEdit = isManager || (currentUser?.role === 'مدرب' && !!restrictedCat);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'رجال')
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.location) return;

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
    } else {
      const newSession: TrainingSession = {
        id: Math.random().toString(36).substr(2, 9),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تمرين عام'
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const filteredSessions = restrictedCat 
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-slate-600 font-bold">المواعيد المجدولة</h3>
        {canEdit && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-blue-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold shadow-lg shadow-blue-200">
            <Plus size={20} /> إضافة موعد تمرين
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 relative group overflow-hidden">
            <div className="flex items-center gap-3 mb-4">
              <div className="bg-orange-50 text-orange-600 p-3 rounded-2xl"><Calendar size={24} /></div>
              <div>
                <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-1 rounded-md font-black uppercase">{session.category}</span>
                <h4 className="font-bold text-lg text-slate-800 mt-1">{session.objective}</h4>
              </div>
            </div>
            <div className="space-y-3 mt-4 pt-4 border-t border-slate-50 text-sm">
