import React from 'react';
import { ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, CheckCircle, Award, GraduationCap, Home } from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord } from '../types';
import ClubLogo from './ClubLogo';

interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  if (!player) return null;

  const isStaff = player.role !== 'لاعب';

  // إحصائيات المباريات وحساب الدقائق بدقة (للاعبين فقط)
  const playerMatchesStats = !isStaff ? state.matches.filter(m => m.isCompleted).map(match => {
    let minutesPlayed = 0;
    const isStarter = match.lineupDetails?.starters.some(p => p.name === player.name);

    const subOut = match.lineupDetails?.substitutionList.find(s => s.playerOut === player.name);
    const subIn = match.lineupDetails?.substitutionList.find(s => s.playerIn === player.name);

    if (isStarter) {
      minutesPlayed = subOut ? parseInt(subOut.time) || 0 : 90;
    } else if (subIn) {
      minutesPlayed = 90 - (parseInt(subIn.time) || 0);
    }

    const goals = match.goalList.filter(g => g.player === player.name).length;
    const cards = match.cardList.filter(c => c.player === player.name);
    const yellowCards = cards.filter(c => c.type === 'صفراء').length;
    const redCards = cards.filter(c => c.type === 'حمراء').length;

    return {
      match,
      minutes: minutesPlayed,
      goals,
      yellowCards,
      redCards,
      played: minutesPlayed > 0
    };
  }).filter(s => s.played) : [];

  const totalMinutes = playerMatchesStats.reduce((sum, s) => sum + s.minutes, 0);
  const totalGoals = playerMatchesStats.reduce((sum, s) => sum + s.goals, 0);
  const totalYellows = playerMatchesStats.reduce((sum, s) => sum + s.yellowCards, 0);
  const totalReds = playerMatchesStats.reduce((sum, s) => sum + s.redCards, 0);

  // إحصائيات التمارين
  const playerAttendance = state.attendance.filter(a => a.personId === player.id);
  const categorySessionsCount = state.sessions.filter(s => s.category === player.category).length;
  const presentCount = playerAttendance.filter(a => a.status === 'حاضر').length;
  const lateCount = playerAttendance.filter(a => a.status === 'متأخر').length;
  const attendanceRate = categorySessionsCount ? Math.round(((presentCount + lateCount * 0.5) / categorySessionsCount) * 100) : 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex justify-between items-center no-print">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-500 hover:text-blue-900 font-black transition-all">
          <ChevronRight size={20} /> العودة للقائمة
        </button>
        <button onClick={() => window.print()} className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black flex items-center gap-2 hover:bg-black shadow-lg">
          <Printer size={18} /> طباعة التقرير الشامل
        </button>
      </div>

      {/* Profile Card */}
      <div className="bg-white rounded-[3rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="bg-gradient-to-l from-blue-900 to-blue-800 h-40 relative">
          <div className="absolute -bottom-16 right-12 flex items-end gap-6">
            <div className="w-40 h-40 bg-white rounded-[3rem] shadow-2xl border-8 border-white flex items-center justify-center overflow-hidden">
               <div className="text-6xl font-black text-blue-900 uppercase">{player.name.charAt(0)}</div>
            </div>
            <div className="mb-4 space-y-1">
              <h1 className="text-4xl font-black text-white drop-shadow-md">{player.name}</h1>
              <div className="flex gap-2">
                <span className="bg-orange-500 text-white text-[10px] font-black px-4 py-1 rounded-full uppercase shadow-lg shadow-orange-500/20">{player.role} - فئة {player.category}</span>
                {player.number && <span className="bg-white/20 backdrop-blur-md text-white text-[10px] font-black px-4 py-1 rounded-full">الرقم: {player.number}</span>}
              </div>
            </div>
          </div>
        </div>
        <div className="h-20"></div>
        <div className="px-12 pb-10 grid grid-cols-1 md:grid-cols-4 gap-8">
           <div className="space-y-1">
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><MapPin size={14}/> مكان الميلاد</p>
             <p className="text-base font-bold text-slate-800">{player.birthPlace || 'غير مسجل'}</p>
           </div>
           <div className="space-y-1">
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Calendar size={14}/> تاريخ الميلاد</p>
             <p className="text-base font-bold text-slate-800">{player.birthDate || 'غير مسجل'}</p>
           </div>
           <div className="space-y-1">
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Home size={14}/> العنوان</p>
             <p className="text-base font-bold text-slate-800">{player.address || 'غير مسجل'}</p>
           </div>
           <div className="space-y-1">
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Shield size={14}/> الرقم الاتحادي</p>
             <p className="text-base font-bold text-slate-800 font-mono">{player.federalNumber || '-'}</p>
           </div>
        </div>

        {/* مؤهلات المدربين */}
        {(player.role === 'مدرب' || player.role === 'مساعد مدرب') && (
          <div className="px-12 pb-8 pt-6 border-t border-slate-50 bg-blue-50/30 flex flex-col md:flex-row gap-8">
             <div className="flex items-center gap-4">
               <div className="p-3 bg-blue-900 text-white rounded-2xl"><Award size={24}/></div>
               <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase">الشهادة التدريبية</p>
                 <p className="text-lg font-black text-blue-900">{player.coachingCertificate || 'لا يوجد'}</p>
               </div>
             </div>
             <div className="flex items-center gap-4">
               <div className="p-3 bg-white border-2 border-blue-900 text-blue-900 rounded-2xl"><GraduationCap size={24}/></div>
               <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase">المؤهل العلمي</p>
                 <p className="text-lg font-black text-slate-800">{player.academicDegree || 'لا يوجد'}</p>
               </div>
             </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm text-center space-y-2">
          <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-3xl flex items-center justify-center mx-auto"><Clock size={32}/></div>
          <p className="text-4xl font-black text-slate-900">{!isStaff ? totalMinutes : playerAttendance.length}</p>
          <p className="text-[10px] font-black text-slate-400 uppercase">{!isStaff ? 'دقائق اللعب' : 'عدد التمارين المقادة'}</p>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm text-center space-y-2">
          <div className="w-16 h-16 bg-orange-50 text-orange-600 rounded-3xl flex items-center justify-center mx-auto"><Target size={32}/></div>
          <p className="text-4xl font-black text-slate-900">{!isStaff ? totalGoals : '-'}</p>
          <p className="text-[10px] font-black text-slate-400 uppercase">{!isStaff ? 'الأهداف المسجلة' : 'الرؤية الفنية'}</p>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm text-center space-y-2">
          <div className="w-16 h-16 bg-yellow-50 text-yellow-600 rounded-3xl flex items-center justify-center mx-auto"><AlertTriangle size={32}/></div>
          <div className="flex justify-center gap-4">
             <span className="text-2xl font-black text-yellow-600">{totalYellows}Y</span>
             <span className="text-2xl font-black text-red-600">{totalReds}R</span>
          </div>
          <p className="text-[10px] font-black text-slate-400 uppercase">سجل العقوبات</p>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm text-center space-y-2">
          <div className="w-16 h-16 bg-emerald-50 text-emerald-600 rounded-3xl flex items-center justify-center mx-auto"><TrendingUp size={32}/></div>
          <p className="text-4xl font-black text-slate-900">{attendanceRate}%</p>
          <p className="text-[10px] font-black text-slate-400 uppercase">معدل الانضباط</p>
        </div>
      </div>

      {!isStaff && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Match Participation Table */}
          <div className="bg-white rounded-[3rem] shadow-sm border border-slate-100 overflow-hidden">
             <div className="p-8 border-b bg-slate-50/50 flex items-center gap-3">
               <Trophy className="text-blue-900" size={24} />
               <h3 className="text-xl font-black text-slate-800">سجل المشاركات الرسمية</h3>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-right">
                  <thead className="bg-slate-50">
                    <tr>
                      <th className="px-6 py-4 text-xs font-black text-slate-500">المنافس</th>
                      <th className="px-6 py-4 text-xs font-black text-slate-500 text-center">الدقائق</th>
                      <th className="px-6 py-4 text-xs font-black text-slate-500 text-center">أهداف</th>
                      <th className="px-6 py-4 text-xs font-black text-slate-500 text-center">بطاقات</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {playerMatchesStats.map((ms, i) => (
                      <tr key={i} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-4">
                          <span className="font-bold text-slate-800">ضد {ms.match.opponent}</span>
                          <span className="text-[10px] text-slate-400 block">{ms.match.date}</span>
                        </td>
                        <td className="px-6 py-4 text-center font-black text-blue-700">{ms.minutes}'</td>
                        <td className="px-6 py-4 text-center">
                          <span className={`px-2 py-1 rounded-lg text-xs font-black ${ms.goals > 0 ? 'bg-orange-500 text-white' : 'text-slate-300'}`}>{ms.goals}</span>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <div className="flex justify-center gap-1">
                             {Array(ms.yellowCards).fill(0).map((_, idx) => <div key={idx} className="w-2 h-3 bg-yellow-400 rounded-sm"></div>)}
                             {Array(ms.redCards).fill(0).map((_, idx) => <div key={idx} className="w-2 h-3 bg-red-600 rounded-sm"></div>)}
                             {ms.yellowCards === 0 && ms.redCards === 0 && <span className="text-slate-200">-</span>}
                          </div>
                        </td>
                      </tr>
                    ))}
                    {playerMatchesStats.length === 0 && (
                      <tr><td colSpan={4} className="p-12 text-center text-slate-300 font-bold italic">لا توجد مشاركات مسجلة حالياً</td></tr>
                    )}
                  </tbody>
               </table>
             </div>
          </div>

          {/* Training Commitment Section */}
          <div className="bg-white rounded-[3rem] shadow-sm border border-slate-100 overflow-hidden">
             <div className="p-8 border-b bg-slate-50/50 flex items-center justify-between">
               <div className="flex items-center gap-3">
                 <Activity className="text-emerald-600" size={24} />
                 <h3 className="text-xl font-black text-slate-800">الالتزام بالتمارين</h3>
               </div>
               <div className="flex gap-4">
                 <div className="text-center"><span className="text-[10px] font-black text-slate-400 block uppercase">حضر</span><span className="font-black text-emerald-600">{presentCount}</span></div>
                 <div className="text-center"><span className="text-[10px] font-black text-slate-400 block uppercase">تأخر</span><span className="font-black text-orange-500">{lateCount}</span></div>
               </div>
             </div>
             <div className="p-8 space-y-4">
                {playerAttendance.slice(-6).reverse().map((att, i) => (
                  <div key={i} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div className="flex items-center gap-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${att.status === 'حاضر' ? 'bg-emerald-100 text-emerald-600' : att.status === 'متأخر' ? 'bg-orange-100 text-orange-600' : 'bg-red-100 text-red-600'}`}>
                        {att.status === 'حاضر' ? <CheckCircle size={20}/> : att.status === 'متأخر' ? <Clock size={20}/> : <AlertTriangle size={20}/>}
                      </div>
                      <div>
                        <p className="text-sm font-bold text-slate-800">تمرين {att.date}</p>
                        <p className="text-[10px] text-slate-400 font-black">{att.time}</p>
                      </div>
                    </div>
                    <span className={`px-4 py-1 rounded-full text-[10px] font-black uppercase ${att.status === 'حاضر' ? 'bg-emerald-600 text-white' : att.status === 'متأخر' ? 'bg-orange-500 text-white' : 'bg-red-600 text-white'}`}>
                      {att.status}
                    </span>
                  </div>
                ))}
                {playerAttendance.length === 0 && (
                  <div className="py-16 text-center text-slate-300 font-bold italic border-2 border-dashed border-slate-100 rounded-[2rem]">لا يوجد سجل حضور مسجل</div>
                )}
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PlayerReport;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'إداري' | 'طبيب';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب';
export type UserRole = 'مدير' | 'مدرب' | 'مشاهد';

export interface AppNotification {
  id: string;
  message: string;
  type: 'info' | 'success' | 'warning';
  timestamp: number;
}

export interface Person {
  id: string;
  name: string; // الاسم الثنائي
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  address?: string; // العنوان لجميع الأعضاء
  joinDate: string;
  federalNumber?: string;
  nationalId?: string;
  birthDate?: string;
  birthPlace?: string; // مكان الميلاد
  fatherName?: string;
  motherName?: string;
  nationality?: string; // الجنسية
  khana?: string; // الخانة (القيد المدني)

  // حقول خاصة بالكوادر التدريبية
  coachingCertificate?: string; // الشهادة التدريبية
  academicDegree?: string; // الشهادة العلمية

  // حقول العقد
  contractValue?: string;
  contractDuration?: string;
  contractStart?: string;
  contractEnd?: string;

  notes?: string; // ملاحظات عامة
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId?: string; // ربط الحضور بتمرين معين
  date: string;
  time: string;
  status: AttendanceStatus;
  note?: string;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
}

export interface GoalRecord {
  player: string;
  number: string;
  time: string;
}

export interface CardRecord {
  player: string;
  number: string;
  time: string;
  type: 'صفراء' | 'حمراء';
}

export interface SubstitutionRecord {
  playerIn: string;
  numberIn: string;
  playerOut: string;
  numberOut: string;
  time: string;
}

export interface LineupPlayer {
  name: string;
  number: string;
}

export interface MatchLineup {
  starters: LineupPlayer[];
  subs: LineupPlayer[];
  captain: string;
  substitutionList: SubstitutionRecord[];
}

export interface Match {
  id: string;
  category: Category;
  opponent: string;
  location: string;
  advancePayment: string;
  date: string;
  time: string;
  isCompleted?: boolean;
  ourScore?: string;
  opponentScore?: string;
  goalList: GoalRecord[];
  cardList: CardRecord[];
  lineupDetails?: MatchLineup;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  categories: Category[]; // قائمة الفئات الديناميكية
  currentUser: AppUser | null;
  notifications: AppNotification[];
}

import React, { useState, useEffect } from 'react';
import { 
  UserPlus, Trash2, Search, X, Hash, Phone, User as UserIcon, 
  Banknote, Edit, MapPin, CreditCard, Shield, Globe, BookOpen, 
  FileBarChart, Layers, Plus, GraduationCap, Award, Calendar, 
  StickyNote, UserCheck 
} from 'lucide-react';
import { AppState, Category, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport }) => {
  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const restrictedCat = currentUser?.restrictedCategory;

  const [selectedCategory, setSelectedCategory] = useState<Category | 'الكل'>(restrictedCat || 'الكل');
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [editingPersonId, setEditingPersonId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<Person>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'رجال'),
    role: 'لاعب',
    nationality: 'سوري'
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'إداري', 'طبيب'];

  const calculateAge = (birthDate?: string) => {
    if (!birthDate) return null;
    const birth = new Date(birthDate);
    const today = new Date();
    if (isNaN(birth.getTime())) return null;
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const filteredPeople = state.people.filter(p => {
    const matchesCategory = selectedCategory === 'الكل' ? true : p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const finalCategory = restrictedCat || (formData.category as Category);

    if (editingPersonId) {
      setState(prev => ({
        ...prev,
        people: prev.people.map(p => p.id === editingPersonId ? { ...p, ...formData, category: finalCategory } as Person : p)
      }));
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        joinDate: new Date().toISOString().split('T')[0],
        ...(formData as Person),
        category: finalCategory
      };
      setState(prev => ({ ...prev, people: [...prev.people, newPerson] }));
    }

    setIsModalOpen(false);
    setEditingPersonId(null);
    setFormData({ category: restrictedCat || (state.categories[0] || 'رجال'), role: 'لاعب', nationality: 'سوري' });
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) {
      alert('هذه الفئة موجودة مسبقاً');
      return;
    }

    setState(prev => ({
      ...prev,
      categories: [...prev.categories, newCatName.trim()],
      notifications: [{
        id: Math.random().toString(36).substr(2, 9),
        message: `تمت إضافة فئة "${newCatName}" بنجاح`,
        type: 'success',
        timestamp: Date.now()
      }]
    }));
    setNewCatName('');
    setIsCatModalOpen(false);
  };

  const deleteCategory = (cat: Category) => {
    if (state.people.some(p => p.category === cat)) {
      alert('لا يمكن حذف الفئة لأنها تحتوي على لاعبين أو كوادر. يرجى نقلهم أو حذفهم أولاً.');
      return;
    }
    if (confirm(`هل أنت متأكد من حذف فئة ${cat}؟`)) {
      setState(prev => ({
        ...prev,
        categories: prev.categories.filter(c => c !== cat)
      }));
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 space-y-4 no-print">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="البحث بالاسم..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-3.5 pr-12 pl-10 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-950" />
          </div>

          <div className="flex gap-2">
            {isManager && (
              <button onClick={() => setIsCatModalOpen(true)}
                className="bg-blue-100 text-blue-700 px-6 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-blue-200 transition-all">
                <Layers size={20} /> إدارة الفئات
              </button>
            )}
            {(isManager || !!restrictedCat) && (
              <button onClick={() => { setEditingPersonId(null); setFormData({ category: restrictedCat || (state.categories[0] || 'رجال'), role: 'لاعب', nationality: 'سوري' }); setIsModalOpen(true); }}
                className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl flex items-center justify-center gap-2 font-black hover:bg-orange-700 transition-all shadow-xl shadow-orange-200">
                <UserPlus size={20} /> إضافة عضو
              </button>
            )}
          </div>
        </div>

        {!restrictedCat && (
          <div className="flex bg-slate-50 p-1.5 rounded-2xl border w-max max-w-full overflow-x-auto no-scrollbar">
            <button onClick={() => setSelectedCategory('الكل')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === 'الكل' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>الكل</button>
            {state.categories.map(cat => (
              <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-6 py-2 rounded-xl text-sm font-black transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500'}`}>{cat}</button>
            ))}
          </div>
        )}
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[1200px]">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100">
                <th className="px-6 py-5 text-slate-500 font-black text-xs">الاسم والتفاصيل</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">العمر والميلاد</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center">الرقم</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs">بيانات القيد والعنوان</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center no-print">تقرير فني</th>
                <th className="px-6 py-5 text-slate-500 font-black text-xs text-center no-print">تحكم</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredPeople.map(person => (
                <tr key={person.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <span className="font-bold text-slate-950 text-base block">{person.name}</span>
                    <span className="text-[10px] text-slate-400 font-black block">{person.phone || 'بدون هاتف'}</span>
                    <div className="flex gap-1.5 mt-1">
                      <span className="text-[9px] bg-blue-50 text-blue-700 px-1.5 py-0.5 rounded font-black">{person.category}</span>
                      <span className="text-[9px] bg-slate-100 text-slate-600 px-1.5 py-0.5 rounded font-black">{person.role}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-sm font-black text-blue-900 block">{calculateAge(person.birthDate) ?? '-'} سنة</span>
                    <span className="text-[10px] text-slate-400 font-bold">{person.birthDate}</span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="inline-flex items-center justify-center w-10 h-10 rounded-xl bg-slate-900 text-white text-sm font-black border-2 border-orange-500/30">
                      {person.number || '-'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-[10px] space-y-1 font-black">
                      <div className="flex items-center gap-1 text-slate-700"><CreditCard size={12}/> {person.nationalId || 'لا يوجد'}</div>
                      <div className="flex items-center gap-1 text-blue-800"><Shield size={12}/> {person.federalNumber || 'لا يوجد'}</div>
                      <div className="flex items-center gap-1 text-slate-500"><MapPin size={12}/> {person.address || 'العنوان غير مسجل'}</div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center no-print">
                    {(person.role === 'لاعب' || person.role === 'مدرب' || person.role === 'مساعد مدرب') && onOpenReport && (
                      <button onClick={() => onOpenReport(person)} 
                        className="bg-emerald-50 text-emerald-600 p-3 rounded-2xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm">
                        <FileBarChart size={20} />
                      </button>
                    )}
                  </td>
                  <td className="px-6 py-4 text-center no-print">
                    <div className="flex items-center justify-center gap-2">
                       {(isManager || restrictedCat === person.category) && (
                         <>
                           <button onClick={() => { setEditingPersonId(person.id); setFormData(person); setIsModalOpen(true); }} className="text-blue-500 p-2 hover:bg-blue-50 rounded-xl"><Edit size={18} /></button>
                           <button onClick={() => { if(confirm('حذف؟')) setState(prev => ({...prev, people: prev.people.filter(p => p.id !== person.id)})); }} className="text-red-400 p-2 hover:bg-red-50 rounded-xl"><Trash2 size={18} /></button>
                         </>
                       )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[100] p-4 no-print overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-5xl shadow-2xl overflow-hidden my-auto border border-white/20">
            <div className="p-8 border-b flex items-center justify-between bg-slate-50">
               <div>
                  <h3 className="text-2xl font-black text-slate-800">{editingPersonId ? 'تحديث البيانات' : 'تسجيل عضو جديد'}</h3>
                  <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">نموذج قيد رسمي - نادي الكرامة</p>
               </div>
               <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl hover:bg-red-100 hover:text-red-600 transition-colors"><X size={24} /></button>
            </div>

            <form onSubmit={handleSave} className="p-10 space-y-10 max-h-[85vh] overflow-y-auto custom-scrollbar">

              {/* 1. البيانات الشخصية والعائلية */}
              <div className="space-y-6">
                <h4 className="text-sm font-black text-blue-900 flex items-center gap-2 border-r-4 border-blue-600 pr-3">
                   البيانات الشخصية والعائلية
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">الاسم الثنائي</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({ ...formData, name: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950 focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">اسم الأب</label>
                    <input type="text" value={formData.fatherName || ''} onChange={e => setFormData({ ...formData, fatherName: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950 focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">اسم الأم</label>
                    <input type="text" value={formData.motherName || ''} onChange={e => setFormData({ ...formData, motherName: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950 focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">تاريخ الولادة</label>
                    <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({ ...formData, birthDate: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950 focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">العمر (تلقائي)</label>
                    <div className="bg-white border-2 border-slate-100 rounded-2xl p-4 font-black text-blue-600 text-center">
                      {calculateAge(formData.birthDate) ?? '--'} عام
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">مكان الولادة</label>
                    <input type="text" value={formData.birthPlace || ''} onChange={e => setFormData({ ...formData, birthPlace: e.target.value })}
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 font-bold text-slate-950 focus:ring-2 focus:ring-blue-500 outline-none" />
                  </div>
                </div>
              </div>

              {/* 2. البيانات الرسمية والعنوان */}
              <div className="space-y-6 pt-6 border-t border-slate-50">
                <h4 className="text-sm font-black text-orange-600 flex items-center gap-2 border-r-4 border-orange-500 pr-3">
                   البيانات الرسمية والعنوان
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">الرقم الوطني</label>
                    <div className="relative">
                       <CreditCard className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                       <input type="text" value={formData.nationalId || ''} onChange={e => setFormData({ ...formData, nationalId: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl py-4 pr-12 pl-4 font-bold text-slate-950 focus:ring-2 focus:ring-orange-500 outline-none" />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">الرقم الاتحادي</label>
                    <div className="relative">
                       <Shield className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                       <input type="text" value={formData.federalNumber || ''} onChange={e => setFormData({ ...formData, federalNumber: e.target.value })}
                        className="w-full bg-slate-100 border-none rounded-2xl py-4 pr-12 pl-4 font-bold text-slate-950 focus:ring-2 focus:ring-orange-500 outline-none" />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-black text-slate-500">رقم الهاتف</label>
