                   </div>
                   <p className="text-xs text-slate-500 font-bold leading-relaxed">
                     بموجب قوانين المكتب، لا يمكن للمدرب تعديل أي حالة حضور بعد حفظها. التعديل متاح فقط للمدير الفني العام للمكتب.
                   </p>
                </div>
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4 items-end no-print">
            <div className="flex-1 grid grid-cols-2 gap-4 w-full">
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 mr-2">الشهر المطلوب</label>
                <select value={selectedMonth} onChange={e => setSelectedMonth(parseInt(e.target.value))}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold text-slate-950 outline-none">
                  {Array.from({length: 12}, (_, i) => <option key={i+1} value={i+1}>{new Date(0, i).toLocaleString('ar-EG', {month: 'long'})}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-black text-slate-400 mr-2">السنة</label>
                <select value={selectedYear} onChange={e => setSelectedYear(parseInt(e.target.value))}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold text-slate-950 outline-none">
                  {[2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
                </select>
              </div>
            </div>
            <button onClick={() => window.print()} className="w-full md:w-auto bg-orange-600 text-white px-10 py-4 rounded-2xl font-black flex items-center justify-center gap-2">
              <FileText size={20} /> تصدير تقرير الشهر
            </button>
          </div>

          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
              <h4 className="font-black text-slate-800">إحصائيات شهر {new Date(0, selectedMonth-1).toLocaleString('ar-EG', {month: 'long'})}</h4>
              <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">فئة {selectedCategory}</span>
            </div>
            <table className="w-full text-right">
              <thead>
                <tr className="bg-slate-50 text-slate-500">
                  <th className="px-6 py-4 text-xs font-black">اللاعب</th>
                  <th className="px-6 py-4 text-xs font-black text-center">حضور</th>
                  <th className="px-6 py-4 text-xs font-black text-center">تأخير</th>
                  <th className="px-6 py-4 text-xs font-black text-center">غياب</th>
                  <th className="px-6 py-4 text-xs font-black text-center">جودة الالتزام</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {getMonthlySummary().map(row => {
                  const rate = row.total ? Math.round(((row.present + row.late * 0.5) / row.total) * 100) : 0;
                  return (
                    <tr key={row.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-6 py-4 font-bold text-slate-950">{row.name}</td>
                      <td className="px-6 py-4 text-center text-emerald-600 font-black">{row.present}</td>
                      <td className="px-6 py-4 text-center text-orange-500 font-black">{row.late}</td>
                      <td className="px-6 py-4 text-center text-red-600 font-black">{row.absent}</td>
                      <td className="px-6 py-4 text-center">
                        <div className="flex flex-col items-center gap-1">
                          <span className="text-[10px] font-black text-slate-900">{rate}%</span>
                          <div className="w-16 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                            <div className={`h-full transition-all ${rate > 80 ? 'bg-emerald-500' : rate > 50 ? 'bg-orange-500' : 'bg-red-500'}`} style={{width: `${rate}%`}} />
                          </div>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Users, 
  Calendar, 
  ClipboardCheck, 
  LayoutDashboard, 
  Settings, 
  LogOut, 
  Menu,
  X,
  Trophy,
  Bell,
  CheckCircle,
  Clock,
  Cloud
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { 
  AppUser, 
  AppState,
  Category,
  Person
} from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

// Supabase Configuration (Assuming standard env vars or placeholders)
const supabaseUrl = (window as any).env?.SUPABASE_URL || '';
const supabaseAnonKey = (window as any).env?.SUPABASE_ANON_KEY || '';
const supabase = supabaseUrl && supabaseAnonKey ? createClient(supabaseUrl, supabaseAnonKey) : null;

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_data');
    const defaultCategories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];

    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.matches) parsed.matches = [];
      if (!parsed.users) parsed.users = [];
      if (!parsed.notifications) parsed.notifications = [];
      if (!parsed.categories) parsed.categories = defaultCategories;

      const hasMainAdmin = parsed.users.some((u: AppUser) => u.username === 'Izzat');
      if (!hasMainAdmin) {
        parsed.users.push({ id: 'admin-main', username: 'Izzat', role: 'مدير' });
      }

      return parsed;
    }

    const mainAdmin: AppUser = { id: 'admin-main', username: 'Izzat', role: 'مدير' };

    const admins = Array.from({ length: 5 }, (_, i) => ({
      id: `admin-${i + 1}`,
      username: `admin${i + 1}`,
      role: 'مدير' as const
    }));

    const categoryUsers: AppUser[] = [
      { id: 'u-men', username: 'MEN', role: 'مدرب', restrictedCategory: 'رجال' },
      { id: 'u-u18', username: 'U18', role: 'مدرب', restrictedCategory: 'شباب' },
      { id: 'u-u16', username: 'U16', role: 'مدرب', restrictedCategory: 'ناشئين' },
      { id: 'u-u14', username: 'U14', role: 'مدرب', restrictedCategory: 'أشبال' }
    ];

    return {
      people: [],
      attendance: [],
      sessions: [],
      matches: [],
      categories: defaultCategories,
      users: [mainAdmin, ...admins, ...categoryUsers],
      currentUser: null,
      notifications: []
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedPlayerForReport, setSelectedPlayerForReport] = useState<Person | null>(null);
  const notificationRef = useRef<HTMLDivElement>(null);

  // Sync with Local Storage
  useEffect(() => {
    localStorage.setItem('alkaramah_data', JSON.stringify(state));
  }, [state]);

  // Sync with Supabase (Cloud)
  useEffect(() => {
    const syncToCloud = async () => {
      if (!supabase) return;
      setIsSyncing(true);
      try {
        await Promise.all([
          supabase.from('people').upsert(state.people),
          supabase.from('attendance').upsert(state.attendance),
          supabase.from('sessions').upsert(state.sessions),
          supabase.from('matches').upsert(state.matches),
          supabase.from('users').upsert(state.users),
          supabase.from('categories_list').upsert(state.categories.map(c => ({ name: c })))
        ]);
      } catch (error) {
        console.error('Cloud Sync Error:', error);
      } finally {
        setIsSyncing(false);
      }
    };

    const timer = setTimeout(() => {
      if (state.currentUser) syncToCloud();
    }, 5000); // Debounced sync

    return () => clearTimeout(timer);
  }, [state.people, state.attendance, state.sessions, state.matches, state.users, state.categories]);

  // Initial Fetch from Cloud
  useEffect(() => {
    const fetchData = async () => {
      if (!supabase) return;
      try {
        const [
          { data: people },
          { data: attendance },
          { data: sessions },
          { data: matches },
          { data: users },
          { data: categories }
        ] = await Promise.all([
          supabase.from('people').select('*'),
          supabase.from('attendance').select('*'),
          supabase.from('sessions').select('*'),
          supabase.from('matches').select('*'),
          supabase.from('users').select('*'),
          supabase.from('categories_list').select('name')
        ]);

        if (people) setState(prev => ({ ...prev, 
          people, 
          attendance: attendance || [], 
          sessions: sessions || [], 
          matches: matches || [], 
          users: users || prev.users,
          categories: categories?.map(c => c.name) || prev.categories
        }));
      } catch (error) {
        console.error('Initial Fetch Error:', error);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogin = (user: AppUser) => {
    setState(prev => ({ ...prev, currentUser: user }));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
  };

  const openPlayerReport = (player: Person) => {
    setSelectedPlayerForReport(player);
    setActiveTab('player-report');
  };

  const markAllAsRead = () => {
    setState(prev => ({
      ...prev,
      notifications: prev.notifications.map(n => ({ ...n, isRead: true }))
    }));
  };

  const clearNotifications = () => {
    setState(prev => ({
      ...prev,
      notifications: []
    }));
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} state={state} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} />;
      case 'squad': return <SquadManagement state={state} setState={setState} onOpenReport={openPlayerReport} />;
      case 'attendance': return <AttendanceTracker state={state} setState={setState} />;
      case 'training': return <TrainingPlanner state={state} setState={setState} />;
      case 'matches': return <MatchPlanner state={state} setState={setState} />;
      case 'settings': return <SettingsView state={state} setState={setState} />;
      case 'player-report': return <PlayerReport state={state} player={selectedPlayerForReport} onBack={() => setActiveTab('squad')} />;
      default: return <Dashboard state={state} />;
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'الفئات واللاعبين', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'جدول التمارين', icon: Calendar },
    { id: 'matches', label: 'جدول المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات والمستخدمين', icon: Settings, adminOnly: true },
  ];

  const unreadCount = state.notifications.filter(n => !n.isRead).length;

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-['Tajawal'] text-right" dir="rtl">
      {/* Sync Status Toast */}
      {isSyncing && (
        <div className="fixed bottom-6 right-6 z-[300] bg-white/90 backdrop-blur-md px-6 py-3 rounded-2xl shadow-2xl border border-blue-100 flex items-center gap-3 animate-in slide-in-from-bottom-4 duration-300">
          <Cloud className="text-blue-500 animate-pulse" size={20} />
          <span className="text-xs font-black text-slate-700">جاري مزامنة البيانات سحابياً...</span>
        </div>
      )}

      {/* Toast Notifications */}
      <div className="fixed top-6 left-6 z-[300] space-y-3 pointer-events-none">
        {state.notifications.filter(n => !n.persistent && !n.isRead).slice(0, 3).map((notif) => (
          <div key={notif.id} className="pointer-events-auto animate-in slide-in-from-left-8 duration-300">
            <div className={`flex items-center gap-4 px-6 py-4 rounded-[1.5rem] shadow-2xl border-2 backdrop-blur-md 
              ${notif.type === 'success' ? 'bg-emerald-50/90 border-emerald-100 text-emerald-800' : 'bg-blue-50/90 border-blue-100 text-blue-800'}`}>
              {notif.type === 'success' ? <CheckCircle size={24} className="text-emerald-500" /> : <Bell size={24} className="text-blue-500" />}
              <span className="font-black text-sm">{notif.message}</span>
              <button onClick={() => setState(prev => ({ ...prev, notifications: prev.notifications.map(n => n.id === notif.id ? {...n, isRead: true} : n) }))}
                className="hover:bg-black/5 p-1 rounded-lg transition-colors mr-2">
                <X size={16} />
              </button>
            </div>
          </div>
        ))}
      </div>

      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-blue-900 text-white transition-transform duration-300 transform md:relative md:translate-x-0 md:w-64 flex flex-col no-print ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
        <div className="p-6 flex items-center justify-between border-b border-blue-800/50">
          <div className="flex items-center gap-3">
            <div className="bg-white p-1 rounded-xl shadow-lg">
              <ClubLogo size={42} />
            </div>
            <div className="overflow-hidden whitespace-nowrap">
              <h1 className="font-black text-lg leading-tight">نادي الكرامة</h1>
              <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">مكتب كرة القدم</p>
            </div>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="md:hidden text-blue-200"><X size={24} /></button>
        </div>

        <nav className="flex-1 mt-6 px-4 space-y-2 overflow-y-auto custom-scrollbar">
          {menuItems.map((item) => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); setSelectedPlayerForReport(null); }}
                className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/40' : 'hover:bg-blue-800 text-blue-100'}`}>
                <Icon size={22} /><span className="font-bold">{item.label}</span>
              </button>
