        <div className="p-6 border-t border-blue-800">
          <button onClick={handleLogout} className="w-full flex items-center gap-4 p-4 rounded-2xl text-red-300 hover:bg-red-900/30 transition-all font-bold">
            <LogOut size={22} /><span>تسجيل الخروج</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden w-full">
        <header className="bg-white border-b px-4 md:px-8 py-4 flex items-center justify-between no-print z-[150]">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="p-2 rounded-xl text-slate-600 md:hidden"><Menu size={24} /></button>
            <h2 className="text-lg md:text-xl font-black text-slate-800 truncate">
              {activeTab === 'player-report' ? `تقرير اللاعب: ${selectedPlayerForReport?.name}` : menuItems.find(m => m.id === activeTab)?.label}
            </h2>
          </div>
          <div className="flex items-center gap-3 md:gap-6">

            {state.currentUser?.role === 'مدير' && (
              <div className="relative" ref={notificationRef}>
                <button 
                  onClick={() => setShowNotifications(!showNotifications)}
                  className={`p-3 rounded-2xl transition-all relative ${showNotifications ? 'bg-orange-100 text-orange-600' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}
                >
                  <Bell size={22} />
                  {unreadCount > 0 && (
                    <span className="absolute top-0 right-0 w-5 h-5 bg-red-600 text-white text-[10px] font-black rounded-full flex items-center justify-center border-2 border-white translate-x-1/4 -translate-y-1/4">
                      {unreadCount}
                    </span>
                  )}
                </button>

                {showNotifications && (
                  <div className="absolute top-full left-0 mt-3 w-[320px] md:w-[400px] bg-white rounded-[2rem] shadow-2xl border border-slate-100 overflow-hidden animate-in slide-in-from-top-2 duration-200">
                    <div className="p-5 border-b flex items-center justify-between bg-slate-50">
                      <h3 className="font-black text-slate-800">تنبيهات النظام</h3>
                      <div className="flex gap-2">
                        <button onClick={markAllAsRead} className="text-[10px] font-bold text-blue-600 hover:underline">تحديد الكل كمقروء</button>
                        <button onClick={clearNotifications} className="text-[10px] font-bold text-red-500 hover:underline">مسح الكل</button>
                      </div>
                    </div>
                    <div className="max-h-[400px] overflow-y-auto custom-scrollbar">
                      {state.notifications.filter(n => n.persistent).length > 0 ? (
                        state.notifications.filter(n => n.persistent).slice().reverse().map(notif => (
                          <div key={notif.id} className={`p-4 border-b border-slate-50 transition-colors ${notif.isRead ? 'opacity-60' : 'bg-blue-50/30'}`}>
                            <div className="flex items-start gap-3">
                              <div className={`mt-1 p-2 rounded-xl ${notif.type === 'success' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                                {notif.type === 'success' ? <Trophy size={16}/> : <Calendar size={16}/>}
                              </div>
                              <div className="flex-1">
                                <p className="text-sm font-bold text-slate-800 leading-tight">{notif.message}</p>
                                <div className="flex items-center gap-1 mt-1 text-slate-400">
                                  <Clock size={10} />
                                  <span className="text-[10px] font-bold">
                                    {new Date(notif.timestamp).toLocaleString('ar-EG', { hour: '2-digit', minute: '2-digit', day: 'numeric', month: 'short' })}
                                  </span>
                                </div>
                              </div>
                            </div>
                          </div>
                        ))
                      ) : (
                        <div className="py-12 text-center">
                          <Bell size={40} className="mx-auto text-slate-100 mb-2" />
                          <p className="text-slate-400 font-bold text-sm">لا توجد تنبيهات جديدة</p>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            <div className="flex items-center gap-3">
              <div className="hidden sm:flex flex-col text-left items-end">
                <span className="font-black text-sm text-slate-700">{state.currentUser?.username}</span>
                <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded-full text-slate-500 font-bold">{state.currentUser?.role} {state.currentUser?.restrictedCategory ? `(${state.currentUser.restrictedCategory})` : ''}</span>
              </div>
              <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-2xl flex items-center justify-center font-black shadow-sm border border-orange-200 uppercase">{state.currentUser?.username?.charAt(0)}</div>
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 md:p-8 flex flex-col custom-scrollbar">
          <div className="max-w-7xl mx-auto flex-1 w-full">
            {renderContent()}
          </div>

          <footer className="mt-12 py-8 border-t border-slate-200 text-center no-print">
            <p className="text-slate-500 text-sm font-black uppercase tracking-widest">
              نظام إدارة مكتب كرة القدم - نادي الكرامة الرياضي
            </p>
            <p className="text-slate-400 text-xs mt-2 font-bold">
              Izzat Amer Alshikha 2026
            </p>
          </footer>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, Trash2, Calendar as CalendarIcon, 
  Target, AlertTriangle, Repeat, X, Users, UserCheck, ShieldAlert 
} from 'lucide-react';
import { AppState, Match, Category, Person } from '../types';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState }) => {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const canEdit = currentUser?.role === 'مدير' || (currentUser?.role === 'مدرب' && !!restrictedCat);
  const isReadOnly = !canEdit;

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null);

  const [formData, setFormData] = useState<Partial<Match>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'رجال')
  });

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.opponent || !formData.location) return;

    const todayStr = new Date().toISOString().split('T')[0];
    if (formData.date < todayStr) {
      alert('خطأ: لا يمكن جدولة مباراة بتاريخ قديم. يرجى اختيار تاريخ اليوم أو تاريخ مستقبلي.');
      return;
    }

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      category: formData.category as Category,
      opponent: formData.opponent,
      location: formData.location,
      advancePayment: formData.advancePayment || '0',
      date: formData.date,
      time: formData.time || '16:00',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      goalList: [],
      cardList: [],
      lineupDetails: {
        starters: Array(11).fill({ name: '', number: '' }),
        subs: Array(7).fill({ name: '', number: '' }),
        captain: '',
        substitutionList: []
      }
    };

    setState(prev => ({ 
      ...prev, 
      matches: [newMatch, ...prev.matches],
      notifications: [
        ...prev.notifications,
        {
          id: Math.random().toString(36).substr(2, 9),
          message: `تمت جدولة مباراة جديدة لفئة ${newMatch.category} ضد فريق ${newMatch.opponent}`,
          type: 'success',
          timestamp: Date.now(),
          isRead: false,
          persistent: true
        }
      ]
    }));
    setIsAddModalOpen(false);
    setFormData({ category: restrictedCat || (state.categories[0] || 'رجال') });
  };

  const handleUpdateResult = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMatch) return;
    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === selectedMatch.id ? { ...selectedMatch, isCompleted: true } : m),
      notifications: [
        ...prev.notifications,
        {
          id: Math.random().toString(36).substr(2, 9),
          message: `تم اعتماد نتيجة مباراة ${selectedMatch.category} ضد ${selectedMatch.opponent}`,
          type: 'success',
          timestamp: Date.now(),
          isRead: false,
          persistent: true
        }
      ]
    }));
    setIsResultModalOpen(false);
    setSelectedMatch(null);
  };

  const matchCategoryPlayers = selectedMatch 
    ? state.people.filter(p => p.category === selectedMatch.category && p.role === 'لاعب')
    : [];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">المواجهات الرسمية</h3>
        {canEdit && (
          <button onClick={() => setIsAddModalOpen(true)} className="bg-orange-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold shadow-lg shadow-orange-200">
            <Plus size={20} /> إضافة مباراة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 gap-6 no-print">
        {state.matches.filter(m => !restrictedCat || m.category === restrictedCat).map(match => (
          <div key={match.id} className="bg-white rounded-[3rem] shadow-sm border border-slate-100 overflow-hidden relative group">
             {canEdit && !match.isCompleted && (
               <button onClick={() => {if(confirm('هل تريد حذف هذه المباراة من الجدول؟')) setState(prev => ({...prev, matches: prev.matches.filter(m => m.id !== match.id)}))}} 
                 className="absolute top-6 left-6 p-2 text-red-300 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-opacity">
                 <Trash2 size={18} />
               </button>
             )}
             <div className="p-8">
                <div className="flex justify-between items-center mb-6">
                  <span className="bg-blue-900 text-white px-4 py-1 rounded-full text-[10px] font-black">{match.category}</span>
                  <span className={`px-4 py-1 rounded-full text-[10px] font-black uppercase ${match.isCompleted ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-50 text-slate-400'}`}>
                    {match.isCompleted ? 'منتهية' : 'قادمة'}
                  </span>
                </div>
                <div className="flex items-center justify-between gap-8">
                  <div className="flex-1 text-center font-black text-slate-800 text-lg">الكرامة <span className="block text-4xl text-blue-900 mt-2">{match.isCompleted ? match.ourScore : '-'}</span></div>
                  <div className="text-orange-500 font-black text-xl">ضد</div>
                  <div className="flex-1 text-center font-black text-slate-800 text-lg">{match.opponent} <span className="block text-4xl text-slate-400 mt-2">{match.isCompleted ? match.opponentScore : '-'}</span></div>
                </div>
                <div className="mt-8 pt-6 border-t border-slate-50 flex justify-between items-center">
                   <div className="flex gap-4 text-[11px] font-bold text-slate-500">
                     <span className="flex items-center gap-1"><MapPin size={14}/> {match.location}</span>
                     <span className="flex items-center gap-1"><CalendarIcon size={14}/> {match.date}</span>
                   </div>
                   {!isReadOnly && !match.isCompleted && (
                     <button onClick={() => {setSelectedMatch(match); setIsResultModalOpen(true);}} className="bg-slate-900 text-white px-6 py-2 rounded-xl text-xs font-black hover:bg-black transition-all">تسجيل النتيجة والتقرير</button>
                   )}
                   {match.isCompleted && (
                      <button onClick={() => {setSelectedMatch(match); setIsResultModalOpen(true);}} className="text-blue-600 text-xs font-black hover:underline">عرض التقرير الكامل</button>
                   )}
                </div>
             </div>
          </div>
        ))}
        {state.matches.filter(m => !restrictedCat || m.category === restrictedCat).length === 0 && (
          <div className="py-20 text-center bg-white rounded-[3rem] border-2 border-dashed border-slate-100 text-slate-400 font-bold italic">
            لا توجد مباريات مجدولة حالياً
          </div>
        )}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[200] p-4 no-print" onClick={(e) => e.target === e.currentTarget && setIsAddModalOpen(false)}>
          <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-slate-800 text-xl">إضافة مباراة جديدة</h3>
              <button onClick={() => setIsAddModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-red-600 transition-all"><X size={20} /></button>
            </div>
            <form onSubmit={handleAddMatch} className="p-8 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الفئة</label>
                  <select className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" value={formData.category} disabled={!!restrictedCat} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                    {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">المنافس</label>
                  <input type="text" required placeholder="اسم المنافس" className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" onChange={e => setFormData({ ...formData, opponent: e.target.value })} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">الملعب / المكان</label>
                <input type="text" required placeholder="الملعب" className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">التاريخ</label>
                  <input type="date" required min={new Date().toISOString().split('T')[0]} className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" onChange={e => setFormData({ ...formData, date: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الوقت</label>
                  <input type="time" required className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>
              <div className="flex gap-3 mt-4">
                <button type="button" onClick={() => setIsAddModalOpen(false)} className="flex-1 bg-slate-100 text-slate-600 font-black py-4 rounded-2xl hover:bg-slate-200 transition-all">إلغاء</button>
                <button type="submit" className="flex-1 bg-blue-900 text-white font-black py-4 rounded-2xl hover:bg-black transition-all">حفظ الجدولة</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {isResultModalOpen && selectedMatch && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[210] p-4 no-print overflow-y-auto" onClick={(e) => e.target === e.currentTarget && setIsResultModalOpen(false)}>
          <div className="bg-white rounded-[3.5rem] w-full max-w-6xl shadow-2xl my-auto max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <div className="flex items-center gap-4">
                 <div className="bg-blue-900 p-3 rounded-2xl text-white"><Trophy size={24}/></div>
                 <div>
                    <h3 className="text-xl font-black text-slate-800 leading-tight">تقرير المباراة الفني</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">فئة {selectedMatch.category} ضد {selectedMatch.opponent}</p>
                 </div>
              </div>
              <button onClick={() => setIsResultModalOpen(false)} className="bg-slate-200 p-2 rounded-xl hover:text-red-600 transition-all"><X size={20} /></button>
            </div>

            <form onSubmit={handleUpdateResult} className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar">

              {/* Score Section */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-center bg-slate-50 p-10 rounded-[3rem] border border-slate-100">
                <div className="space-y-4 text-center">
                  <span className="text-xs font-black text-blue-900 uppercase tracking-widest">نادي الكرامة</span>
                  <input type="number" disabled={isReadOnly} className="w-full bg-white rounded-3xl p-8 text-center text-5xl font-black text-slate-950 outline-none border-4 border-slate-100 focus:border-blue-500 shadow-xl" value={selectedMatch.ourScore} onChange={e => setSelectedMatch({ ...selectedMatch, ourScore: e.target.value })} />
                </div>
                <div className="text-center font-black text-3xl text-slate-300 italic">VS</div>
                <div className="space-y-4 text-center">
                  <span className="text-xs font-black text-slate-500 uppercase tracking-widest">{selectedMatch.opponent}</span>
                  <input type="number" disabled={isReadOnly} className="w-full bg-white rounded-3xl p-8 text-center text-5xl font-black text-slate-950 outline-none border-4 border-slate-100 focus:border-blue-500 shadow-xl" value={selectedMatch.opponentScore} onChange={e => setSelectedMatch({ ...selectedMatch, opponentScore: e.target.value })} />
                </div>
              </div>

              {/* Lineup Section */}
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Starters */}
                <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 space-y-6">
                  <h4 className="text-sm font-black text-blue-900 flex items-center gap-2 border-r-4 border-blue-600 pr-3 uppercase">التشكيلة الأساسية (11)</h4>
                  <div className="grid grid-cols-1 gap-3">
                    {selectedMatch.lineupDetails?.starters.map((slot, i) => (
                      <div key={i} className="flex items-center gap-3 animate-in fade-in duration-300" style={{ animationDelay: `${i * 50}ms` }}>
                         <span className="text-[10px] font-black text-slate-400 w-6 h-6 rounded-full bg-slate-50 flex items-center justify-center">{i+1}</span>
                         <select disabled={isReadOnly} className="flex-1 bg-slate-50 border border-transparent focus:border-blue-200 rounded-xl px-4 py-3 text-sm font-bold text-slate-950 outline-none" 
                           value={state.people.find(p => p.name === slot.name)?.id || ''} 
                           onChange={e => {
                             const p = state.people.find(person => person.id === e.target.value);
                             const newList = [...selectedMatch.lineupDetails!.starters];
                             newList[i] = { name: p?.name || '', number: p?.number?.toString() || '' };
                             setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, starters: newList}});
                           }}>
                           <option value="">-- اختر لاعب --</option>
                           {matchCategoryPlayers.map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                         </select>
                         <div className="w-12 h-10 bg-slate-900 text-white rounded-xl flex items-center justify-center font-black text-xs">
                           {slot.number || '--'}
                         </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Subs */}
                <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 space-y-6">
                   <h4 className="text-sm font-black text-orange-600 flex items-center gap-2 border-r-4 border-orange-500 pr-3 uppercase">قائمة البدلاء</h4>
                   <div className="grid grid-cols-1 gap-3">
                    {selectedMatch.lineupDetails?.subs.map((slot, i) => (
                      <div key={i} className="flex items-center gap-3">
                         <span className="text-[10px] font-black text-slate-400 w-6 h-6 rounded-full bg-slate-50 flex items-center justify-center">{i+1}</span>
                         <select disabled={isReadOnly} className="flex-1 bg-slate-50 border border-transparent focus:border-orange-200 rounded-xl px-4 py-3 text-sm font-bold text-slate-950 outline-none" 
                           value={state.people.find(p => p.name === slot.name)?.id || ''} 
                           onChange={e => {
                             const p = state.people.find(person => person.id === e.target.value);
                             const newList = [...selectedMatch.lineupDetails!.subs];
                             newList[i] = { name: p?.name || '', number: p?.number?.toString() || '' };
                             setSelectedMatch({...selectedMatch, lineupDetails: {...selectedMatch.lineupDetails!, subs: newList}});
                           }}>
                           <option value="">-- اختر لاعب --</option>
                           {matchCategoryPlayers.map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                         </select>
                         <div className="w-12 h-10 bg-orange-600 text-white rounded-xl flex items-center justify-center font-black text-xs">
                           {slot.number || '--'}
                         </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Match Events: Goals, Cards, Substitutions */}
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

                {/* Goals */}
                <div className="space-y-4">
                   <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><Target size={16} className="text-blue-600"/> مسجلو الأهداف</h4>
                   <div className="space-y-2">
                     {selectedMatch.goalList.map((g, i) => (
                       <div key={i} className="flex gap-2">
                          <select disabled={isReadOnly} className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-950 outline-none" 
                            value={state.people.find(p => p.name === g.player)?.id || ''} 
                            onChange={e => {
                              const p = state.people.find(person => person.id === e.target.value);
                              const newList = [...selectedMatch.goalList];
                              newList[i] = { player: p?.name || '', number: p?.number?.toString() || '', time: newList[i].time };
                              setSelectedMatch({...selectedMatch, goalList: newList});
                            }}>
                            <option value="">-- لاعب --</option>
                            {matchCategoryPlayers.map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                          </select>
                          <input type="text" disabled={isReadOnly} placeholder="د'" className="w-16 bg-white border border-slate-200 rounded-xl px-2 py-2 text-xs font-bold text-center text-slate-950" value={g.time} onChange={e => {
                            const newList = [...selectedMatch.goalList];
                            newList[i].time = e.target.value;
                            setSelectedMatch({...selectedMatch, goalList: newList});
                          }} />
                          {!isReadOnly && <button type="button" onClick={() => setSelectedMatch({...selectedMatch, goalList: selectedMatch.goalList.filter((_, idx) => idx !== i)})} className="text-red-400 p-2 hover:bg-red-50 rounded-lg"><X size={14}/></button>}
                       </div>
                     ))}
                     {!isReadOnly && <button type="button" onClick={() => setSelectedMatch({...selectedMatch, goalList: [...selectedMatch.goalList, {player:'', number:'', time:''}]})} className="w-full py-2 border-2 border-dashed border-slate-200 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-300 hover:text-blue-600 transition-all">+ إضافة هدف</button>}
                   </div>
                </div>

                {/* Cards */}
                <div className="space-y-4">
                   <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><AlertTriangle size={16} className="text-yellow-500"/> سجل العقوبات</h4>
                   <div className="space-y-2">
                     {selectedMatch.cardList.map((c, i) => (
                       <div key={i} className="flex gap-2">
                          <select disabled={isReadOnly} className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-950 outline-none" 
                            value={state.people.find(p => p.name === c.player)?.id || ''} 
                            onChange={e => {
                              const p = state.people.find(person => person.id === e.target.value);
                              const newList = [...selectedMatch.cardList];
                              newList[i] = { ...newList[i], player: p?.name || '', number: p?.number?.toString() || '' };
