export interface AppNotification {
  id: string;
  message: string;
  type: 'info' | 'success' | 'warning';
  timestamp: number;
  isRead?: boolean;
  persistent?: boolean;
}

export interface Person {
  id: string;
  name: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  address?: string;
  joinDate: string;
  federalNumber?: string;
