    // مصفوفة المستخدمين الافتراضية المحدثة حسب الطلب
    const defaultUsers: AppUser[] = [
      { id: 'admin-main', username: 'IZZAT', role: 'مدير', password: 'KSC@2026' },
      { id: 'u-men', username: 'MEN', role: 'مدرب', password: 'KSC2026', restrictedCategory: 'رجال' },
      { id: 'u-18', username: 'U18', role: 'مدرب', password: 'KSC2026', restrictedCategory: 'شباب' },
