      { id: 'u-14', username: 'U14', role: 'مدرب', password: 'KSC2026', restrictedCategory: 'أشبال' },
    ];

    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.matches) parsed.matches = [];
      if (!parsed.notifications) parsed.notifications = [];
      if (!parsed.categories) parsed.categories = defaultCategories;

      // دمج المستخدمين الافتراضيين مع المخزنين لضمان وجود الحساب الرئيسي دائماً
      parsed.users = parsed.users || [];
      defaultUsers.forEach(defUser => {
        const existingIdx = parsed.users.findIndex((u: AppUser) => u.username === defUser.username);
        if (existingIdx > -1) {
          // تحديث كلمة المرور للحسابات الافتراضية إذا وجدت
          parsed.users[existingIdx].password = defUser.password;
          parsed.users[existingIdx].role = defUser.role;
        } else {
          parsed.users.push(defUser);
        }
      });

      return parsed;
