import React, { useState } from 'react';
import { Lock, User, Eye, EyeOff } from 'lucide-react';
import { AppUser, AppState } from '../types';
import ClubLogo from './ClubLogo';

interface LoginProps {
  onLogin: (user: AppUser) => void;
  state: AppState;
}

const Login: React.FC<LoginProps> = ({ onLogin, state }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = state.users.find(u => u.username.toUpperCase() === username.trim().toUpperCase());
    if (user && user.password === password) {
      onLogin(user);
    } else {
      setError('خطأ في بيانات الدخول. يرجى التثبت والمحاولة مجدداً.');
    }
  };

  return (
    <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 font-['Tajawal']" dir="rtl">
      <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-white/10 animate-in fade-in zoom-in-95 duration-700">
        <div className="bg-gradient-to-br from-blue-900 to-blue-800 p-12 flex flex-col items-center text-center relative overflow-hidden">
          <div className="absolute -top-10 -right-10 w-40 h-40 bg-orange-500/10 rounded-full blur-3xl"></div>
          <div className="bg-white p-4 rounded-[2.5rem] shadow-2xl mb-6 scale-110">
            <ClubLogo size={100} />
          </div>
          <h2 className="text-white font-black text-2xl tracking-tight leading-snug">أهلاً بك في أفضل أندية سوريا</h2>
          <p className="text-orange-400 font-black mt-2 text-sm uppercase tracking-widest">نادي الكرامة الرياضي</p>
        </div>

        <div className="p-10 space-y-6">
          <form onSubmit={handleLogin} className="space-y-5">
            {error && <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-[10px] font-black text-center border border-red-100">{error}</div>}

            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-400 mr-2 uppercase">اسم المستخدم</label>
              <div className="relative">
                <User className="absolute right-4 top-4 text-slate-300" size={18} />
                <input type="text" value={username} onChange={e => setUsername(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 pr-12 pl-4 outline-none focus:ring-2 focus:ring-blue-500 font-black text-slate-800 transition-all" />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-400 mr-2 uppercase">كلمة المرور</label>
              <div className="relative">
                <Lock className="absolute right-4 top-4 text-slate-300" size={18} />
                <input type={showPass ? "text" : "password"} value={password} onChange={e => setPassword(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 pr-12 pl-12 outline-none focus:ring-2 focus:ring-blue-500 font-black text-slate-800 transition-all" />
                <button type="button" onClick={() => setShowPass(!showPass)} className="absolute left-4 top-4 text-slate-300 hover:text-blue-600 transition-colors">
                  {showPass ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            <button type="submit" className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl hover:bg-black transition-all shadow-xl shadow-blue-200 mt-4 text-lg">دخول للنظام</button>
          </form>

          <div className="pt-6 border-t border-slate-100 text-center space-y-1">
            <p className="text-[10px] text-slate-500 font-black uppercase">Football Management System</p>
            <p className="text-[9px] text-slate-400 font-bold">By: Izzat Amer Alshikha 2026</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React from 'react';
import { Users, Calendar, Trophy, ArrowLeftCircle, Clock, MapPin } from 'lucide-react';
import { AppState, TrainingSession, Match } from '../types';

interface DashboardProps {
  state: AppState;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, onMatchClick, onSessionClick }) => {
  const today = new Date().toISOString().split('T')[0];

  const upcomingMatches = state.matches
    .filter(m => m.date >= today && !m.isCompleted)
    .sort((a, b) => a.date.localeCompare(b.date));

  const upcomingSessions = state.sessions
    .filter(s => s.date >= today)
    .sort((a, b) => a.date.localeCompare(b.date));

  const stats = [
    { label: 'الكوادر المسجلة', value: state.people.length, icon: Users, color: 'blue' },
    { label: 'المباريات القادمة', value: upcomingMatches.length, icon: Trophy, color: 'emerald' },
    { label: 'التمارين القادمة', value: upcomingSessions.length, icon: Calendar, color: 'orange' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {stats.map((s, i) => (
          <div key={i} className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col items-center">
             <div className={`p-4 rounded-2xl mb-4 ${s.color === 'blue' ? 'bg-blue-50 text-blue-600' : s.color === 'emerald' ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
               <s.icon size={28} />
             </div>
             <h3 className="text-slate-400 text-[10px] font-black uppercase tracking-widest">{s.label}</h3>
             <p className="text-3xl font-black text-slate-800 mt-1">{s.value}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Upcoming Matches */}
        <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Trophy className="text-blue-900" size={24} /> المواجهات القادمة
            </h3>
            <span className="text-[10px] bg-blue-50 text-blue-700 px-3 py-1 rounded-full font-black uppercase tracking-tighter">قيد الانتظار</span>
          </div>
          <div className="space-y-4">
            {upcomingMatches.length > 0 ? upcomingMatches.map(m => (
              <button key={m.id} onClick={() => onMatchClick(m.id)} className="w-full text-right p-6 rounded-[2rem] bg-slate-50 border border-slate-100 hover:bg-blue-900 hover:text-white transition-all group relative overflow-hidden">
                <div className="flex justify-between items-center">
                  <div>
                    <p className="text-[10px] font-black opacity-60 mb-1">{m.category} | {m.matchType}</p>
                    <h4 className="font-black text-lg">الكرامة vs {m.opponent}</h4>
                    <div className="flex gap-4 mt-2 text-[10px] font-bold opacity-80">
                       <span className="flex items-center gap-1"><Clock size={12}/> {m.date} | {m.time}</span>
                       <span className="flex items-center gap-1"><MapPin size={12}/> {m.location}</span>
                    </div>
                  </div>
                  <ArrowLeftCircle className="text-blue-900 group-hover:text-white transition-colors" size={24} />
                </div>
              </button>
            )) : (
              <div className="py-12 text-center text-slate-300 font-bold italic">لا توجد مباريات مجدولة</div>
            )}
