        {/* Upcoming Training */}
        <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Calendar className="text-orange-500" size={24} /> التمارين المجدولة
            </h3>
            <span className="text-[10px] bg-orange-50 text-orange-600 px-3 py-1 rounded-full font-black uppercase tracking-tighter">الموعد القادم</span>
          </div>
          <div className="space-y-4">
            {upcomingSessions.length > 0 ? upcomingSessions.map(s => (
              <button key={s.id} onClick={() => onSessionClick(s.id)} className="w-full text-right p-6 rounded-[2rem] bg-slate-50 border border-slate-100 hover:bg-orange-600 hover:text-white transition-all group">
                <div className="flex justify-between items-center">
                  <div>
                    <p className="text-[10px] font-black opacity-60 mb-1">{s.category}</p>
                    <h4 className="font-black text-lg">{s.objective}</h4>
