import React, { useState, useEffect } from 'react';
import { 
  UserPlus, Trash2, Search, X, Hash, Phone, MapPin, CreditCard, 
  Shield, Award, Layers, GraduationCap, Home, Plus, Briefcase, Stethoscope, AlertCircle
} from 'lucide-react';
import { AppState, Person, Category, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCat, setSelectedCat] = useState<Category | 'الكل'>('الكل');

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: state.categories[0] || 'رجال',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return null;
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        ...(formData as Person)
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
    }
    setIsModalOpen(false);
    setEditingId(null);
    setFormData({ role: 'لاعب', category: state.categories[0], joinDate: new Date().toISOString().split('T')[0] });
  };

  const filtered = state.people.filter(p => {
    const matchCat = selectedCat === 'الكل' ? true : p.category === selectedCat;
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchCat && matchSearch;
  });

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4 no-print">
        <div className="flex-1 relative">
          <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" />
          <input type="text" placeholder="البحث بالاسم..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
            className="w-full bg-slate-50 border border-slate-100 rounded-2xl py-4 pr-12 pl-4 outline-none font-black text-slate-800 focus:ring-2 focus:ring-blue-900" />
        </div>
        <div className="flex gap-2">
          <select value={selectedCat} onChange={e => setSelectedCat(e.target.value)} className="bg-slate-50 border border-slate-100 rounded-2xl px-6 font-black text-sm">
            <option value="الكل">كل الفئات</option>
            {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <button onClick={() => { setEditingId(null); setIsModalOpen(true); }} className="bg-blue-900 text-white px-8 rounded-2xl font-black flex items-center gap-2 shadow-xl shadow-blue-200">
            <UserPlus size={20} /> إضافة عضو
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filtered.map(person => {
          const contractDaysLeft = person.contractEnd ? Math.ceil((new Date(person.contractEnd).getTime() - new Date().getTime()) / (1000 * 3600 * 24)) : null;
          const isExpiring = contractDaysLeft !== null && contractDaysLeft < 90;

          return (
            <div key={person.id} className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100 group relative overflow-hidden transition-all hover:shadow-xl">
               <div className="flex justify-between items-start mb-6">
                 <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center font-black text-blue-900 text-xl">
                   {person.name.charAt(0)}
                 </div>
                 <div className="flex flex-col items-end">
                    <span className="bg-blue-900 text-white text-[9px] font-black px-3 py-1 rounded-full uppercase">{person.role}</span>
                    <span className="text-[10px] font-bold text-slate-400 mt-1">{person.category}</span>
                 </div>
               </div>

               <div className="space-y-1">
                 <h4 className="font-black text-xl text-slate-800">{person.name}</h4>
                 <div className="flex gap-3 text-[10px] font-bold text-slate-400">
                   <span className="flex items-center gap-1"><Home size={12}/> {person.birthPlace}</span>
                   <span className="flex items-center gap-1"><Calendar size={12}/> {calculateAge(person.birthDate)} سنة</span>
                 </div>
               </div>

               <div className="mt-6 grid grid-cols-2 gap-2">
                  <div className="bg-slate-50 p-3 rounded-xl">
                    <p className="text-[8px] font-black text-slate-400 uppercase">الرقم الوطني</p>
                    <p className="text-xs font-black text-slate-800">{person.nationalId || '-'}</p>
                  </div>
                  <div className="bg-slate-50 p-3 rounded-xl">
                    <p className="text-[8px] font-black text-slate-400 uppercase">رقم القميص</p>
                    <p className="text-xs font-black text-blue-900">#{person.number || '00'}</p>
                  </div>
               </div>

               {isExpiring && (
                 <div className="mt-4 flex items-center gap-2 text-orange-600 bg-orange-50 p-2 rounded-xl border border-orange-100 animate-pulse">
                   <AlertCircle size={14} />
                   <span className="text-[10px] font-black">ينتهي العقد خلال {contractDaysLeft} يوم</span>
                 </div>
               )}

               <div className="mt-8 pt-6 border-t border-slate-50 flex justify-between items-center opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={() => onOpenReport?.(person)} className="text-blue-900 text-[10px] font-black hover:underline flex items-center gap-1">عرض الملف الكامل <Plus size={12}/></button>
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-2 text-slate-400 hover:text-blue-600"><Plus size={16} /></button>
                    <button onClick={() => { if(confirm('حذف نهائي؟')) setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); }} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={16} /></button>
                  </div>
               </div>
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[200] p-4 overflow-y-auto no-print">
          <div className="bg-white rounded-[4rem] w-full max-w-6xl shadow-2xl my-auto overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-2xl font-black text-slate-800">{editingId ? 'تحديث بيانات العضو' : 'تسجيل عضو جديد بالنادي'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-2xl"><X size={24} /></button>
            </div>

            <form onSubmit={handleSave} className="p-10 max-h-[75vh] overflow-y-auto custom-scrollbar space-y-12">
              <div className="space-y-6">
                <h4 className="text-sm font-black text-blue-900 border-r-4 border-blue-900 pr-3">المعلومات الشخصية والمدنية</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  <div className="space-y-1.5 col-span-1 md:col-span-2">
                    <label className="text-[10px] font-black text-slate-400">الاسم الثنائي الكامل</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 font-black" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400">اسم الأب</label>
                    <input type="text" value={formData.fatherName || ''} onChange={e => setFormData({...formData, fatherName: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 font-black" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400">اسم الأم</label>
                    <input type="text" value={formData.motherName || ''} onChange={e => setFormData({...formData, motherName: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 font-black" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400">تاريخ الميلاد</label>
                    <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({...formData, birthDate: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 font-black" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400">مكان الميلاد</label>
                    <input type="text" value={formData.birthPlace || ''} onChange={e => setFormData({...formData, birthPlace: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 font-black" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400">العمر الحالي</label>
