import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, Clock, AlertTriangle, ShieldCheck, ShieldAlert, History } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus; excuse?: string; fine?: string }>>({});

  const currentUser = state.currentUser!;
  const today = new Date().toISOString().split('T')[0];

  const sessions = state.sessions
    .filter(s => !currentUser.restrictedCategory || s.category === currentUser.restrictedCategory)
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const players = state.people.filter(p => p.role === 'لاعب' && (activeSession ? p.category === activeSession.category : true));

  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  // التحقق من إقفال السجل (بعد 30 دقيقة من وقت التمرين)
  const isSessionLocked = () => {
    if (!activeSession) return false;
    const sessionTime = new Date(`${activeSession.date}T${activeSession.time}`);
    const now = new Date();
    const diff = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diff > 30 && currentUser.role !== 'مدير';
  };

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if (isSessionLocked()) return alert('عفواً، تم إقفال السجل زمنياً (مر أكثر من 30 دقيقة).');
    if (savedRecords.some(r => r.personId === pid) && currentUser.role !== 'مدير') return alert('السجل محفوظ مسبقاً، التعديل متاح للمدير فقط.');

    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status } }));
  };

  const saveAttendance = () => {
    const entries = Object.entries(localRecords);
    if (entries.length === 0) return alert('يرجى تحديد حالة اللاعبين');

    const now = new Date().toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', numberingSystem: 'latn' });
    const newRecords: AttendanceRecord[] = entries.map(([pid, data]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      sessionId: selectedSessionId,
      date: activeSession!.date,
      time: now,
      status: data.status,
      excuse: data.excuse,
      fine: data.fine,
      isLocked: true
    }));

    setState(p => ({
      ...p,
      attendance: [
        ...p.attendance.filter(a => !(a.sessionId === selectedSessionId && localRecords[a.personId])),
        ...newRecords
      ],
      notifications: [...p.notifications, {
        id: Math.random().toString(36).substr(2, 9),
        message: 'تم حفظ ومزامنة سجل الحضور بنجاح.',
        type: 'success',
        timestamp: Date.now()
      }]
    }));
    setLocalRecords({});
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100 flex flex-col md:flex-row gap-6 items-end no-print">
        <div className="flex-1 space-y-2 w-full">
           <label className="text-[10px] font-black text-slate-400 mr-2 uppercase">اختيار تمرين من القائمة</label>
           <select value={selectedSessionId} onChange={e => setSelectedSessionId(e.target.value)}
            className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 font-black outline-none focus:ring-2 focus:ring-blue-900">
             <option value="">-- اختر التمرين المستهدف --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} - {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <button onClick={saveAttendance} className="bg-emerald-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl shadow-emerald-200 flex items-center gap-2 transition-all hover:bg-black">
          <Save size={20} /> اعتماد وحفظ السجل
        </button>
      </div>

      {activeSession && (
        <div className="bg-white rounded-[3rem] shadow-sm border border-slate-100 overflow-hidden relative">
          {isSessionLocked() && (
            <div className="bg-red-50 p-4 border-b border-red-100 text-red-600 flex items-center justify-center gap-3 font-black text-xs">
              <ShieldAlert size={18} /> تم إقفال السجل زمنياً (التعديل مقيد للمدير العام فقط)
            </div>
          )}

          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[800px]">
              <thead className="bg-slate-50">
                <tr>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase">اللاعب</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase text-center">الحالة الانضباطية</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase">ملاحظات / غرامات</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase text-center">الوقت</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {players.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];
                  const status = local?.status || saved?.status;

                  return (
                    <tr key={p.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-8 py-4">
                        <span className="font-black text-slate-800 block">{p.name}</span>
                        <span className="text-[10px] font-bold text-slate-400">رقم: {p.number}</span>
                      </td>
                      <td className="px-8 py-4">
                        <div className="flex justify-center gap-1.5">
                          {['حاضر', 'متأخر', 'غائب', 'غياب بعذر'].map(st => (
                            <button key={st} onClick={() => handleSetStatus(p.id, st as AttendanceStatus)}
                              className={`px-3 py-2 rounded-xl text-[9px] font-black border transition-all ${status === st ? 
                                (st === 'حاضر' ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg shadow-emerald-100' : 
                                 st === 'متأخر' ? 'bg-orange-500 text-white border-orange-500 shadow-lg shadow-orange-100' : 
                                 st === 'غياب بعذر' ? 'bg-blue-600 text-white border-blue-600' : 'bg-red-600 text-white border-red-600 shadow-lg shadow-red-100') 
                                : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}>
                              {st}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-8 py-4">
                        <input type="text" placeholder="عذر أو مخالفة..." disabled={isSessionLocked() && !saved}
                          value={local?.excuse || saved?.excuse || ''}
                          onChange={e => setLocalRecords(prev => ({ ...prev, [p.id]: { ...prev[p.id], excuse: e.target.value } }))}
                          className="bg-slate-50 border border-slate-100 rounded-xl px-4 py-2 text-[10px] font-bold w-full outline-none focus:ring-1 focus:ring-blue-900" />
                      </td>
                      <td className="px-8 py-4 text-center">
                        <span className="text-[9px] font-black text-blue-900 bg-blue-50 px-2 py-1 rounded-lg border border-blue-100 flex items-center gap-1 justify-center w-max mx-auto">
                          <History size={10} /> {local?.status ? 'الآن' : saved?.time || '--:--'}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

