                                <option value="">-- اختر احتياطي --</option>
                                {getAvailablePlayers(activeMatch, s.name).map(p => <option key={p.id} value={p.name}>{p.name} (#{p.number})</option>)}
                              </select>
                              <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: activeMatch.lineup.subs.filter((_, idx) => idx !== i)}})} className="p-2 text-red-300"><Trash2 size={16}/></button>
                            </div>
                          ))}
                          <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: [...activeMatch.lineup.subs, {name:'', number:''}]}})} className="w-full py-3 border-2 border-dashed border-slate-100 rounded-2xl text-[10px] font-black text-slate-400">+ إضافة لاعب بديل</button>
                       </div>
                    </div>
                 </div>

                 <div className="flex gap-4 pt-10 border-t">
                    <button onClick={() => setActiveMatch(null)} className="flex-1 bg-slate-100 text-slate-600 font-black py-5 rounded-[2rem]">إغلاق دون حفظ</button>
                    <button onClick={() => {
                      setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? activeMatch : m) }));
                      setActiveMatch(null);
                    }} className="flex-[2] bg-blue-900 text-white font-black py-5 rounded-[2rem] shadow-2xl">اعتماد وتثبيت التقرير</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

