            <UserPlus size={20} /> إضافة عضو
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filtered.map(person => {
          const contractDaysLeft = person.contractEnd ? Math.ceil((new Date(person.contractEnd).getTime() - new Date().getTime()) / (1000 * 3600 * 24)) : null;
