                <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center font-black text-2xl border border-slate-100">
                  {m.isCompleted ? `${m.ourScore} : ${m.opponentScore}` : 'VS'}
                </div>
                <div className="flex-1 font-black text-xl text-slate-800">{m.opponent}</div>
             </div>
             <div className="mt-8 pt-6 border-t border-slate-50 flex justify-between items-end">
