             </div>
          </div>
        ))}
      </div>

      {isAddOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[250] p-4 no-print">
          <div className="bg-white rounded-[3.5rem] w-full max-w-lg shadow-2xl animate-in zoom-in-95 duration-200">
             <div className="p-8 border-b bg-slate-50 flex justify-between items-center rounded-t-[3.5rem]">
               <h3 className="text-xl font-black text-slate-800">جدولة مباراة جديدة</h3>
