                     {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                   </select>
                 </div>
                 <div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400">نوع المباراة</label>
                   <select value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})} className="w-full bg-slate-50 p-4 rounded-2xl font-black text-sm outline-none border border-slate-100">
                     <option value="دوري">دوري</option><option value="كأس">كأس</option><option value="ودية">ودية</option>
