import React from 'react';
import { Users, Calendar, Trophy, ArrowLeftCircle, Clock, MapPin, AlertCircle, ChevronRight } from 'lucide-react';
import { AppState, TrainingSession, Match } from '../types';

interface DashboardProps {
  state: AppState;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, onMatchClick, onSessionClick }) => {
  const today = new Date().toISOString().split('T')[0];
  const globalFilter = state.globalCategoryFilter;

  const upcomingMatches = state.matches
    .filter(m => (globalFilter === 'الكل' || m.category === globalFilter) && m.date >= today && !m.isCompleted)
    .sort((a, b) => a.date.localeCompare(b.date));

  const upcomingSessions = state.sessions
    .filter(s => (globalFilter === 'الكل' || s.category === globalFilter) && s.date >= today)
    .sort((a, b) => a.date.localeCompare(b.date));

  // تنبيهات العقود
  const expiringContracts = state.people.filter(p => {
    if (!p.contractEnd) return false;
    const diff = (new Date(p.contractEnd).getTime() - new Date().getTime()) / (1000 * 3600 * 24);
    return diff < 90 && diff > 0;
  });

  const stats = [
    { label: 'الكوادر المسجلة', value: state.people.filter(p => globalFilter === 'الكل' || p.category === globalFilter).length, icon: Users, color: 'blue' },
    { label: 'المباريات القادمة', value: upcomingMatches.length, icon: Trophy, color: 'emerald' },
    { label: 'التمارين القادمة', value: upcomingSessions.length, icon: Calendar, color: 'orange' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {stats.map((s, i) => (
          <div key={i} className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100 flex flex-col items-center hover:shadow-xl transition-shadow cursor-default group">
             <div className={`p-5 rounded-3xl mb-4 transition-transform group-hover:scale-110 ${s.color === 'blue' ? 'bg-blue-50 text-blue-600' : s.color === 'emerald' ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
               <s.icon size={32} />
             </div>
             <h3 className="text-slate-400 text-[11px] font-black uppercase tracking-widest">{s.label}</h3>
             <p className="text-4xl font-black text-slate-800 mt-2">{s.value}</p>
          </div>
