import React, { useState } from 'react';
import { ShieldCheck, CloudUpload, Trash2, Key, Info, UserPlus, X, Edit2, ShieldAlert, Layers, Plus } from 'lucide-react';
import { AppState, AppUser, UserRole, Category } from '../types';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState, addLog }) => {
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newCatName, setNewCatName] = useState('');

  const [userFormData, setUserFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'إداري فئة'
  });

  const roles: UserRole[] = ['مدير', 'إداري فئة', 'مشاهد'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.username) return;

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...userFormData } as AppUser : u)
      }));
      addLog?.('تعديل مستخدم', `تم تحديث بيانات المستخدم: ${userFormData.username}`);
    } else {
      const newUser: AppUser = {
        id: Math.random().toString(36).substr(2, 9),
        username: userFormData.username!,
        role: userFormData.role as UserRole,
        password: 'KSC' + (Math.floor(Math.random() * 9000) + 1000),
        restrictedCategory: userFormData.role === 'مدير' ? undefined : userFormData.restrictedCategory
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
      addLog?.('إضافة مستخدم', `تم إنشاء مستخدم جديد: ${newUser.username}`, 'success');
    }

    setIsUserModalOpen(false);
    setEditingUserId(null);
    setUserFormData({ username: '', role: 'إداري فئة' });
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('الفئة موجودة مسبقاً');

    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة', `تمت إضافة فئة جديدة: ${newCatName.trim()}`, 'success');
    setNewCatName('');
  };

  const removeCategory = (cat: string) => {
    if (confirm(`هل أنت متأكد من حذف فئة ${cat}؟ سيؤدي هذا لتغيير فئة المنتسبين لها.`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
      addLog?.('حذف فئة', `تم حذف فئة: ${cat}`, 'warning');
    }
  };

  const exportToDrive = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_pro_v2_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    addLog?.('تصدير بيانات', 'تم تصدير ملف النسخة الاحتياطية بنجاح.');
  };

  return (
    <div className="max-w-5xl mx-auto space-y-10 pb-20">
      {/* Category Management */}
      <div className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-slate-100">
        <h3 className="text-2xl font-black text-slate-800 mb-8 flex items-center gap-4">
          <div className="p-3 bg-blue-50 text-blue-900 rounded-2xl"><Layers size={24} /></div>
          إدارة الفئات الرياضية
        </h3>
        <div className="flex flex-col md:flex-row gap-4 mb-8">
          <input 
            type="text" 
            value={newCatName} 
            onChange={e => setNewCatName(e.target.value)}
            placeholder="اسم الفئة الجديدة (مثلاً: فئة الناشئين ب)"
            className="flex-1 bg-slate-50 border-2 border-slate-100 rounded-2xl p-5 font-black text-lg outline-none focus:ring-2 focus:ring-blue-900 focus:bg-white transition-all"
          />
          <button 
            onClick={handleAddCategory}
            className="bg-blue-900 text-white px-10 py-5 rounded-2xl font-black hover:bg-black transition-all flex items-center justify-center gap-2 shadow-xl shadow-blue-200"
          >
            <Plus size={24} /> إضافة الفئة
          </button>
        </div>
        <div className="flex flex-wrap gap-3">
          {state.categories.map(c => (
            <div key={c} className="group flex items-center gap-4 bg-slate-100 px-6 py-3 rounded-2xl border-2 border-transparent hover:border-blue-200 hover:bg-white transition-all">
              <span className="font-black text-slate-800">{c}</span>
              <button onClick={() => removeCategory(c)} className="text-red-300 hover:text-red-600 transition-colors">
                <Trash2 size={16} />
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* User Management */}
      <div className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-10">
          <h3 className="text-2xl font-black text-slate-800 flex items-center gap-4">
            <div className="p-3 bg-orange-50 text-orange-600 rounded-2xl"><ShieldCheck size={24} /></div>
            الصلاحيات والمستخدمين
          </h3>
          <button 
            onClick={() => { setEditingUserId(null); setUserFormData({ username: '', role: 'إداري فئة' }); setIsUserModalOpen(true); }}
            className="bg-orange-600 text-white px-8 py-3.5 rounded-2xl font-black text-sm flex items-center gap-3 hover:bg-black transition-all shadow-xl shadow-orange-100"
          >
            <UserPlus size={20} /> إضافة حساب جديد
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          {state.users.map(user => (
            <div key={user.id} className="group flex items-center justify-between p-6 bg-slate-50 rounded-[2.5rem] border-2 border-transparent hover:border-orange-200 hover:bg-white transition-all">
              <div className="flex items-center gap-5">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl ${user.role === 'مدير' ? 'bg-blue-900 text-white shadow-lg shadow-blue-200' : 'bg-orange-100 text-orange-600'}`}>
                  {user.username.charAt(0).toUpperCase()}
                </div>
                <div>
                  <p className="font-black text-xl text-slate-800">{user.username}</p>
                  <div className="flex items-center gap-3 mt-1">
                    <span className={`text-[10px] font-black px-3 py-1 rounded-full ${user.role === 'مدير' ? 'bg-blue-50 text-blue-900' : 'bg-orange-50 text-orange-700'}`}>
                      {user.role}
                    </span>
                    {user.restrictedCategory && (
                      <span className="text-[10px] bg-slate-200 text-slate-600 px-3 py-1 rounded-full font-black border border-slate-300 uppercase">
                        فئة: {user.restrictedCategory}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={() => { setEditingUserId(user.id); setUserFormData(user); setIsUserModalOpen(true); }} className="p-3 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-2xl transition-all">
                  <Edit2 size={20} />
                </button>
                {user.username !== 'IZZAT' && (
                  <button onClick={() => { if(confirm('حذف الحساب؟')) { setState(p => ({...p, users: p.users.filter(u => u.id !== user.id)})); addLog?.('حذف حساب', `تم حذف حساب المستخدم: ${user.username}`, 'warning'); } }} className="p-3 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all">
                    <Trash2 size={20} />
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Backup & System Controls */}
      <div className="bg-[#001F3F] p-12 rounded-[4rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-orange-500 to-blue-500"></div>
        <h3 className="text-2xl font-black text-white mb-8 flex items-center gap-4">
          <div className="p-3 bg-white/10 text-orange-400 rounded-2xl"><CloudUpload size={24} /></div>
          الحفظ السحابي والنسخ الاحتياطي
        </h3>
        <div className="bg-white/5 backdrop-blur-md p-8 rounded-[2.5rem] border border-white/10 flex gap-6 mb-10">
          <Info className="text-orange-400 shrink-0" size={28} />
          <p className="text-sm text-blue-100 font-bold leading-relaxed">
            يُرجى تصدير قاعدة البيانات دورياً. جميع العمليات تتم محلياً ومزامنتها سحابياً لضمان عدم ضياع أي ملف أو سجل خاص بالنادي. 
            <br/>
            <span className="text-orange-400 font-black mt-2 block">كلمة السر الافتراضية للمدير: KSC@2026</span>
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-5">
          <button onClick={exportToDrive} className="flex-1 bg-white text-blue-900 font-black py-6 rounded-[2rem] hover:bg-orange-500 hover:text-white transition-all shadow-xl flex items-center justify-center gap-4 text-xl">
            <CloudUpload size={28} /> تصدير ملف JSON الشامل
          </button>
          <button onClick={() => { if(confirm('تصفير النظام؟')) { localStorage.clear(); window.location.reload(); } }} className="sm:w-1/4 bg-red-500/20 text-red-400 font-black py-6 rounded-[2rem] hover:bg-red-600 hover:text-white transition-all flex items-center justify-center gap-3">
            <ShieldAlert size={24} /> تصفير شامل
          </button>
        </div>
      </div>

      {/* User Modal */}
      {isUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-xl flex items-center justify-center z-[200] p-6 no-print">
          <div className="bg-white rounded-[4rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border-4 border-white">
            <div className="p-10 border-b bg-slate-50 flex justify-between items-center rounded-t-[3.5rem]">
              <h3 className="text-2xl font-black text-slate-800">{editingUserId ? 'تحديث حساب مستخدم' : 'فتح حساب جديد بنظام النادي'}</h3>
              <button onClick={() => setIsUserModalOpen(false)} className="bg-slate-200 p-3 rounded-2xl text-slate-600 hover:rotate-90 transition-transform">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSaveUser} className="p-10 space-y-8">
              <div className="space-y-2">
                <label className="text-[11px] font-black text-slate-500 mr-2 uppercase">الاسم التعريفي للمستخدم</label>
                <input required type="text" disabled={userFormData.username === 'IZZAT'} value={userFormData.username || ''} onChange={e => setUserFormData({ ...userFormData, username: e.target.value })}
                  className="w-full bg-slate-100 border-none rounded-2xl py-5 px-8 focus:ring-4 focus:ring-blue-900/10 font-black text-xl text-black placeholder:text-slate-300 disabled:opacity-50" placeholder="مثال: coach_ali" />
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-slate-500 mr-2 uppercase">نوع الصلاحية</label>
                  <select className="w-full bg-slate-100 border-none rounded-2xl p-5 font-black text-lg outline-none focus:ring-2 focus:ring-blue-900"
                    value={userFormData.role} onChange={e => setUserFormData({ ...userFormData, role: e.target.value as UserRole, restrictedCategory: e.target.value === 'مدير' ? undefined : userFormData.restrictedCategory })}>
                    {roles.map(r => <option key={r} value={r}>{r}</option>)}
