                      value={userFormData.restrictedCategory || ''} onChange={e => setUserFormData({ ...userFormData, restrictedCategory: e.target.value as Category || undefined })}>
                      <option value="">جميع الفئات</option>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                )}
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsUserModalOpen(false)} className="flex-1 bg-slate-100 text-slate-600 font-black py-5 rounded-[2rem] hover:bg-slate-200 transition-colors">إلغاء</button>
                <button type="submit" className="flex-[2] bg-blue-900 text-white font-black py-5 rounded-[2rem] shadow-2xl hover:bg-black transition-colors">تثبيت الحساب</button>
              </div>
            </form>
          </div>
        </div>
