import React, { useState } from 'react';
import { ClipboardCheck, Save, Clock, AlertTriangle, ShieldCheck, ShieldAlert, History, Search } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus; excuse?: string; fine?: string }>>({});

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;

  // إظهار التمارين المناسبة للفئة المختارة عالمياً
  const sessions = state.sessions
    .filter(s => (globalFilter === 'الكل' || s.category === globalFilter))
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const players = state.people.filter(p => p.role === 'لاعب' && (activeSession ? p.category === activeSession.category : true));

  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  // منطق قفل الحضور (30 دقيقة من بدء التمرين)
  const getSessionLockStatus = () => {
    if (!activeSession) return { locked: false, message: '' };

    // التمرين قادم
    const sessionDateTime = new Date(`${activeSession.date}T${activeSession.time}`);
    const now = new Date();

    // إذا كان التاريخ مستقبلي، لا يمكن تسجيل حضور
    if (sessionDateTime > now) {
      return { locked: true, message: 'لا يمكن تسجيل الحضور لتمرين لم يبدأ بعد.' };
    }

    const diffMinutes = (now.getTime() - sessionDateTime.getTime()) / (1000 * 60);

    if (diffMinutes > 30 && currentUser.role !== 'مدير') {
      return { locked: true, message: 'تم إقفال السجل زمنياً (مر أكثر من 30 دقيقة على بدء التمرين). التعديل مقيد للمدير.' };
    }

    return { locked: false, message: '' };
  };

  const lockStatus = getSessionLockStatus();

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if (lockStatus.locked) return alert(lockStatus.message);

    // الإداري لا يمكنه تعديل سجل محفوظ
    const existing = savedRecords.find(r => r.personId === pid);
    if (existing && currentUser.role !== 'مدير') {
      alert('السجل محفوظ مسبقاً، التعديل متاح للمدير العام فقط.');
      return;
    }

    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status } }));
  };

  const saveAttendance = () => {
    const entries = Object.entries(localRecords);
    if (entries.length === 0) return alert('يرجى تحديد حالة اللاعبين أولاً');

    const nowTime = new Date().toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', numberingSystem: 'latn' });
    const newRecords: AttendanceRecord[] = entries.map(([pid, data]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      sessionId: selectedSessionId,
      date: activeSession!.date,
      time: nowTime,
      status: data.status,
      excuse: data.excuse,
      fine: data.fine,
      isLocked: true
    }));

    setState(p => ({
      ...p,
      attendance: [
        ...p.attendance.filter(a => !(a.sessionId === selectedSessionId && localRecords[a.personId])),
        ...newRecords
      ],
    }));

    addLog?.('تسجيل حضور', `تم حفظ سجل حضور تمرين: ${activeSession?.objective}`, 'success');
    setLocalRecords({});
    alert('تم حفظ ومزامنة السجل بنجاح.');
  };

  return (
    <div className="space-y-8">
      <div className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row gap-8 items-end no-print">
        <div className="flex-1 space-y-3 w-full">
           <label className="text-xs font-black text-slate-400 mr-2 uppercase flex items-center gap-2">
             <Search size={16} /> اختيار التمرين من القائمة النشطة
           </label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-50 border-2 border-slate-100 rounded-[1.5rem] p-5 font-black text-xl text-slate-800 outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 transition-all">
             <option value="">-- اختر التمرين المستهدف للمزامنة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <button 
          onClick={saveAttendance} 
          disabled={!selectedSessionId || lockStatus.locked}
          className="bg-blue-900 text-white px-12 py-5 rounded-[1.5rem] font-black text-lg shadow-2xl shadow-blue-200 flex items-center gap-3 transition-all hover:bg-black disabled:opacity-50 disabled:grayscale"
        >
          <Save size={24} /> اعتماد وتثبيت السجل
        </button>
      </div>

      {activeSession && (
        <div className="bg-white rounded-[4rem] shadow-sm border border-slate-100 overflow-hidden relative border-b-8 border-blue-900">
          {lockStatus.locked && (
            <div className="bg-red-50 p-6 border-b border-red-100 text-red-600 flex flex-col items-center justify-center gap-2 font-black text-sm">
              <div className="flex items-center gap-3">
                <ShieldAlert size={24} /> 
                <span>{lockStatus.message}</span>
              </div>
            </div>
          )}

          <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
             <div>
               <h3 className="text-2xl font-black text-slate-800">{activeSession.objective}</h3>
               <p className="text-xs font-black text-blue-600 mt-1 uppercase tracking-widest">{activeSession.category} | {activeSession.date} | {activeSession.location}</p>
             </div>
             <div className="flex gap-4">
               <div className="bg-white px-6 py-2 rounded-2xl border border-slate-200 text-center">
                 <p className="text-[9px] font-black text-slate-400">إجمالي اللاعبين</p>
                 <p className="text-lg font-black text-blue-900">{players.length}</p>
               </div>
             </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[900px]">
              <thead className="bg-slate-50/50">
                <tr>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">اللاعب المعتمد</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest text-center">الحالة الانضباطية</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">العذر / ملاحظات الفني</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest text-center">وقت التسجيل</th>
                </tr>
              </thead>
              <tbody className="divide-y-2 divide-slate-50">
                {players.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];
                  const currentStatus = local?.status || saved?.status;

                  return (
                    <tr key={p.id} className="group hover:bg-slate-50/80 transition-all">
                      <td className="px-10 py-6">
                        <span className="font-black text-xl text-slate-800 block group-hover:text-blue-900 transition-colors">{p.name}</span>
                        <div className="flex items-center gap-2 mt-1">
                          <span className="text-[10px] font-black text-orange-500 bg-orange-50 px-2 py-0.5 rounded">#{p.number}</span>
                          <span className="text-[10px] font-bold text-slate-400">لاعب {p.category}</span>
                        </div>
                      </td>
                      <td className="px-10 py-6">
                        <div className="flex justify-center gap-2">
                          {[
                            { id: 'حاضر', color: 'bg-emerald-600', text: 'white' },
                            { id: 'متأخر', color: 'bg-orange-500', text: 'white' },
                            { id: 'غائب', color: 'bg-red-600', text: 'white' },
                            { id: 'غياب بعذر', color: 'bg-blue-600', text: 'white' }
                          ].map(st => (
                            <button 
                              key={st.id} 
                              onClick={() => handleSetStatus(p.id, st.id as AttendanceStatus)}
                              className={`px-5 py-3 rounded-2xl text-[10px] font-black border-2 transition-all transform active:scale-95 ${currentStatus === st.id ? 
                                `${st.color} text-${st.text} border-transparent shadow-xl scale-105` 
                                : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
                            >
                              {st.id}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-10 py-6">
                        <input 
                          type="text" 
                          placeholder="اكتب العذر أو الغرامة المالية هنا..." 
                          disabled={lockStatus.locked && !saved}
                          value={local?.excuse || saved?.excuse || ''}
                          onChange={e => setLocalRecords(prev => ({ ...prev, [p.id]: { ...prev[p.id], excuse: e.target.value } }))}
                          className="bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-xs font-black w-full outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 transition-all placeholder:text-slate-300" 
                        />
                      </td>
                      <td className="px-10 py-6 text-center">
                        {currentStatus ? (
                          <div className="inline-flex items-center gap-2 bg-blue-900 text-white px-4 py-2 rounded-xl text-[10px] font-black shadow-lg">
                            <History size={14} className="text-orange-400" /> {local?.status ? 'قيد الحفظ' : saved?.time}
                          </div>
                        ) : (
                          <span className="text-slate-300 font-bold text-[10px]">بانتظار الرصد</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
      {!activeSession && (
        <div className="py-40 text-center bg-white rounded-[4rem] border-4 border-dashed border-slate-100">
           <ClipboardCheck size={80} className="mx-auto text-slate-100 mb-6" />
           <h3 className="text-2xl font-black text-slate-300">يرجى اختيار تمرين من القائمة أعلاه لبدء رصد الحضور</h3>
        </div>
      )}
    </div>
  );
};

