    const selectedNames = new Set([
      ...currentMatch.lineup.starters.map(s => s.name),
      ...currentMatch.lineup.subs.map(s => s.name)
    ]);
    if (currentSelectedName) selectedNames.delete(currentSelectedName);

    return state.people.filter(p => 
      p.category === currentMatch.category && 
      p.role === 'لاعب' && 
      !selectedNames.has(p.name)
    );
  };

  const filteredMatches = state.matches.filter(m => 
    (globalFilter === 'الكل' || m.category === globalFilter)
  );

  return (
    <div className="space-y-10">
      <div className="flex justify-between items-center no-print bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100">
        <div>
          <h3 className="text-2xl font-black text-slate-800">برنامج المباريات والبطولات</h3>
          <p className="text-xs font-black text-blue-600 mt-1 uppercase tracking-widest">Al-Karamah Pro Match Hub</p>
        </div>
        <button onClick={() => setIsAddOpen(true)} className="bg-orange-500 text-white px-10 py-4 rounded-[1.5rem] font-black flex items-center gap-3 shadow-2xl shadow-orange-200 transition-all hover:bg-black group">
          <Plus size={24} className="group-hover:rotate-90 transition-transform" /> حجز موعد مباراة رسمية
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
        {filteredMatches.map(m => (
          <div key={m.id} className="bg-white p-10 rounded-[4rem] shadow-sm border border-slate-100 relative group overflow-hidden border-b-8 border-slate-50 hover:border-blue-900 transition-all">
             <div className="flex justify-between items-center mb-10">
                <span className="text-[11px] font-black bg-blue-900 text-white px-5 py-2 rounded-2xl uppercase shadow-lg shadow-blue-100">{m.category} | {m.matchType}</span>
                <span className={`text-[11px] font-black px-4 py-1.5 rounded-xl ${m.isCompleted ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600 animate-pulse'}`}>
                  {m.isCompleted ? 'مباراة منتهية' : 'بانتظار الصافرة'}
                </span>
             </div>

             <div className="flex items-center justify-between text-center gap-4 py-6">
                <div className="flex-1">
                  <div className="w-16 h-16 bg-blue-900 text-white rounded-3xl mx-auto flex items-center justify-center font-black text-2xl mb-3 shadow-xl">K</div>
                  <p className="font-black text-xl text-slate-800">الكرامة</p>
                </div>

                <div className="flex flex-col items-center">
                  <div className="bg-slate-50 px-10 py-6 rounded-[2.5rem] flex items-center justify-center font-black text-5xl border-2 border-slate-100 text-slate-800 shadow-inner group-hover:bg-blue-900 group-hover:text-white group-hover:border-blue-900 transition-all">
                    {m.isCompleted ? `${m.ourScore} : ${m.opponentScore}` : 'VS'}
