                </div>

                <div className="flex-1">
                  <div className="w-16 h-16 bg-slate-100 text-slate-400 rounded-3xl mx-auto flex items-center justify-center font-black text-2xl mb-3 border-2 border-dashed border-slate-200">?</div>
