               <h3 className="text-2xl font-black text-slate-800">جدولة لقاء جديد</h3>
               <button onClick={() => setIsAddOpen(false)} className="p-4 bg-slate-200 rounded-3xl hover:rotate-90 transition-transform"><X size={28}/></button>
