                 <div className="space-y-2"><label className="text-[11px] font-black text-slate-500 mr-2 uppercase">الفئة</label>
                   <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} 
                    className="w-full bg-slate-100 border-none p-5 rounded-2xl font-black text-lg outline-none focus:ring-4 focus:ring-blue-900/10">
                     {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                   </select>
                 </div>
                 <div className="space-y-2"><label className="text-[11px] font-black text-slate-500 mr-2 uppercase">نوع المسابقة</label>
                   <select value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})} 
                    className="w-full bg-slate-100 border-none p-5 rounded-2xl font-black text-lg outline-none focus:ring-4 focus:ring-blue-900/10">
                     <option value="دوري">دوري</option><option value="كأس">كأس</option><option value="ودية">ودية</option>
                   </select>
                 </div>
               </div>
               <div className="space-y-2"><label className="text-[11px] font-black text-slate-500 mr-2 uppercase">اسم الفريق الخصم</label>
                 <input required type="text" value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} 
                  className="w-full bg-slate-100 border-none p-5 rounded-2xl font-black text-xl text-slate-800" placeholder="مثال: نادي الفتوة" />
               </div>
               <div className="grid grid-cols-2 gap-6">
                 <div className="space-y-2"><label className="text-[11px] font-black text-slate-500 mr-2 uppercase">التاريخ المقترح</label>
                   <input required type="date" value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full bg-slate-100 border-none p-5 rounded-2xl font-black text-lg" />
                 </div>
                 <div className="space-y-2"><label className="text-[11px] font-black text-slate-500 mr-2 uppercase">وقت انطلاق المباراة</label>
                   <input required type="time" value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} className="w-full bg-slate-100 border-none p-5 rounded-2xl font-black text-lg" />
                 </div>
               </div>
               <div className="grid grid-cols-2 gap-6">
                 <div className="space-y-2"><label className="text-[11px] font-black text-slate-500 mr-2 uppercase">الملعب المستضيف</label>
                   <input required type="text" value={formData.location || ''} onChange={e => setFormData({...formData, location: e.target.value})} className="w-full bg-slate-100 border-none p-5 rounded-2xl font-black text-lg" placeholder="مثال: ملعب خالد بن الوليد" />
                 </div>
                 <div className="space-y-2"><label className="text-[11px] font-black text-slate-500 mr-2 uppercase">سلفة المباراة</label>
                   <input type="text" value={formData.advancePayment || ''} onChange={e => setFormData({...formData, advancePayment: e.target.value})} className="w-full bg-slate-100 border-none p-5 rounded-2xl font-black text-lg" placeholder="مثلاً: 50,000 ل.س" />
                 </div>
               </div>
               <div className="flex gap-6 mt-8">
                 <button type="button" onClick={() => setIsAddOpen(false)} className="flex-1 bg-slate-100 text-slate-600 font-black py-5 rounded-[2rem] text-xl">إلغاء</button>
                 <button type="submit" className="flex-[2] bg-blue-900 text-white font-black py-5 rounded-[2rem] shadow-2xl text-xl">تثبيت المباراة</button>
               </div>
             </form>
          </div>
        </div>
      )}

      {/* Match Details & Lineup Modal */}
      {activeMatch && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-3xl flex items-center justify-center z-[300] p-6 overflow-y-auto no-print">
           <div className="bg-white rounded-[5rem] w-full max-w-7xl shadow-2xl my-auto animate-in fade-in duration-500 border-4 border-white flex flex-col h-[95vh]">
              <div className="p-12 border-b bg-slate-50 flex justify-between items-center rounded-t-[5rem] shrink-0">
                 <div className="flex items-center gap-6">
                    <div className="p-5 bg-blue-900 text-white rounded-[2rem] shadow-xl"><Trophy size={36} /></div>
                    <div>
                      <h3 className="text-4xl font-black text-slate-800">مركز إدارة المباراة: {activeMatch.opponent}</h3>
                      <p className="text-sm font-black text-blue-600 mt-2 uppercase tracking-widest">Al-Karamah SC Tactical HUB</p>
                    </div>
                 </div>
                 <button onClick={() => setActiveMatch(null)} className="p-5 bg-slate-200 rounded-[2.5rem] hover:text-red-600 transition-all hover:rotate-90"><X size={36}/></button>
              </div>

              <div className="p-12 overflow-y-auto custom-scrollbar space-y-16">
                 {/* Match Header Info */}
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                    <div className="bg-blue-50 p-6 rounded-[2.5rem] border border-blue-100 text-center">
                       <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">نوع اللقاء</p>
                       <p className="text-xl font-black text-blue-900">{activeMatch.matchType}</p>
                    </div>
                    <div className="bg-orange-50 p-6 rounded-[2.5rem] border border-orange-100 text-center">
                       <p className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-1">الفئة العمرية</p>
                       <p className="text-xl font-black text-orange-600">{activeMatch.category}</p>
                    </div>
                    <div className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 text-center col-span-2">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">المكان والزمان</p>
                       <p className="text-xl font-black text-slate-800">{activeMatch.location} | {activeMatch.date} - {activeMatch.time}</p>
                    </div>
                 </div>

