                          <Shield size={28} className="text-blue-900" /> التشكيلة الأساسية (11 لاعب)
                       </h4>
                       <div className="space-y-4">
                         {activeMatch.lineup.starters.map((s, i) => (
                           <div key={i} className="flex gap-4 items-center group">
                             <span className="w-12 h-14 bg-slate-100 rounded-2xl flex items-center justify-center text-lg font-black text-slate-400 group-hover:bg-blue-900 group-hover:text-white transition-all">{i+1}</span>
                             <div className="flex-1 relative">
                                <select 
                                  value={s.name} 
                                  onChange={e => {
                                    const p = state.people.find(x => x.name === e.target.value);
                                    const newList = [...activeMatch.lineup.starters];
                                    newList[i] = { name: p?.name || '', number: p?.number?.toString() || '' };
