                                  }}
                                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl py-4 px-6 text-lg font-black outline-none focus:ring-4 focus:ring-blue-900/10 focus:border-blue-900 transition-all appearance-none"
