                              </div>
                              <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: activeMatch.lineup.subs.filter((_, idx) => idx !== i)}})} className="p-4 bg-red-50 text-red-300 hover:bg-red-600 hover:text-white rounded-2xl transition-all shadow-sm">
                                <Trash2 size={24}/>
                              </button>
                            </div>
                          ))}
                          <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: [...activeMatch.lineup.subs, {name:'', number:''}]}})} 
                            className="w-full py-6 border-4 border-dashed border-slate-100 rounded-[2.5rem] text-xl font-black text-slate-300 hover:text-orange-500 hover:border-orange-200 transition-all flex items-center justify-center gap-4">
                            <Plus size={32}/> إضافة لاعب بديل جديد
                          </button>
                       </div>

                       <div className="pt-10 space-y-10">
                         <h4 className="text-2xl font-black text-slate-800 flex items-center gap-4 border-r-8 border-slate-800 pr-6">
                            <ListFilter size={28} className="text-slate-800" /> سجل أحداث المباراة والنتيجة
                         </h4>
                         <div className="grid grid-cols-2 gap-8">
                            <div className="space-y-4">
                               <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest mr-4">أهداف الكرامة</label>
                               <input type="number" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} 
                                className="w-full bg-blue-900 text-white border-none rounded-[2rem] p-8 text-6xl font-black text-center shadow-2xl focus:ring-8 focus:ring-blue-100 transition-all" />
                            </div>
                            <div className="space-y-4">
                               <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest mr-4">أهداف {activeMatch.opponent}</label>
                               <input type="number" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} 
                                className="w-full bg-slate-100 border-none rounded-[2rem] p-8 text-6xl font-black text-center shadow-inner focus:ring-8 focus:ring-slate-200 transition-all" />
                            </div>
                         </div>
                         <div className="bg-orange-50 p-8 rounded-[3rem] border-2 border-dashed border-orange-200">
                           <div className="flex items-center gap-3 mb-4">
                              <AlertTriangle className="text-orange-500" size={24} />
                              <span className="text-sm font-black text-orange-800">ملاحظات فنية، إصابات، أو تفاصيل هامة</span>
                           </div>
                           <textarea value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})}
                            placeholder="اكتب هنا ملخص أحداث المباراة أو أسماء المسجلين..."
                            className="w-full bg-transparent border-none font-bold text-slate-700 outline-none resize-none h-40 text-lg leading-relaxed placeholder:text-orange-200" />
                         </div>
                       </div>
                    </div>
                 </div>

                 {/* Actions */}
                 <div className="flex flex-col md:flex-row gap-8 pt-16 border-t border-slate-100">
                    <button onClick={() => setActiveMatch(null)} className="flex-1 bg-slate-100 text-slate-600 font-black py-8 rounded-[3rem] text-2xl hover:bg-slate-200 transition-all">إغلاق بدون حفظ</button>
                    <button onClick={() => {
                      const finalMatch = {...activeMatch, isCompleted: parseInt(activeMatch.ourScore) + parseInt(activeMatch.opponentScore) > 0 || confirm('هل تريد وسم المباراة كمنتهية؟')};
                      setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? finalMatch : m) }));
                      addLog?.('تحديث مباراة', `تم تحديث تقرير مباراة ${activeMatch.opponent}`, 'success');
                      setActiveMatch(null);
                    }} className="flex-[2] bg-blue-900 text-white font-black py-8 rounded-[3rem] shadow-2xl hover:bg-black transition-all text-2xl">تثبيت التقرير والنتيجة النهائية</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface Person {
  id: string;
  name: string; // الاسم الثنائي
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number; // رقم القميص
  phone?: string;
  joinDate: string;

  // Contracts
  contractStart?: string;
  contractEnd?: string;
  contractDuration?: string;
  contractValue?: string;

  // Medical & Discipline
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;

  // Academic (for staff)
  coachingCertificate?: string;
  academicDegree?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
  isCompleted?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury';
  player: string;
  minute: string;
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  location: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  events: MatchEvent[];
  lineup: {
    starters: { name: string; number: string }[];
    subs: { name: string; number: string }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  lastSyncTimestamp?: number;
  globalCategoryFilter: Category | 'الكل';
}

import React, { useState, useEffect } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, X, Trophy, Bell, Filter
} from 'lucide-react';
import { AppUser, AppState, Category, Person, TrainingSession, Match, AppNotification } from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_pro_final_v1');
    const defaultCategories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
    const defaultUsers: AppUser[] = [
      { id: 'admin-main', username: 'IZZAT', role: 'مدير', password: 'KSC@2026' },
    ];

    if (saved) return JSON.parse(saved);

    return {
      people: [], attendance: [], sessions: [], matches: [],
      categories: defaultCategories, users: defaultUsers,
      currentUser: null, notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  useEffect(() => {
    if (state.currentUser) {
      localStorage.setItem('alkaramah_pro_final_v1', JSON.stringify(state));
    }
  }, [state]);

  const addLog = (message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newLog: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message,
      details,
      type,
      timestamp: Date.now(),
      isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newLog, ...prev.notifications].slice(0, 50)
    }));
  };

  const navigateToMatch = (id: string) => {
    setSelectedMatchId(id);
    setActiveTab('matches');
  };

  const navigateToSession = (id: string) => {
    setSelectedSessionId(id);
    setActiveTab('attendance');
  };

  if (!state.currentUser) {
    return <Login onLogin={(u) => setState(p => ({ ...p, currentUser: u }))} state={state} />;
  }

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الكوادر', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التمارين', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings, adminOnly: true },
  ];

  return (
    <div className="flex h-screen bg-[#F0F4F8] font-['Tajawal'] text-right overflow-hidden" dir="rtl">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-[#001F3F] text-white transition-transform md:relative md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} flex flex-col no-print`}>
        <div className="p-8 flex flex-col items-center border-b border-white/10">
          <ClubLogo size={80} />
          <h1 className="mt-4 font-black text-xl">نادي الكرامة</h1>
          <p className="text-[10px] text-orange-400 font-black tracking-widest uppercase">Football Office</p>
        </div>

        <nav className="flex-1 px-4 py-6 space-y-2 overflow-y-auto custom-scrollbar">
          <div className="px-4 mb-6">
            <label className="text-[10px] font-black text-blue-300 block mb-2 mr-2">تصفية الفئة الشاملة</label>
            <div className="relative">
              <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-white/40" size={14} />
              <select 
                value={state.globalCategoryFilter}
                onChange={e => setState(p => ({ ...p, globalCategoryFilter: e.target.value }))}
                className="w-full bg-white/10 border border-white/20 rounded-xl py-2 pr-10 pl-4 text-xs font-black outline-none focus:ring-1 focus:ring-orange-500"
              >
                <option value="الكل" className="text-black">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c} className="text-black">{c}</option>)}
              </select>
            </div>
          </div>

          {menuItems.map(item => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all font-black text-sm ${activeTab === item.id ? 'bg-orange-600 shadow-lg shadow-orange-900/40' : 'hover:bg-white/5 text-blue-100'}`}>
                <Icon size={20} /> <span>{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-6 border-t border-white/10">
          <button onClick={() => setState(p => ({ ...p, currentUser: null }))} className="w-full flex items-center gap-4 p-4 rounded-2xl text-red-400 hover:bg-red-900/20 font-black text-sm transition-colors">
            <LogOut size={20} /> خروج من النظام
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="bg-white border-b px-8 py-4 flex items-center justify-between no-print z-40 shadow-sm">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="md:hidden p-2 hover:bg-slate-100 rounded-xl transition-colors"><Menu /></button>
            <h2 className="text-xl font-black text-slate-800">{menuItems.find(m => m.id === activeTab)?.label}</h2>
          </div>

          <div className="flex items-center gap-4">
             {state.currentUser.role === 'مدير' && (
               <button 
                onClick={() => setShowNotifications(!showNotifications)}
                className="relative p-2.5 bg-[#F0F4F8] text-[#001F3F] rounded-xl hover:bg-orange-50 hover:text-orange-600 transition-all border border-slate-200"
               >
                 <Bell size={22} />
                 {state.notifications.filter(n => !n.isRead).length > 0 && (
                   <span className="absolute top-2 right-2 w-3 h-3 bg-orange-600 border-2 border-white rounded-full"></span>
                 )}
               </button>
             )}

             <div className="flex items-center gap-3 pr-4 border-r border-slate-100">
               <div className="text-left hidden sm:block">
                 <p className="font-black text-xs text-slate-800">{state.currentUser.username}</p>
                 <p className="text-[9px] text-blue-600 font-black uppercase tracking-widest">{state.currentUser.role}</p>
               </div>
               <div className="w-10 h-10 bg-[#001F3F] text-white rounded-xl flex items-center justify-center font-black shadow-lg shadow-blue-900/20">
                 {state.currentUser.username.charAt(0).toUpperCase()}
               </div>
             </div>
          </div>
        </header>

        {/* Notifications Dropdown (Activity Log) */}
        {showNotifications && state.currentUser.role === 'مدير' && (
          <div className="absolute left-8 top-16 w-96 bg-white rounded-[2rem] shadow-2xl border border-slate-100 z-[60] overflow-hidden animate-in fade-in slide-in-from-top-4 duration-300">
            <div className="p-6 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-[#001F3F] text-sm">سجل نشاطات النظام التفاعلي</h3>
              <button onClick={() => setState(p => ({...p, notifications: []}))} className="text-[10px] font-black text-red-500 hover:underline">تفريغ السجل</button>
            </div>
            <div className="max-h-[32rem] overflow-y-auto custom-scrollbar">
              {state.notifications.length > 0 ? state.notifications.map(n => (
                <div key={n.id} className="p-4 border-b border-slate-50 hover:bg-slate-50 transition-colors flex gap-4">
                  <div className={`w-2 h-2 rounded-full shrink-0 mt-1.5 ${n.type === 'success' ? 'bg-emerald-500' : n.type === 'warning' ? 'bg-orange-500' : 'bg-blue-500'}`}></div>
                  <div>
                    <p className="text-xs font-black text-slate-800">{n.message}</p>
                    {n.details && <p className="text-[10px] text-slate-500 font-bold mt-1">{n.details}</p>}
                    <p className="text-[9px] text-slate-400 font-bold mt-1.5">{new Date(n.timestamp).toLocaleString('ar-EG')}</p>
                  </div>
                </div>
              )) : (
                <div className="p-10 text-center text-slate-400 italic text-sm font-bold">لا توجد نشاطات مسجلة حالياً</div>
              )}
            </div>
          </div>
        )}

        <section className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar bg-slate-50/50">
          <div className="max-w-7xl mx-auto pb-24">
            {activeTab === 'dashboard' && <Dashboard state={state} onMatchClick={navigateToMatch} onSessionClick={navigateToSession} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={setState} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={setState} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <footer className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t py-3 px-8 flex justify-between items-center no-print z-40 shadow-lg">
          <p className="text-[10px] font-black text-slate-500">نظام إدارة مكتب كرة القدم - نادي الكرامة الرياضي</p>
          <p className="text-[10px] font-black text-[#001F3F] border-r-4 border-orange-500 pr-3">By: Izzat Amer Al-Shikha</p>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Lock, User, Eye, EyeOff, ChevronLeft } from 'lucide-react';
import { AppUser, AppState } from '../types';
import ClubLogo from './ClubLogo';

interface LoginProps {
  onLogin: (user: AppUser) => void;
  state: AppState;
}

const Login: React.FC<LoginProps> = ({ onLogin, state }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = state.users.find(u => u.username.toUpperCase() === username.trim().toUpperCase());
    if (user && user.password === password) {
      onLogin(user);
    } else {
      setError('خطأ في بيانات الدخول. يرجى التثبت والمحاولة مجدداً.');
    }
  };

  return (
    <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 font-['Tajawal'] relative overflow-hidden" dir="rtl">
      {/* Decorative Elements */}
      <div className="absolute top-[-15%] right-[-10%] w-[50%] h-[50%] bg-orange-600/10 rounded-full blur-[120px]"></div>
      <div className="absolute bottom-[-15%] left-[-10%] w-[40%] h-[40%] bg-blue-600/10 rounded-full blur-[100px]"></div>

      <div className="max-w-md w-full bg-white rounded-[4rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] overflow-hidden border border-white/20 animate-in fade-in zoom-in-95 duration-700 relative z-10">
        <div className="bg-gradient-to-br from-[#001F3F] to-[#000F21] p-12 flex flex-col items-center text-center">
          <div className="bg-white p-6 rounded-[3rem] shadow-2xl mb-8 ring-8 ring-orange-500/10">
            <ClubLogo size={120} />
          </div>
          <h2 className="text-white font-black text-2xl tracking-tight leading-snug">AL-Karama Sport Club</h2>
          <h2 className="text-white font-black text-3xl tracking-tight leading-snug mt-1">نادي الكرامة الرياضي</h2>
          <p className="text-orange-400 font-black mt-4 text-sm uppercase tracking-widest bg-orange-500/10 px-6 py-2 rounded-full border border-orange-500/20">أهلاً بك في أفضل أندية سوريا</p>
        </div>

        <div className="p-12 space-y-8">
          <form onSubmit={handleLogin} className="space-y-8">
            {error && <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-[10px] font-black text-center border border-red-100 animate-shake">{error}</div>}

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-500 mr-2 uppercase flex items-center gap-2">
                <User size={14} className="text-[#001F3F]" /> اسم المستخدم
              </label>
              <input 
                type="text" 
                value={username} 
                onChange={e => setUsername(e.target.value)}
                placeholder=""
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-5 px-8 outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 font-black text-slate-800 transition-all text-xl" 
              />
            </div>

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-500 mr-2 uppercase flex items-center gap-2">
                <Lock size={14} className="text-[#001F3F]" /> كلمة المرور السرية
              </label>
              <div className="relative">
                <input 
                  type={showPass ? "text" : "password"} 
                  value={password} 
                  onChange={e => setPassword(e.target.value)}
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-5 pr-8 pl-16 outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 font-black text-slate-800 transition-all text-xl" 
                />
                <button 
                  type="button" 
                  onClick={() => setShowPass(!showPass)} 
                  className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-blue-600 transition-colors p-3"
                >
                  {showPass ? <EyeOff size={24} /> : <Eye size={24} />}
                </button>
              </div>
            </div>

            <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-6 rounded-[2.5rem] hover:bg-black transition-all shadow-2xl shadow-blue-900/40 mt-4 text-2xl flex items-center justify-center gap-4 group">
              الدخول لغرفة العمليات 
              <ChevronLeft className="group-hover:-translate-x-2 transition-transform" size={28} />
            </button>
          </form>

          <div className="pt-8 border-t border-slate-100 text-center space-y-2">
            <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em]">Football Management Pro System</p>
            <p className="text-[10px] text-slate-400 font-bold">نظام إدارة نادي الكرامة | By: Izzat Amer Al-Shikha</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React from 'react';
import { Users, Calendar, Trophy, Clock, MapPin, AlertCircle, ChevronLeft } from 'lucide-react';
import { AppState } from '../types';

interface DashboardProps {
  state: AppState;
  onMatchClick: (id: string) => void;
  onSessionClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, onMatchClick, onSessionClick }) => {
  const today = new Date().toISOString().split('T')[0];
  const globalFilter = state.globalCategoryFilter;

  const upcomingMatches = state.matches
    .filter(m => (globalFilter === 'الكل' || m.category === globalFilter) && m.date >= today && !m.isCompleted)
    .sort((a, b) => a.date.localeCompare(b.date));

  const upcomingSessions = state.sessions
    .filter(s => (globalFilter === 'الكل' || s.category === globalFilter) && s.date >= today)
    .sort((a, b) => a.date.localeCompare(b.date));

  const expiringContracts = state.people.filter(p => {
    if (!p.contractEnd) return false;
    const diff = (new Date(p.contractEnd).getTime() - new Date().getTime()) / (1000 * 3600 * 24);
    return diff < 90 && diff > 0;
  });

  const stats = [
    { label: 'الكوادر المسجلة', value: state.people.filter(p => globalFilter === 'الكل' || p.category === globalFilter).length, icon: Users, color: 'blue' },
    { label: 'المواجهات القادمة', value: upcomingMatches.length, icon: Trophy, color: 'emerald' },
    { label: 'التمارين المجدولة', value: upcomingSessions.length, icon: Calendar, color: 'orange' },
  ];

  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {stats.map((s, i) => (
          <div key={i} className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-slate-100 flex flex-col items-center hover:shadow-xl transition-all cursor-default group">
             <div className={`p-6 rounded-[2rem] mb-6 transition-transform group-hover:scale-110 ${s.color === 'blue' ? 'bg-blue-50 text-blue-900' : s.color === 'emerald' ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600'}`}>
               <s.icon size={40} />
             </div>
             <h3 className="text-slate-400 text-xs font-black uppercase tracking-widest">{s.label}</h3>
             <p className="text-5xl font-black text-slate-800 mt-2">{s.value}</p>
          </div>
        ))}
      </div>

      {expiringContracts.length > 0 && (
        <div className="bg-white border-2 border-orange-500/20 p-10 rounded-[4rem] flex flex-col md:flex-row items-center gap-10 shadow-2xl shadow-orange-100 relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-32 h-32 bg-orange-500/5 rounded-full -mr-16 -mt-16 group-hover:scale-110 transition-transform"></div>
          <div className="w-20 h-20 bg-orange-600 text-white rounded-[2rem] flex items-center justify-center shrink-0 shadow-xl shadow-orange-200">
            <AlertCircle size={40} />
          </div>
          <div className="flex-1 text-center md:text-right">
             <h4 className="text-2xl font-black text-orange-900">تنبيه انتهاء عقود (خلال أقل من 90 يوماً)</h4>
             <p className="text-sm font-black text-orange-700 mt-2 opacity-80">يوجد حالياً {expiringContracts.length} أعضاء تنتهي عقودهم قريباً. يرجى مراجعة التفاصيل لتفادي الخسارة الفنية.</p>
             <div className="mt-6 flex flex-wrap gap-3 justify-center md:justify-start">
               {expiringContracts.map(p => (
                 <span key={p.id} className="bg-orange-600 text-white px-5 py-2 rounded-2xl text-[11px] font-black shadow-lg shadow-orange-200">{p.name}</span>
               ))}
             </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
        {/* Upcoming Matches */}
        <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-10">
            <div className="flex items-center gap-4">
              <div className="p-4 bg-[#001F3F] text-white rounded-[1.5rem] shadow-xl">
                <Trophy size={24} />
              </div>
              <h3 className="text-2xl font-black text-slate-800">الأجندة التنافسية</h3>
            </div>
            <span className="text-[11px] bg-blue-50 text-blue-900 px-5 py-2 rounded-full font-black uppercase border border-blue-100">المواجهات القادمة</span>
          </div>
          <div className="space-y-6">
            {upcomingMatches.length > 0 ? upcomingMatches.map(m => (
              <button key={m.id} onClick={() => onMatchClick(m.id)} className="w-full text-right p-8 rounded-[3rem] bg-slate-50 border-4 border-transparent hover:border-blue-900 hover:bg-white transition-all group relative flex items-center justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-3">
