import React, { useState } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus; excuse?: string; fine?: string }>>({});

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;

  // إظهار التمارين النشطة والقادمة فقط للفئة المختارة
  const sessions = state.sessions
    .filter(s => (globalFilter === 'الكل' || s.category === globalFilter))
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const players = state.people.filter(p => p.role === 'لاعب' && (activeSession ? p.category === activeSession.category : true));
  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const getSessionLockStatus = () => {
    if (!activeSession) return { locked: false, message: '' };
    const sessionDateTime = new Date(`${activeSession.date}T${activeSession.time}`);
    const now = new Date();

    if (sessionDateTime > now) {
      return { locked: true, message: 'لا يمكن البدء برصد الحضور قبل موعد انطلاق التمرين رسمياً.' };
    }

    const diffMinutes = (now.getTime() - sessionDateTime.getTime()) / (1000 * 60);
    if (diffMinutes > 30 && currentUser.role !== 'مدير') {
      return { locked: true, message: 'تم إقفال السجل تلقائياً لتجاوزه مهلة الـ 30 دقيقة المسموحة للإداري. التعديل الآن مقيد للمدير العام فقط.' };
    }

    return { locked: false, message: '' };
  };

  const lockStatus = getSessionLockStatus();

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if (lockStatus.locked) return alert(lockStatus.message);
    const existing = savedRecords.find(r => r.personId === pid);
    if (existing && currentUser.role !== 'مدير') {
      alert('تم قفل التعديل على هذا السجل بعد حفظه. يرجى مراجعة المدير للتعديل.');
      return;
    }
    setLocalRecords(prev => ({ ...prev, [pid]: { ...prev[pid], status } }));
  };

  const saveAttendance = () => {
    const entries = Object.entries(localRecords);
    if (entries.length === 0) return alert('يرجى رصد حالات اللاعبين قبل الضغط على حفظ');

    const nowTime = new Date().toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', numberingSystem: 'latn' });
    const newRecords: AttendanceRecord[] = entries.map(([pid, data]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      sessionId: selectedSessionId,
      date: activeSession!.date,
      time: nowTime,
      status: data.status,
      excuse: data.excuse,
      fine: data.fine,
      isLocked: true
    }));

    setState(p => ({
      ...p,
      attendance: [
        ...p.attendance.filter(a => !(a.sessionId === selectedSessionId && localRecords[a.personId])),
        ...newRecords
      ],
    }));

    addLog?.('رصد حضور تمرين', `تم رصد حضور فئة ${activeSession?.category} لتمرين ${activeSession?.objective}`, 'success');
    setLocalRecords({});
    alert('تم تثبيت سجل الحضور بنجاح.');
  };

  return (
    <div className="space-y-10">
      <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-slate-100 flex flex-col md:flex-row gap-10 items-end no-print relative overflow-hidden">
        <div className="absolute top-0 right-0 w-2 h-full bg-orange-500"></div>
        <div className="flex-1 space-y-4 w-full">
           <label className="text-[11px] font-black text-slate-400 mr-2 uppercase flex items-center gap-3">
             <Search size={18} className="text-[#001F3F]" /> قائمة التمارين المتاحة للرصد
           </label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-50 border-2 border-slate-200 rounded-[2rem] p-6 font-black text-2xl text-slate-800 outline-none focus:ring-8 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 transition-all appearance-none">
             <option value="">-- اختر موعد التمرين --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <button 
          onClick={saveAttendance} 
          disabled={!selectedSessionId || lockStatus.locked}
          className="bg-[#001F3F] text-white px-16 py-6 rounded-[2.5rem] font-black text-2xl shadow-2xl shadow-blue-900/20 flex items-center gap-4 transition-all hover:bg-black disabled:opacity-40 disabled:grayscale group"
        >
          <Save size={32} className="group-hover:scale-110 transition-transform" /> تثبيت السجل النهائي
        </button>
      </div>

      {activeSession && (
        <div className="bg-white rounded-[5rem] shadow-sm border border-slate-100 overflow-hidden relative border-b-8 border-[#001F3F]">
          {lockStatus.locked && (
            <div className="bg-red-50 p-8 border-b border-red-100 text-red-600 flex flex-col items-center justify-center gap-3 font-black text-lg">
              <ShieldAlert size={36} className="animate-pulse" />
              <span>{lockStatus.message}</span>
            </div>
          )}

          <div className="p-10 border-b bg-slate-50 flex justify-between items-center">
             <div className="flex items-center gap-6">
               <div className="w-20 h-20 bg-white border-4 border-blue-900 rounded-[2.5rem] flex items-center justify-center font-black text-3xl text-blue-900 shadow-xl">K</div>
               <div>
                 <h3 className="text-3xl font-black text-slate-800">{activeSession.objective}</h3>
                 <p className="text-xs font-black text-blue-600 mt-2 uppercase tracking-[0.2em]">{activeSession.category} • {activeSession.date} • {activeSession.location}</p>
               </div>
             </div>
             <div className="bg-[#001F3F] text-white px-10 py-5 rounded-[2rem] text-center shadow-xl">
               <p className="text-[10px] font-black uppercase tracking-widest text-blue-300 mb-1">لاعبين مرصودين</p>
               <p className="text-3xl font-black">{players.length}</p>
             </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[1000px]">
              <thead className="bg-slate-50/80">
                <tr>
                  <th className="px-12 py-8 text-[12px] font-black text-slate-400 uppercase tracking-widest">اللاعب</th>
                  <th className="px-12 py-8 text-[12px] font-black text-slate-400 uppercase tracking-widest text-center">الرصد الانضباطي</th>
                  <th className="px-12 py-8 text-[12px] font-black text-slate-400 uppercase tracking-widest">العذر / المخالفة</th>
                  <th className="px-12 py-8 text-[12px] font-black text-slate-400 uppercase tracking-widest text-center">التوقيت</th>
                </tr>
              </thead>
              <tbody className="divide-y-4 divide-slate-50">
                {players.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];
                  const currentStatus = local?.status || saved?.status;

                  return (
                    <tr key={p.id} className="group hover:bg-slate-50/80 transition-all">
                      <td className="px-12 py-8">
                        <div className="flex items-center gap-4">
                          <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black text-lg ${currentStatus ? 'bg-blue-900 text-white' : 'bg-slate-100 text-slate-300'}`}>
                            {p.number || '??'}
                          </div>
                          <div>
                            <span className="font-black text-2xl text-slate-800 block group-hover:text-[#001F3F] transition-colors">{p.name}</span>
                            <span className="text-[11px] font-black text-slate-400 uppercase">فئة {p.category}</span>
                          </div>
                        </div>
                      </td>
                      <td className="px-12 py-8">
                        <div className="flex justify-center gap-3">
                          {[
                            { id: 'حاضر', color: 'bg-emerald-600', hover: 'hover:bg-emerald-700' },
                            { id: 'متأخر', color: 'bg-orange-500', hover: 'hover:bg-orange-600' },
                            { id: 'غائب', color: 'bg-red-600', hover: 'hover:bg-red-700' },
                            { id: 'غياب بعذر', color: 'bg-blue-600', hover: 'hover:bg-blue-700' }
                          ].map(st => (
                            <button 
                              key={st.id} 
                              onClick={() => handleSetStatus(p.id, st.id as AttendanceStatus)}
                              className={`px-6 py-4 rounded-2xl text-[11px] font-black border-4 transition-all transform active:scale-95 ${currentStatus === st.id ? 
                                `${st.color} text-white border-transparent shadow-2xl scale-110 z-10` 
                                : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
                            >
                              {st.id}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-12 py-8">
                        <input 
                          type="text" 
                          placeholder="اكتب العذر أو نوع المخالفة..." 
                          disabled={lockStatus.locked && !saved}
                          value={local?.excuse || saved?.excuse || ''}
                          onChange={e => setLocalRecords(prev => ({ ...prev, [p.id]: { ...prev[p.id], excuse: e.target.value } }))}
                          className="bg-slate-50 border-4 border-slate-100 rounded-2xl px-8 py-4 text-sm font-black w-full outline-none focus:ring-8 focus:ring-blue-900/5 focus:bg-white focus:border-[#001F3F] transition-all placeholder:text-slate-300" 
                        />
                      </td>
                      <td className="px-12 py-8 text-center">
                        {currentStatus ? (
                          <div className={`inline-flex items-center gap-3 px-6 py-3 rounded-2xl text-[11px] font-black shadow-lg ${local?.status ? 'bg-orange-500 text-white animate-pulse' : 'bg-blue-900 text-white'}`}>
                            {local?.status ? <ShieldCheck size={18} /> : <History size={18} />}
                            {local?.status ? 'بانتظار الحفظ' : saved?.time}
                          </div>
                        ) : (
                          <span className="text-slate-200 font-black text-xs italic tracking-widest">لم يرصد بعد</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
      {!activeSession && (
        <div className="py-48 text-center bg-white rounded-[5rem] border-8 border-dashed border-slate-100 flex flex-col items-center justify-center space-y-8 group">
           <ClipboardCheck size={120} className="text-slate-100 group-hover:text-blue-900 group-hover:scale-110 transition-all duration-700" />
           <div className="space-y-2">
             <h3 className="text-3xl font-black text-slate-300">نظام رصد الحضور الذكي</h3>
             <p className="text-sm font-black text-slate-200 uppercase tracking-[0.3em]">برجاء اختيار تمرين نشط لبدء المعالجة</p>
           </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

import React, { useState } from 'react';
import { ShieldCheck, CloudUpload, Trash2, Key, Info, UserPlus, X, Edit2, ShieldAlert, Layers, Plus, Database } from 'lucide-react';
import { AppState, AppUser, UserRole, Category } from '../types';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState, addLog }) => {
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newCatName, setNewCatName] = useState('');

  const [userFormData, setUserFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'إداري فئة'
  });

  const roles: UserRole[] = ['مدير', 'إداري فئة', 'مشاهد'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.username) return;

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...userFormData } as AppUser : u)
      }));
      addLog?.('تعديل صلاحية مستخدم', `تم تحديث بيانات المستخدم: ${userFormData.username}`);
    } else {
      const newUser: AppUser = {
        id: Math.random().toString(36).substr(2, 9),
        username: userFormData.username!,
        role: userFormData.role as UserRole,
        password: 'KSC' + (Math.floor(Math.random() * 9000) + 1000),
        restrictedCategory: userFormData.role === 'مدير' ? undefined : userFormData.restrictedCategory
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
      addLog?.('إنشاء حساب مستخدم', `تم إنشاء مستخدم جديد بنجاح: ${newUser.username}`, 'success');
    }

    setIsUserModalOpen(false);
    setEditingUserId(null);
    setUserFormData({ username: '', role: 'إداري فئة' });
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('هذه الفئة موجودة مسبقاً في النظام.');

    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة رياضية', `تم إدراج فئة جديدة بالنظام: ${newCatName.trim()}`, 'success');
    setNewCatName('');
  };

  const removeCategory = (cat: string) => {
    if (confirm(`هل أنت متأكد من حذف فئة ${cat}؟ سيتم فصل كافة اللاعبين المرتبطين بها.`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
      addLog?.('حذف فئة رياضية', `تم مسح الفئة: ${cat}`, 'warning');
    }
  };

  const exportData = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    addLog?.('تصدير قاعدة البيانات', 'تم إنشاء وتنزيل نسخة احتياطية شاملة للنظام.');
  };

  return (
    <div className="max-w-6xl mx-auto space-y-12 pb-24">
      {/* Category Control */}
      <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-slate-100">
        <h3 className="text-3xl font-black text-slate-800 mb-10 flex items-center gap-6">
          <div className="p-4 bg-blue-50 text-blue-900 rounded-[1.5rem] shadow-lg shadow-blue-100"><Layers size={28} /></div>
          إدارة الفئات الرياضية بنظام النادي
        </h3>
        <div className="flex flex-col md:flex-row gap-6 mb-12">
          <input 
            type="text" 
            value={newCatName} 
            onChange={e => setNewCatName(e.target.value)}
            placeholder="ادخل اسم الفئة الجديدة هنا..."
            className="flex-1 bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl outline-none focus:ring-8 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 transition-all placeholder:text-slate-300"
          />
          <button 
            onClick={handleAddCategory}
            className="bg-[#001F3F] text-white px-12 py-6 rounded-[2rem] font-black text-xl hover:bg-black transition-all flex items-center justify-center gap-4 shadow-2xl shadow-blue-900/20 group"
          >
            <Plus size={32} className="group-hover:rotate-90 transition-transform" /> إضافة الفئة الرياضية
          </button>
        </div>
        <div className="flex flex-wrap gap-4">
          {state.categories.map(c => (
            <div key={c} className="group flex items-center gap-6 bg-slate-50 px-8 py-4 rounded-3xl border-4 border-transparent hover:border-blue-900 hover:bg-white transition-all shadow-sm">
              <span className="font-black text-xl text-slate-800">{c}</span>
              <button onClick={() => removeCategory(c)} className="text-red-300 hover:text-red-600 transition-colors transform hover:scale-125">
                <Trash2 size={22} />
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* User Management */}
      <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-12">
          <h3 className="text-3xl font-black text-slate-800 flex items-center gap-6">
            <div className="p-4 bg-orange-50 text-orange-600 rounded-[1.5rem] shadow-lg shadow-orange-100"><ShieldCheck size={28} /></div>
            إدارة صلاحيات المستخدمين والكوادر
          </h3>
          <button 
            onClick={() => { setEditingUserId(null); setUserFormData({ username: '', role: 'إداري فئة' }); setIsUserModalOpen(true); }}
            className="bg-orange-600 text-white px-10 py-5 rounded-[2rem] font-black text-lg flex items-center gap-4 hover:bg-black transition-all shadow-2xl shadow-orange-200 group"
          >
            <UserPlus size={28} className="group-hover:scale-110 transition-transform" /> إضافة مستخدم جديد
          </button>
