import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  CreditCard, MapPin, Hash, UserCheck, Phone
} from 'lucide-react';
import { AppState, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter,
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return '--';
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    // منع تكرار رقم القميص في نفس الفئة
    if (formData.role === 'لاعب' && formData.number) {
      const isDuplicate = state.people.some(p => 
        p.id !== editingId && 
        p.role === 'لاعب' && 
        p.category === formData.category && 
        p.number === formData.number
      );
      if (isDuplicate) {
        alert('خطأ برمجي: رقم القميص هذا محجوز مسبقاً للاعب آخر في نفس الفئة.');
        return;
      }
    }

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        ...(formData as Person)
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name} بفئة ${newPerson.category}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
    setFormData({ role: 'لاعب', category: state.categories[0], joinDate: new Date().toISOString().split('T')[0] });
  };

  const globalFilter = state.globalCategoryFilter;
  const filtered = state.people.filter(p => {
    const matchCat = globalFilter === 'الكل' ? true : p.category === globalFilter;
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                      (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  return (
    <div className="space-y-10 animate-in fade-in duration-500">
      <div className="bg-white p-10 rounded-[4rem] shadow-sm border border-slate-100 flex flex-col lg:flex-row gap-8 no-print items-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-3 h-full bg-[#001F3F]"></div>
        <div className="flex-1 relative w-full">
          <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300" size={28} />
          <input 
            type="text" 
            placeholder="البحث بالاسم أو رقم القميص..." 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)}
            className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2.5rem] py-6 pr-16 pl-8 outline-none font-black text-2xl text-slate-800 focus:ring-8 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 transition-all placeholder:text-slate-200" 
          />
        </div>
        <button 
          onClick={() => { setEditingId(null); setFormData({ role: 'لاعب', category: globalFilter === 'الكل' ? state.categories[0] : globalFilter, joinDate: new Date().toISOString().split('T')[0] }); setIsModalOpen(true); }} 
          className="bg-[#001F3F] text-white px-12 py-6 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 shadow-2xl shadow-blue-900/20 hover:bg-black transition-all group w-full lg:w-auto"
        >
          <UserPlus size={32} className="group-hover:scale-110 transition-transform" /> إضافة عضو جديد
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
        {filtered.map(person => {
          const contractDaysLeft = person.contractEnd ? Math.ceil((new Date(person.contractEnd).getTime() - new Date().getTime()) / (1000 * 3600 * 24)) : null;
          const isExpiring = contractDaysLeft !== null && contractDaysLeft < 90 && contractDaysLeft > 0;

          return (
            <div key={person.id} className="bg-white p-10 rounded-[4rem] shadow-sm border border-slate-100 group relative overflow-hidden transition-all hover:shadow-2xl hover:-translate-y-2 border-b-8 border-slate-50 hover:border-blue-900">
               <div className="flex justify-between items-start mb-8">
                 <div className="w-20 h-20 bg-blue-50 border-4 border-blue-100 rounded-[2rem] flex items-center justify-center font-black text-blue-900 text-3xl shadow-inner">
                   {person.name.charAt(0).toUpperCase()}
                 </div>
                 <div className="flex flex-col items-end">
                    <span className={`text-[11px] font-black px-6 py-2 rounded-2xl uppercase shadow-lg ${person.role === 'لاعب' ? 'bg-orange-600 text-white shadow-orange-100' : 'bg-[#001F3F] text-white shadow-blue-100'}`}>
                      {person.role}
                    </span>
                    <span className="text-[10px] font-black text-slate-400 mt-3 px-3 py-1 bg-slate-50 rounded-lg border border-slate-100 tracking-widest">{person.category}</span>
                 </div>
               </div>

               <div className="space-y-2">
                 <h4 className="font-black text-3xl text-slate-800 leading-tight group-hover:text-blue-900 transition-colors">{person.name}</h4>
                 <div className="flex flex-wrap gap-6 pt-3 text-[12px] font-black text-slate-400">
                   <span className="flex items-center gap-3"><MapPin size={16} className="text-orange-500" /> {person.birthPlace}</span>
                   <span className="flex items-center gap-3"><Calendar size={16} className="text-blue-900" /> {calculateAge(person.birthDate)} سنة</span>
                 </div>
               </div>

               <div className="mt-10 grid grid-cols-2 gap-6">
                  <div className="bg-slate-50 p-6 rounded-[2rem] border-2 border-slate-100">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5">الرقم الوطني</p>
                    <p className="text-base font-black text-slate-800 font-mono tracking-tighter">{person.nationalId || '---'}</p>
                  </div>
                  <div className="bg-[#001F3F] p-6 rounded-[2rem] shadow-2xl shadow-blue-100 flex flex-col items-center justify-center relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-10 h-10 bg-white/10 rounded-full -mr-5 -mt-5"></div>
                    <p className="text-[10px] font-black text-blue-200 uppercase tracking-widest mb-1.5">القميص</p>
                    <p className="text-3xl font-black text-white">#{person.number || '00'}</p>
                  </div>
               </div>

               {isExpiring && (
                 <div className="mt-8 flex items-center gap-4 text-orange-600 bg-orange-50 p-4 rounded-[1.5rem] border-2 border-orange-200 animate-pulse">
                   <AlertCircle size={24} />
                   <span className="text-[12px] font-black italic tracking-tighter">انتهاء العقد خلال {contractDaysLeft} يوم</span>
                 </div>
               )}

               <div className="mt-12 pt-10 border-t border-slate-50 flex justify-between items-center">
                  <button onClick={() => onOpenReport?.(person)} className="text-[#001F3F] text-sm font-black hover:text-orange-600 transition-colors flex items-center gap-3 bg-blue-50 px-8 py-3 rounded-[1.5rem] shadow-sm">
                    الملف الخارق <UserCheck size={20}/>
                  </button>
                  <div className="flex gap-3 opacity-0 group-hover:opacity-100 transition-all transform translate-x-4 group-hover:translate-x-0">
                    <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-4 bg-slate-50 text-slate-400 hover:bg-blue-900 hover:text-white rounded-[1.2rem] shadow-sm transition-all"><Plus size={22}/></button>
                    <button onClick={() => { if(confirm(`هل أنت متأكد من حذف ملف ${person.name} نهائياً؟`)) { setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); addLog?.('حذف عضو', `تم مسح ملف العضو: ${person.name}`, 'error'); } }} className="p-4 bg-red-50 text-red-300 hover:bg-red-600 hover:text-white rounded-[1.2rem] shadow-sm transition-all"><Trash2 size={22}/></button>
                  </div>
               </div>
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/90 backdrop-blur-3xl flex items-center justify-center z-[200] p-6 no-print">
          <div className="bg-white rounded-[5rem] w-full max-w-7xl shadow-2xl my-auto overflow-hidden animate-in zoom-in-95 duration-500 border-[12px] border-white flex flex-col h-[92vh]">
            <div className="p-12 border-b bg-slate-50 flex justify-between items-center shrink-0">
              <div className="flex items-center gap-8">
                <div className="w-20 h-20 bg-[#001F3F] text-white rounded-[2.5rem] flex items-center justify-center shadow-2xl ring-8 ring-blue-900/10"><UserPlus size={40}/></div>
                <div>
                  <h3 className="text-4xl font-black text-slate-800">{editingId ? 'تعديل الملف الخارق للعضو' : 'تسجيل عضو جديد بالنظام الشامل'}</h3>
                  <p className="text-sm font-black text-orange-600 mt-2 uppercase tracking-[0.3em]">Al-Karamah Pro Member Hub</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-6 rounded-[2.5rem] text-slate-500 hover:text-red-600 hover:rotate-90 transition-all"><X size={40} /></button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto custom-scrollbar p-16 space-y-20">
              {/* القسم الأول: البيانات الشخصية */}
              <div className="space-y-12">
