                    <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">الاسم الثنائي (بالكامل)</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2.5rem] py-6 px-10 font-black text-3xl text-slate-800 focus:ring-12 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 outline-none transition-all" />
                  </div>
                  <div className="space-y-4">
                    <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">اسم الأب</label>
                    <input type="text" value={formData.fatherName || ''} onChange={e => setFormData({...formData, fatherName: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl text-slate-800 outline-none focus:border-blue-900 focus:bg-white" />
                  </div>
                  <div className="space-y-4">
                    <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">اسم الأم</label>
                    <input type="text" value={formData.motherName || ''} onChange={e => setFormData({...formData, motherName: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl text-slate-800 outline-none focus:border-blue-900 focus:bg-white" />
                  </div>
                  <div className="space-y-4">
                    <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">تاريخ الولادة</label>
                    <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({...formData, birthDate: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl text-slate-800 outline-none focus:border-blue-900" />
                  </div>
                  <div className="space-y-4">
                    <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">العمر (تلقائي)</label>
                    <div className="w-full bg-blue-50 border-4 border-blue-100 rounded-[2rem] p-6 font-black text-3xl text-blue-900 flex items-center justify-center shadow-inner">
                      {calculateAge(formData.birthDate)} سنة
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">مكان الولادة</label>
                    <input type="text" value={formData.birthPlace || ''} onChange={e => setFormData({...formData, birthPlace: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl text-slate-800 outline-none" />
                  </div>
                  <div className="space-y-4">
                    <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">القيد / الخانة</label>
                    <input type="text" value={formData.khana || ''} onChange={e => setFormData({...formData, khana: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl text-slate-800 outline-none" />
                  </div>
                  <div className="space-y-4">
                    <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">رقم الهاتف</label>
                    <input type="text" value={formData.phone || ''} onChange={e => setFormData({...formData, phone: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl text-slate-800 outline-none" />
                  </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[12px] font-black text-slate-400 mr-4 uppercase">العنوان السكني الحالي</label>
                  <input type="text" value={formData.address || ''} onChange={e => setFormData({...formData, address: e.target.value})} 
