import React, { useState } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit, X } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  // Fix: Added addLog prop to match App.tsx usage
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  // Fix: Comparison with 'مدرب' was invalid for UserRole. Changed to 'إداري فئة'.
  const canEdit = isManager || (currentUser?.role === 'إداري فئة' && !!restrictedCat);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'رجال')
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.location) return;

    // التحقق من أن التاريخ ليس في الماضي (مقارنة اليوم فقط)
    const todayStr = new Date().toISOString().split('T')[0];
    if (formData.date < todayStr) {
      alert('خطأ: لا يمكن إضافة تمرين بتاريخ قديم. يرجى اختيار تاريخ اليوم أو تاريخ مستقبلي.');
      return;
    }

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
      // Fix: Use addLog instead of manual notifications manipulation
      addLog?.('تعديل موعد تمرين', `تم تحديث تمرين فئة ${formData.category} - ${formData.objective}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: Math.random().toString(36).substr(2, 9),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تمرين عام'
      };
      setState(prev => ({ 
        ...prev, 
        sessions: [newSession, ...prev.sessions]
      }));
      // Fix: Use addLog instead of manual notifications manipulation
      addLog?.('إضافة موعد تمرين جديد', `تمت جدولة تمرين لفئة ${newSession.category} بتاريخ ${newSession.date}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
    setFormData({
      category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'رجال')
    });
  };

  const filteredSessions = (restrictedCat 
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-600 font-bold">المواعيد المجدولة للتمارين</h3>
        {canEdit && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-blue-600 text-white px-6 py-2 rounded-xl flex items-center gap-2 font-bold shadow-lg shadow-blue-200">
            <Plus size={20} /> إضافة موعد تمرين
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 relative group overflow-hidden">
            <div className="flex items-center gap-3 mb-4">
              <div className="bg-orange-50 text-orange-600 p-3 rounded-2xl"><Calendar size={24} /></div>
              <div>
                <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-1 rounded-md font-black uppercase">{session.category}</span>
                <h4 className="font-bold text-lg text-slate-800 mt-1">{session.objective}</h4>
              </div>
            </div>
            <div className="space-y-3 mt-4 pt-4 border-t border-slate-50 text-sm">
              <div className="flex items-center gap-3 text-slate-500">
                <MapPin size={18} className="text-orange-500" />
                <span className="font-bold text-slate-950">{session.location}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-500">
                <Clock size={18} className="text-blue-500" />
                <span className="font-black text-slate-950">{session.date} | {session.time}</span>
              </div>
            </div>
            {canEdit && (
              <div className="absolute top-4 left-4 opacity-0 group-hover:opacity-100 transition-all flex gap-1">
                <button onClick={() => {setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true);}} className="p-2 bg-blue-50 text-blue-600 rounded-lg"><Edit size={16}/></button>
                <button onClick={() => {
                  if(confirm('هل أنت متأكد من حذف هذا الموعد؟')) {
                    setState(prev => ({...prev, sessions: prev.sessions.filter(s => s.id !== session.id)}));
                    // Fix: Added addLog call for deletion
                    addLog?.('حذف موعد تمرين', `تم مسح موعد تمرين فئة ${session.category} بتاريخ ${session.date}`, 'warning');
                  }
                }} className="p-2 bg-red-50 text-red-600 rounded-lg"><Trash2 size={16}/></button>
              </div>
            )}
          </div>
        ))}
        {filteredSessions.length === 0 && (
          <div className="col-span-full py-20 text-center bg-white rounded-[2rem] border-2 border-dashed border-slate-100 text-slate-400 font-bold italic">
            لا توجد تمارين مجدولة حالياً
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[200] p-4" onClick={(e) => e.target === e.currentTarget && setIsModalOpen(false)}>
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">{editingSessionId ? 'تعديل موعد التمرين' : 'إضافة موعد تمرين جديد'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl text-slate-500 hover:text-red-600 transition-all">
                <X size={20} />
              </button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">الفئة</label>
                <select className="w-full bg-slate-100 rounded-2xl p-4 outline-none font-bold text-slate-950 disabled:opacity-70"
                  value={formData.category} disabled={!!restrictedCat} onChange={e => setFormData({ ...formData, category: e.target.value as Category })}>
                  {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">التاريخ</label>
                  <input type="date" required 
                    value={formData.date || ''} 
                    min={new Date().toISOString().split('T')[0]}
                    className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" 
                    onChange={e => setFormData({ ...formData, date: e.target.value })} 
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-black text-slate-500">الوقت</label>
                  <input type="time" required value={formData.time || ''} className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" onChange={e => setFormData({ ...formData, time: e.target.value })} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">المكان</label>
                <input type="text" required value={formData.location || ''} placeholder="مكان التمرين" className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-black text-slate-500">الموضوع / الهدف</label>
                <input type="text" value={formData.objective || ''} placeholder="موضوع التمرين الرئيسي" className="w-full bg-slate-100 rounded-2xl p-4 font-bold text-slate-950 outline-none focus:ring-2 focus:ring-blue-500" onChange={e => setFormData({ ...formData, objective: e.target.value })} />
              </div>
              <div className="flex gap-3 mt-6">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-slate-100 text-slate-600 font-black py-4 rounded-2xl hover:bg-slate-200 transition-all">إلغاء</button>
                <button type="submit" className="flex-1 bg-blue-900 text-white font-black py-4 rounded-2xl hover:bg-black transition-all">حفظ البيانات</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  CreditCard, MapPin, Hash, UserCheck, Phone, ChevronLeft
} from 'lucide-react';
import { AppState, Person, Role } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter,
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return '--';
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    // منع تكرار رقم القميص في نفس الفئة
    if (formData.role === 'لاعب' && formData.number) {
      const isDuplicate = state.people.some(p => 
        p.id !== editingId && 
        p.role === 'لاعب' && 
        p.category === formData.category && 
        p.number === formData.number
      );
      if (isDuplicate) {
        alert('خطأ برمجي: رقم القميص هذا محجوز مسبقاً للاعب آخر في نفس الفئة.');
        return;
      }
    }

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        ...(formData as Person)
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name} بفئة ${newPerson.category}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
    setFormData({ role: 'لاعب', category: state.categories[0], joinDate: new Date().toISOString().split('T')[0] });
  };

  const globalFilter = state.globalCategoryFilter;
  const filtered = state.people.filter(p => {
    const matchCat = globalFilter === 'الكل' ? true : p.category === globalFilter;
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                      (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  return (
    <div className="space-y-10 animate-in fade-in duration-500">
      <div className="bg-white p-10 rounded-[4rem] shadow-sm border border-slate-100 flex flex-col lg:flex-row gap-8 no-print items-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-3 h-full bg-[#001F3F]"></div>
        <div className="flex-1 relative w-full">
          <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300" size={28} />
          <input 
            type="text" 
            placeholder="البحث بالاسم أو رقم القميص..." 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)}
            className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2.5rem] py-6 pr-16 pl-8 outline-none font-black text-2xl text-slate-800 focus:ring-8 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 transition-all placeholder:text-slate-200" 
          />
        </div>
        <button 
          onClick={() => { setEditingId(null); setFormData({ role: 'لاعب', category: globalFilter === 'الكل' ? state.categories[0] : globalFilter, joinDate: new Date().toISOString().split('T')[0] }); setIsModalOpen(true); }} 
          className="bg-[#001F3F] text-white px-12 py-6 rounded-[2.5rem] font-black text-xl flex items-center justify-center gap-4 shadow-2xl shadow-blue-900/20 hover:bg-black transition-all group w-full lg:w-auto"
        >
          <UserPlus size={32} className="group-hover:scale-110 transition-transform" /> إضافة عضو جديد
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
        {filtered.map(person => {
          const contractDaysLeft = person.contractEnd ? Math.ceil((new Date(person.contractEnd).getTime() - new Date().getTime()) / (1000 * 3600 * 24)) : null;
          const isExpiring = contractDaysLeft !== null && contractDaysLeft < 90 && contractDaysLeft > 0;

          return (
            <div key={person.id} className="bg-white p-10 rounded-[4rem] shadow-sm border border-slate-100 group relative overflow-hidden transition-all hover:shadow-2xl hover:-translate-y-2 border-b-8 border-slate-50 hover:border-blue-900">
               <div className="flex justify-between items-start mb-8">
                 <div className="w-20 h-20 bg-blue-50 border-4 border-blue-100 rounded-[2rem] flex items-center justify-center font-black text-blue-900 text-3xl shadow-inner">
                   {person.name.charAt(0).toUpperCase()}
                 </div>
                 <div className="flex flex-col items-end">
                    <span className={`text-[11px] font-black px-6 py-2 rounded-2xl uppercase shadow-lg ${person.role === 'لاعب' ? 'bg-orange-600 text-white shadow-orange-100' : 'bg-[#001F3F] text-white shadow-blue-100'}`}>
                      {person.role}
                    </span>
                    <span className="text-[10px] font-black text-slate-400 mt-3 px-3 py-1 bg-slate-50 rounded-lg border border-slate-100 tracking-widest">{person.category}</span>
                 </div>
               </div>

               <div className="space-y-2">
                 <h4 className="font-black text-3xl text-slate-800 leading-tight group-hover:text-blue-900 transition-colors">{person.name}</h4>
                 <div className="flex flex-wrap gap-6 pt-3 text-[12px] font-black text-slate-400">
