             <div className="flex justify-between items-center mb-12">
                <span className="text-[12px] font-black bg-[#001F3F] text-white px-6 py-2.5 rounded-2xl uppercase shadow-xl shadow-blue-900/10 tracking-widest">{m.category} | {m.matchType}</span>
                <span className={`text-[12px] font-black px-5 py-2 rounded-2xl ${m.isCompleted ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600 animate-pulse'}`}>
                  {m.isCompleted ? 'صافرة النهاية' : 'بانتظار الصافرة'}
