                       </h4>
                       <div className="space-y-6">
                          {activeMatch.lineup.subs.map((s, i) => (
                            <div key={i} className="flex gap-6 items-center animate-in slide-in-from-left-8 duration-300">
                              <div className="flex-1 relative">
                                <select 
                                  value={s.name} 
                                  onChange={e => {
                                    const p = state.people.find(x => x.name === e.target.value);
                                    const newList = [...activeMatch.lineup.subs];
                                    newList[i] = { name: p?.name || '', number: p?.number?.toString() || '' };
                                    setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: newList}});
                                  }}
                                  className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] py-5 px-10 text-2xl font-black outline-none focus:ring-12 focus:ring-orange-500/5 focus:border-orange-500 appearance-none"
                                >
                                  <option value="">-- اختر لاعب بديل --</option>
                                  {getAvailablePlayers(activeMatch, s.name).map(p => <option key={p.id} value={p.name}>{p.name} (رقم: {p.number})</option>)}
                                </select>
                                {s.number && (
                                  <div className="absolute left-6 top-1/2 -translate-y-1/2 bg-orange-600 text-white w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-2xl border-4 border-white">#{s.number}</div>
                                )}
                              </div>
                              <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: activeMatch.lineup.subs.filter((_, idx) => idx !== i)}})} className="p-5 bg-red-50 text-red-300 hover:bg-red-600 hover:text-white rounded-[1.8rem] transition-all shadow-sm">
                                <Trash2 size={32}/>
                              </button>
                            </div>
                          ))}
                          <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: [...activeMatch.lineup.subs, {name:'', number:''}]}})} 
                            className="w-full py-10 border-[6px] border-dashed border-slate-100 rounded-[3.5rem] text-2xl font-black text-slate-300 hover:text-orange-600 hover:border-orange-200 transition-all flex items-center justify-center gap-6 group">
                            <Plus size={48} className="group-hover:rotate-180 transition-transform duration-500" /> إضافة مقعد احتياط جديد
                          </button>
                       </div>

                       <div className="pt-16 space-y-12">
                         <h4 className="text-3xl font-black text-slate-800 flex items-center gap-6 border-r-[12px] border-slate-800 pr-8">
                            النتيجة النهائية وسجل المباراة
                         </h4>
                         <div className="grid grid-cols-2 gap-12">
                            <div className="space-y-4">
                               <label className="text-[12px] font-black text-slate-400 uppercase tracking-widest mr-6">أهداف الكرامة</label>
                               <input type="number" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} 
                                className="w-full bg-[#001F3F] text-white border-none rounded-[3rem] p-10 text-7xl font-black text-center shadow-2xl focus:ring-16 focus:ring-blue-100 transition-all" />
                            </div>
                            <div className="space-y-4">
                               <label className="text-[12px] font-black text-slate-400 uppercase tracking-widest mr-6">أهداف الخصم</label>
                               <input type="number" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} 
                                className="w-full bg-slate-100 border-none rounded-[3rem] p-10 text-7xl font-black text-center shadow-inner focus:ring-16 focus:ring-slate-200 transition-all" />
                            </div>
                         </div>
                         <div className="bg-orange-50 p-12 rounded-[4rem] border-4 border-dashed border-orange-200 shadow-inner">
                           <div className="flex items-center gap-4 mb-6">
                              <Shield className="text-orange-600" size={32} />
                              <span className="text-xl font-black text-orange-900 tracking-tighter">سجل أحداث اللقاء (الهدافين، البطاقات، الإصابات)</span>
                           </div>
                           <textarea value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})}
                            placeholder="اكتب هنا ملخص أحداث المباراة بالتفصيل (مثلاً: د.12 هدف اللاعب #9)..."
                            className="w-full bg-transparent border-none font-black text-slate-800 outline-none resize-none h-48 text-2xl leading-relaxed placeholder:text-orange-200" />
                         </div>
                       </div>
                    </div>
                 </div>

                 <div className="flex flex-col md:flex-row gap-10 pt-20 border-t-8 border-slate-50">
                    <button onClick={() => setActiveMatch(null)} className="flex-1 bg-slate-100 text-slate-600 font-black py-10 rounded-[4rem] text-3xl hover:bg-slate-200 shadow-sm transition-all">إلغاء وانسحاب</button>
                    <button onClick={() => {
                      const finalMatch = {...activeMatch, isCompleted: true};
                      setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? finalMatch : m) }));
                      addLog?.('تحديث نتيجة مباراة', `تم اعتماد نتيجة مباراة ${activeMatch.opponent}: (${activeMatch.ourScore}-${activeMatch.opponentScore})`, 'success');
                      setActiveMatch(null);
                    }} className="flex-[2] bg-[#001F3F] text-white font-black py-10 rounded-[4rem] shadow-2xl hover:bg-black transition-all text-4xl group">
                      تثبيت وحفظ التقرير النهائي <ChevronLeft className="inline-block group-hover:-translate-x-4 transition-transform mr-6" size={48} />
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  CreditCard, MapPin, Hash, UserCheck, Phone, ChevronLeft, FolderPlus
} from 'lucide-react';
import { AppState, Person, Role, Category } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isAddCatModalOpen, setIsAddCatModalOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter,
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return '--';
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    if (formData.role === 'لاعب' && formData.number) {
      const isDuplicate = state.people.some(p => 
        p.id !== editingId && 
        p.role === 'لاعب' && 
        p.category === formData.category && 
        p.number === formData.number
      );
      if (isDuplicate) {
        alert('خطأ برمجي: رقم القميص هذا محجوز مسبقاً للاعب آخر في نفس الفئة.');
        return;
      }
    }

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        ...(formData as Person)
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name} بفئة ${newPerson.category}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
    setFormData({ role: 'لاعب', category: state.categories[0], joinDate: new Date().toISOString().split('T')[0] });
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) {
      alert('هذه الفئة موجودة بالفعل.');
      return;
    }
    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة', `تم إضافة فئة جديدة: ${newCatName.trim()}`, 'success');
    setNewCatName('');
    setIsAddCatModalOpen(false);
  };

  const globalFilter = state.globalCategoryFilter;
  const filtered = state.people.filter(p => {
    const matchCat = globalFilter === 'الكل' ? true : p.category === globalFilter;
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                      (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Header Bar with Category Add Option */}
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col lg:flex-row gap-6 no-print items-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-2 h-full bg-[#001F3F]"></div>
        <div className="flex-1 relative w-full">
          <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300" size={22} />
          <input 
            type="text" 
            placeholder="البحث بالاسم أو رقم القميص..." 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)}
            className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-4 pr-14 pl-6 outline-none font-black text-lg text-slate-800 focus:ring-4 focus:ring-blue-900/5 focus:bg-white transition-all placeholder:text-slate-300" 
          />
        </div>

        <div className="flex gap-3 w-full lg:w-auto">
          <button 
            onClick={() => setIsAddCatModalOpen(true)}
            className="bg-orange-500 text-white px-6 py-4 rounded-2xl font-black text-sm flex items-center justify-center gap-2 shadow-lg shadow-orange-100 hover:bg-orange-600 transition-all group"
            title="إضافة فئة رياضية جديدة"
          >
            <FolderPlus size={20} /> إضافة فئة
          </button>

          <button 
            onClick={() => { 
              setEditingId(null); 
              setFormData({ 
                role: 'لاعب', 
                category: globalFilter === 'الكل' ? state.categories[0] : globalFilter, 
                joinDate: new Date().toISOString().split('T')[0] 
              }); 
              setIsModalOpen(true); 
            }} 
            className="bg-[#001F3F] text-white px-8 py-4 rounded-2xl font-black text-sm flex items-center justify-center gap-2 shadow-xl shadow-blue-900/20 hover:bg-black transition-all group"
          >
            <UserPlus size={24} /> إضافة عضو جديد
          </button>
        </div>
      </div>

      {/* Grid of Members with scaled down fonts */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filtered.map(person => {
          const contractDaysLeft = person.contractEnd ? Math.ceil((new Date(person.contractEnd).getTime() - new Date().getTime()) / (1000 * 3600 * 24)) : null;
          const isExpiring = contractDaysLeft !== null && contractDaysLeft < 90 && contractDaysLeft > 0;

          return (
            <div key={person.id} className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100 group relative overflow-hidden transition-all hover:shadow-2xl hover:-translate-y-1 border-b-4 border-slate-50 hover:border-blue-900">
               <div className="flex justify-between items-start mb-6">
                 <div className="w-16 h-16 bg-blue-50 border-2 border-blue-100 rounded-2xl flex items-center justify-center font-black text-blue-900 text-2xl shadow-inner">
                   {person.name.charAt(0).toUpperCase()}
                 </div>
                 <div className="flex flex-col items-end">
                    <span className={`text-[9px] font-black px-4 py-1.5 rounded-full uppercase shadow-md ${person.role === 'لاعب' ? 'bg-orange-600 text-white shadow-orange-100' : 'bg-[#001F3F] text-white shadow-blue-100'}`}>
                      {person.role}
                    </span>
                    <span className="text-[9px] font-black text-slate-400 mt-2 px-3 py-0.5 bg-slate-50 rounded-lg border border-slate-100 tracking-widest">{person.category}</span>
                 </div>
               </div>

               <div className="space-y-1.5">
                 <h4 className="font-black text-xl text-slate-800 leading-tight group-hover:text-blue-900 transition-colors">{person.name}</h4>
                 <div className="flex flex-wrap gap-4 pt-2 text-[10px] font-black text-slate-400">
                   <span className="flex items-center gap-2"><MapPin size={14} className="text-orange-500" /> {person.birthPlace}</span>
                   <span className="flex items-center gap-2"><Calendar size={14} className="text-blue-900" /> {calculateAge(person.birthDate)} سنة</span>
                 </div>
               </div>

               <div className="mt-8 grid grid-cols-2 gap-4">
                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">الرقم الوطني</p>
                    <p className="text-xs font-black text-slate-800 font-mono tracking-tighter">{person.nationalId || '---'}</p>
                  </div>
                  <div className="bg-[#001F3F] p-4 rounded-2xl shadow-lg shadow-blue-100 flex flex-col items-center justify-center relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-8 h-8 bg-white/10 rounded-full -mr-4 -mt-4"></div>
                    <p className="text-[8px] font-black text-blue-200 uppercase tracking-widest mb-1">القميص</p>
                    <p className="text-xl font-black text-white">#{person.number || '00'}</p>
                  </div>
               </div>

               {isExpiring && (
                 <div className="mt-6 flex items-center gap-3 text-orange-600 bg-orange-50 p-3 rounded-[1.2rem] border-2 border-orange-200 animate-pulse">
                   <AlertCircle size={18} />
                   <span className="text-[10px] font-black italic tracking-tighter">انتهاء العقد خلال {contractDaysLeft} يوم</span>
                 </div>
               )}

               <div className="mt-10 pt-8 border-t border-slate-50 flex justify-between items-center">
                  <button onClick={() => onOpenReport?.(person)} className="text-[#001F3F] text-[10px] font-black hover:text-orange-600 transition-colors flex items-center gap-2 bg-blue-50 px-5 py-2 rounded-xl shadow-sm">
                    الملف الخارق <UserCheck size={16}/>
                  </button>
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-all transform translate-x-2 group-hover:translate-x-0">
                    <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-3 bg-slate-50 text-slate-400 hover:bg-blue-900 hover:text-white rounded-[1rem] shadow-sm transition-all"><Plus size={18}/></button>
                    <button onClick={() => { if(confirm(`هل أنت متأكد من حذف ملف ${person.name} نهائياً؟`)) { setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); addLog?.('حذف عضو', `تم مسح ملف العضو: ${person.name}`, 'error'); } }} className="p-3 bg-red-50 text-red-300 hover:bg-red-600 hover:text-white rounded-[1rem] shadow-sm transition-all"><Trash2 size={18}/></button>
                  </div>
               </div>
            </div>
          );
        })}
      </div>

      {/* Add Category Modal */}
      {isAddCatModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/80 backdrop-blur-md flex items-center justify-center z-[250] p-6 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border-8 border-white">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800">إضافة فئة جديدة</h3>
              <button onClick={() => setIsAddCatModalOpen(false)} className="bg-slate-200 p-3 rounded-2xl text-slate-600 hover:rotate-90 transition-transform"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 mr-2 uppercase tracking-widest">اسم الفئة (مثلاً: فئة البراعم)</label>
                <input 
                  type="text" 
                  value={newCatName} 
                  onChange={e => setNewCatName(e.target.value)}
                  className="w-full bg-slate-50 border-4 border-slate-100 rounded-2xl py-4 px-6 font-black text-xl text-slate-800 outline-none focus:ring-8 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 transition-all"
                  placeholder="ادخل الاسم هنا..."
                />
              </div>
              <button onClick={handleAddCategory} className="w-full bg-[#001F3F] text-white font-black py-4 rounded-2xl shadow-xl hover:bg-black transition-all text-lg">تأكيد الإضافة</button>
            </div>
          </div>
        </div>
      )}

      {/* Extensive Member Modal with scaled down fonts */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/90 backdrop-blur-3xl flex items-center justify-center z-[200] p-6 no-print">
          <div className="bg-white rounded-[4rem] w-full max-w-7xl shadow-2xl my-auto overflow-hidden animate-in zoom-in-95 duration-500 border-[8px] border-white flex flex-col h-[90vh]">
            <div className="p-8 border-b bg-slate-50 flex justify-between items-center shrink-0">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 bg-[#001F3F] text-white rounded-[1.8rem] flex items-center justify-center shadow-2xl ring-4 ring-blue-900/10"><UserPlus size={32}/></div>
                <div>
                  <h3 className="text-2xl font-black text-slate-800">{editingId ? 'تعديل الملف الخارق للعضو' : 'تسجيل عضو جديد بالنظام الشامل'}</h3>
                  <p className="text-[10px] font-black text-orange-600 mt-1 uppercase tracking-[0.2em]">Al-Karamah Pro Member Hub</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-4 rounded-[2rem] text-slate-500 hover:text-red-600 hover:rotate-90 transition-all"><X size={32} /></button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto custom-scrollbar p-12 space-y-16">
              <div className="space-y-10">
                <h4 className="text-lg font-black text-blue-900 flex items-center gap-4 border-r-[8px] border-orange-500 pr-6">
                  <Home size={28} /> الهوية الشخصية والبيانات المدنية
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                  <div className="space-y-3 col-span-1 md:col-span-2">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">الاسم الثنائي (بالكامل)</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] py-4 px-8 font-black text-xl text-slate-800 focus:ring-8 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900 outline-none transition-all" />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">اسم الأب</label>
                    <input type="text" value={formData.fatherName || ''} onChange={e => setFormData({...formData, fatherName: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg text-slate-800 outline-none focus:border-blue-900 focus:bg-white" />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">اسم الأم</label>
                    <input type="text" value={formData.motherName || ''} onChange={e => setFormData({...formData, motherName: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg text-slate-800 outline-none focus:border-blue-900 focus:bg-white" />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">تاريخ الولادة</label>
                    <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({...formData, birthDate: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg text-slate-800 outline-none focus:border-blue-900" />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">العمر (تلقائي)</label>
                    <div className="w-full bg-blue-50 border-4 border-blue-100 rounded-[1.5rem] p-4 font-black text-2xl text-blue-900 flex items-center justify-center shadow-inner">
                      {calculateAge(formData.birthDate)} سنة
                    </div>
