                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">مكان الولادة</label>
                    <input type="text" value={formData.birthPlace || ''} onChange={e => setFormData({...formData, birthPlace: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg text-slate-800 outline-none" />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">القيد / الخانة</label>
                    <input type="text" value={formData.khana || ''} onChange={e => setFormData({...formData, khana: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg text-slate-800 outline-none" />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">رقم الهاتف</label>
                    <input type="text" value={formData.phone || ''} onChange={e => setFormData({...formData, phone: e.target.value})} 
