                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">الرقم الاتحادي</label>
                    <input type="text" value={formData.federalNumber || ''} onChange={e => setFormData({...formData, federalNumber: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg text-slate-800 outline-none" />
