                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">الرقم الدولي</label>
                    <input type="text" value={formData.internationalId || ''} onChange={e => setFormData({...formData, internationalId: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg text-slate-800 outline-none" />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-orange-600 mr-4 uppercase italic">رقم قميص اللاعب</label>
                    <input type="number" value={formData.number || ''} onChange={e => setFormData({...formData, number: parseInt(e.target.value)})} 
                      className="w-full bg-[#001F3F] text-white border-none rounded-[1.8rem] p-4 font-black text-3xl text-center outline-none focus:ring-8 focus:ring-blue-100 transition-all shadow-2xl" />
                  </div>
                </div>
              </div>

              <div className="space-y-12">
                <h4 className="text-lg font-black text-emerald-600 flex items-center gap-6 border-r-[8px] border-orange-500 pr-6">
                  <Shield size={28} /> الصفة الفنية، الفئة وسجل التعاقدات
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                   <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">الصفة / الدور بالنادي</label>
                    <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as Role})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg outline-none focus:border-blue-900">
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
