                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">الفئة الرياضية</label>
                    <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg outline-none focus:border-blue-900">
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">بداية العقد</label>
                    <input type="date" value={formData.contractStart || ''} onChange={e => setFormData({...formData, contractStart: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg outline-none focus:border-blue-900" />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 mr-4 uppercase">نهاية العقد</label>
                    <input type="date" value={formData.contractEnd || ''} onChange={e => setFormData({...formData, contractEnd: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 rounded-[1.5rem] p-4 font-black text-lg outline-none focus:border-blue-900" />
