        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  CreditCard, MapPin, Hash, UserCheck, Phone, ChevronLeft, FolderPlus, Filter, Settings2
} from 'lucide-react';
import { AppState, Person, Role, Category } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isManageCatsOpen, setIsManageCatsOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return '--';
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    if (formData.role === 'لاعب' && formData.number) {
      const isDuplicate = state.people.some(p => 
        p.id !== editingId && 
        p.role === 'لاعب' && 
        p.category === formData.category && 
        p.number === formData.number
      );
      if (isDuplicate) {
        alert('خطأ: رقم القميص محجوز مسبقاً في هذه الفئة.');
        return;
      }
    }

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        ...(formData as Person)
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('الفئة موجودة مسبقاً.');
    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة', `تم إضافة فئة: ${newCatName.trim()}`, 'success');
    setNewCatName('');
  };

  const handleDeleteCategory = (cat: string) => {
    if (confirm(`هل أنت متأكد من حذف فئة "${cat}"؟ سيتم إلغاء ربط اللاعبين بها.`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
      addLog?.('حذف فئة', `تم حذف فئة: ${cat}`, 'warning');
    }
  };

  const filtered = state.people.filter(p => {
    const matchCat = localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter;
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                      (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  // كلاس موحد لضمان خط غامق جداً وغير باهت في الحقول
  const fieldClass = "w-full bg-white border-2 border-slate-300 rounded-2xl py-3 px-6 font-black text-slate-900 outline-none focus:ring-4 focus:ring-blue-900/10 focus:border-blue-900 transition-all placeholder:text-slate-400";

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* التحكم الداخلي: فلتر، بحث، وإدارة الفئات */}
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 no-print space-y-4">
        <div className="flex flex-col lg:flex-row gap-4 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="البحث بالاسم أو الرقم..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
              className={`${fieldClass} pr-12 text-sm`} 
            />
          </div>

          <div className="flex items-center gap-3 w-full lg:w-auto">
            <div className="relative group">
              <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-[#001F3F]" size={16} />
              <select 
                value={localCategoryFilter}
                onChange={e => setLocalCategoryFilter(e.target.value)}
                className="bg-slate-50 border-2 border-slate-200 rounded-xl py-3 pr-10 pl-4 font-black text-xs text-[#001F3F] outline-none focus:border-[#001F3F] appearance-none cursor-pointer"
              >
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <button 
              onClick={() => setIsManageCatsOpen(true)}
              className="bg-orange-100 text-orange-700 px-5 py-3 rounded-xl font-black text-xs flex items-center gap-2 hover:bg-orange-200 transition-all"
            >
              <Settings2 size={16} /> إدارة الفئات
            </button>

            <button 
              onClick={() => { 
                setEditingId(null); 
                setFormData({ role: 'لاعب', category: state.categories[0] || '', joinDate: new Date().toISOString().split('T')[0] }); 
                setIsModalOpen(true); 
              }} 
              className="bg-[#001F3F] text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 hover:bg-black transition-all shadow-lg"
            >
              <UserPlus size={18} /> إضافة عضو
            </button>
          </div>
        </div>
      </div>

      {/* Grid Members */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filtered.map(person => (
          <div key={person.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 group relative transition-all hover:shadow-xl border-b-4 border-slate-50 hover:border-blue-900">
             <div className="flex justify-between items-start mb-4">
               <div className="w-14 h-14 bg-blue-50 border-2 border-blue-100 rounded-2xl flex items-center justify-center font-black text-blue-900 text-xl shadow-inner">
                 {person.name.charAt(0).toUpperCase()}
               </div>
               <div className="flex flex-col items-end">
                  <span className={`text-[8px] font-black px-3 py-1 rounded-full uppercase ${person.role === 'لاعب' ? 'bg-orange-500 text-white' : 'bg-[#001F3F] text-white'}`}>
                    {person.role}
                  </span>
                  <span className="text-[8px] font-black text-slate-400 mt-2 px-2 py-0.5 bg-slate-50 rounded border border-slate-100">{person.category}</span>
               </div>
             </div>

             <div className="space-y-1">
               <h4 className="font-black text-lg text-slate-900 leading-tight group-hover:text-blue-900 transition-colors">{person.name}</h4>
               <div className="flex flex-wrap gap-4 pt-1 text-[9px] font-black text-slate-500">
                 <span className="flex items-center gap-1.5"><MapPin size={12} className="text-orange-500" /> {person.birthPlace}</span>
                 <span className="flex items-center gap-1.5"><Calendar size={12} className="text-blue-900" /> {calculateAge(person.birthDate)} سنة</span>
               </div>
             </div>

             <div className="mt-6 pt-6 border-t border-slate-50 flex justify-between items-center">
                <div className="flex items-center gap-2">
                   <div className="bg-[#001F3F] text-white w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs">#{person.number || '00'}</div>
                   <button onClick={() => onOpenReport?.(person)} className="text-[#001F3F] text-[9px] font-black hover:underline">الملف الكامل</button>
                </div>
                <div className="flex gap-1.5 opacity-0 group-hover:opacity-100 transition-all">
                  <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-2 bg-slate-50 text-slate-400 hover:bg-blue-900 hover:text-white rounded-lg transition-all"><Plus size={14}/></button>
                  <button onClick={() => { if(confirm(`حذف ${person.name}؟`)) { setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); addLog?.('حذف عضو', `تم مسح ملف: ${person.name}`, 'error'); } }} className="p-2 bg-red-50 text-red-300 hover:bg-red-600 hover:text-white rounded-lg transition-all"><Trash2 size={14}/></button>
                </div>
             </div>
          </div>
        ))}
      </div>

      {/* مودال إدارة الفئات (إضافة وحذف) */}
      {isManageCatsOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/80 backdrop-blur-md flex items-center justify-center z-[300] p-6 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-lg font-black text-slate-800 flex items-center gap-2"><Layers size={20} className="text-orange-500" /> إدارة الفئات</h3>
              <button onClick={() => setIsManageCatsOpen(false)} className="bg-slate-200 p-2 rounded-xl hover:rotate-90 transition-transform"><X size={20} /></button>
            </div>
            <div className="p-6 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 mr-2 uppercase">إضافة فئة جديدة</label>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={newCatName} 
                    onChange={e => setNewCatName(e.target.value)}
                    className={`${fieldClass} text-xs py-2`}
                    placeholder="اسم الفئة..."
                  />
                  <button onClick={handleAddCategory} className="bg-[#001F3F] text-white px-4 rounded-xl font-black text-xs hover:bg-black">إضافة</button>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 mr-2 uppercase">الفئات الحالية (اضغط للحذف)</label>
                <div className="max-h-40 overflow-y-auto custom-scrollbar space-y-1">
                  {state.categories.map(c => (
                    <div key={c} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl group border border-transparent hover:border-red-200">
                      <span className="font-black text-xs text-slate-800">{c}</span>
                      <button onClick={() => handleDeleteCategory(c)} className="text-red-300 hover:text-red-600 transition-colors">
                        <Trash2 size={16} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
              <button onClick={() => setIsManageCatsOpen(false)} className="w-full bg-slate-100 text-slate-600 font-black py-3 rounded-xl text-xs">إغلاق</button>
            </div>
          </div>
        </div>
      )}

      {/* مودال العضوية (كافة الحقول خط غامق) */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/90 backdrop-blur-3xl flex items-center justify-center z-[200] p-4 no-print">
          <div className="bg-white rounded-[3.5rem] w-full max-w-5xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-500 border-[6px] border-white flex flex-col h-[90vh]">
            <div className="p-6 border-b bg-slate-50 flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-[#001F3F] text-white rounded-2xl flex items-center justify-center shadow-xl"><UserPlus size={24}/></div>
                <h3 className="text-xl font-black text-slate-800">{editingId ? 'تعديل الملف' : 'تسجيل عضو جديد'}</h3>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-3 rounded-2xl text-slate-500 hover:text-red-600 hover:rotate-90 transition-all"><X size={24} /></button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto custom-scrollbar p-10 space-y-12">
              <div className="space-y-8">
                <h4 className="text-md font-black text-blue-900 flex items-center gap-3 border-r-8 border-orange-500 pr-5"><Home size={22} /> البيانات الشخصية</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  <div className="space-y-2 col-span-1 md:col-span-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">الاسم الثنائي</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className={`${fieldClass} text-base`} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">اسم الأب</label>
                    <input type="text" value={formData.fatherName || ''} onChange={e => setFormData({...formData, fatherName: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">اسم الأم</label>
                    <input type="text" value={formData.motherName || ''} onChange={e => setFormData({...formData, motherName: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">تاريخ الميلاد</label>
                    <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({...formData, birthDate: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">العمر الحالي</label>
                    <div className="w-full bg-blue-50 border-2 border-blue-200 rounded-2xl py-3 px-6 font-black text-lg text-blue-900 flex items-center justify-center">{calculateAge(formData.birthDate)} سنة</div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">مكان الولادة</label>
                    <input type="text" value={formData.birthPlace || ''} onChange={e => setFormData({...formData, birthPlace: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">القيد / الخانة</label>
                    <input type="text" value={formData.khana || ''} onChange={e => setFormData({...formData, khana: e.target.value})} className={fieldClass} />
                  </div>
                </div>
              </div>

              <div className="space-y-8">
                <h4 className="text-md font-black text-orange-600 flex items-center gap-3 border-r-8 border-blue-900 pr-5"><Hash size={22} /> الأرقام الاتحادية والقميص</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">الرقم الوطني</label>
                    <input type="text" value={formData.nationalId || ''} onChange={e => setFormData({...formData, nationalId: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">الرقم الاتحادي</label>
                    <input type="text" value={formData.federalNumber || ''} onChange={e => setFormData({...formData, federalNumber: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">رقم الهاتف</label>
                    <input type="text" value={formData.phone || ''} onChange={e => setFormData({...formData, phone: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-orange-600 mr-2 italic font-black">رقم القميص المميز</label>
                    <input type="number" value={formData.number || ''} onChange={e => setFormData({...formData, number: parseInt(e.target.value)})} className="w-full bg-[#001F3F] text-white border-none rounded-2xl py-3 px-6 font-black text-2xl text-center outline-none focus:ring-8 focus:ring-blue-100 transition-all shadow-xl" />
                  </div>
                </div>
              </div>

              <div className="space-y-8">
                <h4 className="text-md font-black text-emerald-600 flex items-center gap-3 border-r-8 border-orange-500 pr-5"><Shield size={22} /> الصفة والعقود</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                   <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">الدور بالنادي</label>
                    <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as Role})} className={fieldClass}>
                      {roles.map(r => <option key={r} value={r} className="font-black text-slate-900">{r}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">الفئة الرياضية</label>
                    <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className={fieldClass}>
                      {state.categories.map(c => <option key={c} value={c} className="font-black text-slate-900">{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">بداية العقد</label>
                    <input type="date" value={formData.contractStart || ''} onChange={e => setFormData({...formData, contractStart: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 mr-2">نهاية العقد</label>
                    <input type="date" value={formData.contractEnd || ''} onChange={e => setFormData({...formData, contractEnd: e.target.value})} className={fieldClass} />
                  </div>
                </div>
              </div>

              <div className="flex gap-4 pt-8 border-t-2 border-slate-50 shrink-0">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-slate-100 text-slate-600 font-black py-4 rounded-2xl text-sm hover:bg-slate-200 transition-colors">إلغاء</button>
                <button type="submit" className="flex-[2] bg-[#001F3F] text-white font-black py-4 rounded-2xl shadow-xl hover:bg-black transition-all text-sm group flex items-center justify-center gap-3">
                  تثبيت الملف الخارق <ChevronLeft size={20} className="group-hover:-translate-x-1 transition-transform" />
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

