import React, { useState, useEffect, useCallback } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, X, Trophy, Bell
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { AppUser, AppState, Category, Person, TrainingSession, Match, AppNotification } from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

// Initialize Supabase client
const supabaseUrl = (window as any).process?.env?.SUPABASE_URL || '';
const supabaseAnonKey = (window as any).process?.env?.SUPABASE_ANON_KEY || '';
const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkaramah_pro_final_v1');
    const defaultCategories: Category[] = ['رجال', 'شباب', 'ناشئين', 'أشبال'];
    const defaultUsers: AppUser[] = [
      { id: 'admin-main', username: 'IZZAT', role: 'مدير', password: 'KSC@2026' },
    ];

    if (saved) return JSON.parse(saved);

    return {
      people: [], attendance: [], sessions: [], matches: [],
      categories: defaultCategories, users: defaultUsers,
      currentUser: null, notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // Supabase Sync Logic
  const fetchData = useCallback(async () => {
    if (!state.currentUser || !supabaseUrl) return;
    setIsSyncing(true);
    try {
      const [
        { data: cats }, { data: ppl }, { data: sess }, { data: mtch }, { data: attn }
      ] = await Promise.all([
        supabase.from('categories').select('*'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
      ]);

      setState(prev => ({
        ...prev,
        categories: cats?.map(c => c.name) || prev.categories,
        people: ppl || prev.people,
        sessions: sess || prev.sessions,
        matches: mtch || prev.matches,
        attendance: attn || prev.attendance
      }));
    } catch (error) {
      console.error("Error fetching from Supabase:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  useEffect(() => {
    if (state.currentUser) {
      fetchData();
    }
  }, [state.currentUser, fetchData]);

  // Sync Categories specifically as requested
  useEffect(() => {
    const syncCategories = async () => {
      if (!supabaseUrl) return;
      // Simple logic: delete all and re-insert for categories to match local array
      // In production, a more sophisticated diffing or specific upsert is better
      await supabase.from('categories').delete().neq('id', '00000000-0000-0000-0000-000000000000');
      const insertData = state.categories.map(name => ({ name }));
      await supabase.from('categories').insert(insertData);
    };
    if (state.currentUser?.role === 'مدير') {
      syncCategories();
    }
    localStorage.setItem('alkaramah_pro_final_v1', JSON.stringify(state));
  }, [state.categories, state.currentUser]);

  // Sync other state changes to LocalStorage
  useEffect(() => {
    if (state.currentUser) {
      localStorage.setItem('alkaramah_pro_final_v1', JSON.stringify(state));
    }
  }, [state]);

  const addLog = (message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newLog: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message,
      details,
      type,
      timestamp: Date.now(),
      isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newLog, ...prev.notifications].slice(0, 50)
    }));
  };

  const navigateToMatch = (id: string) => {
    setSelectedMatchId(id);
    setActiveTab('matches');
  };

  const navigateToSession = (id: string) => {
    setSelectedSessionId(id);
    setActiveTab('attendance');
  };

  if (!state.currentUser) {
    return <Login onLogin={(u) => setState(p => ({ ...p, currentUser: u }))} state={state} />;
  }

  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الكوادر', icon: Users },
    { id: 'attendance', label: 'سجل الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التمارين', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings, adminOnly: true },
  ];

  return (
    <div className="flex h-screen bg-[#F0F4F8] font-['Tajawal'] text-right overflow-hidden" dir="rtl">
      {/* Sidebar - Cleaned and font shrunk */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transition-transform md:relative md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} flex flex-col no-print`}>
        <div className="p-6 flex flex-col items-center border-b border-white/10">
          <ClubLogo size={60} />
          <h1 className="mt-3 font-black text-lg">نادي الكرامة</h1>
          <p className="text-[9px] text-orange-400 font-black tracking-widest uppercase">Football Office</p>
        </div>

        <nav className="flex-1 px-3 py-4 space-y-1.5 overflow-y-auto custom-scrollbar">
          {menuItems.map(item => {
            if (item.adminOnly && state.currentUser?.role !== 'مدير') return null;
            const Icon = item.icon;
            return (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all font-black text-xs ${activeTab === item.id ? 'bg-orange-600 shadow-lg shadow-orange-900/40' : 'hover:bg-white/5 text-blue-100'}`}>
                <Icon size={18} /> <span>{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-white/10">
          <button onClick={() => setState(p => ({ ...p, currentUser: null }))} className="w-full flex items-center gap-3 p-3 rounded-xl text-red-400 hover:bg-red-900/20 font-black text-xs transition-colors">
            <LogOut size={18} /> خروج
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="bg-white border-b px-6 py-3 flex items-center justify-between no-print z-40 shadow-sm">
          <div className="flex items-center gap-3">
            <button onClick={() => setSidebarOpen(true)} className="md:hidden p-2 hover:bg-slate-100 rounded-xl"><Menu size={20}/></button>
            <h2 className="text-lg font-black text-slate-800">{menuItems.find(m => m.id === activeTab)?.label}</h2>
            {isSyncing && <span className="text-[9px] font-black text-blue-500 animate-pulse mr-4">جاري المزامنة...</span>}
          </div>

          <div className="flex items-center gap-3">
             {state.currentUser.role === 'مدير' && (
               <button onClick={() => setShowNotifications(!showNotifications)} className="relative p-2 bg-[#F0F4F8] text-[#001F3F] rounded-lg border border-slate-200">
                 <Bell size={18} />
                 {state.notifications.filter(n => !n.isRead).length > 0 && (
                   <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-orange-600 border border-white rounded-full"></span>
                 )}
               </button>
             )}

             <div className="flex items-center gap-2 pr-3 border-r border-slate-100">
               <div className="text-left hidden sm:block">
                 <p className="font-black text-[10px] text-slate-800">{state.currentUser.username}</p>
                 <p className="text-[8px] text-blue-600 font-black uppercase">{state.currentUser.role}</p>
               </div>
               <div className="w-8 h-8 bg-[#001F3F] text-white rounded-lg flex items-center justify-center font-black text-xs">
                 {state.currentUser.username.charAt(0).toUpperCase()}
               </div>
             </div>
          </div>
        </header>

        {showNotifications && state.currentUser.role === 'مدير' && (
          <div className="absolute left-6 top-14 w-80 bg-white rounded-3xl shadow-2xl border border-slate-100 z-[60] overflow-hidden">
            <div className="p-4 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="font-black text-[#001F3F] text-xs">سجل النشاطات</h3>
              <button onClick={() => setState(p => ({...p, notifications: []}))} className="text-[9px] font-black text-red-500">حذف</button>
            </div>
            <div className="max-h-80 overflow-y-auto custom-scrollbar">
              {state.notifications.length > 0 ? state.notifications.map(n => (
                <div key={n.id} className="p-3 border-b border-slate-50 flex gap-3">
                  <div className={`w-1.5 h-1.5 rounded-full mt-1 ${n.type === 'success' ? 'bg-emerald-500' : 'bg-blue-500'}`}></div>
                  <div>
                    <p className="text-[10px] font-black text-slate-800">{n.message}</p>
                    <p className="text-[8px] text-slate-400 mt-1">{new Date(n.timestamp).toLocaleTimeString()}</p>
                  </div>
                </div>
              )) : <div className="p-6 text-center text-slate-400 text-xs italic">فارغ</div>}
            </div>
          </div>
        )}

        <section className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar bg-slate-50/50">
          <div className="max-w-6xl mx-auto pb-16">
            {activeTab === 'dashboard' && <Dashboard state={state} onMatchClick={navigateToMatch} onSessionClick={navigateToSession} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={setState} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={setState} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <footer className="bg-white/95 backdrop-blur-md border-t py-2 px-6 flex justify-between items-center no-print z-40">
          <p className="text-[8px] font-black text-slate-500">نظام إدارة مكتب كرة القدم - نادي الكرامة الرياضي</p>
          <p className="text-[8px] font-black text-[#001F3F] border-r-2 border-orange-500 pr-2">By: Izzat Amer Al-Shikha</p>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  MapPin, Hash, UserCheck, ChevronLeft, FolderPlus, Filter, Settings2
} from 'lucide-react';
import { AppState, Person, Role, Category } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isManageCatsOpen, setIsManageCatsOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return '--';
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    if (formData.role === 'لاعب' && formData.number) {
      const isDuplicate = state.people.some(p => 
        p.id !== editingId && 
        p.role === 'لاعب' && 
        p.category === formData.category && 
        p.number === formData.number
      );
      if (isDuplicate) {
        alert('خطأ: رقم القميص محجوز مسبقاً في هذه الفئة.');
        return;
      }
    }

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        ...(formData as Person)
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('الفئة موجودة مسبقاً.');
    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة', `تم إضافة فئة: ${newCatName.trim()}`, 'success');
    setNewCatName('');
  };

  const handleDeleteCategory = (cat: string) => {
    if (confirm(`هل أنت متأكد من حذف فئة "${cat}"؟ سيتم إلغاء ربط اللاعبين بها.`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
      addLog?.('حذف فئة', `تم حذف فئة: ${cat}`, 'warning');
    }
  };

  const filtered = state.people.filter(p => {
    const matchCat = localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter;
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                      (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  // كلاس موحد لضمان خط غامق جداً وأسود (Strictly Bold Black) في الحقول
  const fieldClass = "w-full bg-white border-2 border-slate-400 rounded-xl py-2 px-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-blue-900/10 focus:border-blue-900 transition-all placeholder:text-slate-500";

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      {/* التحكم الداخلي: فلتر، بحث، وإدارة الفئات */}
      <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 no-print space-y-3">
        <div className="flex flex-col lg:flex-row gap-3 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500" size={16} />
            <input 
              type="text" 
              placeholder="البحث بالاسم أو الرقم..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
              className={`${fieldClass} pr-10 text-xs`} 
            />
          </div>

          <div className="flex items-center gap-2 w-full lg:w-auto">
            <div className="relative">
              <Filter className="absolute right-2 top-1/2 -translate-y-1/2 text-[#001F3F]" size={14} />
              <select 
                value={localCategoryFilter}
                onChange={e => setLocalCategoryFilter(e.target.value)}
                className="bg-slate-100 border-2 border-slate-300 rounded-lg py-2 pr-8 pl-3 font-black text-[10px] text-[#001F3F] outline-none focus:border-[#001F3F] appearance-none cursor-pointer"
              >
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <button 
              onClick={() => setIsManageCatsOpen(true)}
              className="bg-orange-50 text-orange-700 px-3 py-2 rounded-lg font-black text-[10px] flex items-center gap-1.5 hover:bg-orange-100 transition-all border border-orange-200"
            >
              <Settings2 size={14} /> الفئات
            </button>

            <button 
              onClick={() => { 
                setEditingId(null); 
                setFormData({ role: 'لاعب', category: localCategoryFilter !== 'الكل' ? localCategoryFilter : (state.categories[0] || ''), joinDate: new Date().toISOString().split('T')[0] }); 
                setIsModalOpen(true); 
              }} 
              className="bg-[#001F3F] text-white px-4 py-2 rounded-lg font-black text-[10px] flex items-center gap-1.5 hover:bg-black transition-all shadow-md"
            >
              <UserPlus size={16} /> إضافة عضو
            </button>
          </div>
        </div>
      </div>

      {/* Grid Members */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filtered.map(person => (
          <div key={person.id} className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 group relative transition-all hover:shadow-md border-b-2 hover:border-blue-900">
             <div className="flex justify-between items-start mb-2">
               <div className="w-10 h-10 bg-blue-50 border border-blue-100 rounded-lg flex items-center justify-center font-black text-blue-900 text-sm shadow-inner">
                 {person.name.charAt(0).toUpperCase()}
               </div>
               <div className="flex flex-col items-end">
                  <span className={`text-[7px] font-black px-2 py-0.5 rounded-full uppercase ${person.role === 'لاعب' ? 'bg-orange-500 text-white' : 'bg-[#001F3F] text-white'}`}>
                    {person.role}
                  </span>
                  <span className="text-[7px] font-black text-slate-400 mt-1">{person.category}</span>
               </div>
             </div>

             <div className="space-y-0.5">
               <h4 className="font-black text-xs text-slate-900 leading-tight group-hover:text-blue-900 transition-colors">{person.name}</h4>
               <div className="flex flex-wrap gap-2 pt-0.5 text-[8px] font-black text-slate-500">
                 <span className="flex items-center gap-1"><MapPin size={10} className="text-orange-500" /> {person.birthPlace}</span>
                 <span className="flex items-center gap-1"><Calendar size={10} className="text-blue-900" /> {calculateAge(person.birthDate)} سنة</span>
               </div>
             </div>

             <div className="mt-4 pt-3 border-t border-slate-50 flex justify-between items-center">
                <div className="flex items-center gap-1.5">
                   <div className="bg-[#001F3F] text-white w-6 h-6 rounded flex items-center justify-center font-black text-[9px]">#{person.number || '00'}</div>
                   <button onClick={() => onOpenReport?.(person)} className="text-[#001F3F] text-[8px] font-black hover:underline">الملف</button>
                </div>
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-all">
                  <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-400 hover:bg-blue-900 hover:text-white rounded transition-all"><Plus size={12}/></button>
                  <button onClick={() => { if(confirm(`حذف ${person.name}؟`)) { setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); addLog?.('حذف عضو', `تم مسح ملف: ${person.name}`, 'error'); } }} className="p-1.5 bg-red-50 text-red-300 hover:bg-red-600 hover:text-white rounded transition-all"><Trash2 size={12}/></button>
                </div>
             </div>
          </div>
        ))}
      </div>

      {/* إدارة الفئات */}
      {isManageCatsOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/80 backdrop-blur-md flex items-center justify-center z-[300] p-4 no-print">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-4 border-b bg-slate-50 flex justify-between items-center">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><Layers size={16} className="text-orange-500" /> إدارة الفئات</h3>
              <button onClick={() => setIsManageCatsOpen(false)} className="bg-slate-200 p-1.5 rounded-lg hover:rotate-90 transition-transform"><X size={16} /></button>
            </div>
