import React, { useState } from 'react';
import { Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, ChevronLeft, Trash2, Target, AlertTriangle } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter 
  });

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'غير معروف',
      location: formData.location || 'غير محدد',
      date: formData.date || '',
      time: formData.time || '16:00',
      category: formData.category || state.categories[0],
      advancePayment: formData.advancePayment || '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({name:'', number:''}), subs: [], staff: [], captain: '' }
    };
    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة قادمة', `تمت جدولة مواجهة ضد ${newMatch.opponent} بنجاح.`, 'success');
    setIsAddOpen(false);
  };

  const getAvailablePlayers = (currentMatch: Match, currentSelectedName?: string) => {
    const selectedNames = new Set([
      ...currentMatch.lineup.starters.map(s => s.name),
      ...currentMatch.lineup.subs.map(s => s.name)
    ]);
    if (currentSelectedName) selectedNames.delete(currentSelectedName);

    return state.people.filter(p => 
      p.category === currentMatch.category && 
      p.role === 'لاعب' && 
      !selectedNames.has(p.name)
    );
  };

  const filteredMatches = state.matches.filter(m => (globalFilter === 'الكل' || m.category === globalFilter));

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      player: '',
      minute: '',
    };
    setActiveMatch({
      ...activeMatch,
      events: [...activeMatch.events, newEvent]
    });
  };

  const removeEvent = (id: string) => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.filter(e => e.id !== id)
    });
  };

  const updateEvent = (id: string, updates: Partial<MatchEvent>) => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.map(e => e.id === id ? { ...e, ...updates } : e)
    });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-1.5 h-full bg-orange-500"></div>
        <div>
          <h3 className="text-lg font-black text-slate-800">مركز إدارة المواجهات</h3>
          <p className="text-[10px] font-black text-blue-600 mt-1 uppercase tracking-widest">Al-Karamah Pro HUB</p>
        </div>
        <button onClick={() => setIsAddOpen(true)} className="bg-orange-600 text-white px-6 py-2.5 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg shadow-orange-100 transition-all hover:bg-black group mt-4 md:mt-0">
          <Plus size={18} className="group-hover:rotate-90 transition-transform" /> جدولة مواجهة جديدة
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {filteredMatches.map(m => (
          <div key={m.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 relative group overflow-hidden border-b-[8px] border-slate-50 hover:border-[#001F3F] transition-all">
             <div className="flex justify-between items-center mb-6">
                <span className="text-[9px] font-black bg-[#001F3F] text-white px-3 py-1.5 rounded-lg uppercase tracking-wider">{m.category} | {m.matchType}</span>
                <span className={`text-[9px] font-black px-3 py-1 rounded-lg ${m.isCompleted ? 'bg-emerald-50 text-emerald-600' : 'bg-orange-50 text-orange-600 animate-pulse'}`}>
                  {m.isCompleted ? 'منتهية' : 'قادمة'}
                </span>
             </div>

             <div className="flex items-center justify-between text-center gap-4 py-4">
                <div className="flex-1">
                  <div className="w-12 h-12 bg-[#001F3F] text-white rounded-xl mx-auto flex items-center justify-center font-black text-lg mb-2 shadow-lg">K</div>
                  <p className="font-black text-xs text-slate-800">الكرامة</p>
                </div>

                <div className="flex flex-col items-center">
