                                      <select value={e.type} onChange={opt => updateEvent(e.id, {type: opt.target.value as any})} className="bg-white border rounded p-1 font-black text-[9px] outline-none">
                                         <option value="goal">هدف</option>
                                         <option value="assist">أسيست</option>
