                                      <select value={e.player} onChange={opt => updateEvent(e.id, {player: opt.target.value})} className="flex-1 bg-white border rounded p-1 font-black text-[10px] outline-none">
                                         <option value="">اختر اللاعب</option>
                                         {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(p => p.name).map(p => <option key={p.name} value={p.name}>{p.name}</option>)}
                                      </select>
                                      <input type="text" placeholder="دقيقة" value={e.minute} onChange={opt => updateEvent(e.id, {minute: opt.target.value})} className="w-12 bg-white border rounded p-1 font-black text-[10px] text-center outline-none" />
                                      <button onClick={() => removeEvent(e.id)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                                   </div>
                                ))}
                             </div>
                          </div>

                          {/* سجل البطاقات */}
                          <div className="space-y-4">
                             <div className="flex justify-between items-center">
                                <h4 className="text-xs font-black text-orange-600 flex items-center gap-2 border-r-4 border-red-600 pr-3">
