                             <div className="space-y-2">
                                {activeMatch.events.filter(e => e.type === 'yellow' || e.type === 'red').map(e => (
                                   <div key={e.id} className="flex gap-2 items-center bg-orange-50/50 p-2 rounded-xl border border-orange-100">
                                      <select value={e.type} onChange={opt => updateEvent(e.id, {type: opt.target.value as any})} className="bg-white border rounded p-1 font-black text-[9px] outline-none">
                                         <option value="yellow">صفراء</option>
                                         <option value="red">حمراء</option>
                                      </select>
                                      <select value={e.player} onChange={opt => updateEvent(e.id, {player: opt.target.value})} className="flex-1 bg-white border rounded p-1 font-black text-[10px] outline-none">
                                         <option value="">اختر اللاعب</option>
                                         {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(p => p.name).map(p => <option key={p.name} value={p.name}>{p.name}</option>)}
