                         <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1.5">
                               <label className="text-[9px] font-black text-slate-400 uppercase mr-2">الكرامة</label>
                               <input type="number" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} 
                                className="w-full bg-[#001F3F] text-white border-none rounded-2xl p-4 text-3xl font-black text-center shadow-lg" />
                            </div>
                            <div className="space-y-1.5">
                               <label className="text-[9px] font-black text-slate-400 uppercase mr-2">الخصم</label>
                               <input type="number" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} 
                                className="w-full bg-slate-100 border-none rounded-2xl p-4 text-3xl font-black text-center shadow-inner" />
                            </div>
                         </div>
                       </div>
                    </div>
                 </div>

                 <div className="flex flex-col md:flex-row gap-4 pt-12 border-t-4 border-slate-50">
                    <button onClick={() => setActiveMatch(null)} className="flex-1 bg-slate-100 text-slate-600 font-black py-4 rounded-xl text-xs hover:bg-slate-200 transition-all">إلغاء</button>
                    <button onClick={() => {
                      const finalMatch = {...activeMatch, isCompleted: true};
                      setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? finalMatch : m) }));
                      addLog?.('تحديث نتيجة مباراة', `تم اعتماد نتيجة مباراة ${activeMatch.opponent}: (${activeMatch.ourScore}-${activeMatch.opponentScore})`, 'success');
                      setActiveMatch(null);
                    }} className="flex-[2] bg-[#001F3F] text-white font-black py-4 rounded-xl shadow-lg hover:bg-black transition-all text-sm group">
                      تثبيت وحفظ التقرير النهائي
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

