import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  MapPin, Hash, UserCheck, ChevronLeft, FolderPlus, Filter, Settings2, BookOpen, Globe
} from 'lucide-react';
import { AppState, Person, Role, Category } from '../types';

interface SquadManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isManageCatsOpen, setIsManageCatsOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return '--';
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: Math.random().toString(36).substr(2, 9),
        ...(formData as Person)
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const filtered = state.people.filter(p => {
    const matchCat = localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter;
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                      (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-blue-900/10 focus:border-blue-900 transition-all placeholder:text-slate-600";
  const labelClass = "text-[9px] font-black text-slate-900 mr-2 uppercase block mb-1";

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-3.5 rounded-2xl shadow-sm border border-slate-300 no-print space-y-3">
        <div className="flex flex-col lg:flex-row gap-3 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-900" size={15} />
            <input 
              type="text" 
              placeholder="البحث بالاسم أو الرقم..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
              className={`${fieldClass} pr-9 text-[10px] h-10`} 
            />
          </div>

          <div className="flex items-center gap-2 w-full lg:w-auto">
            <select 
              value={localCategoryFilter}
              onChange={e => setLocalCategoryFilter(e.target.value)}
              className="bg-slate-100 border-2 border-slate-900 rounded-lg py-1.5 pr-3 pl-3 font-black text-[9px] text-slate-900 outline-none h-10"
            >
              <option value="الكل">جميع الفئات</option>
              {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>

            <button 
              onClick={() => { 
                setEditingId(null); 
                setFormData({ role: 'لاعب', category: localCategoryFilter !== 'الكل' ? localCategoryFilter : (state.categories[0] || ''), joinDate: new Date().toISOString().split('T')[0] }); 
                setIsModalOpen(true); 
              }} 
              className="bg-[#001F3F] text-white px-4 h-10 rounded-lg font-black text-[9px] flex items-center gap-1.5 hover:bg-black transition-all shadow-md"
            >
              <UserPlus size={14} /> إضافة عضو
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
        {filtered.map(person => (
          <div key={person.id} className="bg-white p-3.5 rounded-2xl shadow-sm border border-slate-900 group relative transition-all hover:shadow-md border-b-4 hover:border-orange-600">
             <div className="flex justify-between items-start mb-2">
               <div className="w-9 h-9 bg-slate-100 border border-slate-900 rounded-lg flex items-center justify-center font-black text-slate-900 text-xs shadow-inner">
                 {person.name.charAt(0).toUpperCase()}
               </div>
               <div className="flex flex-col items-end">
                  <span className={`text-[8px] font-black px-1.5 py-0.5 rounded-full uppercase ${person.role === 'لاعب' ? 'bg-orange-600 text-white' : 'bg-[#001F3F] text-white'}`}>
                    {person.role}
                  </span>
                  <span className="text-[9px] font-black text-slate-900 mt-0.5">{person.category}</span>
               </div>
             </div>

             <div className="space-y-0.5">
               <h4 className="font-black text-[12px] text-slate-900 leading-tight group-hover:text-blue-900 transition-colors">{person.name}</h4>
               <div className="flex flex-wrap gap-2 pt-1 text-[9px] font-black text-slate-900">
                 <span className="flex items-center gap-1"><MapPin size={10} className="text-orange-600" /> {person.birthPlace}</span>
                 <span className="flex items-center gap-1"><Calendar size={10} className="text-[#001F3F]" /> {calculateAge(person.birthDate)} سنة</span>
               </div>
             </div>

             <div className="mt-3 pt-2.5 border-t border-slate-200 flex justify-between items-center">
                <div className="flex items-center gap-1.5">
                   <div className="bg-[#001F3F] text-white w-6 h-6 rounded flex items-center justify-center font-black text-[10px]">#{person.number || '00'}</div>
                   <button onClick={() => onOpenReport?.(person)} className="text-slate-900 text-[10px] font-black hover:text-orange-600 underline">الملف الفني</button>
                </div>
                <div className="flex gap-1">
                  <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-1.5 bg-slate-100 text-slate-900 hover:bg-blue-900 hover:text-white rounded border border-slate-900 transition-all"><Plus size={12}/></button>
                </div>
             </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[200] p-4 no-print">
          <div className="bg-white rounded-[2rem] w-full max-w-4xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border-4 border-slate-900 flex flex-col h-[85vh]">
            <div className="p-4 border-b bg-slate-100 flex justify-between items-center shrink-0">
              <h3 className="text-sm font-black text-slate-900">{editingId ? 'تعديل بيانات العضو' : 'تسجيل عضو جديد'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-300 p-2 rounded-xl text-slate-900 hover:text-red-600 transition-all"><X size={18} /></button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-8">
              <div className="space-y-6">
                <h4 className="text-[11px] font-black text-blue-900 flex items-center gap-2 border-r-4 border-slate-900 pr-3 uppercase">البيانات الشخصية</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div className="space-y-1 col-span-1 md:col-span-2">
                    <label className={labelClass}>الاسم الثنائي</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>اسم الأب</label>
                    <input type="text" value={formData.fatherName || ''} onChange={e => setFormData({...formData, fatherName: e.target.value})} className={fieldClass} />
