import React, { useState } from 'react';
import { Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, ChevronLeft, Trash2, Target, AlertTriangle } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter 
  });

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'غير معروف',
      location: formData.location || 'غير محدد',
      date: formData.date || '',
      time: formData.time || '16:00',
      category: formData.category || state.categories[0],
      advancePayment: formData.advancePayment || '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({name:'', number:''}), subs: [], staff: [], captain: '' }
    };
    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة قادمة', `تمت جدولة مواجهة ضد ${newMatch.opponent} بنجاح.`, 'success');
    setIsAddOpen(false);
  };

  const filteredMatches = state.matches.filter(m => (globalFilter === 'الكل' || m.category === globalFilter));

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      player: '',
      minute: '',
    };
    setActiveMatch({
      ...activeMatch,
      events: [...activeMatch.events, newEvent]
    });
  };

  const removeEvent = (id: string) => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.filter(e => e.id !== id)
    });
  };

  const updateEvent = (id: string, updates: Partial<MatchEvent>) => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.map(e => e.id === id ? { ...e, ...updates } : e)
    });
  };

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-slate-900 outline-none";

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-900 flex flex-col md:flex-row justify-between items-center no-print relative overflow-hidden">
        <div className="absolute top-0 right-0 w-2 h-full bg-orange-600"></div>
        <div>
          <h3 className="text-md font-black text-slate-900">مركز إدارة المواجهات المباشرة</h3>
          <p className="text-[9px] font-black text-blue-900 mt-1 uppercase">Al-Karamah Football System</p>
        </div>
        <button onClick={() => setIsAddOpen(true)} className="bg-orange-600 text-white px-5 py-2 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg hover:bg-black transition-all mt-3 md:mt-0">
          <Plus size={16} /> جدولة مواجهة جديدة
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        {filteredMatches.map(m => (
          <div key={m.id} className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-[6px] border-[#001F3F] transition-all">
             <div className="flex justify-between items-center mb-4">
                <span className="text-[9px] font-black bg-[#001F3F] text-white px-2.5 py-1 rounded uppercase">{m.category} | {m.matchType}</span>
                <span className={`text-[9px] font-black px-2.5 py-1 rounded border ${m.isCompleted ? 'bg-emerald-100 text-emerald-900 border-emerald-900' : 'bg-orange-100 text-orange-900 border-orange-900 animate-pulse'}`}>
                  {m.isCompleted ? 'انتهت' : 'قادمة'}
                </span>
             </div>

             <div className="flex items-center justify-between text-center gap-2 py-2">
                <div className="flex-1">
                  <div className="w-10 h-10 bg-[#001F3F] text-white rounded-lg mx-auto flex items-center justify-center font-black text-lg mb-1 shadow-md">K</div>
                  <p className="font-black text-[10px] text-slate-900">الكرامة</p>
                </div>

                <div className="bg-slate-100 px-4 py-3 rounded-xl flex items-center justify-center font-black text-xl border border-slate-900 text-slate-900 shadow-inner">
                  {m.isCompleted ? `${m.ourScore}:${m.opponentScore}` : 'VS'}
                </div>

                <div className="flex-1">
                  <div className="w-10 h-10 bg-white border border-slate-900 text-slate-900 rounded-lg mx-auto flex items-center justify-center font-black text-lg mb-1">?</div>
                  <p className="font-black text-[10px] text-slate-900">{m.opponent}</p>
                </div>
             </div>

             <div className="mt-5 pt-4 border-t border-slate-200 flex flex-col xl:flex-row justify-between items-center gap-3">
                <div className="space-y-1.5 w-full xl:w-auto">
                  <div className="flex items-center gap-2 text-[10px] font-black text-slate-900"><Calendar size={12} className="text-[#001F3F]"/> {m.date} | {m.time}</div>
                  <div className="flex items-center gap-2 text-[10px] font-black text-slate-900"><MapPin size={12} className="text-orange-600"/> {m.location}</div>
                </div>
                <button onClick={() => setActiveMatch(m)} className="w-full xl:w-auto bg-[#001F3F] text-white px-4 py-2 rounded-lg text-[10px] font-black hover:bg-orange-600 transition-all shadow-md">
                  إدارة التكتيك والتقرير
                </button>
             </div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-md flex items-center justify-center z-[300] p-4 overflow-y-auto no-print">
           <div className="bg-white rounded-[2.5rem] w-full max-w-5xl shadow-2xl border-4 border-slate-900 flex flex-col h-[90vh]">
              <div className="p-6 border-b bg-slate-100 flex justify-between items-center shrink-0">
                 <div className="flex items-center gap-3">
                    <Trophy size={20} className="text-orange-600" />
                    <h3 className="text-sm font-black text-slate-900">الكرامة × {activeMatch.opponent}</h3>
                 </div>
                 <button onClick={() => setActiveMatch(null)} className="p-2 bg-slate-300 rounded-lg text-slate-900 hover:text-red-600 transition-all"><X size={20}/></button>
              </div>

              <div className="p-8 overflow-y-auto custom-scrollbar space-y-10">
                 <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                    <div className="space-y-4">
                       <h4 className="text-[11px] font-black text-slate-900 border-r-4 border-orange-600 pr-3 uppercase">التشكيلة المختارة</h4>
                       <div className="space-y-2.5">
                         {activeMatch.lineup.starters.map((s, i) => (
                           <div key={i} className="flex gap-2 items-center">
                             <span className="w-7 h-7 bg-slate-200 rounded border border-slate-900 flex items-center justify-center text-[10px] font-black text-slate-900">{i+1}</span>
                             <div className="flex-1">
                                <select 
                                  value={s.name} 
                                  onChange={e => {
                                    const p = state.people.find(x => x.name === e.target.value);
                                    const newList = [...activeMatch.lineup.starters];
                                    newList[i] = { name: p?.name || '', number: p?.number?.toString() || '' };
                                    setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, starters: newList}});
                                  }}
                                  className="w-full bg-white border border-slate-900 rounded-lg py-1.5 px-3 text-[10px] font-black text-slate-900 outline-none"
                                >
                                  <option value="">اختر لاعب...</option>
                                  {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => <option key={p.id} value={p.name}>{p.name} (#{p.number})</option>)}
                                </select>
                             </div>
                           </div>
                         ))}
                       </div>
                    </div>

                    <div className="space-y-8">
                       <div className="bg-emerald-50 p-5 rounded-2xl border-2 border-emerald-900">
                          <h4 className="text-[11px] font-black text-emerald-900 flex items-center gap-2 mb-4 border-r-4 border-blue-900 pr-2">
                             <Target size={16} /> سجل الأهداف (Goals)
                          </h4>
                          <div className="space-y-2">
                             {activeMatch.events.filter(e => e.type === 'goal' || e.type === 'assist').map(e => (
                                <div key={e.id} className="flex gap-2 items-center bg-white p-2 rounded-lg border border-slate-900">
                                   <select value={e.type} onChange={opt => updateEvent(e.id, {type: opt.target.value as any})} className="bg-slate-100 border rounded p-1 font-black text-[10px] text-slate-900">
                                      <option value="goal">هدف</option><option value="assist">أسيست</option>
                                   </select>
                                   <select value={e.player} onChange={opt => updateEvent(e.id, {player: opt.target.value})} className="flex-1 bg-slate-100 border rounded p-1 font-black text-[10px] text-slate-900">
                                      <option value="">اختر اللاعب</option>
                                      {[...activeMatch.lineup.starters].filter(p => p.name).map(p => <option key={p.name} value={p.name}>{p.name}</option>)}
                                   </select>
                                   <button onClick={() => removeEvent(e.id)} className="text-red-600"><Trash2 size={14}/></button>
                                </div>
                             ))}
                             <button onClick={() => addEvent('goal')} className="w-full border-2 border-dashed border-emerald-900 py-2 rounded-lg text-emerald-900 font-black text-[10px] hover:bg-emerald-100">+ إضافة حدث هجومي</button>
                          </div>
                       </div>

                       <div className="bg-red-50 p-5 rounded-2xl border-2 border-red-900">
                          <h4 className="text-[11px] font-black text-red-900 flex items-center gap-2 mb-4 border-r-4 border-slate-900 pr-2">
                             <AlertTriangle size={16} /> سجل المخالفات (Cards)
                          </h4>
                          <div className="space-y-2">
                             {activeMatch.events.filter(e => e.type === 'yellow' || e.type === 'red').map(e => (
                                <div key={e.id} className="flex gap-2 items-center bg-white p-2 rounded-lg border border-slate-900">
                                   <select value={e.type} onChange={opt => updateEvent(e.id, {type: opt.target.value as any})} className="bg-slate-100 border rounded p-1 font-black text-[10px] text-slate-900">
                                      <option value="yellow">صفراء</option><option value="red">حمراء</option>
                                   </select>
                                   <select value={e.player} onChange={opt => updateEvent(e.id, {player: opt.target.value})} className="flex-1 bg-slate-100 border rounded p-1 font-black text-[10px] text-slate-900">
                                      <option value="">اختر اللاعب</option>
                                      {[...activeMatch.lineup.starters].filter(p => p.name).map(p => <option key={p.name} value={p.name}>{p.name}</option>)}
                                   </select>
                                   <button onClick={() => removeEvent(e.id)} className="text-red-600"><Trash2 size={14}/></button>
                                </div>
                             ))}
                             <button onClick={() => addEvent('yellow')} className="w-full border-2 border-dashed border-red-900 py-2 rounded-lg text-red-900 font-black text-[10px] hover:bg-red-100">+ إضافة بطاقة ملونة</button>
                          </div>
                       </div>

                       <div className="bg-slate-100 p-5 rounded-2xl border-2 border-slate-900">
                         <h4 className="text-[11px] font-black text-slate-900 mb-3 uppercase tracking-wider">النتيجة النهائية (Score)</h4>
                         <div className="flex items-center gap-4">
                            <div className="flex-1 space-y-1">
                               <label className="text-[8px] font-black text-slate-900 block uppercase">الكرامة</label>
                               <input type="number" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} 
                                className="w-full bg-[#001F3F] text-white border-none rounded-xl p-3 text-2xl font-black text-center" />
                            </div>
                            <span className="font-black text-2xl text-slate-900">:</span>
                            <div className="flex-1 space-y-1">
                               <label className="text-[8px] font-black text-slate-900 block uppercase">الخصم</label>
                               <input type="number" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} 
                                className="w-full bg-white border-2 border-slate-900 rounded-xl p-3 text-2xl font-black text-center text-slate-900" />
                            </div>
                         </div>
                       </div>
                    </div>
                 </div>

                 <div className="flex gap-4 pt-10">
                    <button onClick={() => setActiveMatch(null)} className="flex-1 bg-slate-200 text-slate-900 font-black py-4 rounded-xl text-[11px] border border-slate-900">إلغاء</button>
                    <button onClick={() => {
                      const finalMatch = {...activeMatch, isCompleted: true};
                      setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? finalMatch : m) }));
                      addLog?.('تحديث مباراة', `تم اعتماد نتيجة: الكرامة ${activeMatch.ourScore} - ${activeMatch.opponentScore} ${activeMatch.opponent}`, 'success');
                      setActiveMatch(null);
                    }} className="flex-[2] bg-[#001F3F] text-white font-black py-4 rounded-xl shadow-lg hover:bg-black transition-all text-[11px] uppercase">
                      اعتماد وحفظ تقرير المباراة
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

