                <div className="bg-slate-100 px-4 py-3 rounded-xl flex items-center justify-center font-black text-xl border-2 border-slate-900 text-slate-900 shadow-inner">
                  {m.isCompleted ? `${m.ourScore}:${m.opponentScore}` : 'VS'}
