               <div className="flex gap-4 mt-4">
                 <button type="button" onClick={() => setIsAddOpen(false)} className="flex-1 bg-slate-200 text-slate-900 font-black py-3 rounded-xl border border-slate-900 uppercase text-[11px]">إلغاء</button>
                 <button type="submit" className="flex-[2] bg-[#001F3F] text-white font-black py-3 rounded-xl shadow-lg uppercase text-[11px] hover:bg-black transition-all">تثبيت المواجهة</button>
               </div>
             </form>
          </div>
