                             <button onClick={() => addEvent('yellow')} className="w-full border-2 border-dashed border-red-900 py-2 rounded-lg text-red-900 font-black text-[10px] hover:bg-red-100">+ إضافة بطاقة</button>
                          </div>
                       </div>

                       <div className="bg-slate-100 p-5 rounded-2xl border-2 border-slate-900">
                         <h4 className="text-[11px] font-black text-slate-900 mb-3 uppercase tracking-wider">النتيجة النهائية</h4>
