            >
              <option value="الكل">جميع الفئات</option>
              {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>

            <button 
              onClick={() => { 
                setEditingId(null); 
                setFormData({ role: 'لاعب', category: localCategoryFilter !== 'الكل' ? localCategoryFilter : (state.categories[0] || ''), joinDate: new Date().toISOString().split('T')[0] }); 
                setIsModalOpen(true); 
              }} 
              className="bg-[#001F3F] text-white px-5 h-11 rounded-xl font-black text-[11px] flex items-center gap-2 hover:bg-black transition-all shadow-lg shrink-0"
            >
              <UserPlus size={16} /> إضافة عضو
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filtered.map(person => (
          <div key={person.id} className="bg-white p-4 rounded-2xl shadow-sm border-2 border-slate-900 group relative transition-all hover:shadow-md border-b-[6px] hover:border-orange-600">
             <div className="flex justify-between items-start mb-3">
