                 <span className="flex items-center gap-1.5"><Calendar size={12} className="text-[#001F3F]" /> {calculateAge(person.birthDate)} سنة</span>
               </div>
             </div>

             <div className="mt-4 pt-3 border-t-2 border-slate-100 flex justify-between items-center">
                <div className="flex items-center gap-2">
                   <div className="bg-[#001F3F] text-white w-7 h-7 rounded-lg flex items-center justify-center font-black text-[12px]">#{person.number || '00'}</div>
                   <button onClick={() => onOpenReport?.(person)} className="text-slate-900 text-[11px] font-black hover:text-orange-600 underline underline-offset-4 decoration-2">الملف الفني</button>
                </div>
                <div className="flex gap-1.5">
                  <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-2 bg-slate-100 text-slate-900 hover:bg-[#001F3F] hover:text-white rounded-lg border-2 border-slate-900 transition-all"><Plus size={14}/></button>
                  <button onClick={() => { if(confirm(`هل أنت متأكد من حذف ${person.name}؟`)) { setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); addLog?.('حذف عضو', `تم مسح ملف: ${person.name}`, 'error'); } }} className="p-2 bg-red-50 text-red-600 hover:bg-red-600 hover:text-white rounded-lg border-2 border-red-900 transition-all"><Trash2 size={14}/></button>
                </div>
             </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
