          <div className="bg-white rounded-[2.5rem] w-full max-w-4xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border-[6px] border-slate-900 flex flex-col h-[90vh]">
            <div className="p-5 border-b-2 bg-slate-50 flex justify-between items-center shrink-0">
              <h3 className="text-md font-black text-slate-900 uppercase tracking-wider">{editingId ? 'تحديث بيانات الكادر' : 'تسجيل عضو جديد بالنادي'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2.5 rounded-xl text-slate-900 hover:text-red-600 transition-all hover:rotate-90"><X size={22} /></button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10">
              {/* القسم الأول: الشخصية */}
              <div className="space-y-6">
                <h4 className="text-[12px] font-black text-[#001F3F] flex items-center gap-2 border-r-4 border-orange-600 pr-3 uppercase">البيانات الشخصية والولادة</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div className="space-y-1 col-span-1 md:col-span-2">
                    <label className={labelClass}>الاسم الثنائي الكامل</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>اسم الأب</label>
                    <input type="text" value={formData.fatherName || ''} onChange={e => setFormData({...formData, fatherName: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>اسم الأم</label>
                    <input type="text" value={formData.motherName || ''} onChange={e => setFormData({...formData, motherName: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>تاريخ الميلاد</label>
                    <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({...formData, birthDate: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-orange-600 mr-2 uppercase block mb-1.5">العمر المحسوب (تلقائياً)</label>
                    <div className="w-full bg-orange-50 border-2 border-orange-600 rounded-xl py-2.5 px-4 font-black text-lg text-[#001F3F] flex items-center justify-center h-[46px] shadow-inner">
                      {calculateAge(formData.birthDate) !== null ? `${calculateAge(formData.birthDate)} سنة` : '--'}
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>مكان الولادة</label>
                    <input type="text" value={formData.birthPlace || ''} onChange={e => setFormData({...formData, birthPlace: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>القيد (الخانة)</label>
                    <input type="text" value={formData.khana || ''} onChange={e => setFormData({...formData, khana: e.target.value})} className={fieldClass} />
                  </div>
                </div>
              </div>

              {/* القسم الثاني: الأرقام والاتصال */}
              <div className="space-y-6">
                <h4 className="text-[12px] font-black text-orange-600 flex items-center gap-2 border-r-4 border-slate-900 pr-3 uppercase">الوثائق الثبوتية والاتصال والعنوان</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div className="space-y-1">
                    <label className={labelClass}>الرقم الوطني</label>
                    <input type="text" value={formData.nationalId || ''} onChange={e => setFormData({...formData, nationalId: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>الرقم الاتحادي</label>
                    <input type="text" value={formData.federalNumber || ''} onChange={e => setFormData({...formData, federalNumber: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>الرقم الدولي</label>
                    <input type="text" value={formData.internationalId || ''} onChange={e => setFormData({...formData, internationalId: e.target.value})} className={fieldClass} placeholder="ID الدولي..." />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>رقم الهاتف</label>
                    <input type="text" value={formData.phone || ''} onChange={e => setFormData({...formData, phone: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1 col-span-1 md:col-span-4">
                    <label className={labelClass}>العنوان الحالي بالتفصيل</label>
                    <div className="relative">
                      <Map className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="text" value={formData.address || ''} onChange={e => setFormData({...formData, address: e.target.value})} className={`${fieldClass} pr-10`} placeholder="المحافظة - المنطقة - الشارع - البناء..." />
                    </div>
                  </div>
                </div>
              </div>

              {/* القسم الثالث: الفنية والتعاقد */}
              <div className="space-y-6">
                <h4 className="text-[12px] font-black text-emerald-700 flex items-center gap-2 border-r-4 border-slate-900 pr-3 uppercase">الوضعية الفنية والتعاقدية</h4>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div className="space-y-1">
                    <label className={labelClass}>الدور / الصفة</label>
                    <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as Role})} className={fieldClass}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>الفئة الرياضية</label>
                    <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className={fieldClass}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>بداية العقد</label>
                    <input type="date" value={formData.contractStart || ''} onChange={e => setFormData({...formData, contractStart: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>نهاية العقد</label>
                    <input type="date" value={formData.contractEnd || ''} onChange={e => setFormData({...formData, contractEnd: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1 col-span-1 md:col-span-2">
                    <label className={labelClass}>القيمة المالية / الراتب</label>
                    <input type="text" value={formData.contractValue || ''} onChange={e => setFormData({...formData, contractValue: e.target.value})} className={fieldClass} placeholder="القيمة بالعقد..." />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[11px] font-black text-orange-600 block mb-1.5 uppercase tracking-tighter">رقم القميص</label>
                    <input type="number" value={formData.number || ''} onChange={e => setFormData({...formData, number: parseInt(e.target.value)})} className="w-full bg-[#001F3F] text-white border-none rounded-xl py-2 px-4 font-black text-2xl text-center outline-none h-14 shadow-2xl" />
                  </div>
                </div>
              </div>

              <div className="flex gap-4 pt-10 border-t-2 border-slate-200 pb-10">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-slate-200 text-slate-900 font-black py-4 rounded-xl text-[12px] border-2 border-slate-900 uppercase">إلغاء الأمر</button>
                <button type="submit" className="flex-[2] bg-[#001F3F] text-white font-black py-4 rounded-xl shadow-2xl hover:bg-black transition-all text-[12px] uppercase">
                  حفظ وتثبيت البيانات بالنظام
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState } from 'react';
import { Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, Printer, FileText } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showReport, setShowReport] = useState(false);
  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter 
  });

  const globalFilter = state.globalCategoryFilter;

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date || !formData.time || !formData.category) {
      alert("يرجى ملء جميع الحقول المطلوبة (الخصم، التاريخ، الوقت، الفئة)");
      return;
    }

    // التحقق من أن الوقت في المستقبل
    const selectedDateTime = new Date(`${formData.date}T${formData.time}`);
    const now = new Date();
    if (selectedDateTime <= now) {
      alert("خطأ صرامة: لا يمكن جدولة مباراة في وقت قديم. يرجى اختيار وقت مستقبلي.");
      return;
    }

    const newMatch: Match = {
      id: Math.random().toString(36).substr(2, 9),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      location: formData.location || 'غير محدد',
      date: formData.date,
      time: formData.time,
      category: formData.category,
      advancePayment: formData.advancePayment || '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({name:'', number:''}), subs: [], staff: [], captain: '' }
    };

    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة جديدة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const getPlayerNumber = (name: string) => {
    return state.people.find(p => p.name === name)?.number?.toString() || '';
  };

  const addSub = () => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        subs: [...activeMatch.lineup.subs, { name: '', number: '' }]
      }
    });
  };

  const removeSub = (index: number) => {
    if (!activeMatch) return;
    const newSubs = [...activeMatch.lineup.subs];
    newSubs.splice(index, 1);
    setActiveMatch({
      ...activeMatch,
      lineup: { ...activeMatch.lineup, subs: newSubs }
    });
  };

  const updateSub = (index: number, name: string) => {
    if (!activeMatch) return;
    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { name, number: getPlayerNumber(name) };
    setActiveMatch({
      ...activeMatch,
      lineup: { ...activeMatch.lineup, subs: newSubs }
    });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      player: '',
      minute: '',
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const updateEvent = (id: string, updates: Partial<MatchEvent>) => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.map(e => e.id === id ? { ...e, ...updates } : e)
    });
  };

  const removeEvent = (id: string) => {
    if (!activeMatch) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const filteredMatches = state.matches.filter(m => (globalFilter === 'الكل' || m.category === globalFilter));
  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1";

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-5 rounded-2xl shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print relative overflow-hidden">
        <div className="absolute top-0 right-0 w-2 h-full bg-orange-600"></div>
        <div>
          <h3 className="text-md font-black text-slate-900">مركز إدارة المواجهات المباشرة</h3>
          <p className="text-[9px] font-black text-[#001F3F] mt-1 uppercase tracking-widest">Al-Karamah Football System</p>
        </div>
        <button 
          onClick={() => {
            setFormData({ matchType: 'دوري', category: globalFilter === 'الكل' ? state.categories[0] : globalFilter });
            setIsAddOpen(true);
          }} 
          className="bg-orange-600 text-white px-5 py-2 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg hover:bg-black transition-all mt-3 md:mt-0"
        >
          <Plus size={16} /> جدولة مواجهة جديدة
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        {filteredMatches.map(m => (
          <div key={m.id} className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-[6px] border-[#001F3F] transition-all no-print">
             <div className="flex justify-between items-center mb-4">
                <span className="text-[9px] font-black bg-[#001F3F] text-white px-2.5 py-1 rounded-lg uppercase">{m.category} | {m.matchType}</span>
                <span className={`text-[9px] font-black px-2.5 py-1 rounded-lg border-2 ${m.isCompleted ? 'bg-emerald-100 text-emerald-900 border-emerald-900' : 'bg-orange-100 text-orange-900 border-orange-900 animate-pulse'}`}>
                  {m.isCompleted ? 'انتهت' : 'قادمة'}
                </span>
             </div>

             <div className="flex items-center justify-between text-center gap-2 py-2">
                <div className="flex-1">
                  <div className="w-12 h-12 bg-[#001F3F] text-white rounded-xl mx-auto flex items-center justify-center font-black text-xl mb-1 shadow-lg">K</div>
                  <p className="font-black text-[10px] text-slate-900 uppercase">الكرامة</p>
                </div>

                <div className="bg-slate-100 px-5 py-4 rounded-2xl flex items-center justify-center font-black text-2xl border-2 border-slate-900 text-slate-900 shadow-inner">
                  {m.isCompleted ? `${m.ourScore}:${m.opponentScore}` : 'VS'}
                </div>

                <div className="flex-1">
                  <div className="w-12 h-12 bg-white border-2 border-slate-900 text-slate-900 rounded-xl mx-auto flex items-center justify-center font-black text-xl mb-1 shadow-md">?</div>
                  <p className="font-black text-[10px] text-slate-900 uppercase">{m.opponent}</p>
                </div>
             </div>

             <div className="mt-5 pt-4 border-t-2 border-slate-100 flex flex-col xl:flex-row justify-between items-center gap-3">
                <div className="space-y-1 w-full xl:w-auto">
                  <div className="flex items-center gap-2 text-[10px] font-black text-slate-900"><Calendar size={12} className="text-[#001F3F]"/> {m.date} | {m.time}</div>
                  <div className="flex items-center gap-2 text-[10px] font-black text-slate-900"><MapPin size={12} className="text-orange-600"/> {m.location}</div>
                </div>
                <div className="flex gap-2 w-full xl:w-auto">
                  <button onClick={() => { setActiveMatch(m); setShowReport(true); }} className="flex-1 bg-white border-2 border-slate-900 text-slate-900 px-3 py-2 rounded-lg text-[9px] font-black hover:bg-slate-100 flex items-center justify-center gap-1.5 shadow-sm">
                    <FileText size={14}/> التقرير
                  </button>
                  <button onClick={() => { setActiveMatch(m); setShowReport(false); }} className="flex-1 bg-[#001F3F] text-white px-4 py-2 rounded-lg text-[9px] font-black hover:bg-black transition-all shadow-md">
                    إدارة المباراة
                  </button>
                </div>
             </div>
          </div>
        ))}
      </div>

      {/* Add Match Modal */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-md flex items-center justify-center z-[250] p-6 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-4 border-slate-900">
             <div className="p-6 border-b-2 border-slate-100 bg-slate-50 flex justify-between items-center rounded-t-[2.2rem]">
