            <button onClick={() => setSidebarOpen(true)} className="md:hidden p-2 hover:bg-slate-100 rounded-lg"><Menu size={18}/></button>
            <h2 className="text-md font-black text-slate-800">{menuItems.find(m => m.id === activeTab)?.label}</h2>
            {isSyncing && <span className="text-[8px] font-black text-blue-500 animate-pulse mr-3">مزامنة سحابية...</span>}
          </div>

          <div className="flex items-center gap-2">
             {state.currentUser.role === 'مدير' && (
               <button onClick={() => setShowNotifications(!showNotifications)} className="relative p-1.5 bg-slate-50 text-[#001F3F] rounded-lg border border-slate-200">
                 <Bell size={16} />
                 {state.notifications.filter(n => !n.isRead).length > 0 && (
                   <span className="absolute top-1 right-1 w-1.5 h-1.5 bg-orange-600 rounded-full"></span>
                 )}
