import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, X, Trophy, Bell, CheckCircle2, Trash2, RefreshCw
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { AppUser, AppState, Category, Person, TrainingSession, Match, AppNotification } from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

// Initialize Supabase client
const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';

const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // Ref to track state for sync to prevent infinite loops
  const lastSyncStateRef = useRef<string>('');

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_state_v2');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error("Error parsing saved state:", e);
      }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      attendance: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // 1. وظيفة جلب البيانات من السحابة (Pull)
  const fetchData = useCallback(async () => {
    if (!state.currentUser || !supabase) return;
    setIsSyncing(true);
    try {
      const [
        { data: cats }, 
        { data: ppl }, 
        { data: sess }, 
        { data: mtch }, 
        { data: attn }
      ] = await Promise.all([
        supabase.from('categories').select('name'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
      ]);

      setState(prev => {
        const newState = {
          ...prev,
          categories: (cats && cats.length > 0) ? cats.map(c => c.name) : prev.categories,
          people: ppl || prev.people,
          sessions: sess || prev.sessions,
          matches: mtch || prev.matches,
          attendance: attn || prev.attendance
        };
        lastSyncStateRef.current = JSON.stringify({
          p: newState.people,
          s: newState.sessions,
          m: newState.matches,
          a: newState.attendance
        });
        return newState;
      });
    } catch (error) {
      console.error("Sync Pull Error:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  // 2. وظيفة دفع البيانات للسحابة (Push)
  const pushData = useCallback(async () => {
    if (!state.currentUser || !supabase || isSyncing) return;

    const currentStateToSync = JSON.stringify({
      p: state.people,
      s: state.sessions,
      m: state.matches,
      a: state.attendance
    });

    // لا تدفع إذا لم يتغير شيء عن آخر مزامنة
    if (currentStateToSync === lastSyncStateRef.current) return;

    try {
      // مزامنة الجداول بشكل متوازي
      await Promise.all([
        state.people.length > 0 ? supabase.from('people').upsert(state.people) : Promise.resolve(),
        state.sessions.length > 0 ? supabase.from('sessions').upsert(state.sessions) : Promise.resolve(),
        state.matches.length > 0 ? supabase.from('matches').upsert(state.matches) : Promise.resolve(),
        state.attendance.length > 0 ? supabase.from('attendance').upsert(state.attendance) : Promise.resolve()
      ]);
      lastSyncStateRef.current = currentStateToSync;
      console.log("Data pushed to cloud successfully");
    } catch (error) {
      console.error("Sync Push Error:", error);
    }
  }, [state.people, state.sessions, state.matches, state.attendance, state.currentUser, isSyncing]);

  // تأثير المزامنة التلقائية كل 3 ثوانٍ
  useEffect(() => {
    if (state.currentUser) {
      fetchData(); // جلب أولي
      const interval = setInterval(() => {
        fetchData();
      }, 3000); // تحديث كل 3 ثوانٍ كما طلب المستخدم
      return () => clearInterval(interval);
    }
  }, [state.currentUser, fetchData]);

  // دفع البيانات عند حدوث تغيير محلي
  useEffect(() => {
    const timeout = setTimeout(() => {
      pushData();
    }, 1000); // دفع التغييرات بعد ثانية من التوقف عن الكتابة/التعديل
    return () => clearTimeout(timeout);
  }, [state.people, state.sessions, state.matches, state.attendance, pushData]);

  // حفظ الحالة في التخزين المحلي كنسخة احتياطية
  useEffect(() => {
    localStorage.setItem('alkarama_state_v2', JSON.stringify(state));
  }, [state]);

  const addLog = (message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message,
      details,
      type,
      timestamp: Date.now(),
      isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    localStorage.removeItem('alkarama_state_v2');
    setActiveTab('dashboard');
  };

  if (!state.currentUser) {
    return <Login onLogin={(user) => setState(prev => ({ ...prev, currentUser: user }))} state={state} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const unreadCount = state.notifications.filter(n => !n.isRead).length;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:inset-0
        ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print
      `}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-white/70 hover:text-white">
              <X size={24} />
            </button>
          </div>

          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`
                  w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 group
                  ${activeTab === item.id 
                    ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' 
                    : 'text-white/70 hover:bg-white/5 hover:text-white'}
                `}
              >
                <item.icon size={20} className={activeTab === item.id ? 'animate-pulse' : 'group-hover:scale-110 transition-transform'} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>

          <div className="p-4 border-t border-white/10">
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 transition-colors font-bold"
            >
              <LogOut size={20} />
              <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between no-print shadow-sm">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
              <Menu size={24} />
            </button>
            <h1 className="text-xl font-black text-slate-800">{navItems.find(i => i.id === activeTab)?.label}</h1>
          </div>

          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-slate-50 rounded-xl border border-slate-100">
               <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-orange-500 animate-ping' : 'bg-emerald-500'}`}></div>
               <span className="text-[10px] font-black text-slate-500 uppercase">{isSyncing ? 'مزامنة...' : 'متصل'}</span>
            </div>

            <button 
              onClick={fetchData}
              disabled={isSyncing}
              className={`p-2.5 rounded-xl transition-all ${isSyncing ? 'bg-orange-50 text-orange-500 animate-spin' : 'bg-slate-100 text-slate-600 hover:bg-slate-200 border border-slate-200'}`}
              title="مزامنة فورية"
            >
              <RefreshCw size={20} />
            </button>

            <div className="relative">
              <button 
                onClick={() => setShowNotifications(!showNotifications)}
                className={`p-2.5 rounded-xl relative transition-all border ${showNotifications ? 'bg-orange-600 text-white border-orange-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200 border-slate-200'}`}
              >
                <Bell size={20} />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] bg-red-600 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white animate-bounce">
                    {unreadCount}
                  </span>
                )}
              </button>

              {/* Notifications Panel */}
              {showNotifications && (
                <div className="absolute left-0 top-12 w-80 bg-white rounded-2xl shadow-2xl border-2 border-slate-900 overflow-hidden z-[100] animate-in slide-in-from-top-2 duration-200 text-right">
                  <div className="p-4 border-b-2 bg-slate-50 border-slate-900 flex justify-between items-center">
                    <h3 className="font-black text-slate-800 text-xs uppercase">مركز التنبيهات</h3>
                    <button onClick={() => setState(prev => ({ ...prev, notifications: prev.notifications.map(n => ({...n, isRead: true})) }))} className="text-[10px] text-blue-600 font-bold hover:underline">قراءة الكل</button>
                  </div>
                  <div className="max-h-96 overflow-y-auto custom-scrollbar">
                    {state.notifications.length === 0 ? (
                      <div className="p-10 text-center text-slate-400 font-bold text-xs italic opacity-50">لا توجد تنبيهات جديدة</div>
                    ) : (
                      state.notifications.map(n => (
                        <div key={n.id} className={`p-4 border-b hover:bg-slate-50 transition-colors ${!n.isRead ? 'bg-orange-50/50' : ''}`}>
                          <div className="flex gap-3">
                             <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${n.type === 'success' ? 'bg-emerald-100 text-emerald-600' : n.type === 'error' ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                                <Bell size={16}/>
                             </div>
                             <div>
                                <p className="text-[11px] font-black text-slate-700 leading-tight">{n.message}</p>
                                <span className="text-[9px] text-slate-400 mt-1 block">{new Date(n.timestamp).toLocaleTimeString('ar-SY')}</span>
                             </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar relative">
          <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={setState} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={setState} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <footer className="bg-white/95 backdrop-blur-md border-t py-1.5 px-5 flex justify-between items-center no-print z-40">
          <p className="text-[7px] font-black text-slate-500 tracking-tighter">نظام إدارة مكتب كرة القدم - نادي الكرامة</p>
          <p className="text-[7px] font-black text-[#001F3F] border-r-2 border-orange-500 pr-2">By: Izzat Amer Al-Shikha</p>
        </footer>
      </main>

      {/* Backdrop for notifications panel close on click outside */}
      {showNotifications && (
        <div className="fixed inset-0 z-30" onClick={() => setShowNotifications(false)}></div>
      )}
    </div>
  );
};

