import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, X, Trophy, Bell, CheckCircle2, Trash2, RefreshCw, User
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { AppUser, AppState, Category, Person, TrainingSession, Match, AppNotification } from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

// Initialize Supabase client
const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';

const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // Refs للتحكم الدقيق في المزامنة ومنع تعارض البيانات
  const lastSyncStateRef = useRef<string>('');
  const syncTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_state_v2');
    const defaultAdmin: AppUser = { id: 'admin-main', username: 'IZZAT', role: 'مدير', password: 'KSC@2026' };

    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (!parsed.users) parsed.users = [defaultAdmin];
        return parsed;
      } catch (e) {
        console.error("Error parsing saved state:", e);
      }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      attendance: [],
      users: [defaultAdmin],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // حفظ نسخة من الـ state في ref للوصول إليها في المهام غير المتزامنة دون مشاكل Stale Closure
  const stateRef = useRef(state);
  useEffect(() => {
    stateRef.current = state;
    localStorage.setItem('alkarama_state_v2', JSON.stringify(state));
  }, [state]);

  // 1. وظيفة جلب البيانات (Pull) - محمية تماماً من مسح التعديلات المحلية
  const fetchData = useCallback(async (isManual = false) => {
    if (!stateRef.current.currentUser || !supabase || isSyncing) return;

    // فحص حرج: هل هناك بيانات محلية لم ترفع بعد؟
    const currentLocalDataStr = JSON.stringify({
      p: stateRef.current.people,
      s: stateRef.current.sessions,
      m: stateRef.current.matches,
      a: stateRef.current.attendance,
      u: stateRef.current.users
    });

    // إذا كانت الحالة الحالية تختلف عن آخر مزامنة ناجحة، فهذا يعني وجود تعديلات محلية قيد الانتظار
    // نمنع الجلب تماماً في هذه الحالة حتى لا نمسح البيانات الجديدة
    if (!isManual && currentLocalDataStr !== lastSyncStateRef.current) {
      console.log("Sync Pull Skipped: Local changes pending push.");
      return;
    }

    setIsSyncing(true);
    try {
      const [
        { data: cats }, 
        { data: ppl }, 
        { data: sess }, 
        { data: mtch }, 
        { data: attn },
        { data: usrs }
      ] = await Promise.all([
        supabase.from('categories').select('name'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('users').select('*'),
      ]);

      const cloudDataString = JSON.stringify({
        p: ppl || [],
        s: sess || [],
        m: mtch || [],
        a: attn || [],
        u: usrs || []
      });

      // نحدث الحالة فقط إذا كانت بيانات السحاب مختلفة ولم نقم نحن بتغيير شيء محلياً أثناء الطلب
      if (cloudDataString !== lastSyncStateRef.current) {
        setState(prev => ({
          ...prev,
          categories: (cats && cats.length > 0) ? cats.map(c => c.name) : prev.categories,
          people: ppl || prev.people,
          sessions: sess || prev.sessions,
          matches: mtch || prev.matches,
          attendance: attn || prev.attendance,
          users: usrs || prev.users
        }));
        lastSyncStateRef.current = cloudDataString;
      }
    } catch (error) {
      console.error("Pull Error:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [isSyncing]);

  // 2. وظيفة دفع البيانات (Push)
  const pushData = useCallback(async () => {
    if (!stateRef.current.currentUser || !supabase) return;

    const dataToPush = {
      p: stateRef.current.people,
      s: stateRef.current.sessions,
      m: stateRef.current.matches,
      a: stateRef.current.attendance,
      u: stateRef.current.users
    };

    const currentStateToSync = JSON.stringify(dataToPush);

    if (currentStateToSync === lastSyncStateRef.current) return;

    try {
      setIsSyncing(true);
      await Promise.all([
        dataToPush.p.length > 0 ? supabase.from('people').upsert(dataToPush.p) : Promise.resolve(),
        dataToPush.s.length > 0 ? supabase.from('sessions').upsert(dataToPush.s) : Promise.resolve(),
        dataToPush.m.length > 0 ? supabase.from('matches').upsert(dataToPush.m) : Promise.resolve(),
        dataToPush.a.length > 0 ? supabase.from('attendance').upsert(dataToPush.a) : Promise.resolve(),
        dataToPush.u.length > 0 ? supabase.from('users').upsert(dataToPush.u) : Promise.resolve()
      ]);

      lastSyncStateRef.current = currentStateToSync;
      console.log("Push Success - Cloud Updated");
    } catch (error) {
      console.error("Push Error:", error);
    } finally {
      setIsSyncing(false);
    }
  }, []);

  // المزامنة الدورية (كل 3 ثوانٍ) لجلب تعديلات الآخرين فقط إذا كنا نحن خاملين
  useEffect(() => {
    if (state.currentUser) {
      fetchData();
      const interval = setInterval(() => fetchData(), 3000); 
      return () => clearInterval(interval);
    }
  }, [state.currentUser, fetchData]);

  // مراقبة التغييرات المحلية والرفع بعد 3 ثوانٍ من آخر تعديل (Debounce)
  useEffect(() => {
    const currentLocalStr = JSON.stringify({
      p: state.people,
      s: state.sessions,
      m: state.matches,
      a: state.attendance,
      u: state.users
    });

    if (state.currentUser && currentLocalStr !== lastSyncStateRef.current) {
      if (syncTimeoutRef.current) clearTimeout(syncTimeoutRef.current);

      syncTimeoutRef.current = setTimeout(() => {
        pushData();
      }, 3000); // المزامنة تتم بعد 3 ثوانٍ من أي تعديل
    }
  }, [state.people, state.sessions, state.matches, state.attendance, state.users, state.currentUser, pushData]);

  const addLog = (message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message,
      details,
      type,
      timestamp: Date.now(),
      isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('dashboard');
  };

  if (!state.currentUser) {
    return <Login onLogin={(user) => setState(prev => ({ ...prev, currentUser: user }))} state={state} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const unreadCount = state.notifications.filter(n => !n.isRead).length;
  const currentTabLabel = navItems.find(i => i.id === activeTab)?.label || (activeTab === 'report' ? 'التقرير الفني' : 'تفاصيل');

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:inset-0
        ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print
      `}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-white/70 hover:text-white">
              <X size={24} />
            </button>
          </div>

          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`
                  w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 group
                  ${activeTab === item.id 
                    ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' 
                    : 'text-white/70 hover:bg-white/5 hover:text-white'}
                `}
              >
                <item.icon size={20} className={activeTab === item.id ? 'animate-pulse' : 'group-hover:scale-110 transition-transform'} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>

          <div className="p-4 border-t border-white/10">
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 transition-colors font-bold"
            >
              <LogOut size={20} />
              <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between no-print shadow-sm">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
              <Menu size={24} />
            </button>
            <h1 className="text-xl font-black text-slate-800">
              {currentTabLabel}
            </h1>
          </div>

          <div className="flex items-center gap-4">
            {/* اسم المستخدم بشكل بارز في أعلى الصفحة */}
            <div className="hidden md:flex flex-col items-end px-4 border-r-2 border-orange-500">
              <span className="text-[10px] font-black text-slate-400 uppercase leading-none mb-1">المسؤول عن النظام</span>
              <div className="flex items-center gap-2">
                <span className="text-sm font-black text-[#001F3F]">{state.currentUser.username}</span>
                <User size={14} className="text-orange-600" />
