import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

// Initialize Supabase client
const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';

const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // Refs للتحكم الدقيق في المزامنة ومنع تعارض البيانات
  const lastSyncStateRef = useRef<string>('');
  // Use ReturnType<typeof setTimeout> instead of NodeJS.Timeout for browser compatibility
  const syncTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_state_v2');
    const defaultAdmin: AppUser = { id: 'admin-main', username: 'IZZAT', role: 'مدير', password: 'KSC@2026' };

    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (!parsed.users) parsed.users = [defaultAdmin];
        return parsed;
      } catch (e) {
        console.error("Error parsing saved state:", e);
      }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      attendance: [],
      users: [defaultAdmin],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // حفظ نسخة من الـ state في ref للوصول إليها في المهام غير المتزامنة دون مشاكل Stale Closure
  const stateRef = useRef(state);
  useEffect(() => {
    stateRef.current = state;
    localStorage.setItem('alkarama_state_v2', JSON.stringify(state));
  }, [state]);

  // 1. وظيفة جلب البيانات (Pull) - محمية تماماً من مسح التعديلات المحلية
  const fetchData = useCallback(async (isManual = false) => {
    if (!stateRef.current.currentUser || !supabase || isSyncing) return;

    // فحص حرج: هل هناك بيانات محلية لم ترفع بعد؟
    const currentLocalDataStr = JSON.stringify({
      p: stateRef.current.people,
      s: stateRef.current.sessions,
      m: stateRef.current.matches,
      a: stateRef.current.attendance,
      u: stateRef.current.users
    });

    // إذا كانت الحالة الحالية تختلف عن آخر مزامنة ناجحة، فهذا يعني وجود تعديلات محلية قيد الانتظار
    // نمنع الجلب تماماً في هذه الحالة حتى لا نمسح البيانات الجديدة
    if (!isManual && currentLocalDataStr !== lastSyncStateRef.current) {
      console.log("Sync Pull Skipped: Local changes pending push.");
      return;
    }

    setIsSyncing(true);
    try {
      const [
        { data: cats }, 
        { data: ppl }, 
        { data: sess }, 
        { data: mtch }, 
        { data: attn },
        { data: usrs }
      ] = await Promise.all([
        supabase.from('categories').select('name'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('users').select('*'),
      ]);

      const cloudDataString = JSON.stringify({
        p: ppl || [],
        s: sess || [],
        m: mtch || [],
        a: attn || [],
        u: usrs || []
      });

      // نحدث الحالة فقط إذا كانت بيانات السحاب مختلفة ولم نقم نحن بتغيير شيء محلياً أثناء الطلب
      if (cloudDataString !== lastSyncStateRef.current) {
        setState(prev => ({
          ...prev,
          categories: (cats && cats.length > 0) ? cats.map(c => c.name) : prev.categories,
          people: ppl || prev.people,
          sessions: sess || prev.sessions,
          matches: mtch || prev.matches,
          attendance: attn || prev.attendance,
          users: usrs || prev.users
        }));
        lastSyncStateRef.current = cloudDataString;
      }
    } catch (error) {
      console.error("Pull Error:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [isSyncing]);

  // 2. وظيفة دفع البيانات (Push)
  const pushData = useCallback(async () => {
    if (!stateRef.current.currentUser || !supabase) return;

    const dataToPush = {
      p: stateRef.current.people,
      s: stateRef.current.sessions,
      m: stateRef.current.matches,
      a: stateRef.current.attendance,
      u: stateRef.current.users
    };

    const currentStateToSync = JSON.stringify(dataToPush);

    if (currentStateToSync === lastSyncStateRef.current) return;

    try {
      setIsSyncing(true);
      await Promise.all([
        dataToPush.p.length > 0 ? supabase.from('people').upsert(dataToPush.p) : Promise.resolve(),
        dataToPush.s.length > 0 ? supabase.from('sessions').upsert(dataToPush.s) : Promise.resolve(),
        dataToPush.m.length > 0 ? supabase.from('matches').upsert(dataToPush.m) : Promise.resolve(),
        dataToPush.a.length > 0 ? supabase.from('attendance').upsert(dataToPush.a) : Promise.resolve(),
        dataToPush.u.length > 0 ? supabase.from('users').upsert(dataToPush.u) : Promise.resolve()
      ]);

      lastSyncStateRef.current = currentStateToSync;
      console.log("Push Success - Cloud Updated");
    } catch (error) {
      console.error("Push Error:", error);
    } finally {
      setIsSyncing(false);
    }
  }, []);

  // المزامنة الدورية (كل 3 ثوانٍ) لجلب تعديلات الآخرين فقط إذا كنا نحن خاملين
  useEffect(() => {
    if (state.currentUser) {
      fetchData();
      const interval = setInterval(() => fetchData(), 3000); 
      return () => clearInterval(interval);
    }
  }, [state.currentUser, fetchData]);

  // مراقبة التغييرات المحلية والرفع بعد 3 ثوانٍ من آخر تعديل (Debounce)
  useEffect(() => {
    const currentLocalStr = JSON.stringify({
      p: state.people,
      s: state.sessions,
      m: state.matches,
      a: state.attendance,
      u: state.users
    });

    if (state.currentUser && currentLocalStr !== lastSyncStateRef.current) {
      if (syncTimeoutRef.current) clearTimeout(syncTimeoutRef.current);

      syncTimeoutRef.current = setTimeout(() => {
        pushData();
      }, 3000); // المزامنة تتم بعد 3 ثوانٍ من أي تعديل
    }
  }, [state.people, state.sessions, state.matches, state.attendance, state.users, state.currentUser, pushData]);

  const addLog = (message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message,
      details,
      type,
      timestamp: Date.now(),
      isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('dashboard');
  };

  if (!state.currentUser) {
    return <Login onLogin={(user) => setState(prev => ({ ...prev, currentUser: user }))} state={state} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const unreadCount = state.notifications.filter(n => !n.isRead).length;
  const currentTabLabel = navItems.find(i => i.id === activeTab)?.label || (activeTab === 'report' ? 'التقرير الفني' : 'تفاصيل');

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:inset-0
        ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print
      `}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-white/70 hover:text-white">
              <X size={24} />
            </button>
          </div>

          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`
                  w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 group
                  ${activeTab === item.id 
                    ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' 
                    : 'text-white/70 hover:bg-white/5 hover:text-white'}
                `}
              >
                <item.icon size={20} className={activeTab === item.id ? 'animate-pulse' : 'group-hover:scale-110 transition-transform'} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>

          <div className="p-4 border-t border-white/10">
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 transition-colors font-bold"
            >
              <LogOut size={20} />
              <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between no-print shadow-sm">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg">
              <Menu size={24} />
            </button>
            <h1 className="text-xl font-black text-slate-800">
              {currentTabLabel}
            </h1>
          </div>

          <div className="flex items-center gap-4">
            {/* اسم المستخدم بشكل بارز في أعلى الصفحة */}
            <div className="hidden md:flex flex-col items-end px-4 border-r-2 border-orange-500">
              <span className="text-[10px] font-black text-slate-400 uppercase leading-none mb-1">المسؤول عن النظام</span>
              <div className="flex items-center gap-2">
                <span className="text-sm font-black text-[#001F3F]">{state.currentUser.username}</span>
                <User size={14} className="text-orange-600" />
              </div>
            </div>

            <div className="flex items-center gap-2 px-3 py-1.5 bg-slate-50 rounded-xl border border-slate-100">
               <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-orange-500 animate-ping' : 'bg-emerald-500'}`}></div>
               <span className="text-[10px] font-black text-slate-500 uppercase">{isSyncing ? 'مزامنة...' : 'متصل'}</span>
            </div>

            <button 
              onClick={() => fetchData(true)}
              disabled={isSyncing}
              className={`p-2.5 rounded-xl transition-all ${isSyncing ? 'bg-orange-50 text-orange-500 animate-spin' : 'bg-slate-100 text-slate-600 hover:bg-slate-200 border border-slate-200'}`}
              title="تحديث البيانات الآن"
            >
              <RefreshCw size={20} />
            </button>

            <div className="relative">
              <button 
                onClick={() => setShowNotifications(!showNotifications)}
                className={`p-2.5 rounded-xl relative transition-all border ${showNotifications ? 'bg-orange-600 text-white border-orange-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200 border-slate-200'}`}
              >
                <Bell size={20} />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] bg-red-600 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white animate-bounce">
                    {unreadCount}
                  </span>
                )}
              </button>

              {showNotifications && (
                <div className="absolute left-0 top-12 w-80 bg-white rounded-2xl shadow-2xl border-2 border-slate-900 overflow-hidden z-[100] animate-in slide-in-from-top-2 duration-200 text-right">
                  <div className="p-4 border-b-2 bg-slate-50 border-slate-900 flex justify-between items-center">
                    <h3 className="font-black text-slate-800 text-xs uppercase">مركز التنبيهات</h3>
                    <button onClick={() => setState(prev => ({ ...prev, notifications: prev.notifications.map(n => ({...n, isRead: true})) }))} className="text-[10px] text-blue-600 font-bold hover:underline">قراءة الكل</button>
                  </div>
                  <div className="max-h-96 overflow-y-auto custom-scrollbar">
                    {state.notifications.length === 0 ? (
                      <div className="p-10 text-center text-slate-400 font-bold text-xs italic opacity-50">لا توجد تنبيهات جديدة</div>
                    ) : (
                      state.notifications.map(n => (
                        <div key={n.id} className={`p-4 border-b hover:bg-slate-50 transition-colors ${!n.isRead ? 'bg-orange-50/50' : ''}`}>
                          <div className="flex gap-3">
                             <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${n.type === 'success' ? 'bg-emerald-100 text-emerald-600' : n.type === 'error' ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                                <Bell size={16}/>
                             </div>
                             <div>
                                <p className="text-[11px] font-black text-slate-700 leading-tight">{n.message}</p>
                                <span className="text-[9px] text-slate-400 mt-1 block">{new Date(n.timestamp).toLocaleTimeString('ar-SY')}</span>
                             </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar relative">
          <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={setState} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={setState} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <footer className="bg-white/95 backdrop-blur-md border-t py-1.5 px-5 flex justify-between items-center no-print z-40">
          <p className="text-[7px] font-black text-slate-500 tracking-tighter">نظام إدارة مكتب كرة القدم - نادي الكرامة</p>
          <p className="text-[7px] font-black text-[#001F3F] border-r-2 border-orange-500 pr-2">By: Izzat Amer Al-Shikha | User: {state.currentUser.username}</p>
        </footer>
      </main>

      {showNotifications && (
        <div className="fixed inset-0 z-30" onClick={() => setShowNotifications(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck, Lock, Clock, Calendar as CalendarIcon } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord } from '../types';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus; excuse?: string; fine?: string; time?: string; date?: string }>>({});

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;

  const sessions = state.sessions
    .filter(s => (globalFilter === 'الكل' || s.category === globalFilter))
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const players = state.people.filter(p => p.role === 'لاعب' && (activeSession ? p.category === activeSession.category : true));
  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    // تسجيل الوقت والتاريخ فوراً عند اختيار الحالة
    const now = new Date();
    // تنسيق الوقت (الساعة:الدقيقة)
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
    // تنسيق التاريخ (السنة-الشهر-اليوم)
    const dateStr = now.toISOString().split('T')[0];

    setLocalRecords(prev => ({ 
      ...prev, 
      [pid]: { ...prev[pid], status, time: timeStr, date: dateStr } 
    }));
  };

  const saveAttendance = () => {
    // Explicitly cast Object.entries to provide types for 'data' in map
    const entries = Object.entries(localRecords) as [string, { status: AttendanceStatus; excuse?: string; fine?: string; time?: string; date?: string }][];
    if (entries.length === 0) return alert('يرجى رصد حالات اللاعبين أولاً');

    const newRecords: AttendanceRecord[] = entries.map(([pid, data]) => ({
      id: Math.random().toString(36).substr(2, 9),
      personId: pid,
      sessionId: selectedSessionId,
      date: data.date || activeSession!.date,
      time: data.time || (new Date().getHours().toString().padStart(2, '0') + ':' + new Date().getMinutes().toString().padStart(2, '0')),
      status: data.status,
      excuse: data.excuse,
      fine: data.fine,
      isLocked: true
    }));

    setState(p => ({
      ...p,
      attendance: [
        ...p.attendance.filter(a => !(a.sessionId === selectedSessionId && localRecords[a.personId])),
        ...newRecords
      ],
    }));

    addLog?.('حفظ الحضور', `تم تثبيت سجل حضور تمرين ${activeSession?.objective}`, 'success');
    setLocalRecords({});
    alert('تم حفظ السجل بنجاح وقفل البيانات');
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row gap-6 items-end no-print relative overflow-hidden">
        <div className="absolute top-0 right-0 w-2 h-full bg-[#001F3F]"></div>
        <div className="flex-1 space-y-2 w-full">
           <label className="text-[10px] font-black text-slate-900 mr-2 uppercase tracking-widest">اختيار جلسة التمرين للرصد</label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-100 border-2 border-slate-900 rounded-xl p-4 font-black text-xl text-slate-900 outline-none focus:border-orange-600 transition-all">
             <option value="">-- اختر التمرين من القائمة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <button 
          onClick={saveAttendance} 
          disabled={!selectedSessionId}
          className="bg-[#001F3F] text-white px-10 py-5 rounded-2xl font-black text-lg shadow-xl hover:bg-black disabled:opacity-30 transition-all flex items-center gap-2 border-b-4 border-black"
        >
          <Save size={24} /> تثبيت السجل النهائي
        </button>
      </div>

      {activeSession && (
        <div className="bg-white rounded-[2.5rem] shadow-sm border-2 border-slate-900 overflow-hidden relative">
          <div className="p-6 border-b-2 border-slate-900 bg-slate-100 flex justify-between items-center">
             <div className="flex items-center gap-4">
               <div className="w-14 h-14 bg-white border-2 border-slate-900 rounded-xl flex items-center justify-center font-black text-2xl text-[#001F3F] shadow-md">K</div>
               <div>
                 <h3 className="text-xl font-black text-slate-900">{activeSession.objective}</h3>
                 <p className="text-[10px] font-black text-[#001F3F] uppercase tracking-widest">{activeSession.category} • {activeSession.date}</p>
               </div>
             </div>
             <div className="flex gap-3">
               <div className="bg-white border-2 border-slate-900 px-5 py-2 rounded-xl text-center">
                 <p className="text-[8px] font-black uppercase text-slate-400">إجمالي الحضور</p>
                 <p className="text-lg font-black text-emerald-600">
                    {state.attendance.filter(r => r.sessionId === selectedSessionId && (r.status === 'حاضر' || r.status === 'متأخر')).length}
                 </p>
               </div>
               <div className="bg-[#001F3F] text-white px-5 py-2 rounded-xl text-center border-2 border-slate-900">
                 <p className="text-[8px] font-black uppercase text-blue-200">اللاعبين</p>
                 <p className="text-lg font-black">{players.length}</p>
               </div>
             </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[800px]">
              <thead className="bg-slate-200 border-b-2 border-slate-900">
                <tr>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">بيانات اللاعب</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest text-center">رصد الحالة الفوري</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">التوقيت المسجل</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">ملاحظات إضافية</th>
                </tr>
              </thead>
              <tbody className="divide-y-2 divide-slate-200">
                {players.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];
                  const currentStatus = local?.status || saved?.status;
                  const currentTime = local?.time || saved?.time;

                  // منع إداري الفئة من التعديل بعد الحفظ - التنبيه الصارم
                  const isLockedForUser = saved && currentUser.role === 'إداري فئة';

