import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, X, Trophy, Bell, CheckCircle2, Trash2, RefreshCw, User
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { AppUser, AppState, Category, Person, TrainingSession, Match, AppNotification } from './types';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';

// Initialize Supabase client
const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';

const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // Refs للتحكم المطلق في تدفق البيانات ومنع الحذف
  const lastSyncedJSONRef = useRef<string>('');
  const isDirtyRef = useRef<boolean>(false); // العلم الذي يمنع المسح
  const syncTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_state_v3');
    const defaultAdmin: AppUser = { id: 'admin-main', username: 'IZZAT', role: 'مدير', password: 'KSC@2026' };

    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (!parsed.users) parsed.users = [defaultAdmin];
        return parsed;
      } catch (e) {
        console.error("Error parsing saved state:", e);
      }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      attendance: [],
      users: [defaultAdmin],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // تحديث المرجع اللحظي للحالة
  const currentStateRef = useRef(state);
  useEffect(() => {
    currentStateRef.current = state;
    localStorage.setItem('alkarama_state_v3', JSON.stringify(state));
  }, [state]);

  // وظيفة رفع البيانات (PUSH) - فورية وبأولوية قصوى
  const pushToCloud = useCallback(async () => {
    if (!currentStateRef.current.currentUser || !supabase) return;

    const data = {
      p: currentStateRef.current.people,
      s: currentStateRef.current.sessions,
      m: currentStateRef.current.matches,
      a: currentStateRef.current.attendance,
      u: currentStateRef.current.users
    };

    const dataString = JSON.stringify(data);
    if (dataString === lastSyncedJSONRef.current) {
      isDirtyRef.current = false;
      return;
    }

    setIsSyncing(true);
    try {
      // إرسال البيانات فوراً
      await Promise.all([
        data.p.length >= 0 ? supabase.from('people').upsert(data.p) : Promise.resolve(),
        data.s.length >= 0 ? supabase.from('sessions').upsert(data.s) : Promise.resolve(),
        data.m.length >= 0 ? supabase.from('matches').upsert(data.m) : Promise.resolve(),
        data.a.length >= 0 ? supabase.from('attendance').upsert(data.a) : Promise.resolve(),
        data.u.length >= 0 ? supabase.from('users').upsert(data.u) : Promise.resolve(),
      ]);

      lastSyncedJSONRef.current = dataString;
      isDirtyRef.current = false; // فك قفل الجلب بعد نجاح الرفع
      console.log("✅ تمت المزامنة مع السحاب بنجاح.");
    } catch (error) {
      console.error("❌ خطأ في الرفع:", error);
    } finally {
      setIsSyncing(false);
    }
  }, []);

  // وظيفة جلب البيانات (PULL) - محمية ضد مسح البيانات المحلية
  const pullFromCloud = useCallback(async (isManual = false) => {
    if (!currentStateRef.current.currentUser || !supabase || isSyncing) return;

    // الميزة الأهم: إذا كانت هناك بيانات محلية معدلة (isDirty)، نمنع الجلب تماماً
    if (!isManual && isDirtyRef.current) {
      console.log("⚠️ تم تعليق الجلب لحماية التعديلات المحلية الجديدة.");
      return;
    }

    setIsSyncing(true);
    try {
      const [
        { data: cats }, { data: ppl }, { data: sess }, { data: mtch }, { data: attn }, { data: usrs }
      ] = await Promise.all([
        supabase.from('categories').select('name'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('users').select('*'),
      ]);

      const cloudDataString = JSON.stringify({
        p: ppl || [], s: sess || [], m: mtch || [], a: attn || [], u: usrs || []
      });

      // نحدث فقط إذا كانت هناك بيانات جديدة فعلياً في السحاب ولم نكن في حالة "Dirty"
      if (cloudDataString !== lastSyncedJSONRef.current && !isDirtyRef.current) {
        setState(prev => ({
          ...prev,
          categories: (cats && cats.length > 0) ? cats.map(c => c.name) : prev.categories,
          people: ppl || prev.people,
          sessions: sess || prev.sessions,
          matches: mtch || prev.matches,
          attendance: attn || prev.attendance,
          users: usrs || prev.users
        }));
        lastSyncedJSONRef.current = cloudDataString;
      }
    } catch (error) {
      console.error("❌ خطأ في الجلب:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [isSyncing]);

  // مراقبة التعديلات المحلية للرفع الفوري (500ms)
  useEffect(() => {
    const dataStr = JSON.stringify({
      p: state.people, s: state.sessions, m: state.matches, a: state.attendance, u: state.users
    });

    if (state.currentUser && dataStr !== lastSyncedJSONRef.current) {
      isDirtyRef.current = true; // قفل الجلب فوراً عند حدوث أي تعديل
      if (syncTimeoutRef.current) clearTimeout(syncTimeoutRef.current);

      syncTimeoutRef.current = setTimeout(() => {
        pushToCloud();
      }, 500); // مزامنة فورية بعد نصف ثانية من التوقف عن التعديل
    }
  }, [state.people, state.sessions, state.matches, state.attendance, state.users, state.currentUser, pushToCloud]);

  // جلب دوري كل 5 ثوانٍ فقط إذا كان النظام خامل (ليس Dirty)
  useEffect(() => {
    if (state.currentUser) {
      pullFromCloud();
      const interval = setInterval(() => pullFromCloud(), 5000);
      return () => clearInterval(interval);
    }
  }, [state.currentUser, pullFromCloud]);

  const addLog = (message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: Math.random().toString(36).substr(2, 9),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  };

  if (!state.currentUser) {
    return <Login onLogin={(user) => setState(prev => ({ ...prev, currentUser: user }))} state={state} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const unreadCount = state.notifications.filter(n => !n.isRead).length;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 lg:translate-x-0 lg:static lg:inset-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print shadow-2xl`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' : 'text-white/70 hover:bg-white/5 hover:text-white'}`}>
                <item.icon size={20} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-4 border-t border-white/10">
            <button onClick={() => setState(prev => ({ ...prev, currentUser: null }))} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 transition-colors font-bold">
              <LogOut size={20} /> <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between shadow-sm no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-lg"><Menu size={24} /></button>
            <h1 className="text-xl font-black text-slate-800">{navItems.find(i => i.id === activeTab)?.label}</h1>
          </div>

          <div className="flex items-center gap-4">
            {/* عرض اسم المستخدم المسؤول */}
            <div className="hidden md:flex flex-col items-end px-4 py-1 border-r-2 border-orange-600">
               <span className="text-[10px] font-black text-slate-400 uppercase leading-none mb-1">المسؤول عن النظام</span>
               <div className="flex items-center gap-2">
                  <span className="text-xs font-black text-[#001F3F]">عزت عامر الشيخة (IZZAT)</span>
                  <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
               </div>
            </div>

            <div className={`flex items-center gap-2 px-3 py-1.5 rounded-xl border ${isSyncing ? 'bg-orange-50 border-orange-200' : 'bg-slate-50 border-slate-100'}`}>
               <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-orange-500 animate-ping' : 'bg-emerald-500'}`}></div>
               <span className="text-[10px] font-black text-slate-600 uppercase">{isSyncing ? 'جاري المزامنة...' : 'متصل بالسحاب'}</span>
            </div>

            <button onClick={() => pullFromCloud(true)} disabled={isSyncing} className={`p-2.5 rounded-xl transition-all bg-slate-100 hover:bg-slate-200 border border-slate-200 ${isSyncing ? 'animate-spin opacity-50' : ''}`}>
              <RefreshCw size={20} />
            </button>

            <div className="relative">
              <button onClick={() => setShowNotifications(!showNotifications)} className={`p-2.5 rounded-xl relative border ${showNotifications ? 'bg-orange-600 text-white' : 'bg-slate-100 text-slate-600'}`}>
                <Bell size={20} />
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-600 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{unreadCount}</span>}
              </button>
              {showNotifications && (
                <div className="absolute left-0 top-12 w-80 bg-white rounded-2xl shadow-2xl border-2 border-slate-900 overflow-hidden z-[100] text-right">
                  <div className="p-4 border-b bg-slate-50 flex justify-between items-center">
                    <h3 className="font-black text-xs uppercase text-slate-800">التنبيهات</h3>
                    <button onClick={() => setState(p => ({ ...p, notifications: p.notifications.map(n => ({...n, isRead: true})) }))} className="text-[10px] text-blue-600 font-bold">قراءة الكل</button>
                  </div>
                  <div className="max-h-96 overflow-y-auto custom-scrollbar">
                    {state.notifications.length === 0 ? <div className="p-8 text-center text-slate-400 text-xs italic">لا توجد تنبيهات</div> : state.notifications.map(n => (
                      <div key={n.id} className={`p-4 border-b hover:bg-slate-50 transition-colors ${!n.isRead ? 'bg-orange-50/50' : ''}`}>
                        <p className="text-[11px] font-black text-slate-700 leading-tight">{n.message}</p>
                        <span className="text-[9px] text-slate-400 mt-1 block">{new Date(n.timestamp).toLocaleTimeString('ar-SY')}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={setState} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={setState} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={setState} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <footer className="bg-white border-t py-1.5 px-5 flex justify-between items-center no-print z-40">
           <p className="text-[7px] font-black text-slate-500 tracking-tighter">نادي الكرامة الرياضي - مكتب كرة القدم</p>
           <p className="text-[7px] font-black text-[#001F3F] border-r-2 border-orange-500 pr-2">By: Izzat Amer Al-Shikha | المسؤول: {state.currentUser.username}</p>
        </footer>
      </main>
    </div>
  );
};

