            </h1>
          </div>

          <div className="flex items-center gap-4">
            <div className={`flex items-center gap-2 px-4 py-2 rounded-2xl border transition-all duration-500 ${
              syncStatus === 'synced' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' :
