               </div>
             </div>

             <div className="space-y-2">
               <h4 className="font-black text-xl text-slate-900 leading-tight group-hover:text-blue-900 transition-colors">{person.name}</h4>
               <p className="text-[11px] font-black text-slate-600">{person.birthPlace} | {calculateAge(person.birthDate)} سنة</p>
             </div>

             <div className="mt-6 pt-4 border-t-2 border-slate-100 flex justify-between items-center">
                <div className="flex items-center gap-3">
                   <div className="bg-[#001F3F] text-white w-9 h-9 rounded-xl flex items-center justify-center font-black text-lg border-2 border-black">
                     #{person.number || '00'}
                   </div>
                   <button onClick={() => onOpenReport?.(person)} className="text-slate-900 text-xs font-black hover:text-orange-600 underline">الملف الفني</button>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-2.5 bg-slate-100 rounded-xl border-2 border-slate-900"><Plus size={16}/></button>
                  <button onClick={() => { if(confirm(`حذف ${person.name}؟`)) { setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); addLog?.('حذف عضو', `تم مسح ملف: ${person.name}`, 'error'); } }} className="p-2.5 bg-red-50 text-red-600 rounded-xl border-2 border-red-900"><Trash2 size={16}/></button>
                </div>
             </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[250] p-4 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-4xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border-[6px] border-slate-900 flex flex-col h-[90vh]">
            <div className="p-5 border-b-2 bg-slate-50 flex justify-between items-center">
              <h3 className="text-md font-black text-slate-900">تسجيل عضو جديد</h3>
