import React, { useState } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck, Lock, Clock, Calendar as CalendarIcon } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord } from '../types';
import { generateUUID } from '../App';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus; excuse?: string; fine?: string; time?: string; date?: string }>>({});

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;

  const sessions = state.sessions
    .filter(s => (globalFilter === 'الكل' || s.category === globalFilter))
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const players = state.people.filter(p => p.role === 'لاعب' && (activeSession ? p.category === activeSession.category : true));
  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
    const dateStr = now.toISOString().split('T')[0];
    setLocalRecords(prev => ({ 
      ...prev, 
      [pid]: { ...prev[pid], status, time: timeStr, date: dateStr } 
    }));
  };

  const saveAttendance = () => {
    const entries = Object.entries(localRecords) as [string, { status: AttendanceStatus; excuse?: string; fine?: string; time?: string; date?: string }][];
    if (entries.length === 0) return alert('يرجى رصد حالات اللاعبين أولاً');

    const newRecords: AttendanceRecord[] = entries.map(([pid, data]) => ({
      id: generateUUID(),
      personId: pid,
      sessionId: selectedSessionId,
      date: data.date || activeSession!.date,
      time: data.time || (new Date().getHours().toString().padStart(2, '0') + ':' + new Date().getMinutes().toString().padStart(2, '0')),
      status: data.status,
      excuse: data.excuse,
      fine: data.fine,
      isLocked: true
    }));

    setState(p => ({
      ...p,
      attendance: [
        ...p.attendance.filter(a => !(a.sessionId === selectedSessionId && localRecords[a.personId])),
        ...newRecords
      ],
    }));

    addLog?.('حفظ الحضور', `تم تثبيت سجل حضور تمرين ${activeSession?.objective}`, 'success');
    setLocalRecords({});
    alert('تم حفظ السجل بنجاح وقفل البيانات');
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row gap-6 items-end no-print relative overflow-hidden">
        <div className="flex-1 space-y-2 w-full">
           <label className="text-[10px] font-black text-slate-900 uppercase">اختيار جلسة التمرين</label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-100 border-2 border-slate-900 rounded-xl p-4 font-black text-xl text-slate-900 outline-none">
             <option value="">-- اختر التمرين من القائمة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective}</option>)}
           </select>
        </div>
        <button 
          onClick={saveAttendance} 
          disabled={!selectedSessionId}
          className="bg-[#001F3F] text-white px-10 py-5 rounded-2xl font-black text-lg shadow-xl disabled:opacity-30 flex items-center gap-2 border-b-4 border-black"
        >
          <Save size={24} /> تثبيت السجل النهائي
        </button>
      </div>

      {activeSession && (
        <div className="bg-white rounded-[2.5rem] shadow-sm border-2 border-slate-900 overflow-hidden">
          <table className="w-full text-right min-w-[800px]">
            <thead className="bg-slate-200 border-b-2 border-slate-900">
              <tr>
                <th className="px-6 py-4 text-[10px] font-black uppercase">اللاعب</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-center">رصد الحالة</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase">التوقيت</th>
              </tr>
            </thead>
            <tbody className="divide-y-2 divide-slate-200">
              {players.map(p => {
                const saved = savedRecords.find(r => r.personId === p.id);
                const local = localRecords[p.id];
                const currentStatus = local?.status || saved?.status;
                const currentTime = local?.time || saved?.time;
                return (
                  <tr key={p.id}>
                    <td className="px-6 py-5 border-l-2 border-slate-100">
                      <span className="font-black text-[15px]">{p.name} (#{p.number})</span>
                    </td>
                    <td className="px-6 py-5">
                      <div className="flex justify-center gap-2">
                        {['حاضر', 'متأخر', 'غائب', 'غياب بعذر'].map(st => (
                          <button 
                            key={st} 
                            onClick={() => handleSetStatus(p.id, st as AttendanceStatus)}
                            className={`px-4 py-2 rounded-lg text-[9px] font-black border-2 ${currentStatus === st ? `bg-slate-900 text-white border-slate-900` : 'bg-white text-slate-900 border-slate-300'}`}
                          >
                            {st}
                          </button>
                        ))}
                      </div>
                    </td>
                    <td className="px-6 py-5">
                       <span className="font-black text-[10px] text-slate-900 bg-slate-100 px-3 py-1 rounded-lg border border-slate-200">{currentTime || '--:--'}</span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

import React, { useState } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';
import { generateUUID } from '../App';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const canEdit = isManager || (currentUser?.role === 'إداري فئة' && !!restrictedCat);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [showReport, setShowReport] = useState<TrainingSession | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'رجال')
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time || !formData.location) return;

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث تمرين فئة ${formData.category}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const filteredSessions = (restrictedCat 
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-900 font-black text-md">أجندة الحصص التدريبية</h3>
        {canEdit && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-[#001F3F] text-white px-6 py-2 rounded-xl flex items-center gap-2 font-black shadow-lg">
            <Plus size={20} /> إضافة حصة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 hover:border-[#001F3F] transition-all no-print">
            <h4 className="font-black text-lg text-slate-900 mb-4">{session.objective}</h4>
            <p className="text-xs font-black text-slate-500">{session.date} | {session.time}</p>
            <div className="mt-5 flex gap-2">
              <button onClick={() => setShowReport(session)} className="flex-1 bg-slate-100 border-2 border-slate-900 text-slate-900 py-2 rounded-xl font-black text-[10px]">تقرير التمرين</button>
            </div>
            {canEdit && (
              <button onClick={() => {setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true);}} className="absolute top-4 left-4 opacity-0 group-hover:opacity-100 p-2 bg-slate-100 rounded-lg"><Edit size={16}/></button>
            )}
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center z-[200] p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden border-4 border-slate-900 p-8">
            <form onSubmit={handleSave} className="space-y-4">
              <input type="date" required value={formData.date || ''} className="w-full bg-slate-100 border-2 border-slate-900 rounded-2xl p-4 font-black" onChange={e => setFormData({ ...formData, date: e.target.value })} />
              <input type="time" required value={formData.time || ''} className="w-full bg-slate-100 border-2 border-slate-900 rounded-2xl p-4 font-black" onChange={e => setFormData({ ...formData, time: e.target.value })} />
              <input type="text" required value={formData.location || ''} placeholder="المكان..." className="w-full bg-slate-100 border-2 border-slate-900 rounded-2xl p-4 font-black" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              <input type="text" value={formData.objective || ''} placeholder="الهدف..." className="w-full bg-slate-100 border-2 border-slate-900 rounded-2xl p-4 font-black" onChange={e => setFormData({ ...formData, objective: e.target.value })} />
              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-4 rounded-2xl shadow-xl">حفظ التمرين</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, Printer, FileText } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
