import React, { useState } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';
import { generateUUID } from '../App';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  const isManager = currentUser?.role === 'مدير';
  const canEdit = isManager || (currentUser?.role === 'إداري فئة' && !!restrictedCat);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [showReport, setShowReport] = useState<TrainingSession | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'رجال')
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time || !formData.location) return;

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث تمرين فئة ${formData.category}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const filteredSessions = (restrictedCat 
    ? state.sessions.filter(s => s.category === restrictedCat)
    : state.sessions).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center no-print">
        <h3 className="text-slate-900 font-black text-md">أجندة الحصص التدريبية المجدولة</h3>
        {canEdit && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-[#001F3F] text-white px-6 py-2 rounded-xl flex items-center gap-2 font-black shadow-lg hover:bg-black transition-all">
            <Plus size={20} /> إضافة حصة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => (
          <div key={session.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 hover:border-[#001F3F] transition-all no-print">
            <h4 className="font-black text-lg text-slate-900 mt-1">{session.objective}</h4>
            <div className="mt-5 flex gap-2">
              <button onClick={() => setShowReport(session)} className="flex-1 bg-slate-100 border-2 border-slate-900 text-slate-900 py-2 rounded-xl font-black text-[10px] flex items-center justify-center gap-2 hover:bg-white transition-all">
                <FileText size={14}/> تقرير التمرين
              </button>
              {canEdit && (
                <button onClick={() => {setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true);}} className="p-2 bg-[#001F3F] text-white rounded-xl shadow-md"><Edit size={16}/></button>
              )}
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center z-[200] p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden border-4 border-slate-900">
            <div className="p-8 border-b-2 bg-slate-50 flex justify-between items-center rounded-t-[2.2rem]">
              <h3 className="text-xl font-black text-slate-900 uppercase">جدولة تمرين</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-4">
              <input type="date" required value={formData.date || ''} className="w-full bg-slate-100 border-2 border-slate-900 rounded-2xl p-4 font-black" onChange={e => setFormData({ ...formData, date: e.target.value })} />
              <input type="time" required value={formData.time || ''} className="w-full bg-slate-100 border-2 border-slate-900 rounded-2xl p-4 font-black" onChange={e => setFormData({ ...formData, time: e.target.value })} />
              <input type="text" required value={formData.location || ''} placeholder="المكان..." className="w-full bg-slate-100 border-2 border-slate-900 rounded-2xl p-4 font-black" onChange={e => setFormData({ ...formData, location: e.target.value })} />
              <input type="text" value={formData.objective || ''} placeholder="الهدف..." className="w-full bg-slate-100 border-2 border-slate-900 rounded-2xl p-4 font-black" onChange={e => setFormData({ ...formData, objective: e.target.value })} />
              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-4 rounded-2xl shadow-xl">حفظ التمرين</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, Printer, FileText } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID } from '../App';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [showReport, setShowReport] = useState(false);
  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter 
  });

  const globalFilter = state.globalCategoryFilter;

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date || !formData.time || !formData.category) {
      alert("يرجى ملء جميع الحقول المطلوبة");
      return;
    }

    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      location: formData.location || 'غير محدد',
      date: formData.date,
      time: formData.time,
      category: formData.category,
      advancePayment: formData.advancePayment || '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({name:'', number:''}), subs: [], staff: [], captain: '' }
    };

    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة جديدة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const getPlayerNumber = (name: string) => {
    return state.people.find(p => p.name === name)?.number?.toString() || '';
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const updateEvent = (id: string, updates: Partial<MatchEvent>) => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.map(e => e.id === id ? { ...e, ...updates } : e)
    });
  };

  const removeEvent = (id: string) => {
    if (!activeMatch) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const filteredMatches = state.matches.filter(m => (globalFilter === 'الكل' || m.category === globalFilter));
  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1";

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-5 rounded-2xl shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print">
        <h3 className="text-md font-black text-slate-900">إدارة المواجهات المباشرة</h3>
        <button onClick={() => setIsAddOpen(true)} className="bg-orange-600 text-white px-5 py-2 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg">
          <Plus size={16} /> جدولة مواجهة جديدة
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
        {filteredMatches.map(m => (
          <div key={m.id} className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-[6px] border-[#001F3F] transition-all no-print">
             <div className="flex justify-between items-center mb-4">
                <span className="text-[9px] font-black bg-[#001F3F] text-white px-2.5 py-1 rounded-lg uppercase">{m.opponent}</span>
             </div>
             <div className="flex gap-2 w-full xl:w-auto mt-4">
               <button onClick={() => { setActiveMatch(m); setShowReport(true); }} className="flex-1 bg-white border-2 border-slate-900 text-slate-900 px-3 py-2 rounded-lg text-[9px] font-black">التقرير</button>
               <button onClick={() => { setActiveMatch(m); setShowReport(false); }} className="flex-1 bg-[#001F3F] text-white px-4 py-2 rounded-lg text-[9px] font-black">إدارة</button>
             </div>
          </div>
        ))}
      </div>

      {isAddOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-md flex items-center justify-center z-[250] p-6 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-4 border-slate-900 p-6">
             <form onSubmit={handleAdd} className="space-y-4">
               <input required type="text" placeholder="الخصم..." value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} className={fieldClass} />
               <input required type="date" value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} className={fieldClass} />
               <input required type="time" value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} className={fieldClass} />
               <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-4 rounded-xl shadow-lg uppercase">تثبيت المواجهة</button>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

