import React, { useState } from 'react';
import { ShieldCheck, CloudUpload, Trash2, Key, Info, UserPlus, X, Edit2, ShieldAlert, Layers, Plus, Database } from 'lucide-react';
import { AppState, AppUser, UserRole, Category } from '../types';
import { generateUUID } from '../App';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState, addLog }) => {
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newCatName, setNewCatName] = useState('');

  const [userFormData, setUserFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'إداري فئة'
  });

  const roles: UserRole[] = ['مدير', 'إداري فئة', 'مشاهد'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.username) return;

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...userFormData } as AppUser : u)
      }));
      addLog?.('تعديل صلاحية مستخدم', `تم تحديث بيانات المستخدم: ${userFormData.username}`);
    } else {
      const newUser: AppUser = {
        id: generateUUID(),
        username: userFormData.username!,
        role: userFormData.role as UserRole,
        password: 'KSC' + (Math.floor(Math.random() * 9000) + 1000),
        restrictedCategory: userFormData.role === 'مدير' ? undefined : userFormData.restrictedCategory
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
      addLog?.('إنشاء حساب مستخدم', `تم إنشاء مستخدم جديد بنجاح: ${newUser.username}`, 'success');
    }

    setIsUserModalOpen(false);
    setEditingUserId(null);
    setUserFormData({ username: '', role: 'إداري فئة' });
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('هذه الفئة موجودة مسبقاً في النظام.');

    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة رياضية', `تم إدراج فئة جديدة بالنظام: ${newCatName.trim()}`, 'success');
    setNewCatName('');
  };

  const removeCategory = (cat: string) => {
    if (confirm(`هل أنت متأكد من حذف فئة ${cat}؟ سيتم فصل كافة اللاعبين المرتبطين بها.`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
      addLog?.('حذف فئة رياضية', `تم مسح الفئة: ${cat}`, 'warning');
    }
  };

  const exportData = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `alkaramah_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    addLog?.('تصدير قاعدة البيانات', 'تم إنشاء وتنزيل نسخة احتياطية شاملة للنظام.');
  };

  return (
    <div className="max-w-6xl mx-auto space-y-12 pb-24">
      <div className="bg-white p-12 rounded-[4rem] shadow-sm border border-slate-100">
        <h3 className="text-3xl font-black text-slate-800 mb-10">إدارة الفئات</h3>
        <div className="flex flex-col md:flex-row gap-6 mb-12">
          <input 
            type="text" 
            value={newCatName} 
            onChange={e => setNewCatName(e.target.value)}
            placeholder="فئة جديدة..."
            className="flex-1 bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-2xl outline-none"
          />
          <button 
            onClick={handleAddCategory}
            className="bg-[#001F3F] text-white px-12 py-6 rounded-[2rem] font-black"
          >
            إضافة الفئة
          </button>
        </div>
      </div>

      <div className="bg-[#001F3F] p-16 rounded-[5rem] shadow-2xl relative overflow-hidden">
        <button onClick={exportData} className="w-full bg-white text-[#001F3F] font-black py-8 rounded-[2.5rem] flex items-center justify-center gap-5 text-2xl">
          تصدير قاعدة البيانات (JSON)
        </button>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/90 backdrop-blur-3xl flex items-center justify-center z-[200] p-6 no-print">
          <div className="bg-white rounded-[5rem] w-full max-w-2xl shadow-2xl border-[10px] border-white p-12">
            <form onSubmit={handleSaveUser} className="space-y-6">
              <input required type="text" value={userFormData.username || ''} onChange={e => setUserFormData({ ...userFormData, username: e.target.value })}
                className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] py-6 px-10 font-black text-2xl" placeholder="اسم المستخدم" />
              <select className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2rem] p-6 font-black text-xl"
                value={userFormData.role} onChange={e => setUserFormData({ ...userFormData, role: e.target.value as UserRole })}>
                {roles.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-6 rounded-[2.5rem] shadow-2xl text-2xl">تثبيت الحساب</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SettingsView;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  location: string;
  objective: string;
  isCompleted?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury';
  player: string; // الاسم أو ID
  minute: string;
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  location: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string }[];
    subs: { playerId: string; name: string; number: string }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React, { useState, useMemo } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID } from '../App';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter 
  });

  const matchTypes: MatchType[] = ['دوري', 'كأس', 'ودية', 'بطولة ودية', 'مباراة دولية'];

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter));
  }, [state.matches, state.globalCategoryFilter]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date || !formData.time || !formData.category) return;

    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      location: formData.location || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time,
      category: formData.category,
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { 
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '' })), 
        subs: [], 
        staff: [], 
        captain: '' 
      },
      notes: ''
    };

    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ${newMatch.matchType} ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      newLineup.starters[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    } else {
      // Logic for adding subs is handled separately via button
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addSub = () => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '' }]
      }
    });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
      note: ''
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const saveMatchDetails = () => {
    if (!activeMatch) return;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? activeMatch : m)
    }));
    addLog?.('تحديث المباراة', `تم حفظ تفاصيل مباراة ${activeMatch.opponent}`, 'info');
    setActiveMatch(null);
  };

  // Prevent duplicate players in dropdowns
  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId)
    ].filter(id => id && id !== currentId);

    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-[#001F3F] mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      {/* Header Section */}
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
           <h2 className="text-xl font-black text-slate-900 flex items-center gap-3">
             <Trophy size={24} className="text-orange-600" /> إدارة أجندة المباريات
           </h2>
           <p className="text-[10px] font-black text-slate-400 mt-1">تنسيق التشكيل، الأهداف، والبطاقات للفئات العمرية</p>
        </div>
        <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg border-b-4 border-black hover:bg-black transition-all">
          <Plus size={20} /> جدولة مواجهة جديدة
        </button>
      </div>

      {/* Matches Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 hover:border-orange-600 transition-all">
             <div className="flex justify-between items-start mb-6">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400 flex items-center gap-1"><Calendar size={12}/> {m.date}</span>
             </div>

             <div className="flex items-center justify-between gap-4 mb-8">
                <div className="text-center flex-1">
                   <div className="w-14 h-14 bg-slate-100 border-2 border-slate-900 rounded-2xl flex items-center justify-center mx-auto mb-2 font-black text-xl">K</div>
                   <p className="font-black text-xs">الكرامة</p>
                </div>
                <div className="text-center px-4">
                   <p className="text-3xl font-black text-slate-900">{m.ourScore} - {m.opponentScore}</p>
                   <p className="text-[9px] font-black text-slate-400 uppercase mt-2">{m.time}</p>
                </div>
                <div className="text-center flex-1">
                   <div className="w-14 h-14 bg-slate-100 border-2 border-slate-900 rounded-2xl flex items-center justify-center mx-auto mb-2 font-black text-xl">{m.opponent.charAt(0)}</div>
                   <p className="font-black text-xs truncate max-w-[80px]">{m.opponent}</p>
                </div>
             </div>

             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 hover:bg-black">
                  <BookOpen size={16}/> إدارة المباراة
                </button>
                <button onClick={() => { if(confirm('حذف المباراة؟')) setState(p => ({...p, matches: p.matches.filter(x => x.id !== m.id)})) }} className="p-3 bg-red-50 text-red-600 rounded-xl border-2 border-red-900"><Trash2 size={16}/></button>
             </div>
          </div>
        ))}
      </div>

      {/* Add Match Modal */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-md flex items-center justify-center z-[300] p-4 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-[6px] border-slate-900 overflow-hidden">
             <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                <h3 className="font-black text-slate-900">جدولة مواجهة جديدة</h3>
                <button onClick={() => setIsAddOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
             </div>
             <form onSubmit={handleAddMatch} className="p-8 space-y-5">
                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className={labelClass}>الفئة</label>
                      <select required className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                   </div>
                   <div>
                      <label className={labelClass}>نوع المباراة</label>
                      <select required className={fieldClass} value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})}>
                        {matchTypes.map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                   </div>
                </div>
                <div>
                   <label className={labelClass}>اسم الخصم</label>
                   <input required type="text" className={fieldClass} value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className={labelClass}>التاريخ</label>
                      <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                   </div>
                   <div>
                      <label className={labelClass}>التوقيت</label>
                      <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                   </div>
                </div>
                <button type="submit" className="w-full bg-[#001F3F] text-white py-4 rounded-xl font-black shadow-xl hover:bg-black transition-all mt-4 uppercase">تثبيت الجدولة</button>
             </form>
          </div>
        </div>
      )}

      {/* Match Management Panel (Advanced) */}
      {activeMatch && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl z-[400] overflow-y-auto custom-scrollbar p-4 lg:p-10 no-print">
           <div className="max-w-6xl mx-auto bg-white rounded-[3rem] border-[8px] border-slate-900 min-h-screen flex flex-col shadow-2xl">
              <header className="p-8 border-b-4 border-slate-900 bg-slate-50 flex flex-col md:flex-row justify-between items-center gap-6">
                 <div className="flex items-center gap-4">
                    <div className="bg-[#001F3F] text-white w-16 h-16 rounded-2xl flex items-center justify-center font-black text-2xl border-4 border-slate-900">K</div>
                    <div>
                       <h2 className="text-2xl font-black text-slate-900">إدارة تفاصيل المباراة</h2>
                       <p className="text-sm font-black text-orange-600 tracking-widest uppercase">نادي الكرامة × {activeMatch.opponent}</p>
                    </div>
                 </div>
                 <div className="flex gap-3">
                    <button onClick={saveMatchDetails} className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-black flex items-center gap-2 border-b-4 border-black hover:bg-emerald-700">
                       <Save size={20}/> حفظ التغييرات
                    </button>
                    <button onClick={() => setActiveMatch(null)} className="bg-red-50 text-red-600 px-6 py-3 rounded-xl font-black border-2 border-red-900">
                       إلغاء
                    </button>
                 </div>
              </header>

              <div className="flex-1 p-8 grid grid-cols-1 lg:grid-cols-3 gap-10">
                 {/* Right Column: Lineup */}
                 <div className="lg:col-span-2 space-y-10">
                    <section>
                       <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                          <Users size={22}/> التشكيل الأساسي (11 لاعب)
                       </h3>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {activeMatch.lineup.starters.map((s, idx) => (
                             <div key={idx} className="flex items-center gap-3 bg-slate-50 p-3 rounded-xl border-2 border-slate-200">
                                <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-xs shrink-0">{idx + 1}</span>
                                <select 
                                  className="flex-1 bg-white border-2 border-slate-300 rounded-lg p-2 font-black text-xs outline-none focus:border-blue-600"
                                  value={s.playerId}
                                  onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}
                                >
                                   <option value="">-- اختر اللاعب --</option>
                                   {getAvailablePlayers(s.playerId).map(p => (
                                      <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                   ))}
                                </select>
                                <div className="w-12 text-center bg-white border-2 border-slate-300 rounded-lg p-2 font-black text-xs">
                                   #{s.number || '--'}
                                </div>
                             </div>
                          ))}
                       </div>
                    </section>

                    <section>
                       <div className="flex justify-between items-center mb-6">
                          <h3 className="text-lg font-black text-slate-900 flex items-center gap-3 border-r-4 border-blue-900 pr-4">
                             <UserPlus size={22}/> قائمة البدلاء
                          </h3>
                          <button onClick={addSub} className="bg-blue-900 text-white px-4 py-2 rounded-lg font-black text-xs flex items-center gap-2">
                             <Plus size={16}/> إضافة بديل
                          </button>
                       </div>
                       <div className="space-y-3">
                          {activeMatch.lineup.subs.map((s, idx) => (
                             <div key={idx} className="flex items-center gap-3 bg-blue-50/50 p-3 rounded-xl border-2 border-blue-100">
                                <select 
                                  className="flex-1 bg-white border-2 border-slate-300 rounded-lg p-2 font-black text-xs"
                                  value={s.playerId}
                                  onChange={e => updateSub(idx, e.target.value)}
                                >
                                   <option value="">-- اختر البديل --</option>
                                   {getAvailablePlayers(s.playerId).map(p => (
                                      <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                   ))}
                                </select>
                                <div className="w-12 text-center bg-white border-2 border-slate-300 rounded-lg p-2 font-black text-xs">#{s.number || '--'}</div>
                                <button onClick={() => {
                                   const newSubs = activeMatch.lineup.subs.filter((_, i) => i !== idx);
                                   setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: newSubs}});
                                }} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                             </div>
                          ))}
                       </div>
                    </section>
                 </div>

                 {/* Left Column: Events & Score */}
                 <div className="space-y-10">
                    <section className="bg-slate-900 text-white p-8 rounded-[2rem] border-4 border-orange-600 shadow-xl">
                       <h3 className="text-center font-black text-sm uppercase tracking-widest mb-6 text-orange-400">النتيجة النهائية</h3>
                       <div className="flex items-center justify-center gap-6">
                          <input type="number" className="w-20 h-20 bg-white text-slate-900 rounded-2xl text-center font-black text-4xl border-4 border-orange-600 outline-none" 
                            value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                          <span className="text-4xl font-black">:</span>
                          <input type="number" className="w-20 h-20 bg-white text-slate-900 rounded-2xl text-center font-black text-4xl border-4 border-slate-300 outline-none" 
                            value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                       </div>
                       <div className="mt-8">
                          <label className="flex items-center gap-3 cursor-pointer justify-center bg-white/10 p-4 rounded-xl">
                             <input type="checkbox" className="w-5 h-5 accent-orange-600" checked={activeMatch.isCompleted} onChange={e => setActiveMatch({...activeMatch, isCompleted: e.target.checked})} />
                             <span className="font-black text-xs uppercase">تم تأكيد انتهاء المباراة</span>
                          </label>
                       </div>
                    </section>

                    <section className="space-y-4">
                       <div className="flex justify-between items-center mb-4">
                          <h3 className="text-md font-black text-slate-900 flex items-center gap-2">
                             <Target size={20} className="text-orange-600"/> أحداث المباراة
                          </h3>
                       </div>
                       <div className="grid grid-cols-2 gap-2">
                          <button onClick={() => addEvent('goal')} className="bg-emerald-50 text-emerald-700 p-3 rounded-xl font-black text-[10px] border-2 border-emerald-200 hover:bg-emerald-100 uppercase">⚽ هدف</button>
                          <button onClick={() => addEvent('assist')} className="bg-blue-50 text-blue-700 p-3 rounded-xl font-black text-[10px] border-2 border-blue-200 hover:bg-blue-100 uppercase">👟 صناعة</button>
                          <button onClick={() => addEvent('yellow')} className="bg-yellow-50 text-yellow-700 p-3 rounded-xl font-black text-[10px] border-2 border-yellow-200 hover:bg-yellow-100 uppercase">🟨 بطاقة صفراء</button>
                          <button onClick={() => addEvent('red')} className="bg-red-50 text-red-700 p-3 rounded-xl font-black text-[10px] border-2 border-red-200 hover:bg-red-100 uppercase">🟥 بطاقة حمراء</button>
                       </div>

                       <div className="space-y-3 mt-6 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
                          {activeMatch.events.map((ev, idx) => (
                             <div key={ev.id} className="bg-slate-50 p-4 rounded-xl border-2 border-slate-200 space-y-3">
                                <div className="flex justify-between items-center">
                                   <span className="text-[10px] font-black uppercase flex items-center gap-1">
                                      {ev.type === 'goal' && '⚽ هدف للكرامة'}
                                      {ev.type === 'assist' && '👟 تمريرة حاسمة'}
                                      {ev.type === 'yellow' && '🟨 إنذار أصفر'}
                                      {ev.type === 'red' && '🟥 طرد مباشر'}
                                   </span>
                                   <button onClick={() => removeEvent(ev.id)} className="text-red-500"><X size={14}/></button>
                                </div>
                                <div className="flex gap-2">
                                   <select className="flex-1 bg-white border border-slate-300 rounded-lg p-2 text-[10px] font-black"
                                     value={ev.player} onChange={e => {
                                       const updatedEvents = [...activeMatch.events];
                                       updatedEvents[idx].player = e.target.value;
                                       setActiveMatch({...activeMatch, events: updatedEvents});
                                     }}>
                                      <option value="">-- اختر اللاعب --</option>
                                      {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => (
                                         <option key={p.id} value={p.name}>{p.name} (#{p.number})</option>
                                      ))}
                                   </select>
                                   <input type="text" placeholder="دقيقة.." className="w-16 bg-white border border-slate-300 rounded-lg p-2 text-[10px] font-black text-center" 
                                     value={ev.minute} onChange={e => {
                                       const updatedEvents = [...activeMatch.events];
                                       updatedEvents[idx].minute = e.target.value;
                                       setActiveMatch({...activeMatch, events: updatedEvents});
                                     }} />
                                </div>
                             </div>
                          ))}
                       </div>
                    </section>

                    <section>
                       <label className={labelClass}>ملاحظات فنية وإدارية للمباراة</label>
                       <textarea className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-4 font-black text-xs h-32 outline-none" 
                         value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})} placeholder="اكتب تقريرك المختصر هنا..."></textarea>
                    </section>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

