import React, { useState, useMemo } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle, ShieldCheck, Lock, AlertCircle } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';
import { generateUUID } from '../App';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // Strict Role Control
  const isManager = currentUser?.role === 'مدير';
  const canModifyConfig = isManager; // Only manager can add/edit/delete sessions

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'الرجال'),
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time || !formData.location) return;

    // Time validation: Prevent past dates
    const selectedDateTime = new Date(`${formData.date}T${formData.time}`);
    const now = new Date();
    if (!editingSessionId && selectedDateTime < now) {
      alert("لا يمكن جدولة تمرين في وقت سابق.");
      return;
    }

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث تمرين فئة ${formData.category}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين جديد لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const filteredSessions = useMemo(() => {
    return (restrictedCat 
      ? state.sessions.filter(s => s.category === restrictedCat)
      : state.sessions).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.sessions, restrictedCat]);

  // Check if session is older than 30 minutes for locking UI
  const isSessionLocked = (session: TrainingSession) => {
    const sessionTime = new Date(`${session.date}T${session.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  };

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-4 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
           <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
             <Calendar size={24} className="text-blue-900" /> أجندة التدريبات المركزية
           </h3>
           <p className="text-[10px] font-black text-slate-400 mt-1">تنظيم المواعيد، المواقع والأهداف الفنية للحصص</p>
        </div>
        {canModifyConfig && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-[#001F3F] text-white px-8 py-3 rounded-xl flex items-center gap-2 font-black text-sm shadow-lg border-b-4 border-black hover:bg-black transition-all">
            <Plus size={20} /> إضافة حصة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => {
          const locked = isSessionLocked(session);
          return (
            <div key={session.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 transition-all no-print ${locked ? 'border-slate-300 opacity-80' : 'hover:border-blue-900'}`}>
              <div className="flex justify-between items-center mb-4">
                 <span className="bg-[#001F3F] text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{session.category}</span>
                 {locked ? (
                   <span className="text-[9px] font-black text-red-600 flex items-center gap-1 bg-red-50 px-2 py-1 rounded-lg"><Lock size={12}/> مغلق (مضى 30 د)</span>
                 ) : (
                   <span className="text-[9px] font-black text-emerald-600 flex items-center gap-1 bg-emerald-50 px-2 py-1 rounded-lg"><ShieldCheck size={12}/> متاح للرصد</span>
                 )}
              </div>

              <h4 className="font-black text-lg text-slate-900 leading-tight mb-4">{session.objective}</h4>

              <div className="space-y-2 mb-6">
                 <div className="flex items-center gap-2 text-[11px] font-black text-slate-600">
                    <Clock size={14} className="text-orange-600"/> {session.time} • {session.date}
                 </div>
                 <div className="flex items-center gap-2 text-[11px] font-black text-slate-600">
                    <MapPin size={14} className="text-blue-900"/> {session.location}
                 </div>
              </div>

              <div className="flex gap-2">
                <div className="flex-1 bg-slate-100 border-2 border-slate-900 text-slate-900 py-2.5 rounded-xl font-black text-[10px] flex items-center justify-center gap-2">
                  <FileText size={14}/> تفاصيل التمرين
                </div>
                {canModifyConfig && (
                  <div className="flex gap-1">
                    <button onClick={() => {setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true);}} className="p-2.5 bg-blue-50 text-blue-900 rounded-xl border-2 border-blue-900 hover:bg-blue-900 hover:text-white"><Edit size={16}/></button>
                    <button onClick={() => { if(confirm('حذف التمرين؟')) setState(p => ({...p, sessions: p.sessions.filter(x => x.id !== session.id)})) }} className="p-2.5 bg-red-50 text-red-600 rounded-xl border-2 border-red-900 hover:bg-red-600 hover:text-white"><Trash2 size={16}/></button>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center z-[200] p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden border-[6px] border-slate-900">
            <div className="p-8 border-b-2 bg-slate-100 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-900 uppercase">تخطيط حصة تدريبية</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-white p-2 rounded-xl border-2 border-slate-900"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-5">
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className={labelClass}>الفئة</label>
                    <select required className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                 </div>
                 <div>
                    <label className={labelClass}>الموقع</label>
                    <input type="text" required placeholder="ملعب الكرامة.." className={fieldClass} value={formData.location || ''} onChange={e => setFormData({ ...formData, location: e.target.value })} />
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className={labelClass}>تاريخ التمرين</label>
                    <input type="date" required className={fieldClass} value={formData.date || ''} onChange={e => setFormData({ ...formData, date: e.target.value })} />
                 </div>
                 <div>
                    <label className={labelClass}>التوقيت</label>
                    <input type="time" required className={fieldClass} value={formData.time || ''} onChange={e => setFormData({ ...formData, time: e.target.value })} />
                 </div>
              </div>
              <div>
                 <label className={labelClass}>الهدف التدريبي (المحتوى)</label>
                 <textarea required rows={3} placeholder="مثال: تحسين إنهاء الهجمات.." className={`${fieldClass} py-3 h-24`} value={formData.objective || ''} onChange={e => setFormData({ ...formData, objective: e.target.value })}></textarea>
              </div>

              <div className="bg-orange-50 p-4 rounded-xl border-2 border-orange-200 flex gap-3 items-start">
                 <AlertCircle className="text-orange-600 shrink-0" size={18}/>
                 <p className="text-[10px] font-black text-orange-900 leading-relaxed">سيتم قفل رصد الحضور لهذا التمرين تلقائياً بعد مضي 30 دقيقة من الموعد المحدد أعلاه.</p>
              </div>

              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-5 rounded-2xl shadow-xl border-b-4 border-black hover:bg-black transition-all uppercase tracking-widest">حفظ وتثبيت التمرين</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useMemo } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord } from '../types';
import ClubLogo from './ClubLogo';

interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';

  const calculateAge = (birthDate?: string) => {
    if (!birthDate) return null;
    const birth = new Date(birthDate);
    const today = new Date();
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
    return age;
  };

  const matchStats = useMemo(() => {
    if (isStaff) return { played: 0, goals: 0, assists: 0, yellows: 0, reds: 0, minutes: 0, list: [] };

    let totalMinutes = 0;
    const statsList = state.matches.filter(m => m.isCompleted).map(m => {
      const starter = m.lineup.starters.find(s => s.playerId === player.id);
      const sub = m.lineup.subs.find(s => s.playerId === player.id);

      let mins = 0;
      if (starter) mins = 90;
      else if (sub) mins = 20; // Default estimate for subs

      totalMinutes += mins;

      const goals = m.events.filter(e => e.type === 'goal' && e.player === player.name).length;
      const assists = m.events.filter(e => e.type === 'assist' && e.player === player.name).length;
      const yellow = m.events.filter(e => e.type === 'yellow' && e.player === player.name).length;
      const red = m.events.filter(e => e.type === 'red' && e.player === player.name).length;

      return { opponent: m.opponent, date: m.date, mins, goals, assists, yellow, red, played: !!(starter || sub) };
    }).filter(s => s.played);

    return {
      played: statsList.length,
      goals: statsList.reduce((a, b) => a + b.goals, 0),
      assists: statsList.reduce((a, b) => a + b.assists, 0),
      yellows: statsList.reduce((a, b) => a + b.yellow, 0),
      reds: statsList.reduce((a, b) => a + b.red, 0),
      minutes: totalMinutes,
      list: statsList
    };
  }, [state.matches, player, isStaff]);

  const attendanceData = useMemo(() => {
    const records = state.attendance.filter(a => a.personId === player.id);
    const sessions = state.sessions.filter(s => s.category === player.category);

    const present = records.filter(r => r.status === 'حاضر').length;
    const late = records.filter(r => r.status === 'متأخر').length;
    const absent = records.filter(r => r.status === 'غائب').length;
    const excused = records.filter(r => r.status === 'غياب بعذر').length;

    const rate = sessions.length > 0 ? Math.round(((present + late * 0.7) / sessions.length) * 100) : 0;

    return { records, present, late, absent, excused, rate, total: sessions.length };
  }, [state.attendance, state.sessions, player]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-24">
      {/* Navbar Actions */}
      <div className="flex justify-between items-center no-print">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-500 hover:text-blue-900 font-black transition-all">
          <ChevronRight size={20} /> العودة للفريق
        </button>
        <div className="flex items-center gap-4">
           <span className="text-xs font-black text-slate-400">نظام الكرامة الذكي | الملف الفني</span>
           <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg hover:bg-black transition-all">
             <Printer size={18} /> طباعة التقرير / PDF
           </button>
        </div>
      </div>

      {/* Main Identity Card */}
      <div className="bg-white rounded-[3rem] shadow-xl border-4 border-slate-900 overflow-hidden relative">
        <div className="bg-[#001F3F] h-32 relative">
          <div className="absolute top-6 left-10 opacity-10">
             <ClubLogo size={180} />
          </div>
          <div className="absolute -bottom-16 right-12 flex items-end gap-6">
            <div className="w-40 h-40 bg-white rounded-[2.5rem] shadow-2xl border-8 border-white flex items-center justify-center overflow-hidden font-black text-6xl text-blue-900 uppercase">
               {player.name.charAt(0)}
            </div>
            <div className="mb-4">
              <h1 className="text-3xl font-black text-white drop-shadow-lg">{player.name}</h1>
              <div className="flex gap-2 mt-2">
                 <span className="bg-orange-600 text-white text-[10px] font-black px-4 py-1 rounded-full uppercase border-2 border-white shadow-md">{player.role}</span>
                 <span className="bg-blue-600 text-white text-[10px] font-black px-4 py-1 rounded-full uppercase border-2 border-white shadow-md">{player.category}</span>
              </div>
            </div>
          </div>
        </div>
        <div className="h-20"></div>
        <div className="px-12 pb-10 grid grid-cols-1 md:grid-cols-4 gap-8">
           <div className="space-y-1">
             <p className="text-[10px] font-black text-slate-400 uppercase flex items-center gap-2"><MapPin size={14} className="text-orange-600"/> مكان وتاريخ الولادة</p>
             <p className="text-sm font-black text-slate-900">{player.birthPlace || '---'} | {player.birthDate} ({calculateAge(player.birthDate)} سنة)</p>
           </div>
           <div className="space-y-1">
             <p className="text-[10px] font-black text-slate-400 uppercase flex items-center gap-2"><Users size={14} className="text-blue-900"/> الأب والأم</p>
             <p className="text-sm font-black text-slate-900">{player.fatherName} / {player.motherName}</p>
           </div>
           <div className="space-y-1">
