           </div>
        </div>
      </div>

      {/* Statistics Section */}
      {!isStaff && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 bg-white p-8 rounded-[3rem] border-4 border-slate-900 shadow-sm">
             <h3 className="text-xl font-black text-slate-900 mb-8 flex items-center gap-3 border-r-8 border-orange-600 pr-4">
