import React, { useState, useMemo } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle, ShieldCheck, Lock, AlertCircle } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';
import { generateUUID } from '../App';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // Strict Role Control: Only Manager ('مدير') can add/edit/delete
  const isManager = currentUser?.role === 'مدير';
  const canModifyConfig = isManager; 

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'الرجال'),
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time || !formData.location) return;

    // Time validation: Prevent past dates/times
    const selectedDateTime = new Date(`${formData.date}T${formData.time}`);
    const now = new Date();
    if (!editingSessionId && selectedDateTime < now) {
      alert("تنبيه: لا يمكن جدولة تمرين في تاريخ أو وقت سابق للوقت الحالي.");
      return;
    }

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث بيانات تمرين فئة ${formData.category}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        location: formData.location || '',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين جديد لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const filteredSessions = useMemo(() => {
    return (restrictedCat 
      ? state.sessions.filter(s => s.category === restrictedCat)
      : state.sessions).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.sessions, restrictedCat]);

  // Check if session is older than 30 minutes for locking UI
  const isSessionLocked = (session: TrainingSession) => {
    const sessionTime = new Date(`${session.date}T${session.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  };

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-4 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
           <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
             <Calendar size={24} className="text-blue-900" /> أجندة التدريبات المركزية (الجدولة)
           </h3>
           <p className="text-[10px] font-black text-slate-400 mt-1">تنظيم مواعيد التدريب لجميع الفئات - ميزة التعديل محصورة بمدير المكتب</p>
        </div>
        {canModifyConfig && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-[#001F3F] text-white px-8 py-3 rounded-xl flex items-center gap-2 font-black text-sm shadow-lg border-b-4 border-black hover:bg-black transition-all">
            <Plus size={20} /> إضافة حصة تدريبية جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => {
          const locked = isSessionLocked(session);
          return (
            <div key={session.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 transition-all no-print ${locked ? 'border-slate-300 opacity-80' : 'hover:border-blue-900'}`}>
              <div className="flex justify-between items-center mb-4">
                 <span className="bg-[#001F3F] text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{session.category}</span>
                 {locked ? (
                   <span className="text-[9px] font-black text-red-600 flex items-center gap-1 bg-red-50 px-2 py-1 rounded-lg border border-red-200"><Lock size={12}/> مغلق إدارياً</span>
                 ) : (
                   <span className="text-[9px] font-black text-emerald-600 flex items-center gap-1 bg-emerald-50 px-2 py-1 rounded-lg border border-emerald-200"><ShieldCheck size={12}/> متاح للرصد</span>
                 )}
              </div>

              <h4 className="font-black text-lg text-slate-900 leading-tight mb-4">{session.objective}</h4>

              <div className="space-y-2 mb-6">
                 <div className="flex items-center gap-2 text-[11px] font-black text-slate-600">
                    <Clock size={14} className="text-orange-600"/> {session.time} • {session.date}
                 </div>
                 <div className="flex items-center gap-2 text-[11px] font-black text-slate-600">
                    <MapPin size={14} className="text-blue-900"/> {session.location}
                 </div>
              </div>

              <div className="flex gap-2">
                <div className="flex-1 bg-slate-100 border-2 border-slate-900 text-slate-900 py-2.5 rounded-xl font-black text-[10px] flex items-center justify-center gap-2">
                  <FileText size={14}/> تفاصيل التمرين
                </div>
                {canModifyConfig && (
                  <div className="flex gap-1">
                    <button onClick={() => {setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true);}} className="p-2.5 bg-blue-50 text-blue-900 rounded-xl border-2 border-blue-900 hover:bg-blue-900 hover:text-white transition-all"><Edit size={16}/></button>
                    <button onClick={() => { if(confirm('تنبيه: هل أنت متأكد من حذف هذا التمرين نهائياً؟')) setState(p => ({...p, sessions: p.sessions.filter(x => x.id !== session.id)})) }} className="p-2.5 bg-red-50 text-red-600 rounded-xl border-2 border-red-900 hover:bg-red-600 hover:text-white transition-all"><Trash2 size={16}/></button>
                  </div>
                )}
              </div>
            </div>
          );
        })}
        {filteredSessions.length === 0 && (
          <div className="col-span-full py-20 text-center bg-slate-50 border-4 border-dashed border-slate-200 rounded-[3rem]">
            <Calendar size={48} className="text-slate-200 mx-auto mb-4" />
            <p className="text-slate-400 font-black italic">لا يوجد تمارين مجدولة حالياً لهذه الفئة</p>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center z-[200] p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden border-[6px] border-slate-900">
            <div className="p-8 border-b-2 bg-slate-100 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-900 uppercase">جدولة حصة تدريبية مركزية</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-white p-2 rounded-xl border-2 border-slate-900"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-5">
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className={labelClass}>الفئة المستهدفة</label>
                    <select required className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                 </div>
                 <div>
                    <label className={labelClass}>الموقع الجغرافي</label>
                    <input type="text" required placeholder="ملعب الكرامة.." className={fieldClass} value={formData.location || ''} onChange={e => setFormData({ ...formData, location: e.target.value })} />
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className={labelClass}>تاريخ التمرين</label>
                    <input type="date" required className={fieldClass} value={formData.date || ''} onChange={e => setFormData({ ...formData, date: e.target.value })} />
                 </div>
                 <div>
                    <label className={labelClass}>التوقيت المعتمد</label>
                    <input type="time" required className={fieldClass} value={formData.time || ''} onChange={e => setFormData({ ...formData, time: e.target.value })} />
                 </div>
              </div>
              <div>
                 <label className={labelClass}>الهدف التدريبي الرئيسي</label>
                 <textarea required rows={3} placeholder="مثال: تحسين اللياقة البدنية والكرات العرضية.." className={`${fieldClass} py-3 h-24`} value={formData.objective || ''} onChange={e => setFormData({ ...formData, objective: e.target.value })}></textarea>
              </div>

              <div className="bg-orange-50 p-4 rounded-xl border-2 border-orange-200 flex gap-3 items-start">
                 <AlertCircle className="text-orange-600 shrink-0" size={18}/>
                 <div className="space-y-1">
                    <p className="text-[10px] font-black text-orange-900 leading-relaxed">تنبيه نظام الرقابة: سيتم قفل إمكانية رصد الحضور لهذا التمرين تلقائياً بعد مضي 30 دقيقة من الموعد المحدد.</p>
                 </div>
              </div>

              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-5 rounded-2xl shadow-xl border-b-4 border-black hover:bg-black transition-all uppercase tracking-widest text-lg">تثبيت الجدولة في النظام</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ClipboardCheck, Save, ShieldAlert, History, Search, ShieldCheck, Lock, Clock, Calendar as CalendarIcon, AlertCircle } from 'lucide-react';
import { AppState, AttendanceStatus, AttendanceRecord, TrainingSession } from '../types';
import { generateUUID } from '../App';

interface AttendanceTrackerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const AttendanceTracker: React.FC<AttendanceTrackerProps> = ({ state, setState, addLog }) => {
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [localRecords, setLocalRecords] = useState<Record<string, { status: AttendanceStatus; excuse?: string; time?: string; date?: string }>>({});

  const currentUser = state.currentUser!;
  const globalFilter = state.globalCategoryFilter;

  const sessions = state.sessions
    .filter(s => (globalFilter === 'الكل' || s.category === globalFilter))
    .sort((a, b) => b.date.localeCompare(a.date));

  const activeSession = state.sessions.find(s => s.id === selectedSessionId);
  const players = state.people.filter(p => p.role === 'لاعب' && (activeSession ? p.category === activeSession.category : true));
  const savedRecords = state.attendance.filter(r => r.sessionId === selectedSessionId);

  // Auto-lock check: Is session older than 30 minutes?
  const isLockedByTime = activeSession ? (() => {
    const sessionTime = new Date(`${activeSession.date}T${activeSession.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  })() : false;

  const handleSetStatus = (pid: string, status: AttendanceStatus) => {
    if (isLockedByTime) return;
    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
    const dateStr = now.toISOString().split('T')[0];

    setLocalRecords(prev => ({ 
      ...prev, 
      [pid]: { ...prev[pid], status, time: timeStr, date: dateStr } 
    }));
  };

  const handleSetExcuse = (pid: string, excuse: string) => {
    if (isLockedByTime) return;
    setLocalRecords(prev => ({
      ...prev,
      [pid]: { ...prev[pid], excuse }
    }));
  };

  const saveAttendance = () => {
    if (isLockedByTime) {
      alert("عذراً، تم قفل رصد الحضور لهذا التمرين بسبب تجاوز المهلة المسموحة (30 دقيقة).");
      return;
    }

    const entries = Object.entries(localRecords) as [string, { status: AttendanceStatus; excuse?: string; time?: string; date?: string }][];
    if (entries.length === 0) return alert('يرجى رصد حالات اللاعبين أولاً قبل التثبيت');

    const newRecords: AttendanceRecord[] = entries.map(([pid, data]) => ({
      id: generateUUID(),
      personId: pid,
      sessionId: selectedSessionId,
      date: data.date || activeSession!.date,
      time: data.time || (new Date().getHours().toString().padStart(2, '0') + ':' + new Date().getMinutes().toString().padStart(2, '0')),
      status: data.status,
      excuse: data.excuse,
      isLocked: true
    }));

    setState(p => ({
      ...p,
      attendance: [
        ...p.attendance.filter(a => !(a.sessionId === selectedSessionId && localRecords[a.personId])),
        ...newRecords
      ],
    }));

    addLog?.('حفظ الحضور', `تم تثبيت سجل حضور تمرين فئة ${activeSession?.category} - ${activeSession?.objective}`, 'success');
    setLocalRecords({});
    alert('تم حفظ وتثبيت سجل الحضور بنجاح في قاعدة البيانات.');
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row gap-6 items-end no-print relative overflow-hidden">
        <div className="absolute top-0 right-0 w-2 h-full bg-[#001F3F]"></div>
        <div className="flex-1 space-y-2 w-full">
           <label className="text-[10px] font-black text-slate-900 mr-2 uppercase tracking-widest flex items-center gap-2">
             <ClipboardCheck size={14} className="text-blue-900"/> اختيار جلسة التمرين المستهدفة
           </label>
           <select value={selectedSessionId} onChange={e => { setSelectedSessionId(e.target.value); setLocalRecords({}); }}
            className="w-full bg-slate-100 border-2 border-slate-900 rounded-xl p-4 font-black text-xl text-slate-900 outline-none focus:border-orange-600 transition-all">
             <option value="">-- اختر التمرين من القائمة --</option>
             {sessions.map(s => <option key={s.id} value={s.id}>{s.date} | {s.objective} ({s.category})</option>)}
           </select>
        </div>
        <button 
          onClick={saveAttendance} 
          disabled={!selectedSessionId || isLockedByTime}
          className="bg-[#001F3F] text-white px-10 py-5 rounded-2xl font-black text-lg shadow-xl hover:bg-black disabled:opacity-30 transition-all flex items-center gap-2 border-b-4 border-black"
        >
          <Save size={24} /> تثبيت الرصد النهائي
        </button>
      </div>

      {isLockedByTime && (
        <div className="bg-red-50 p-6 rounded-[2.5rem] border-4 border-red-900 flex items-center gap-4 shadow-lg animate-in slide-in-from-top duration-500">
           <div className="p-4 bg-red-900 text-white rounded-2xl"><Lock size={32}/></div>
           <div>
              <h3 className="text-xl font-black text-red-900">نظام الرقابة المركزي: السجل مقفل</h3>
              <p className="text-xs font-black text-red-700 mt-1 uppercase">مضى أكثر من 30 دقيقة على موعد الحصة التدريبية. لا يمكن تعديل أو إضافة رصد جديد حفاظاً على النزاهة.</p>
           </div>
        </div>
      )}

      {activeSession && (
        <div className={`bg-white rounded-[2.5rem] shadow-sm border-2 border-slate-900 overflow-hidden relative transition-all ${isLockedByTime ? 'opacity-70 pointer-events-none grayscale-[0.5]' : ''}`}>
          <div className="p-6 border-b-2 border-slate-900 bg-slate-100 flex justify-between items-center">
             <div className="flex items-center gap-4">
               <div className="w-14 h-14 bg-white border-2 border-slate-900 rounded-xl flex items-center justify-center font-black text-2xl text-[#001F3F] shadow-md uppercase">K</div>
               <div>
                 <h3 className="text-xl font-black text-slate-900 uppercase">{activeSession.objective}</h3>
                 <p className="text-[10px] font-black text-[#001F3F] uppercase tracking-widest">{activeSession.category} • {activeSession.date} • {activeSession.time}</p>
               </div>
             </div>
             {!isLockedByTime && (
               <div className="flex items-center gap-2 bg-emerald-50 text-emerald-700 px-4 py-2 rounded-xl border border-emerald-200">
                  <ShieldCheck size={18}/>
                  <span className="text-[10px] font-black uppercase tracking-tighter">رصد متاح حالياً</span>
               </div>
             )}
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[900px]">
              <thead className="bg-slate-200 border-b-2 border-slate-900">
                <tr>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">بيانات اللاعب</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest text-center">الحالة الانضباطية</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest text-center">التوقيت</th>
                  <th className="px-6 py-4 text-[10px] font-black text-slate-900 uppercase tracking-widest">العذر الإداري / ملاحظات</th>
                </tr>
              </thead>
              <tbody className="divide-y-2 divide-slate-200">
                {players.map(p => {
                  const saved = savedRecords.find(r => r.personId === p.id);
                  const local = localRecords[p.id];
                  const currentStatus = local?.status || saved?.status;
                  const currentTime = local?.time || saved?.time;
                  const currentExcuse = local?.excuse !== undefined ? local.excuse : (saved?.excuse || '');

                  return (
                    <tr key={p.id} className="hover:bg-blue-50/30 transition-all">
                      <td className="px-6 py-5 border-l-2 border-slate-100">
                        <div className="flex items-center gap-3">
                          <div className={`w-10 h-10 rounded-lg flex items-center justify-center font-black text-md border-2 border-slate-900 ${currentStatus ? 'bg-[#001F3F] text-white shadow-lg' : 'bg-white text-slate-900'}`}>
                            {p.number || '??'}
                          </div>
                          <span className="font-black text-[15px] text-slate-900 block">{p.name}</span>
                        </div>
                      </td>
                      <td className="px-6 py-5">
                        <div className="flex justify-center gap-2">
                          {['حاضر', 'متأخر', 'غائب', 'غياب بعذر'].map(st => (
                            <button 
                              key={st} 
                              onClick={() => handleSetStatus(p.id, st as AttendanceStatus)}
                              className={`px-4 py-2 rounded-lg text-[9px] font-black border-2 transition-all ${currentStatus === st ? 
                                `bg-slate-900 text-white border-slate-900 scale-105 z-10 shadow-lg` 
                                : 'bg-white text-slate-900 border-slate-300 hover:border-slate-900'}`}
                            >
                              {st}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-6 py-5 text-center">
                        <span className="font-black text-[10px] text-slate-900 bg-slate-100 px-3 py-1 rounded-lg border border-slate-200">{currentTime || '--:--'}</span>
                      </td>
                      <td className="px-6 py-5">
                        <input 
                          type="text" 
                          placeholder="اكتب العذر أو الملاحظة هنا..." 
                          value={currentExcuse}
                          onChange={e => handleSetExcuse(p.id, e.target.value)}
                          className="bg-white border-2 border-slate-200 rounded-lg px-4 py-2 text-[10px] font-black w-full outline-none focus:border-[#001F3F] text-slate-900 placeholder:text-slate-400" 
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {players.length === 0 && (
            <div className="p-20 text-center">
               <AlertCircle className="mx-auto text-slate-200 mb-4" size={48}/>
               <p className="text-slate-400 font-black italic">لا يوجد لاعبين مسجلين في هذه الفئة حالياً</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AttendanceTracker;

import React, { useMemo } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord } from '../types';
