    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      // استبعاد الحقول غير الموجودة في قاعدة البيانات لحل خطأ Sync Error
      delete cleanItem.pitch;
      delete cleanItem.location;

      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined || cleanItem[key] === "") {
          cleanItem[key] = null;
        }
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async () => {
    if (!state.currentUser) return;

    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const [
        { data: cats },
        { data: ppl },
        { data: sess },
        { data: mtch },
        { data: attn },
        { data: usrs }
      ] = await Promise.all([
        supabase.from('categories').select('name'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('users').select('*'),
      ]);

      setState(prev => ({
        ...prev,
        categories: (cats && cats.length > 0) ? cats.map(c => c.name) : prev.categories,
        people: ppl || [],
        sessions: sess || [],
        matches: mtch || [],
        attendance: attn || [],
        users: usrs || prev.users
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      console.error("❌ Fetch Error:", error);
      setSyncStatus('error');
      addLog('خطأ في جلب البيانات', error.message || 'فشل الوصول للسحاب.', 'error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser, addLog]);

  const pushData = useCallback(async (updatedState: AppState) => {
    if (!updatedState.currentUser) return;

    setSyncStatus('syncing');
    try {
      const tables = [
        { name: 'people', data: updatedState.people },
        { name: 'sessions', data: updatedState.sessions },
        { name: 'matches', data: updatedState.matches },
        { name: 'attendance', data: updatedState.attendance },
        { name: 'users', data: updatedState.users }
      ];

      for (const table of tables) {
        if (table.data.length > 0) {
          const { error } = await supabase
            .from(table.name)
            .upsert(sanitize(table.data), { onConflict: 'id' });

          if (error) {
            const msg = typeof error === 'string' ? error : (error.message || JSON.stringify(error));
            throw new Error(`${table.name}: ${msg}`);
          }
        }
      }

      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      const errorMsg = error.message || 'خطأ غير معروف في السحاب';
      addLog('فشل مزامنة الجداول', errorMsg, 'error');
      console.error("❌ Sync Error:", errorMsg);
    }
  }, [addLog]);

  useEffect(() => {
    if (state.currentUser) {
      fetchData();
    }
  }, [state.currentUser, fetchData]);

  const updateStateAndSync = async (updater: (prev: AppState) => AppState) => {
    let nextState: AppState | null = null;
    setState(prev => {
      nextState = updater(prev);
      return nextState;
    });

    if (nextState) {
      await pushData(nextState);
    }
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('dashboard');
  };

  if (!state.currentUser) {
    return <Login onLogin={(user) => setState(prev => ({ ...prev, currentUser: user }))} state={state} />;
  }

  const navItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: LayoutDashboard },
    { id: 'squad', label: 'إدارة الفريق', icon: Users },
    { id: 'attendance', label: 'نظام الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const unreadCount = state.notifications.filter(n => !n.isRead).length;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#001F3F] text-white transform transition-transform duration-300 lg:translate-x-0 lg:static lg:inset-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print shadow-2xl`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center justify-between border-b border-white/10">
            <div className="flex items-center gap-3">
              <ClubLogo size={40} />
              <span className="font-black text-lg tracking-tight">نادي الكرامة</span>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' : 'text-white/70 hover:bg-white/5 hover:text-white'}`}>
                <item.icon size={20} />
                <span className="font-bold">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-4 border-t border-white/10">
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-400/10 transition-colors font-bold">
              <LogOut size={20} /> <span>تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/90 backdrop-blur-md border-b sticky top-0 z-40 px-4 lg:px-8 py-4 flex items-center justify-between shadow-sm no-print">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-lg"><Menu size={24} /></button>
            <h1 className="text-xl font-black text-slate-800">
              {navItems.find(i => i.id === activeTab)?.label || (activeTab === 'report' ? 'التقرير الفني' : 'تفاصيل')}
            </h1>
          </div>

          <div className="flex items-center gap-4">
            <div className={`flex items-center gap-2 px-4 py-2 rounded-2xl border transition-all duration-500 ${
              syncStatus === 'synced' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' :
              syncStatus === 'error' ? 'bg-red-50 border-red-200 text-red-700 animate-pulse' :
              'bg-orange-50 border-orange-200 text-orange-700'
            }`}>
               {syncStatus === 'synced' && <CloudCheck size={18} />}
               {syncStatus === 'error' && <CloudOff size={18} />}
               {syncStatus === 'syncing' && <Cloud size={18} className="animate-bounce" />}
               <span className="text-[10px] font-black uppercase whitespace-nowrap hidden sm:inline">
                 {syncStatus === 'synced' ? 'مزامنة كاملة' : syncStatus === 'error' ? 'خطأ بالربط' : 'جاري الرفع...'}
               </span>
            </div>

            <div className="hidden md:flex flex-col items-end px-4 border-r-2 border-orange-500">
              <span className="text-[10px] font-black text-slate-400 uppercase leading-none mb-1">المسؤول الحالي</span>
              <div className="flex items-center gap-2">
                <span className="text-sm font-black text-[#001F3F]">{state.currentUser.username}</span>
                <User size={14} className="text-orange-600" />
              </div>
            </div>

            <button onClick={fetchData} className="p-2.5 rounded-xl bg-slate-100 text-slate-600 hover:bg-slate-200 transition-all">
              <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
            </button>

            <div className="relative">
              <button onClick={() => setShowNotifications(!showNotifications)} className={`p-2.5 rounded-xl relative border ${showNotifications ? 'bg-orange-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}>
                <Bell size={20} />
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-600 text-white text-[9px] font-black rounded-full flex items-center justify-center border-2 border-white">{unreadCount}</span>}
              </button>
              {showNotifications && (
                <div className="absolute left-0 top-12 w-80 bg-white rounded-2xl shadow-2xl border-2 border-slate-900 overflow-hidden z-[100] text-right">
                  <div className="p-4 border-b bg-slate-50 flex justify-between items-center">
                    <h3 className="font-black text-xs uppercase text-slate-800">تنبيهات النظام</h3>
                    <button onClick={() => setState(p => ({ ...p, notifications: p.notifications.map(n => ({...n, isRead: true})) }))} className="text-[10px] text-blue-600 font-bold">قراءة الكل</button>
                  </div>
                  <div className="max-h-96 overflow-y-auto custom-scrollbar">
                    {state.notifications.length === 0 ? (
                      <div className="p-8 text-center text-slate-400 text-xs italic opacity-50">لا توجد تنبيهات</div>
                    ) : (
                      state.notifications.map(n => (
                        <div key={n.id} className={`p-4 border-b hover:bg-slate-50 transition-colors ${!n.isRead ? 'bg-orange-50/50' : ''}`}>
                          <p className="text-[11px] font-black text-slate-700 leading-tight">{n.message}</p>
                          <span className="text-[9px] text-slate-400 mt-1 block">{new Date(n.timestamp).toLocaleTimeString('ar-SY')}</span>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto space-y-6 pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <footer className="bg-white/95 backdrop-blur-md border-t py-1.5 px-5 flex justify-between items-center no-print z-40">
           <p className="text-[7px] font-black text-slate-500 tracking-tighter">نادي الكرامة الرياضي - مكتب كرة القدم المركزي</p>
           <p className="text-[7px] font-black text-[#001F3F] border-r-2 border-orange-500 pr-2">By: Izzat Amer Al-Shikha | النسخة السحابية الموحدة (V4)</p>
        </footer>
      </main>

      {showNotifications && (
        <div className="fixed inset-0 z-30" onClick={() => setShowNotifications(false)}></div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Calendar, MapPin, Clock, Plus, Trash2, Edit, X, Printer, FileText, CheckCircle, ShieldCheck, Lock, AlertCircle, Map } from 'lucide-react';
import { AppState, TrainingSession, Category } from '../types';
import { generateUUID } from '../App';

interface TrainingPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

export default function TrainingPlanner({ state, setState, defaultSelectedId, addLog }: TrainingPlannerProps) {
  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;

  // Strict Role Control: Only Manager ('مدير') can add/edit/delete
  const isManager = currentUser?.role === 'مدير';
  const canModifyConfig = isManager; 

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<TrainingSession>>({
    category: restrictedCat || (state.categories.length > 0 ? state.categories[0] : 'الرجال'),
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    pitch: ''
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.date || !formData.time) return;

    // Time validation: Prevent past dates/times
    const selectedDateTime = new Date(`${formData.date}T${formData.time}`);
    const now = new Date();
    if (!editingSessionId && selectedDateTime < now) {
      alert("تنبيه: لا يمكن جدولة تمرين في تاريخ أو وقت سابق للوقت الحالي.");
      return;
    }

    if (editingSessionId) {
      setState(prev => ({
        ...prev,
        sessions: prev.sessions.map(s => s.id === editingSessionId ? { ...s, ...formData } as TrainingSession : s)
      }));
      addLog?.('تعديل موعد تمرين', `تم تحديث بيانات تمرين فئة ${formData.category}`, 'info');
    } else {
      const newSession: TrainingSession = {
        id: generateUUID(),
        category: formData.category as Category,
        date: formData.date || '',
        time: formData.time || '16:00',
        pitch: formData.pitch || 'غير محدد',
        objective: formData.objective || 'تمرين عام',
        isCompleted: false
      };
      setState(prev => ({ ...prev, sessions: [newSession, ...prev.sessions] }));
      addLog?.('إضافة موعد تمرين', `تمت جدولة تمرين جديد لفئة ${newSession.category}`, 'info');
    }
    setIsModalOpen(false);
    setEditingSessionId(null);
  };

  const filteredSessions = useMemo(() => {
    return (restrictedCat 
      ? state.sessions.filter(s => s.category === restrictedCat)
      : state.sessions).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.sessions, restrictedCat]);

  // Check if session is older than 30 minutes for locking UI
  const isSessionLocked = (session: TrainingSession) => {
    const sessionTime = new Date(`${session.date}T${session.time}`);
    const now = new Date();
    const diffInMinutes = (now.getTime() - sessionTime.getTime()) / (1000 * 60);
    return diffInMinutes > 30;
  };

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-4 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
           <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
             <Calendar size={24} className="text-blue-900" /> أجندة التدريبات المركزية (الجدولة)
           </h3>
           <p className="text-[10px] font-black text-slate-400 mt-1">تنظيم مواعيد التدريب لجميع الفئات - ميزة التعديل محصورة بمدير المكتب</p>
        </div>
        {canModifyConfig && (
          <button onClick={() => { setEditingSessionId(null); setIsModalOpen(true); }}
            className="bg-[#001F3F] text-white px-8 py-3 rounded-xl flex items-center gap-2 font-black text-sm shadow-lg border-b-4 border-black hover:bg-black transition-all">
            <Plus size={20} /> إضافة حصة تدريبية جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredSessions.map(session => {
          const locked = isSessionLocked(session);
          return (
            <div key={session.id} className={`bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 transition-all no-print ${locked ? 'border-slate-300 opacity-80' : 'hover:border-blue-900'}`}>
              <div className="flex justify-between items-center mb-4">
                 <span className="bg-[#001F3F] text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{session.category}</span>
                 {locked ? (
                   <span className="text-[9px] font-black text-red-600 flex items-center gap-1 bg-red-50 px-2 py-1 rounded-lg border border-red-200"><Lock size={12}/> مغلق إدارياً</span>
                 ) : (
                   <span className="text-[9px] font-black text-emerald-600 flex items-center gap-1 bg-emerald-50 px-2 py-1 rounded-lg border border-emerald-200"><ShieldCheck size={12}/> متاح للرصد</span>
                 )}
              </div>

              <h4 className="font-black text-lg text-slate-900 leading-tight mb-4">{session.objective}</h4>

              <div className="space-y-2 mb-6">
                 <div className="flex items-center gap-2 text-[11px] font-black text-slate-600">
                    <Clock size={14} className="text-orange-600"/> {session.time} • {session.date}
                 </div>
                 {session.pitch && (
                   <div className="flex items-center gap-2 text-[11px] font-black text-slate-600">
                      <Map size={14} className="text-emerald-600"/> {session.pitch}
                   </div>
                 )}
              </div>

              <div className="flex gap-2">
                <div className="flex-1 bg-slate-100 border-2 border-slate-900 text-slate-900 py-2.5 rounded-xl font-black text-[10px] flex items-center justify-center gap-2">
                  <FileText size={14}/> تفاصيل التمرين
                </div>
                {canModifyConfig && (
                  <div className="flex gap-1">
                    <button onClick={() => {setEditingSessionId(session.id); setFormData(session); setIsModalOpen(true);}} className="p-2.5 bg-blue-50 text-blue-900 rounded-xl border-2 border-blue-900 hover:bg-blue-900 hover:text-white transition-all"><Edit size={16}/></button>
                    <button onClick={() => { if(confirm('تنبيه: هل أنت متأكد من حذف هذا التمرين نهائياً؟')) setState(p => ({...p, sessions: p.sessions.filter(x => x.id !== session.id)})) }} className="p-2.5 bg-red-50 text-red-600 rounded-xl border-2 border-red-900 hover:bg-red-600 hover:text-white transition-all"><Trash2 size={16}/></button>
                  </div>
                )}
              </div>
            </div>
          );
        })}
        {filteredSessions.length === 0 && (
          <div className="col-span-full py-20 text-center bg-slate-50 border-4 border-dashed border-slate-200 rounded-[3rem]">
            <Calendar size={48} className="text-slate-200 mx-auto mb-4" />
            <p className="text-slate-400 font-black italic">لا يوجد تمارين مجدولة حالياً لهذه الفئة</p>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-md flex items-center justify-center z-[200] p-4 no-print">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden border-[6px] border-slate-900">
            <div className="p-8 border-b-2 bg-slate-100 flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-900 uppercase">جدولة حصة تدريبية مركزية</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-white p-2 rounded-xl border-2 border-slate-900"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-5">
              <div className="grid grid-cols-1 gap-4">
                 <div>
                    <label className={labelClass}>الفئة المستهدفة</label>
                    <select required className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                 </div>
              </div>
              <div>
                 <label className={labelClass}>الملعب المستضيف</label>
                 <input type="text" placeholder="مثلاً: ملعب منشأة الكرامة.." className={fieldClass} value={formData.pitch || ''} onChange={e => setFormData({ ...formData, pitch: e.target.value })} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className={labelClass}>تاريخ التمرين</label>
                    <input type="date" required className={fieldClass} value={formData.date || ''} onChange={e => setFormData({ ...formData, date: e.target.value })} />
                 </div>
                 <div>
                    <label className={labelClass}>التوقيت المعتمد</label>
                    <input type="time" required className={fieldClass} value={formData.time || ''} onChange={e => setFormData({ ...formData, time: e.target.value })} />
                 </div>
              </div>
              <div>
                 <label className={labelClass}>الهدف التدريبي الرئيسي</label>
                 <textarea required rows={3} placeholder="مثال: تحسين اللياقة البدنية والكرات العرضية.." className={`${fieldClass} py-3 h-24`} value={formData.objective || ''} onChange={e => setFormData({ ...formData, objective: e.target.value })}></textarea>
              </div>

              <div className="bg-orange-50 p-4 rounded-xl border-2 border-orange-200 flex gap-3 items-start">
                 <AlertCircle className="text-orange-600 shrink-0" size={18}/>
                 <div className="space-y-1">
                    <p className="text-[10px] font-black text-orange-900 leading-relaxed">تنبيه نظام الرقابة: سيتم قفل إمكانية رصد الحضور لهذا التمرين تلقائياً بعد مضي 30 دقيقة من الموعد المحدد.</p>
                 </div>
              </div>

              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-5 rounded-2xl shadow-xl border-b-4 border-black hover:bg-black transition-all uppercase tracking-widest text-lg">تثبيت الجدولة في النظام</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID } from '../App';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter 
  });

  const matchTypes: MatchType[] = ['دوري', 'كأس', 'ودية', 'بطولة ودية', 'مباراة دولية'];

  // Sync formData category when modal opens
  useEffect(() => {
    if (isAddOpen) {
      setFormData(prev => ({
        ...prev,
        category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter
      }));
    }
  }, [isAddOpen, state.globalCategoryFilter, state.categories]);

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter));
  }, [state.matches, state.globalCategoryFilter]);

  const handleAddMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date || !formData.time || !formData.category) return;

    const newMatch: Match = {
      id: generateUUID(),
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time,
      category: formData.category,
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { 
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })), 
        subs: [], 
        staff: [], 
        captain: '' 
      },
      notes: ''
    };

    setState(p => ({ ...p, matches: [newMatch, ...p.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ${newMatch.matchType} ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      newLineup.starters[index] = { ...newLineup.starters[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const toggleCaptain = (playerId: string) => {
    if (!activeMatch || !playerId) return;
    const newLineup = { ...activeMatch.lineup };
    // إذا كان اللاعب هو الكابتن الحالي، نلغيه، وإلا نجعله الكابتن الجديد
    newLineup.captain = newLineup.captain === playerId ? '' : playerId;
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateMinutes = (index: number, minutes: string, isStarter: boolean) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      newLineup.starters[index].minutesPlayed = minutes;
    } else {
      newLineup.subs[index].minutesPlayed = minutes;
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const handleSubstitutionCalculation = (subIndex: number, replacedPlayerId: string, subMinute: string) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    const minute = parseInt(subMinute) || 0;

    // 1. تحديث بيانات التبديل في البدلاء
    newLineup.subs[subIndex].replacedPlayerId = replacedPlayerId;
    newLineup.subs[subIndex].substitutionMinute = subMinute;

    // 2. حساب دقائق اللاعب الداخل (الاحتياطي)
    newLineup.subs[subIndex].minutesPlayed = (90 - minute).toString();

    // 3. البحث عن اللاعب الخارج في الأساسيين وتحديث دقائقه
    const starterIdx = newLineup.starters.findIndex(s => s.playerId === replacedPlayerId);
    if (starterIdx !== -1) {
      newLineup.starters[starterIdx].minutesPlayed = subMinute;
    }

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addSub = () => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' }]
      }
    });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { ...newSubs[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const removeSub = (index: number) => {
    if (!activeMatch) return;
    const newSubs = activeMatch.lineup.subs.filter((_, i) => i !== index);
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
      note: ''
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const removeEvent = (eventId: string) => {
    if (!activeMatch) return;
    setActiveMatch({
      ...activeMatch,
      events: activeMatch.events.filter(e => e.id !== eventId)
    });
  };

  const saveMatchDetails = () => {
    if (!activeMatch) return;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? activeMatch : m)
    }));
    addLog?.('تحديث المباراة', `تم حفظ تفاصيل مباراة ${activeMatch.opponent}`, 'info');
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId)
    ].filter(id => id && id !== currentId);

    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-[#001F3F] mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
           <h2 className="text-xl font-black text-slate-900 flex items-center gap-3">
             <Trophy size={24} className="text-orange-600" /> إدارة أجندة المباريات المركزية
           </h2>
           <p className="text-[10px] font-black text-slate-400 mt-1">تنسيق التشكيلة، دقائق اللعب، الأهداف، والبطاقات للفئات</p>
        </div>
        <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg border-b-4 border-black hover:bg-black transition-all">
          <Plus size={20} /> جدولة مواجهة جديدة
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border-2 border-slate-900 relative group overflow-hidden border-b-8 hover:border-orange-600 transition-all">
             <div className="flex justify-between items-start mb-6">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400 flex items-center gap-1"><Calendar size={12}/> {m.date} - {m.category}</span>
             </div>

             <div className="flex items-center justify-between gap-4 mb-4">
                <div className="text-center flex-1">
                   <div className="w-14 h-14 bg-slate-100 border-2 border-slate-900 rounded-2xl flex items-center justify-center mx-auto mb-2 font-black text-xl">K</div>
                   <p className="font-black text-xs">الكرامة</p>
                </div>
                <div className="text-center px-4">
                   <p className="text-3xl font-black text-slate-900">{m.ourScore} - {m.opponentScore}</p>
                   <p className="text-[9px] font-black text-slate-400 uppercase mt-2">{m.time}</p>
                </div>
                <div className="text-center flex-1">
                   <div className="w-14 h-14 bg-slate-100 border-2 border-slate-900 rounded-2xl flex items-center justify-center mx-auto mb-2 font-black text-xl">{m.opponent.charAt(0)}</div>
                   <p className="font-black text-xs truncate max-w-[80px]">{m.opponent}</p>
                </div>
             </div>

             <div className="mb-6 flex flex-col gap-1 px-2">
                {m.pitch && (
                  <div className="flex items-center gap-2 text-[10px] font-black text-slate-500">
                     <Map size={12} className="text-emerald-600" /> {m.pitch}
                  </div>
                )}
             </div>

             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 hover:bg-black">
                  <BookOpen size={16}/> إدارة المباراة والتشكيل
                </button>
                <button onClick={() => { if(confirm('حذف المباراة؟')) setState(p => ({...p, matches: p.matches.filter(x => x.id !== m.id)})) }} className="p-3 bg-red-50 text-red-600 rounded-xl border-2 border-red-900 hover:bg-red-600 hover:text-white transition-all"><Trash2 size={16}/></button>
             </div>
          </div>
        ))}
      </div>

      {isAddOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-md flex items-center justify-center z-[300] p-4 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-[6px] border-slate-900 overflow-hidden">
             <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                <h3 className="font-black text-slate-900 uppercase">جدولة مواجهة جديدة</h3>
                <button onClick={() => setIsAddOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
             </div>
             <form onSubmit={handleAddMatch} className="p-8 space-y-5">
                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className={labelClass}>الفئة</label>
                      <select required className={fieldClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                   </div>
                   <div>
                      <label className={labelClass}>نوع المباراة</label>
                      <select required className={fieldClass} value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})}>
                        {matchTypes.map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                   </div>
                </div>
                <div>
                   <label className={labelClass}>اسم الخصم</label>
                   <input required type="text" className={fieldClass} value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} />
                </div>
                <div>
                   <label className={labelClass}>الملعب</label>
                   <input type="text" className={fieldClass} value={formData.pitch || ''} onChange={e => setFormData({...formData, pitch: e.target.value})} placeholder="مثلاً: ملعب الباسل.." />
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className={labelClass}>التاريخ</label>
                      <input required type="date" className={fieldClass} value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                   </div>
                   <div>
                      <label className={labelClass}>التوقيت</label>
                      <input required type="time" className={fieldClass} value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                   </div>
                </div>
                <button type="submit" className="w-full bg-[#001F3F] text-white py-4 rounded-xl font-black shadow-xl hover:bg-black transition-all mt-4 uppercase">تثبيت الجدولة المركزية</button>
             </form>
          </div>
        </div>
      )}

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-xl z-[400] overflow-y-auto custom-scrollbar p-4 lg:p-10 no-print">
           <div className="max-w-6xl mx-auto bg-white rounded-[3rem] border-[8px] border-slate-900 min-h-screen flex flex-col shadow-2xl">
              <header className="p-8 border-b-4 border-slate-900 bg-slate-50 flex flex-col md:flex-row justify-between items-center gap-6">
                 <div className="flex items-center gap-4">
                    <div className="bg-[#001F3F] text-white w-16 h-16 rounded-2xl flex items-center justify-center font-black text-2xl border-4 border-slate-900">K</div>
                    <div>
                       <h2 className="text-2xl font-black text-slate-900">إدارة تفاصيل المباراة والتشكيل</h2>
                       <p className="text-sm font-black text-orange-600 tracking-widest uppercase">نادي الكرامة × {activeMatch.opponent} ({activeMatch.matchType}) {activeMatch.pitch ? `| ${activeMatch.pitch}` : ''}</p>
                    </div>
                 </div>
                 <div className="flex gap-3">
                    <button onClick={saveMatchDetails} className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-black flex items-center gap-2 border-b-4 border-black hover:bg-emerald-700">
                       <Save size={20}/> حفظ التغييرات والتشكيل
                    </button>
                    <button onClick={() => setActiveMatch(null)} className="bg-red-50 text-red-600 px-6 py-3 rounded-xl font-black border-2 border-red-900">
                       إلغاء التعديل
                    </button>
                 </div>
              </header>

              <div className="flex-1 p-8 grid grid-cols-1 lg:grid-cols-3 gap-10">
                 <div className="lg:col-span-2 space-y-10">
                    <section>
                       <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                          <Users size={22}/> التشكيل الأساسي (11 لاعب)
                       </h3>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {activeMatch.lineup.starters.map((s, idx) => {
                             const isCaptain = activeMatch.lineup.captain === s.playerId;
                             return (
                             <div key={idx} className={`flex flex-col gap-2 bg-slate-50 p-4 rounded-xl border-2 transition-all ${isCaptain ? 'border-orange-600 bg-orange-50/50 shadow-md ring-2 ring-orange-100' : 'border-slate-200'}`}>
                                <div className="flex items-center gap-3">
                                   <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-xs shrink-0">{idx + 1}</span>
                                   <select 
                                     className="flex-1 bg-white border-2 border-slate-300 rounded-lg p-2 font-black text-xs outline-none focus:border-blue-600"
                                     value={s.playerId}
                                     onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}
                                   >
                                      <option value="">-- اختر اللاعب --</option>
                                      {getAvailablePlayers(s.playerId).map(p => (
                                         <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                      ))}
                                   </select>
                                   <div className="w-12 text-center bg-[#001F3F] text-white border-2 border-slate-900 rounded-lg p-2 font-black text-xs">
                                      #{s.number || '--'}
                                   </div>
                                   <button 
                                     onClick={() => toggleCaptain(s.playerId)}
                                     title={isCaptain ? "إلغاء شارة الكابتن" : "تعيين ككابتن للفريق"}
                                     disabled={!s.playerId}
                                     className={`p-2 rounded-lg border-2 transition-all ${isCaptain ? 'bg-orange-600 text-white border-orange-900' : 'bg-white text-slate-300 border-slate-200 hover:text-orange-600 hover:border-orange-600 disabled:opacity-30'}`}
                                   >
                                      <Crown size={18} />
                                   </button>
                                </div>
                                <div className="flex items-center justify-between">
                                  <div className="flex items-center gap-2">
                                     <Timer size={14} className="text-slate-400" />
                                     <label className="text-[9px] font-black text-slate-500 uppercase">دقائق اللعب النهائية:</label>
                                     <input 
                                       type="number" 
                                       className="w-20 bg-white border border-slate-300 rounded px-2 py-1 text-[10px] font-black outline-none" 
                                       value={s.minutesPlayed || '90'} 
                                       onChange={e => updateMinutes(idx, e.target.value, true)} 
                                     />
                                  </div>
                                  {isCaptain && <span className="text-[9px] font-black text-orange-600 bg-white px-2 py-0.5 rounded border border-orange-600 uppercase animate-pulse">القائد (Captain)</span>}
                                </div>
                             </div>
                          )})}
                       </div>
                    </section>

                    <section>
                       <div className="flex justify-between items-center mb-6">
                          <h3 className="text-lg font-black text-slate-900 flex items-center gap-3 border-r-4 border-blue-900 pr-4">
                             <UserPlus size={22}/> التبديلات وحساب الدقائق الذكي
                          </h3>
                          <button onClick={addSub} className="bg-blue-900 text-white px-4 py-2 rounded-lg font-black text-xs flex items-center gap-2 shadow-md">
                             <Plus size={16}/> إضافة تبديل جديد
                          </button>
                       </div>
                       <div className="space-y-4">
                          {activeMatch.lineup.subs.map((s, idx) => (
                             <div key={idx} className="bg-blue-50/50 p-6 rounded-[2rem] border-2 border-blue-100 shadow-sm space-y-4 relative group">
                                <div className="flex items-center gap-4">
                                   <div className="flex-1">
                                      <label className="text-[9px] font-black text-blue-900 mb-1 block uppercase">اللاعب البديل (الداخل)</label>
                                      <select 
                                        className="w-full bg-white border-2 border-slate-300 rounded-lg p-3 font-black text-xs shadow-sm"
                                        value={s.playerId}
                                        onChange={e => updateSub(idx, e.target.value)}
                                      >
                                         <option value="">-- اختر البديل --</option>
                                         {getAvailablePlayers(s.playerId).map(p => (
                                            <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                         ))}
                                      </select>
                                   </div>
                                   <div className="w-16 h-16 bg-white border-2 border-blue-900 rounded-2xl flex items-center justify-center font-black text-xl text-blue-900 shadow-inner shrink-0 mt-4">
                                      #{s.number || '--'}
                                   </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-white/60 p-4 rounded-2xl border border-white">
                                   <div className="space-y-1">
                                      <label className="text-[9px] font-black text-slate-500 flex items-center gap-1 uppercase">
                                        <LogOut size={12} className="text-red-500" /> اللاعب المستبدل (الخارج)
                                      </label>
                                      <select 
                                        className="w-full bg-white border border-slate-200 rounded-lg p-2 text-[10px] font-black"
                                        value={s.replacedPlayerId || ''}
                                        onChange={e => handleSubstitutionCalculation(idx, e.target.value, s.substitutionMinute || '0')}
                                      >
                                         <option value="">-- اختر اللاعب الخارج --</option>
                                         {activeMatch.lineup.starters.map(starter => (
                                            <option key={starter.playerId} value={starter.playerId}>{starter.name || 'لاعب فارغ'} (#{starter.number})</option>
                                         ))}
                                      </select>
                                   </div>
                                   <div className="space-y-1">
                                      <label className="text-[9px] font-black text-slate-500 flex items-center gap-1 uppercase">
                                        <Clock size={12} className="text-orange-600" /> وقت التبديل (الدقيقة)
                                      </label>
                                      <input 
                                        type="number" 
                                        placeholder="0"
                                        className="w-full bg-white border border-slate-200 rounded-lg p-2 text-[10px] font-black text-center"
                                        value={s.substitutionMinute || ''}
