                          <button onClick={() => addEvent('assist')} className="bg-blue-50 text-blue-700 p-3 rounded-xl font-black text-[10px] border-2 border-blue-200 hover:bg-blue-100 uppercase transition-all shadow-sm">👟 صناعة هدف</button>
