                         value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})} placeholder="سجل تقريرك الفني المختصر للمباراة هنا..."></textarea>
                    </section>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

