           {/* Signatures */}
           <div className="mt-12 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-10">
                 <p className="font-black text-[10px]">توقيع مدرب الفئة</p>
                 <p className="text-[10px] text-slate-300">..................................</p>
              </div>
              <div className="text-center space-y-10">
                 <p className="font-black text-[10px]">خاتم مكتب كرة القدم</p>
                 <div className="w-20 h-20 border-2 border-dashed border-slate-200 rounded-full mx-auto flex items-center justify-center text-[6px] text-slate-200 italic">مساحة الختم</div>
