         </div>
      </div>

      {/* Contract Expiry Alert Section */}
      {expiringContracts.length > 0 && (
        <div className="bg-red-50 border-4 border-red-900 rounded-[2.5rem] p-6 shadow-xl animate-pulse no-print">
